	["%s también arregla el buzón: dos «Tomar todo» se estorban."] = "%s 也會改善信箱：兩個「全部拿取」按鈕會互相干擾。",
	["%s también cambia tus bolsas y el banco: las dos ventanas se pisan al abrirlas."] = "%s 也會修改你的背包和銀行：兩個視窗開啟時會互相干擾。",
