	["*bosteza* Cazar contigo es lo mejor de mi día."] = "*打哈欠* 和你一起狩獵是我一天中最開心的事。",
	["*la devora en un segundo* ¡Gracias! Ahora sí, a cazar."] = "*一秒就吞下去了* 謝謝！現在可以去狩獵了。",
	["*levanta la manita* ¿Salchicha? Prometo cuidarte el doble."] = "*舉起小爪子* 香腸嗎？我保證加倍照顧你。",
