	["*olfatea el aire* Huele a aventura."] = "*嗅了嗅空氣* 有冒險的味道。",
	["*olfatea el suelo* Por aquí pasó un jabalí... hace rato."] = "*嗅嗅地面* 有一頭野豬從這裡經過…有一陣子了。",
	["*persigue su cola un ratito* …¡Casi la atrapo!"] = "*追了一會兒自己的尾巴* ……差點就抓到了！",
	["*se echa un ratito* No estoy dormida, estoy vigilando con los ojos cerrados."] = "*趴下來歇一會兒* 我沒睡著，我是閉著眼睛在站崗。",
	["*se estira y bosteza* Listo, ¡a seguir!"] = "*伸了個懶腰，打了個哈欠* 好了，繼續出發！",
