	["A estas horas hasta los murlocs duermen. No te desveles mucho, que mañana también se caza."] = "這個時間連魚人都睡了。別熬太晚：明天還要狩獵呢。",
	["A la entrada de Ventormenta, estatuas de los grandes héroes de la Segunda Guerra reciben a los visitantes."] = "在暴風城的入口，第二次戰爭英雄們的雕像迎接著來訪者。",
