	["A mitad de la pelea se protege con un escudo y prepara una gran explosión: cuando lo veas brillar, ¡aléjate de él!"] = "戰鬥進行到一半時，他會用護盾保護自己並準備大爆炸：看到他發光時，快離他遠一點！",
	["A nivel 10 haces las misiones para domar a tu primera mascota."] = "10 級時你要做任務來馴服你的第一隻寵物。",
