	["A tu lado"] = "在你身邊",
	["A tu medida"] = "照你的方式",
	["A tu nivel los enemigos caen rápido: remata con 3 puntos de combo."] = "在你這個等級敵人倒得很快：攢 3 點連擊點數就終結。",
	["A tu nivel te conviene %s: lo vende el posadero o un vendedor de comida."] = "你這個等級買 %s 吧：旅店老闆和食物商人都有賣。",
	["A tu nivel: %s"] = "適合你等級的：%s",
	["A un clic"] = "一鍵直達",
	["A veces"] = "有時",
	["A veces el golpe ni te toca."] = "有時攻擊根本碰不到你。",
	["A veces el juego tarda o no deja mover a nadie más a esa capa. Puedes salir del grupo y probar con otra."] = "有時遊戲會慢一點，或不再讓人進入那個位面。你可以離隊試試別的。",
	["A veces pescas cajas y botellas con mensajes que empiezan una misión."] = "有時你會釣到箱子和裝著信的瓶子，可以開始一個任務。",
	["A veces salen gemas al minar: guárdalas, porque varias profesiones las usan en sus recetas."] = "採礦時有時會挖到寶石：收好，好幾個專業的配方都用得到。",
	["Abajo"] = "向下",
	["Abajo del modelo, elige lo que hace tu personaje (caminar, bailar, saludar...) y páusalo."] = "在模型下方選擇角色的動作（走路、跳舞、揮手...），也可以暫停。",
	["Abajo y al centro del ícono, con letra que crece con él. Apagada, chiquita en la esquina."] = "在圖示底部置中，字體隨圖示變大。關閉時，以小字顯示在角落。",
	["Abalorio"] = "飾品",
	["Abalorios"] = "飾品",
	["Abandonar"] = "放棄",
	["Abandonar marcadas (%d)"] = "放棄已標記的任務（%d）",
	["Abandonaste %d misiones"] = "你放棄了 %d 個任務",
	["Abierta"] = "已開放",
	["Abierta: si alguien de la manada pide entrar, Alfa lo invita a tu grupo (fuera de combate)."] = "開啟：狼群裡有人想進來時，Alfa 會邀請他入隊（非戰鬥中）。",
	["Abiertas"] = "已開啟",
	["Abrazo vampírico: tu daño de sombras te cura."] = "吸血鬼的擁抱：你的暗影傷害會治療你。",
	["Abre Heridas profundas."] = "解鎖重傷。",
	["Abre Hoy: ahí te digo lo más útil para este momento en grande, y tu camino a un par de clics."] = "打開「今天」：那裡大大地顯示此刻最有用的事，你的路線也只需點幾下。",
	["Abre Paisaje y gráficos"] = "開啟風景與圖形",
	["Abre Recolección. Con «ruta», crea y sigue una ruta de farmeo en tu zona."] = "開啟採集。加上「ruta」會在你所在地區建立並跟隨一條採集路線。",
	["Abre desde el sigilo para empezar con ventaja."] = "從潛行中開場，搶得先機。",
	["Abre el mapa del juego en esta misma zona. En combate el mapa del juego no se abre desde Alfa."] = "在同一地區開啟遊戲地圖。戰鬥中無法從 Alfa 開啟遊戲地圖。",
	["Abre el mapa y haz clic derecho (o Mayús+clic) donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras. En el mapa del juego, Mayús+clic derecho."] = "開啟地圖，在想要的位置按右鍵（或 Shift+點擊）：設定名稱、圖示與顏色，箭頭隨時都能帶你過去。在遊戲地圖上則用 Shift+右鍵。",
	["Abre el mapa: cada muelle dice cuánto falta para que llegue su barco o zepelín."] = "開啟地圖：每個碼頭都顯示它的船或飛艇還有多久抵達。",
	["Abre el modo pesca (aquí, con /alfa pesca o al ponerte la caña) y pulsa %s: tu tecla te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "開啟釣魚模式（在這裡、用 /alfa pesca 或裝備魚竿時），然後按 %s：你的按鍵會幫你換上裝備、上魚餌、拋竿，並在水花濺起時收竿。",
	["Abre el modo pesca y elige tu tecla: te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "開啟釣魚模式並選擇你的按鍵：它會幫你換上裝備、上魚餌、拋竿，並在水花濺起時收竿。",
	["Abre el modo pesca y pulsa tu tecla: lo que saques aparece aquí."] = "開啟釣魚模式並按你的按鍵：釣到的東西會顯示在這裡。",
	["Abre la Cocina del juego (el botón lo hace) y vuelve a pulsar."] = "開啟遊戲的烹飪視窗（按鈕會幫你開啟），然後再按一次。",
	["Abre la Enciclopedia y en la ficha del objeto toca «Agregar a mi ruta»."] = "開啟百科，在物品詳細頁面點擊「加入我的路線」。",
	["Abre la casa de subastas para escanear."] = "請開啟拍賣場以進行掃描。",
	["Abre la casa de subastas y pulsa «Escanear con Alfa» para saber cuánto valen tus objetos."] = "開啟拍賣場並按下「用 Alfa 掃描」，就能知道你的物品值多少錢。",
	["Abre la guía de Alfa que te lleva a conseguir este objeto."] = "開啟能帶你取得此物品的 Alfa 指南。",
	["Abre la pelea a distancia antes de que llegue."] = "在它靠近之前先從遠距離開打。",
	["Abre la pelea: te acerca al enemigo y te da ira."] = "開場技能：讓你衝到敵人身邊並獲得怒氣。",
	["Abre la siguiente fila."] = "解鎖下一排。",
	["Abre la ventana Historias."] = "開啟「故事」視窗。",
	["Abre la ventana de clic para lanzar de Blizzard para que armes ahí los mismos clics y cures igual en sus marcos de grupo (el juego no deja que un addon los copie)."] = "開啟暴雪的點擊施法視窗，在那裡設定相同的點擊，在它的隊伍框架上同樣治療（遊戲不允許插件複製它們）。",
	["Abre la ventana de talentos del juego una vez o espera unos segundos: en cuanto Alfa la lea, te dice qué poner. Mientras, abajo ves tu build."] = "開啟一次遊戲的天賦視窗或稍等幾秒：Alfa 一讀取到，就會告訴你該點什麼。在此期間，下方會顯示你的配點。",
	["Abre la ventana de tu profesión una vez y Alfa leerá tus recetas para decirte cuáles te dejan ganancia."] = "開啟一次你的專業視窗，Alfa 就會讀取你的配方，告訴你哪些能賺錢。",
	["Abre la ventana principal de Alfa."] = "開啟 Alfa 主視窗。",
	["Abre o cierra el mapa de Alfa"] = "開啟或關閉 Alfa 地圖",
	["Abre siempre con Cargar y pon Desgarrar al empezar la pelea."] = "一律用衝鋒開場，並在戰鬥一開始上撕裂。",
	["Abre siempre desde el sigilo con tu ataque más fuerte."] = "一律從潛行中用你最強的攻擊開場。",
	["Abre su ficha en Mazmorras y toca «Guíame»: la flecha te lleva hasta la puerta, aunque esté escondida en una cueva."] = "在「地城」裡打開它的資料並點「帶我去」：箭頭會帶你到門口，哪怕藏在山洞裡。",
	["Abre su ficha."] = "開啟它的詳細頁面。",
	["Abre tus bolsas con su tecla o con el botón de la mochila."] = "用背包鍵或背包按鈕開啟你的背包。",
	["Abre tus bolsas con tu tecla (%s)."] = "用你的按鍵（%s）開啟背包。",
	["Abre un buzón para tomar tus cartas."] = "開啟信箱來拿取郵件。",
	["Abre un susurro con tu mensaje listo. Si no está conectado, el juego te lo dirá."] = "開啟密語並準備好你的訊息。如果對方不在線上，遊戲會告訴你。",
