	["Abrir su guía"] = "開啟它的指南",
	["Abrumar casi siempre crítico."] = "壓制幾乎必定致命一擊。",
	["Abrumar crítico contra pícaros que esquivan."] = "對會閃躲的盜賊，壓制更容易致命一擊。",
	["Abrumar hace crítico casi siempre."] = "壓制幾乎每次都會致命一擊。",
	["Abrumar hace crítico mucho más seguido."] = "壓制致命一擊的機率大幅提高。",
	["Acaba de abrirle la puerta a alguien. Prueba en un momento."] = "剛給別人開過門。稍後再試。",
	["Acabas de vencer a un enemigo: este ataque es gratis y te cura."] = "你剛擊敗了一個敵人：這次攻擊免費，還能治療你。",
	["Accesos rápidos"] = "快速捷徑",
	["Acecho"] = "潛行",
	["Acento propio (elegido en Ajustes)"] = "自訂強調色（在設定中選擇）",
	["Acento: %s"] = "強調色：%s",
	["Acepta invitaciones de grupo de tus amigos y de tu hermandad."] = "接受好友與公會成員的組隊邀請。",
	["Acepta por ti"] = "替你接受",
	["Acepta su invitación al grupo. Al llegar a su guarida, Alfa te avisa para salir del grupo."] = "接受他的組隊邀請。到了他的巢穴後，Alfa 會提醒你離隊。",
	["Acepta una invocación al momento, salvo en combate."] = "立即接受召喚，戰鬥中除外。",
	["Acepta una resurrección en cuanto se puede. Nunca en Hardcore."] = "一有機會就接受復活。專家模式下絕不接受。",
	["Acepta y entrega las demás (normales, diarias y semanales). Nunca las grises ni las que piden oro o materiales."] = "接受並交付其餘任務（一般、每日與每週）。絕不接灰色任務，也不接要求金幣或材料的任務。",
	["Acepta y entrega tus misiones, elige tu guía y sigue sola, vende, repara y toma tus vuelos. Tú solo juegas."] = "接交任務、選指南並繼續、賣東西、修理、搭飛行。你只管玩。",
	["Aceptar"] = "確定",
	["Aceptar invocaciones"] = "接受召喚",
	["Aceptar las misiones de tu guía"] = "接受指南中的任務",
	["Aceptar resurrecciones"] = "接受復活",
	["Aceptar solas las misiones de la guía"] = "自動接受指南中的任務",
	["Aceptar todas las misiones ya no pierde una diaria porque la ventana se cerraba antes de tiempo."] = "接受所有任務時，不會再因為視窗太早關閉而漏掉每日任務。",
	["Aceptar y entregar"] = "接受並交付",
	["Aceptar y entregar misiones"] = "接受和交付任務",
	["Aceptar y entregar solo las misiones de mi ruta"] = "只接受與交付我路線上的任務",
	["Aceptar y entregar todas las misiones"] = "接受並交付所有任務",
	["Acercar"] = "放大",
	["Acomoda con el ratón a Lya, tu guía, la flecha y tus marcos: Ajustes > Estilo y sonido o /alfa acomodar."] = "用滑鼠佈置 Lya、你的指南、箭頭和框架：設定 > 風格與聲音，或 /alfa acomodar。",
	["Acomoda tus marcos"] = "擺放你的框架",
	["Acomodar"] = "整理",
	["Acomodar [pantalla]"] = "佈置",
	["Acomodar la pantalla"] = "佈置介面",
	["Actitud de batalla"] = "戰鬥姿態",
	["Actitud defensiva"] = "防禦姿態",
	["Actitud rabiosa"] = "狂暴姿態",
	["Activa el rastreo de hierbas para verlas en el minimapa mientras viajas."] = "開啟尋找草藥，旅行時就能在小地圖上看到它們。",
	["Activa el rastreo de minerales y sigue las montañas: ahí están las mejores vetas."] = "開啟尋找礦物，沿著山脈走：最好的礦脈都在那裡。",
	["Activa máquinas en las paredes que sueltan bombas que caminan: pulsa el botón junto a la máquina para apagarla, o maten las bombas antes de que lleguen."] = "他會啟動牆上的機器，放出會走路的炸彈：按下機器旁的按鈕把它關掉，或在炸彈靠近前把它們打掉。",
	["Activar el medidor de daño"] = "啟用傷害統計",
	["Activar el modo limpio"] = "開啟簡潔模式",
	["Activar módulo"] = "開啟模組",
	["Activar módulos"] = "開啟模組",
	["Activo"] = "生效中",
	["Actual"] = "目前",
	["Actualizar mi guía"] = "更新我的指南",
	["Actualizar mis barras"] = "更新我的快捷列",
	["Actualízala con la app de CurseForge o con el zip más reciente y luego usa /reload."] = "請用 CurseForge 應用程式或最新的 zip 更新，然後輸入 /reload。",
	["Actualízalo con la app de CurseForge o con el zip más reciente y luego reinicia el juego o usa /reload."] = "請使用 CurseForge 應用程式或最新的壓縮檔更新，然後重新啟動遊戲或輸入 /reload。",
	["Acércate para usar %s"] = "靠近一點才能使用 %s",
	["Además del ícono, un brillo dorado que late alrededor de su barra."] = "除了圖示，其框架周圍還會有一圈跳動的金色光芒。",
	["Adopta a un lobo 10 niveles menor que tú. Si acepta, ves su nivel, su zona y su misión (solo tú) y te aviso si se atora."] = "收養一隻比你低 10 級的狼。如果他接受，你能看到他的等級、區域和任務（只有你能看到），他卡住時我會告訴你。",
	["Adopta a un lobo nuevo o deja que uno con más nivel te adopte. Lo que comparten queda entre los dos."] = "收養一隻新來的狼，或讓等級更高的狼收養你。你們分享的內容只有你們兩個知道。",
	["Adoptar"] = "收養",
	["Afinar cosa por cosa"] = "逐項細調",
	["Afinar siempre"] = "一律銳利化",
	["Aflicción"] = "痛苦",
	["Aflicción para subir"] = "痛苦（練等）",
	["Agarras a varios enemigos a la vez."] = "你能同時穩住好幾個敵人。",
	["Agilidad"] = "敏捷",
	["Agrega la primera: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota."] = "新增第一個：物品、金幣、專業、地點、任務、等級或備註。",
	["Agrega tramos arriba: Alfa elige las misiones por ti."] = "在上方新增路段：Alfa 會為你選擇任務。",
	["Agrega una línea con el objetivo de esa unidad; si te tiene a ti, lo dice."] = "加上一行顯示該單位的目標；如果目標是你，也會註明。",
	["Agregada"] = "已加入",
	["Agregada a Cerrar mis misiones"] = "已加入「完成我的任務」",
	["Agregado a tu plan"] = "已加入你的計畫",
	["Agregado a tu ruta"] = "已加入你的路線",
	["Agregar a Cerrar mis misiones"] = "加入「完成我的任務」",
	["Agregar a Mis planes"] = "加入我的計畫",
	["Agregar a mi lista"] = "加入我的清單",
	["Agregar a mi ruta"] = "加入我的路線",
	["Agregar lo que me falta"] = "加入我缺的東西",
	["Agregar todo a mi lista"] = "全部加入我的清單",
	["Agregar un tramo:"] = "新增路段：",
	["Agregar una meta"] = "新增目標",
	["Agregué %s ×%d a tu lista."] = "已把 %s ×%d 加入你的清單。",
	["Agregué lo que falta para %s"] = "已加入 %s 所需的前置條件",
	["Agregué lo que te falta para subir %s. Lo ves en Comercio."] = "已把提升 %s 還缺的東西加入清單。你會在交易裡看到。",
	["Agrégale una en Mis planes."] = "在「我的計畫」中新增一個。",
	["Agrégale uno en la página Ruta."] = "在「路線」頁面新增一個。",
	["Agua"] = "水體",
	["Agua de manantial refrescante"] = "清涼的泉水",
	["Agua y comida"] = "水和食物",
	["Agua: llevas %d (mejor %d o más). A tu nivel: %s"] = "水：你帶了 %d 個（最好 %d 個以上）。適合你等級的：%s",
	["Aguante"] = "耐力",
	["Aguas conocidas"] = "已知水域",
	["Ahora"] = "現在",
	["Ahora corre más que la manada. ¡Auuu!"] = "現在他跑得比狼群還快了。嗷嗚！",
	["Ahora estás en la %s. Ya puedes salir del grupo: el plano se queda contigo."] = "你現在在%s。你可以離開隊伍了：位面會保留。",
	["Ahora ganas la XP normal"] = "現在獲得的是一般經驗值",
	["Ahora mismo te ayudaría con"] = "現在我可以幫你",
	["Ahora no"] = "現在不要",
	["Ahora no hay nada de Alfa a la vista para mover. Abre tu guía, la pesca o Lya y vuelve a entrar."] = "現在畫面上沒有可以移動的 Alfa 元素。打開你的指南、釣魚或 Lya 後再進來。",
	["Ahora no pude armar el camino a esta misión."] = "現在無法建立前往這個任務的路線。",
	["Ahora no sale: Alfa busca cómo unirse a la manada."] = "目前未傳送：Alfa 正在尋找連接狼群的方式。",
	["Ahora no se puede"] = "現在無法進行",
	["Ahora no se puede anunciar"] = "現在無法通報",
	["Ahora no se puede avisar a la manada. Inténtalo en un momento."] = "現在無法通知狼群。稍後再試。",
	["Ahora no se puede hablar con la manada. Prueba en un rato."] = "現在聯絡不上狼群。過一會兒再試。",
	["Ahora no se puede llamar a la manada: Alfa busca cómo unirse a ella."] = "現在無法呼喚狼群：Alfa 正在尋找加入的方法。",
	["Ahora no se pueden enviar mensajes (en una instancia o con una cuenta de prueba). %s"] = "現在無法傳送訊息（在副本中或使用試玩帳號）。%s",
	["Ahora toca la colección: completa tu diario, los logros y prueba el concurso de los domingos."] = "接下來就是收集了：填滿你的圖鑑、完成成就，再去試試週日的釣魚大賽。",
	["Ahora usan: %s. Activa los pesos de %s para que Alfa compare el equipo como lo pide tu build."] = "目前使用：%s。啟用%s的權重，讓 Alfa 依你的配點需求比較裝備。",
	["Ahora va por el canal oculto de Alfa."] = "現在透過 Alfa 的隱藏頻道傳送。",
	["Ahora va por tu hermandad: el canal oculto de Alfa no está disponible, así que solo te ven quienes comparten en tu hermandad."] = "現在透過你的公會傳送：Alfa 的隱藏頻道無法使用，所以只有公會中分享位置的人看得到你。",
	["Ahora vas a: %s"] = "現在前往：%s",
	["Ahora · %s"] = "現在 · %s",
	["Ahora: %d %% del nivel %d"] = "現在：%d %%（%d 級）",
	["Ahora: %s"] = "目前：%s",
	["Ahora: %s · De fábrica: %s"] = "目前：%s · 預設：%s",
	["Ahora: %s."] = "現在：%s。",
	["Ahí no hay ninguna zona: pon el marcador sobre tierra."] = "那裡沒有任何地區：請把標記放在陸地上。",
	["Ahí no se puede poner la flecha."] = "無法在那裡設定箭頭。",
	["Ahí nos organizamos para todo. Haz clic en el enlace y cópialo con Ctrl+C."] = "我們在那裡安排所有活動。點擊連結後用 Ctrl+C 複製。",
	["Ajustar"] = "調整",
	["Ajustar los avisos"] = "調整提醒",
	["Ajustes"] = "設定",
	["Ajustes de Alfa en todos los idiomas: las fechas en el orden de cada uno y los nombres de cada especialización bien puestos."] = "所有語言的 Alfa 調整：日期依各語言的順序顯示，每個專精的名稱都正確。",
	["Ajustes de Bolsas"] = "背包設定",
	["Ajustes de Lya"] = "Lya 設定",
	["Ajustes de mazmorras"] = "地城設定",
	["Ajustes de pesca"] = "釣魚設定",
	["Ajustes del mapa"] = "地圖設定",
	["Ajustes del medidor"] = "傷害統計設定",
	["Ajustes en orden: Comodidades y Calidad de vida son una sola página con pestañas, y todo lo de misiones vive en Ajustes > Misiones. Tu configuración se mudó sola, sin perder nada."] = "設定更有條理：便利功能和生活品質合併為一個帶分頁的頁面，所有任務相關設定都在「設定 > 任務」中。你的設定已自動遷移，什麼都沒丟。",
	["Ajustes importados"] = "設定已匯入",
	["Al abrir el buzón, un aviso si una carta con objetos vence en menos de 3 días."] = "開啟信箱時，如果有附物品的郵件將在 3 天內到期，會提醒你。",
	["Al abrirse el mapa de vuelo, vuela al destino que marca tu ruta."] = "開啟飛行地圖時，飛往你路線標記的目的地。",
	["Al acercar o cargar el mapa, cada parte aparece completa de una vez, sin cuadritos sueltos."] = "放大或載入地圖時，每個部分都會一次完整出現，不再有零散的小方塊。",
	["Al acercar se ven las montañas y el relieve, igual que en el minimapa. Apagado: el mapa pintado del juego."] = "放大後可以看到山脈與地形，與小地圖一樣。關閉：使用遊戲的手繪地圖。",
	["Al armar tus rutas, Alfa deja fuera las que piden élites."] = "建立路線時，Alfa 會排除需要對付精英的任務。",
	["Al banco (%d)"] = "存入銀行（%d）",
	["Al cambiar de forma o de actitud, el juego usa otra barra de abajo. Si está vacía, Alfa te avisa una vez y puede llenar sus casillas vacías con las habilidades de esa forma que ya sabes, fuera de combate y sin tocar lo que ya tienes."] = "切換形態或姿態時，遊戲會改用下方的另一條快捷列。如果它是空的，Alfa 會提醒你一次，並可在戰鬥外用你已學會的該形態技能填滿它的空格，不會動到你已經放好的東西。",
	["Al cambiar de forma, el juego cambia tu barra de abajo por la de esa forma, y esta todavía no tiene nada: por eso parece que desaparece. Alfa puede poner en sus casillas vacías las habilidades de esa forma que ya sabes."] = "切換形態時，遊戲會把你下方的快捷列換成該形態的快捷列，而它目前還是空的：所以看起來像是消失了。Alfa 可以把你已學會的該形態技能放進它的空格。",
	["Al comerciante"] = "賣給商人",
	["Al comparar objetos, Alfa valora más lo que pide %s: lo de arriba en la lista de estadísticas."] = "比較物品時，Alfa 會更重視%s需要的屬性：也就是屬性清單上方的那些。",
	["Al completar una misión vuelve a salir en el chat: «[Misión] está lista para entregar» y, al entregarla, «¡Misión completada!». En grupo lo ve todo el grupo; solo, tú."] = "完成任務會再次顯示在聊天中：「[任務] 可以交付了」，交付時「任務完成！」。組隊時全隊可見；單人時只有你看到。",
	["Al completar una misión vuelve a salir en tu chat: «[Misión] está lista para entregar» y «¡Misión completada!». Si lo prendes, también tu grupo lo ve."] = "完成任務會再次顯示在你的聊天框：「[任務] 可以交付了」和「任務完成！」。打開後隊伍也看得到。",
	["Al curar con un clic, ese compañero queda seleccionado para tus otros poderes."] = "點擊治療時，那名隊友會被選取，方便使用你的其他技能。",
	["Al día"] = "已分配完",
	["Al elegir un build, las flechas de mejora de tus bolsas valoran lo que ese build necesita."] = "選擇配點後，背包中的提升箭頭會依該配點的需求評估。",
	["Al empezar aturde a quien lo despertó en el altar: es normal."] = "戰鬥開始時，他會擊昏在祭壇喚醒他的人：這是正常的。",
	["Al enemigo le queda poca vida: Quemadura de las Sombras lo remata."] = "敵人生命力很低：暗影灼燒可以終結它。",
	["Al enemigo le queda poca vida: remátalo al instante."] = "敵人生命力很低：立刻終結它。",
	["Al enemigo le queda poca vida: remátalo."] = "敵人生命值很低：補上最後一擊。",
	["Al entrar a una mazmorra, Lya te da un consejo corto y un botón para verla. Nunca en combate."] = "進入地城時，莉婭會給你一條簡短的建議和一個查看按鈕。戰鬥中絕不打擾。",
	["Al entrar a una zona con enemigos muy arriba de tu nivel, un aviso corto (una vez por zona)."] = "進入敵人等級遠高於你的區域時，給一則簡短提醒（每個區域一次）。",
	["Al entrar al juego, Lya te dice quién de tu hermandad anda conectado y dónde."] = "登入遊戲時，莉婭會告訴你公會裡誰在線上、在哪裡。",
	["Al entrar o al juntarse tu grupo reviso tu equipo, tus bolsas, tu comida y lo de tu clase. Si falta algo te digo qué y te llevo a conseguirlo. También con /alfa listo."] = "你進去或隊伍滿員時，我會檢查你的裝備、背包、食物和職業材料。缺什麼我會告訴你，並帶你去買。也可以用 /alfa listo。",
	["Al entrar o al juntarse tu grupo: equipo, bolsas, comida, agua, munición y lo de tu clase. Nunca en combate."] = "進入時或隊伍滿員時：裝備、背包、食物、水、彈藥和職業材料。戰鬥中絕不會。",
	["Al entregar una misión, Lya te ofrece contarte cómo terminó."] = "交付任務時，Lya 會提議跟你說說它的結局。",
	["Al final de la Tercera Guerra, Arthas subió al Trono Helado, se puso el yelmo y se volvió uno con el Rey Exánime."] = "第三次戰爭結束時，阿薩斯登上冰封王座，戴上頭盔，與巫妖王合而為一。",
	["Al final de la pelea se enfurece y pega más rápido: guarda curación para ese momento."] = "戰鬥接近尾聲時他會狂怒，攻擊變得更快：留一些治療到那個時候。",
	["Al final se enfurece: guarden su mejor daño para el final."] = "她在最後會狂怒：把最強的輸出留到最後。",
	["Al final, habla con el Discípulo de Naralex y protégelo mientras camina: así aparece el último jefe."] = "最後，和納拉雷克斯的信徒交談並在他行走時保護他：這樣最後一個首領才會出現。",
	["Al hablar con el maestro de vuelo, abre su mapa directamente."] = "與飛行管理員交談時，直接開啟其地圖。",
	["Al hablar con quien da una misión de tu ruta, se acepta sola."] = "與發放你路線上任務的人交談時，任務會自動接受。",
	["Al hablar con quien da una misión de tu ruta, se acepta sola. Mayús la deja para ti."] = "與提供你路線上任務的人交談時，會自動接受。按住 Shift 則由你自己決定。",
	["Al hablar con un PNJ"] = "與 NPC 交談時",
	["Al hablar con un banquero se abre el banco de Alfa, con depositar rápido. La primera visita de cada personaje muestra el del juego: así recibe su primera pestaña."] = "與銀行職員交談時會開啟 Alfa 的銀行，可快速存放。每個角色第一次造訪時會顯示遊戲內建的銀行：這樣才能取得第一個分頁。",
	["Al hurtar a los humanoides ganas monedas y a veces cajas cerradas."] = "對人型生物偷竊可以得到錢幣，有時還有上鎖的箱子。",
	["Al invitar a una comunidad ya no sale el aviso de bloqueo: Alfa te deja el nombre listo para copiar y te abre la ventana. A tu hermandad, un clic como antes."] = "邀請加入社群時不再出現阻擋警告：Alfa 會準備好要複製的名字並為你打開視窗。邀請加入公會仍然一鍵完成。",
	["Al llegar a una ciudad o posada. También repite la nota de entrenar de la guía cuando su ventana está oculta."] = "抵達城鎮或旅店時提醒。指南視窗隱藏時，也會重複指南的訓練提示。",
	["Al llegar a una zona con una mazmorra para tu nivel, Lya te dice quién de la manada anda cerca y va a tu nivel, con «Invitar»."] = "到達有適合你等級地城的區域時，莉婭會告訴你狼群裡誰在附近且和你等級相近，並附「邀請」按鈕。",
	["Al llegar a una zona con una mazmorra para tu nivel, te digo quién de la manada anda cerca y va a tu nivel, con «Invitar»."] = "到達有適合你等級地城的區域時，我會告訴你狼群裡誰在附近且和你等級相近，並附「邀請」按鈕。",
	["Al llegar en barco o al encontrar un raro, un anuncio grande con animación, como la intro."] = "搭船抵達或發現稀有怪時，會有像開場動畫一樣的大型動畫通知。",
	["Al llegar en barco o cuando Lya encuentra un raro, un anuncio grande con animación, como la intro, en vez de una tarjeta."] = "搭船抵達或莉婭發現稀有怪時，顯示像開場動畫那樣的大型動態公告，而不是卡片。",
	["Al morir aparecen cuatro abisarios que caminan juntos por el patio: prepárense para pelear con varios."] = "他死後會出現四個虛空行者，一起走過庭院：準備好同時對付好幾個。",
	["Al morir en un campo de batalla, liberas tu espíritu al momento."] = "在戰場中死亡時，立即釋放靈魂。",
	["Al morir llegan muchos aprendices: prepárense para muchos enemigos a la vez."] = "他死後會湧入許多學徒：準備好同時面對大量敵人。",
	["Al moverte, la tecla vuelve a la normal"] = "移動時，按鍵恢復原本功能",
	["Al moverte, solo de lado"] = "移動時只左右平移",
	["Al norte de estas montañas están las Estepas Ardientes y la Montaña Roca Negra, de donde salen los orcos que amenazan Villa del Lago."] = "這些山脈的北邊是燃燒平原與黑石山，威脅湖畔鎮的獸人就是從那裡來的。",
	["Al objetivo le queda poca vida: Ejecutar lo remata usando tu ira."] = "目標生命值很低：用斬殺消耗怒氣終結它。",
	["Al objetivo le queda poca vida: el martillo lo remata a distancia."] = "目標生命值很低：憤怒之錘可在遠處終結它。",
	["Al pasar el ratón por un objeto: «Tienes 12 (Lobato: 7 en bolsas, Alt: 5 en banco)», con todos tus personajes."] = "滑鼠移到物品上時顯示：「你有 12 個（Lobato：背包 7、Alt：銀行 5）」，涵蓋你所有的角色。",
	["Al pasar el ratón sobre un objeto: su precio en la subasta, lo que paga el comerciante y qué te conviene."] = "滑鼠移到物品上時顯示：拍賣價格、商人收購價，以及怎麼處理最划算。",
	["Al pie de Cima del Trueno está el poblado Pezuña de Sangre, donde Baine, el hijo de Cairne, cuida a su gente."] = "雷霆崖腳下是血蹄村，凱恩的兒子貝恩在那裡照顧他的族人。",
	["Al poner algo a la venta en la subasta: su precio sugerido, su historial de 14 días y un aviso si lo das muy barato."] = "在拍賣場上架物品時：顯示建議價格、14 天的價格紀錄，賣太便宜時還會提醒你。",
	["Al recibir daño suelta pedazos más pequeños: mátenlos con ataques en área."] = "它受到傷害時會碎裂出較小的碎片：用範圍攻擊清掉它們。",
	["Al sacar algo"] = "釣到東西時",
	["Al salir de una mazmorra"] = "離開地城時",
	["Al seguir, Alfa se recarga para cambiar el idioma y esta configuración sigue donde la dejaste."] = "繼續後，Alfa 會重新載入以切換語言，本設定會從你離開的地方繼續。",
	["Al subir de nivel (y al entrar, si te quedan puntos), un aviso dice qué talento poner, con el botón para aplicarlo."] = "升級時（以及登入時若還有未分配點數），會提示該點哪個天賦，並附套用按鈕。",
	["Al subir de nivel te muestra qué aprender y cuánto cuesta."] = "升級時顯示可以學什麼、要花多少錢。",
	["Al subir de nivel, un aviso dice qué aprender, cuánto cuesta y con qué entrenador, con el botón Llévame."] = "升級時，會提示該學什麼、多少錢、找哪位訓練師，並附「帶我去」按鈕。",
	["Al sur de Cuna del Invierno, una garganta escondida está llena de demonios."] = "冬泉谷南邊有一道隱蔽的峽谷，裡面滿是惡魔。",
	["Al sur de Los Baldíos, el Gran Elevador baja hasta Las Mil Agujas. ¡No mires hacia abajo!"] = "在貧瘠之地南部，大升降梯一路降到千針石林。別往下看！",
	["Al sur está Dalaran, la ciudad de los magos. Archimonde la arrasó en la Tercera Guerra, y sus magos la reconstruyen protegidos bajo una cúpula."] = "南邊是法師之城達拉然。阿克蒙德在第三次戰爭中摧毀了它，法師們正在一座護罩下重建它。",
	["Al sur se alza una muralla enorme: el rey Genn Cringris la levantó para aislar Gilneas del resto del mundo."] = "南邊聳立著一道巨大的城牆：吉恩·葛雷邁恩國王建起它，把吉爾尼斯與世界其他地方隔絕開來。",
	["Al terminar una guía de nivel, carga la siguiente sin preguntar."] = "完成一份升級指南後，不詢問直接載入下一份。",
	["Al terminar una guía, la que sigue para tu nivel a un clic."] = "完成一個指南後，下一個適合你等級的指南一鍵可達。",
	["Al terminar una pelea, Alfa te deja una tarjeta pequeña con cuánto duró, tu daño y tu curación por segundo y lo que más te pegó. Usa el medidor oficial del juego y solo cuenta lo tuyo."] = "戰鬥結束後，Alfa 會留給你一張小卡片：戰鬥持續了多久、你的每秒傷害和每秒治療，以及打你最痛的東西。使用遊戲官方的統計，只計算你自己的。",
	["Al terminar una pelea, aquí queda su resumen: tu daño, tu curación y lo que más te pegó."] = "戰鬥結束後，這裡會留下總結：你的傷害、你的治療和打你最痛的東西。",
	["Al terminar: cuánto duró, tu daño y tu curación por segundo y lo que más te pegó."] = "結束時：持續了多久、你的每秒傷害和每秒治療，以及打你最痛的東西。",
	["Al terminarla, te propongo la siguiente para tu nivel. Un clic en «Seguir con…» y seguimos de caza."] = "完成後，我會推薦下一個適合你等級的指南。點一下「繼續…」，我們接著狩獵。",
	["Al tomar una misión te la resumo en dos líneas, a mi modo: qué hay que hacer y un consejito. La historia completa sigue en «Historias»."] = "你接任務時，我會用我的方式兩行總結：要做什麼，再加一個小建議。完整的故事還在「故事」裡。",
	["Al tomar una misión, Lya te la resume en dos líneas: qué hay que hacer y un consejito suyo."] = "你接任務時，莉婭會用兩行總結：要做什麼，再加她的一個小建議。",
	["Al volver con una misión lista, se entrega sola. Si hay recompensas para elegir, eliges tú."] = "帶著完成的任務回來時會自動交付。如果有獎勵可選，由你來選。",
	["Alamuerte forjó en secreto el Alma de Demonio, un disco dorado cargado con el poder de los demás Aspectos, que se lo dieron sin saber para qué lo quería."] = "死亡之翼秘密鑄造了惡魔之魂，那是一個蘊含其他守護巨龍力量的金色圓盤，牠們給了他力量，卻不知道他想拿它做什麼。",
	["Alamuerte se hizo pasar por Lord Daval Prestor, un noble que casi llegó a rey de Alterac. ¡A esa familia le encantan los disfraces!"] = "死亡之翼曾假扮成達瓦爾·普瑞斯托領主，這位貴族差點當上奧特蘭克國王。那一家子可真愛喬裝打扮！",
	["Alcance de las sombras"] = "陰影距離",
	["Alcanza para %d"] = "夠做 %d 份",
	["Alejar"] = "縮小",
	["Alejar la cámara"] = "鏡頭最遠距離",
	["Alejar más la cámara"] = "鏡頭拉得更遠",
	["Alertas"] = "警示",
	["Alexandros Mograine empuñaba la Crematoria, y la Plaga le temía como a nadie. Lo traicionó su propio hijo, Renault."] = "亞歷山德羅·莫格萊尼手持灰燼使者，天譴軍團對他的畏懼無人能及。背叛他的是他的親生兒子雷諾。",
	["Alfa"] = "Alfa",
	["Alfa %s ya está aquí"] = "Alfa %s 來了",
	["Alfa %s · cliente %s (%s) · %s · Alfa en %s"] = "Alfa %s · 用戶端 %s（%s）· %s · Alfa 語言：%s",
	["Alfa (el de siempre), Clásico WoW (marcos y letras del juego), Cristal (transparente), La Jauría nocturno (azul de noche y plata de luna) o Fogata (carbón y brasas). El modo compacto y tus colores funcionan en todos."] = "Alfa（熟悉的那款）、經典 WoW（遊戲的框架和字型）、玻璃（透明）、La Jauría 夜色（夜空藍和月光銀）或營火（炭黑與餘燼）。精簡模式和你的顏色在所有風格中都能用。",
	["Alfa (el estilo propio, por omisión), Clásico WoW (marcos y letras del juego) o Cristal (transparente, con el acento que elijas). El modo compacto y tus colores funcionan en los tres."] = "Alfa（專屬風格，預設）、經典 WoW（遊戲的框架與字型）或玻璃（透明，搭配你選擇的強調色）。精簡模式與你的顏色在三種風格中都能使用。",
	["Alfa arma el reporte y tú lo pegas en el buzón privado del Discord de La Jauría. También con /alfa reportar."] = "Alfa 會產生回報內容，你把它貼到 La Jauría Discord 的私人信箱。也可以用 /alfa reportar。",
	["Alfa arma la ruta más corta para cobrarlas, junta por PNJ. La flecha usa vuelos y tu piedra de hogar cuando conviene, y te avisa si una entrega queda lejos."] = "Alfa 會規劃交付它們的最短路線，依 NPC 分組。箭頭會在划算時使用飛行與爐石，並在交付點很遠時提醒你。",
	["Alfa atrapó errores"] = "Alfa 捕捉到錯誤",
	["Alfa borrará lo que guardó de %s: sus bolsas, su banco, su equipo y sus recetas de Comercio. Si vuelves a jugar con él, se guarda de nuevo."] = "Alfa 會刪除為 %s 儲存的資料：背包、銀行、裝備以及交易中的配方。再次用該角色遊玩時會重新儲存。",
	["Alfa completo"] = "完整 Alfa",
	["Alfa de La Jauría"] = "La Jauría 的阿爾法",
	["Alfa elige las misiones que más XP dan cerca de ti, en tres tandas."] = "Alfa 會分三批選出你附近經驗最多的任務。",
	["Alfa elige por ti: entregar las que tienes listas, cerrar las de esta zona o recoger misiones nuevas."] = "Alfa 替你選：交付已完成的任務、完成本區域的任務，或接新任務。",
	["Alfa elige todo: misiones ordenadas por XP por distancia y tus misiones de clase."] = "Alfa 會幫你挑好一切：依經驗值與距離的效率排序的任務，以及你的職業任務。",
	["Alfa es la %s, pero estas son de otra: %s. Reinstala Alfa completo para que todo sea de la misma."] = "Alfa 是 %s，但這些來自其他版本：%s。重新安裝整個 Alfa，讓一切保持一致。",
	["Alfa es un addon que toxic3000 creó para sus amigos y quiso compartir con todos."] = "Alfa 是 toxic3000 為朋友們製作的插件，他也想把它分享給所有人。",
	["Alfa estable: en orden y en manada"] = "穩定版 Alfa：井然有序，結伴同行",
	["Alfa está armando tu ruta..."] = "Alfa 正在建立你的路線...",
	["Alfa está eligiendo..."] = "Alfa 正在挑選...",
	["Alfa está leyendo tu clase"] = "Alfa 正在讀取你的職業",
	["Alfa está oculto: clic para mostrarlo y abrir su ventana"] = "Alfa 已隱藏：點擊以顯示並開啟其視窗",
	["Alfa guarda una copia de tus ajustes y perfiles cada semana y antes de cada actualización. Quedan las últimas 3."] = "Alfa 每週以及每次更新前都會保存一份你的設定和設定檔。保留最近 3 份。",
	["Alfa guarda unos %.1f MB. Es mucho: el juego tarda más en entrar. Lo que más pesa: %s."] = "Alfa 儲存了約 %.1f MB 資料。這很多：遊戲登入會變慢。最大的部分：%s。",
	["Alfa guarda unos %.1f MB. Todo bien."] = "Alfa 儲存了約 %.1f MB 資料。一切正常。",
	["Alfa junta tus misiones y las de aquí y busca el camino más corto."] = "Alfa 會把你的任務和這裡的任務集合起來，找出最短的路線。",
	["Alfa la vuelve a poner al entrar."] = "登入時 Alfa 會重新套用它。",
	["Alfa las ordena por el camino más corto y te lleva de una en una."] = "Alfa 按最短路線排序，帶你逐一去交。",
	["Alfa le agregó lo que ayuda a arreglarlo: versiones, idioma, tu clase y nivel y dónde estás. No lleva tu nombre ni tu reino."] = "Alfa 附上了有助於修正的資訊：版本、語言、你的職業與等級，以及你所在的位置。不包含你的名字和伺服器。",
	["Alfa lee el medidor oficial del juego. Enciéndelo y aquí verás el daño de tu grupo; su ventana puedes ocultarla en el Modo de edición."] = "Alfa 讀取遊戲官方的傷害統計。開啟後，這裡會顯示你隊伍的傷害；它的視窗可以在編輯模式中隱藏。",
	["Alfa lo creó toxic3000 para sus amigos y quiso compartirlo con todos. No juega por ti: te ayuda a entender y disfrutar el juego a tu ritmo."] = "toxic3000 為朋友們做了 Alfa，又想分享給所有人。它不替你玩：它幫你照自己的節奏理解並享受遊戲。",
	["Alfa lo hace por ti"] = "Alfa 幫你做",
	["Alfa lo hace toxic3000 para La Jauría. Es software libre (GPL-3.0) y su código está en github.com/toxic3000/alfa-forever."] = "Alfa 由 toxic3000 為 La Jauría 製作。它是自由軟體（GPL-3.0），原始碼位於 github.com/toxic3000/alfa-forever。",
	["Alfa los cambia por el rango nuevo sin moverlos de lugar."] = "Alfa 會把它們換成新等級，位置不變。",
	["Alfa mantiene %d ajustes que elegiste. Abre la ventana para ver o cambiar cada uno."] = "Alfa 保留了你選擇的 %d 項設定。開啟視窗即可查看或變更每一項。",
	["Alfa mantiene %d ajustes tuyos y los vuelve a poner al entrar."] = "Alfa 保留了你的 %d 項設定，並在登入時重新套用。",
	["Alfa mide los caminos (vuelos y piedra de hogar): tarda unos segundos."] = "Alfa 正在計算路程（飛行與爐石）：需要幾秒鐘。",
	["Alfa nació en La Jauría, la comunidad de Toxic (toxic3000) en WoW Forever: un solo addon con todo lo que la manada necesita para jugar, con un solo estilo."] = "Alfa 誕生於 La Jauría，Toxic（toxic3000）在 WoW Forever 的社群：一個插件，裝下狼群遊戲所需的一切，風格一致。",
	["Alfa no está afiliado a esos proyectos ni ellos lo respaldan; gracias a todos por compartir su trabajo."] = "Alfa 與這些專案沒有關聯，也未獲得其背書；感謝大家分享自己的成果。",
	["Alfa no ha cambiado nada todavía. Prueba «Paisaje de la manada» o abre la ventana para ver los ajustes que el menú del juego no enseña."] = "Alfa 還沒有變更任何東西。試試「狼群風景」，或開啟視窗查看遊戲選單裡沒有的設定。",
	["Alfa no pudo armar el camino a %s. Míralo en la Enciclopedia."] = "Alfa 無法規劃前往%s的路線。請在百科中查看。",
	["Alfa no sabe dónde estás (en una instancia no hay notas)."] = "Alfa 不知道你在哪（副本裡沒有筆記）。",
	["Alfa no sabe en qué zona estás."] = "Alfa 不知道你在哪個區域。",
	["Alfa no tiene datos de esto todavía."] = "Alfa 還沒有這方面的資料。",
	["Alfa no tiene el instructor de tu raza: busca «equitación» en PNJ."] = "Alfa 不知道你種族的訓練師：在 NPC 中搜尋「騎術」。",
	["Alfa no toma misiones que no sirven a tu ruta, ni las entrega solas. Lo respeta también «todas las misiones» de Comodidades."] = "Alfa 不會接受對你路線無用的任務，也不會自動交付它們。便利功能中的「所有任務」也會遵守這一點。",
	["Alfa no toma misiones que no sirven a tu ruta, ni las entrega solas. Lo respeta también «todas las misiones»."] = "Alfa 不會接受你的路線用不到的任務，也不會自己交付。「所有任務」同樣遵守這一點。",
	["Alfa no toma misiones que no sirven a tu ruta. Tu registro queda limpio."] = "Alfa 不會接對你路線沒用的任務。你的任務日誌保持整潔。",
	["Alfa nunca apaga otros addons: eso lo decides tú en tu lista de addons."] = "Alfa 從不關閉其他插件：這由你在插件清單裡決定。",
	["Alfa ordena las paradas para que no camines de más. Tarda unos segundos y no traba el juego."] = "Alfa 會安排站點順序，讓你不多走冤枉路。需要幾秒鐘，不會卡住遊戲。",
	["Alfa recuerda cuándo cayó cada raro: su cuadro dice hace cuánto lo cazaron y si pudo volver ya."] = "Alfa 記得每隻稀有怪何時倒下：它的滑鼠提示會顯示多久前被擊殺，以及是否可能已重生。",
	["Alfa recuerda lo que llevabas antes de ponerte lo de pesca y te lo vuelve a poner."] = "Alfa 會記住你換上釣魚裝備前穿的東西，並幫你換回來。",
	["Alfa revisa lo que elegiste cuando el juego termina de cargar. Si los cambias en el menú del juego, se queda con lo nuevo."] = "遊戲載入完成時，Alfa 會檢查你的選擇。如果你在遊戲選單中變更了它們，就保留新的設定。",
	["Alfa revisa su base de objetos sin trabar el juego. Tarda unos segundos la primera vez."] = "Alfa 會在不卡住遊戲的情況下檢查物品資料庫。第一次需要幾秒鐘。",
	["Alfa revisa su base de objetos, se queda con lo que tu clase puede usar cerca de tu nivel y lo compara con lo que llevas, con los pesos de tu build."] = "Alfa 會檢查物品資料庫，留下你的職業在你等級附近能用的物品，並依你配點的權重與身上的裝備比較。",
	["Alfa se encarga de lo repetitivo (aceptar, entregar, vender, reparar) y te pregunta en los cruces del camino."] = "Alfa 負責重複的事（接、交、賣、修），在每個岔路口問你。",
	["Alfa se está uniendo al canal oculto de La Jauría. En unos segundos ves a quien comparte."] = "Alfa 正在加入 La Jauría 的隱藏頻道。幾秒後就能看到正在分享的人。",
	["Alfa se muestra en el idioma que elijas, aunque tu juego esté en otro."] = "即使遊戲是其他語言，Alfa 也會以你選擇的語言顯示。",
	["Alfa se recarga para cambiar el idioma. La configuración sigue donde la dejaste."] = "Alfa 正在重新載入以切換語言。設定會從你離開的地方繼續。",
	["Alfa sencillo"] = "簡潔 Alfa",
	["Alfa solo leyó tus valores: nada cambia hasta que toques un control."] = "Alfa 只讀取了你的數值：在你調整某個控制項之前，什麼都不會改變。",
	["Alfa solo te sugiere: el precio lo pones tú."] = "Alfa 只提供建議：價格由你決定。",
	["Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus recargas, los efectos que el juego activa y la vida del enemigo cuando se puede leer. Con varios enemigos cambia a las de área. Tú decides qué presionar."] = "Alfa 依其針對%s的優先順序給出建議，只讀取你的角色：你的資源、冷卻、遊戲觸發的效果，以及可讀取時的敵人生命力。敵人多時會切換為範圍技能。按什麼由你決定。",
	["Alfa tampoco tiene todavía una prioridad para tu clase con lo que sabes. Los avisos de reacción y el medidor sí funcionan."] = "Alfa 也還沒有針對你的職業與已學技能的優先順序。反應提醒與傷害統計仍可使用。",
	["Alfa te avisa aquí de lo importante: equipo por reparar, bolsas llenas, habilidades nuevas, tu buff y tu descanso."] = "Alfa 會在這裡提醒你重要的事：需要修理的裝備、背包已滿、新技能、你的增益效果與休息狀態。",
	["Alfa te avisa del equipo gastado, las bolsas llenas, lo que puedes entrenar, tu buff y tu descanso. Aquí eliges cuáles y cuándo."] = "Alfa 會提醒你裝備磨損、背包已滿、可訓練的技能、你的增益效果與休息狀態。在這裡選擇提醒哪些以及何時提醒。",
	["Alfa te avisa del equipo gastado, las bolsas llenas, lo que puedes entrenar, tu buff, tu descanso, tu comida y lo que te falta para una mazmorra. Aquí eliges cuáles y cuándo."] = "Alfa 會提醒你裝備磨損、背包滿了、能訓練的技能、你的增益、休息、食物以及去地城還缺什麼。在這裡選擇提醒哪些、什麼時候提醒。",
	["Alfa te guía con la flecha y te avisa, pero tú aceptas, entregas, eliges y viajas. Lo mínimo: vender lo gris y reparar."] = "Alfa 用箭頭帶路並提醒你，但接、交、選、走都由你。最少：賣灰色物品和修理。",
	["Alfa te lleva paso a paso, con la flecha y la ruta en el mapa. Elige la de tu zona y tu nivel."] = "Alfa 會用箭頭和地圖上的路線一步步帶你。請選擇適合你所在地區與等級的指南。",
	["Alfa te recomienda: %s"] = "Alfa 推薦：%s",
	["Alfa tiene muchas páginas, ¿se puede más sencillo?"] = "Alfa 頁面好多，能更簡單一點嗎？",
	["Alfa todavía no tiene builds para tu clase"] = "Alfa 還沒有適合你職業的配點",
	["Alfa usa %.1f MB de memoria ahora. Lo que más usa:"] = "Alfa 現在使用 %.1f MB 記憶體。用得最多的是：",
	["Alfa usa código y datos de estos proyectos libres, con sus avisos de autor y sus licencias incluidos en cada carpeta:"] = "Alfa 使用了以下自由專案的程式碼與資料，每個資料夾中都附有其著作權聲明與授權條款：",
	["Alfa vuelve a elegir desde donde estás ahora (las misiones fijas se quedan)."] = "Alfa 會從你目前的位置重新挑選（已釘選的任務會保留）。",
	["Alfa ya no se pone encima de %s. %s sigue como estaba."] = "Alfa 不再妨礙 %s 了。%s 維持原樣。",
	["Alfa · Top %d de %s (%s%s)"] = "Alfa · 前 %d 名 %s（%s%s）",
	["Alfa, Clásico WoW o Cristal, la flecha del lobo y el aullido."] = "Alfa、經典 WoW 或玻璃風格，狼形箭頭與狼嚎。",
	["Alfa: agregar a Cerrar mis misiones"] = "Alfa：加入「完成我的任務」",
	["Alfa: capas del mapa"] = "Alfa：地圖圖層",
	["Alfa: cerrar mis misiones"] = "Alfa：完成我的任務",
	["Alfa: quitar de Cerrar mis misiones"] = "Alfa：從「完成我的任務」中移除",
	["Alfa: ver la cadena completa"] = "Alfa：查看完整任務鏈",
	["Alfa_Codex está apagado en la lista de addons."] = "Alfa_Codex 在插件清單中被停用了。",
	["Algo de Alfa no funciona, ¿qué reviso?"] = "Alfa 有地方不正常，我該檢查什麼？",
	["Algo importante pasa aquí; no te lo pierdas."] = "這裡會發生重要的事；別錯過了。",
	["Algo no anda bien en el árbol: los furbolgs que viven en él se están volviendo agresivos."] = "樹上出了點問題：住在上面的熊怪變得具有攻擊性了。",
	["Algunas cosas se ven completas al recargar."] = "有些內容重新載入後才會完整顯示。",
	["Algunas fórmulas de encantamiento muy buscadas caen de enemigos en las Tierras de la Peste."] = "一些搶手的附魔公式會從瘟疫之地的敵人身上掉落。",
	["Algunas recetas raras se compran a vendedores lejanos o caen de enemigos; vale la pena buscarlas."] = "有些稀有配方要向遠方的商人購買，或從敵人身上掉落；很值得去找。",
	["Algunos ajustes, como el HDR, se ven hasta reiniciar los gráficos. Te pide confirmación."] = "有些設定（例如 HDR）要重新啟動圖形後才能看到效果。會請你確認。",
	["Algunos ogros tienen dos cabezas, y no siempre se ponen de acuerdo entre ellas."] = "有些巨魔長著兩個腦袋，而且兩個腦袋不一定意見一致。",
	["Algunos orcos nunca siguieron a Thrall: los Roca Negra de la montaña sirven a los dragones negros."] = "有些獸人從未追隨索爾：山裡的黑石獸人效忠於黑龍。",
	["Alianza"] = "聯盟",
	["Alimenta a tu mascota: si está contenta pega más y te es más leal."] = "餵飽你的寵物：牠開心時打得更痛，也更忠誠。",
	["Alquimia"] = "鍊金術",
	["Alt"] = "Alt",
	["Alt+clic en un objeto abre su ficha"] = "Alt+點擊物品可開啟其詳細頁面",
	["Alta"] = "高",
	["Altas"] = "高",
	["Alto"] = "高度",
	["Alto [calidad]"] = "高",
	["Alto de las barras"] = "黑邊高度",
	["Altos"] = "高",
	["Ambiente mientras pescas"] = "釣魚時的環境音",
	["Amenaza"] = "仇恨",
	["Anasterian, el rey de los altos elfos, dejó la Alianza tras la Segunda Guerra, y murió frente a Arthas defendiendo la Fuente del Sol."] = "高等精靈之王安納斯特里安在第二次戰爭後退出了聯盟，後來在保衛太陽之井時死在阿薩斯面前。",
	["Ancho"] = "寬度",
	["Andan conectados: %s."] = "目前在線上：%s。",
	["Andorhal era el granero de Lordaeron. Kel'Thuzad repartió ahí grano apestado y la plaga se extendió por todo el reino."] = "安多哈爾曾是洛丹倫的糧倉。科爾蘇加德在那裡分發了染疫的穀物，瘟疫隨之蔓延整個王國。",
	["Anduin Lothar, el León de Azeroth, llevó a los refugiados de Ventormenta hasta Lordaeron y fue el primer comandante de la Alianza."] = "「艾澤拉斯之獅」安度因·洛薩帶領暴風城的難民前往洛丹倫，是聯盟的第一位統帥。",
	["Anillos"] = "戒指",
	["Animación anterior"] = "上一個動作",
	["Animación siguiente"] = "下一個動作",
	["Anisotrópico 16x"] = "16 倍非等向性",
	["Anisotrópico 2x"] = "2 倍非等向性",
	["Anisotrópico 4x"] = "4 倍非等向性",
	["Anisotrópico 8x"] = "8 倍非等向性",
	["Ankh"] = "十字章",
	["Anterior"] = "上一場",
	["Antes de %s te falta:"] = "進入 %s 之前你還需要：",
	["Antes de abandonarla"] = "放棄之前",
	["Antes de atacar, mira quién está cerca. Pelear con uno a la vez es más seguro."] = "攻擊之前，先看看附近有誰。一次只打一個比較安全。",
	["Antes de buscar la espada, Arthas mandó quemar sus propios barcos para que sus soldados no pudieran volver a casa."] = "在尋找那把劍之前，阿薩斯下令燒掉自己的船，讓士兵們無法回家。",
	["Antes de comprar algo en la subasta, revisa si un vendedor lo tiene más barato."] = "在拍賣場買東西之前，先看看商人是不是賣得更便宜。",
	["Antes de empezar, unas palabras de la manada."] = "開始之前，狼群有幾句話要說。",
	["Antes de entrar"] = "進入之前",
	["Antes de entregarla te falta: %s."] = "繳交前還差：%s。",
	["Antes de importar"] = "匯入之前",
	["Antes de irte: tienes %d misiones listas para entregar. ¿Pasamos a cobrarlas?"] = "走之前：你有 %d 個任務可以交付。去領獎勵嗎？",
	["Antes de irte: tienes una misión lista para entregar. ¿Pasamos a cobrarla?"] = "走之前：你有一個任務可以交付。去領獎勵嗎？",
	["Antes de la mazmorra te falta:"] = "進地城之前你還需要：",
	["Antes de pelear"] = "戰鬥之前",
	["Antes de pelear: abre con Piroexplosión, tu hechizo más fuerte."] = "戰鬥之前：用炎爆術開場，這是你最強的法術。",
	["Antes de restaurar"] = "還原之前",
	["Antes de salir de caza, configura Alfa a tu medida: el idioma, cómo se ve, qué hace sola por ti y si quieres que la manada te vea en el mapa del juego."] = "出發狩獵之前，依你的喜好設定 Alfa：語言、外觀、它能替你做什麼，以及是否讓狼群在遊戲地圖上看到你。",
	["Antes de una misión de élite o de grupo, un aviso con «Llamar a la manada»."] = "精英或組隊任務之前，會提醒你並附上「呼喚狼群」。",
	["Antes esto era un pantano. La magia del portal y la guerra lo dejaron rojo, seco y sin vida."] = "這裡以前是一片沼澤。傳送門的魔法與戰爭讓它變得赤紅、乾涸、毫無生機。",
	["Antes hay que hacer otra misión"] = "需要先完成另一個任務",
	["Antes necesitas"] = "前置條件",
	["Antes necesitas otra misión"] = "需要先完成另一個任務",
	["Antes pide %s (%s)"] = "前置：%s（%s）",
	["Antes que los elfos, los trols tuvieron grandes imperios en Azeroth, como el Amani en el norte y el Gurubashi en el sur."] = "在精靈之前，食人妖就在艾澤拉斯建立過偉大的帝國，例如北方的阿曼尼和南方的古拉巴什。",
	["Antes, el reino de Ventormenta se llamaba Azeroth, igual que el mundo; Ventormenta era solo el nombre de su capital."] = "暴風王國以前叫做艾澤拉斯，跟這個世界同名；暴風城只是它首都的名字。",
	["Antes: %s"] = "先完成：%s",
	["Antes: %s."] = "先完成：%s。",
	["Antes: %s. Ahora: %s."] = "之前：%s。現在：%s。",
	["Anunciar"] = "通報",
	["Anunciar en el chat"] = "在聊天中通報",
	["Anunciar en el grupo"] = "通報給隊伍",
	["Anuncios animados"] = "動態公告",
	["Anuncios animados y la manada a la vista"] = "動畫通知與身邊的狼群",
	["Apaga la viñeta, el grano, las barras y el tinte de un clic."] = "一鍵關閉暗角、顆粒、黑邊與色調。",
	["Apagada"] = "關閉",
	["Apagadas"] = "已關閉",
	["Apagado"] = "已關閉",
	["Apagado en los ajustes de abajo."] = "已在下方設定中關閉。",
	["Apagado, el grano se queda quieto."] = "關閉時，顆粒保持靜止。",
	["Apagado, solo las acepta y la entrega la haces tú."] = "關閉時只會接受任務，交付由你自己來。",
	["Apagados"] = "已關閉",
	["Apagar la parte de Alfa que choca"] = "關閉衝突的 Alfa 部分",
	["Apagarlo"] = "關閉",
	["Aparece al final del evento del Discípulo de Naralex: protege al druida mientras camina."] = "他會在納拉雷克斯的信徒事件結束時出現：在德魯伊行走時保護他。",
	["Aparece al tocar el gong por tercera vez, después de dos oleadas de arañas."] = "第三次敲響銅鑼時，他會在兩波蜘蛛之後出現。",
	["Aparece con una misión de la Horda (un objeto en el agua). Lanza escarcha."] = "要用部落的任務（水中的一個物件）才會出現。會施放冰霜法術。",
	["Aparece en cuanto termines la bienvenida de Alfa."] = "完成 Alfa 的歡迎設定後，她就會出現。",
	["Aparece en el evento de la explosivista: protégela mientras llegan oleadas de troggs."] = "他會在爆破專家的事件中出現：在一波波穴居人來襲時保護她。",
	["Aparecen marcos de ejemplo: arrástralos a donde los quieras y ajusta su tamaño. Así se verá tu grupo."] = "會出現範例框架：把它們拖到你想要的位置並調整大小。你的隊伍就會這樣顯示。",
	["Aplaudir"] = "鼓掌",
	["Aplica la nitidez de abajo aunque no uses el escalado de resolución."] = "即使不使用解析度縮放，也套用下方的銳利化。",
	["Aplicar"] = "套用",
	["Aplicar %d puntos"] = "套用 %d 點",
	["Aprende %s"] = "學習 %s",
	["Aprende Cocina con un instructor."] = "向訓練師學習烹飪。",
	["Aprende Cocina para encender fogatas."] = "學習烹飪才能點燃營火。",
	["Aprende Minería o Herboristería"] = "學習採礦或草藥學",
	["Aprende Pesca"] = "學習釣魚",
	["Aprende Pesca con un instructor"] = "向訓練師學習釣魚",
	["Aprende Pesca con un instructor de pesca y compra una caña: la guía te lleva."] = "向釣魚訓練師學習釣魚並買一根魚竿：指南會帶你去。",
	["Aprende Pesca con un instructor, compra una caña y pesca en tu zona de inicio o en la capital. Pide el rango Oficial desde 50."] = "向訓練師學習釣魚，買一根魚竿，然後在你的新手地區或主城釣魚。50 點起去學中級。",
	["Aprende equitación con %s"] = "向%s學習騎術",
	["Aprende las dos, consigue una caña y cocina lo que pescas hasta 75."] = "兩個都學，弄一根魚竿，把釣到的東西烹飪到 75。",
	["Aprender %s"] = "學習%s",
	["Aprender de tus búsquedas"] = "從你的搜尋中學習價格",
	["Aprender una profesión o llegar a un nivel en ella."] = "學習一項專業，或在該專業達到某個等級。",
	["Aprendiste %s. %s"] = "你學會了%s。%s",
	["Aprendiste un hechizo que le queda mejor a tus clics:"] = "你學會了一個更適合你點擊配置的法術：",
	["Aprendiz"] = "初級",
	["Aprendí un hechizo nuevo, ¿para qué sirve?"] = "我學會了新法術：它有什麼用？",
	["Apréndelos con el entrenador de tu clase, en cualquier capital."] = "向你的職業訓練師學習，任何主城都有。",
	["Apunto el primer día que te vi. Cada año, ese día, lo festejamos juntos. Y el 16 de noviembre es el cumpleaños de Alfa."] = "我記下了第一次見到你的那天。每年的那一天，我們都一起慶祝。11 月 16 日是 Alfa 的生日。",
	["Apágalo si no quieres que Alfa toque tus teclas, tu equipo ni tus ajustes al pescar."] = "如果不希望 Alfa 在釣魚時動到你的按鍵、裝備或設定，請關閉此選項。",
	["Aquí"] = "這裡",
	["Aquí adentro se caza en equipo: espera a que quien cura tenga maná antes de seguir."] = "這裡要團隊狩獵：等治療者有法力了再繼續。",
	["Aquí aparecerán los demás módulos de Alfa (bolsas, rutas, mundo y más) en cuanto estén instalados."] = "Alfa 的其他模組（背包、路線、世界等）安裝後就會出現在這裡。",
	["Aquí el juego no da tu posición (por ejemplo, dentro de una mazmorra)."] = "遊戲在這裡不提供你的位置（例如在地城內）。",
	["Aquí el juego no deja compartir nada. Al salir, tu rastro vuelve a salir solo."] = "遊戲在這裡不允許分享任何內容。離開後，你的蹤跡會自動恢復傳送。",
	["Aquí empieza tu historia. Y yo voy contigo."] = "你的故事從這裡開始。我和你一起走。",
	["Aquí estoy, como siempre. Nunca dejo a nadie atrás."] = "我在這裡，一如往常。我從不丟下任何人。",
	["Aquí estoy. Si no sabes por dónde empezar, toca «¿Por dónde empiezo?»."] = "我在這兒。不知道從哪開始，就點「從哪裡開始？」。",
	["Aquí está el Portal Oscuro: por él cruzó la Horda desde Draenor para invadir Azeroth en la Primera Guerra."] = "黑暗之門就在這裡：第一次戰爭時，部落從德拉諾穿過它入侵艾澤拉斯。",
	["Aquí está la tumba de Uther el Iluminado, el maestro de Arthas. Murió a manos de su propio alumno, defendiendo las cenizas del rey Terenas."] = "這裡是光明使者烏瑟的陵墓，他是阿薩斯的導師。他為守護泰納瑞斯國王的骨灰，死在了自己學生的手裡。",
	["Aquí juntas XP descansada poco a poco (más si cierras sesión aquí): luego ganas el doble por enemigo hasta gastarla."] = "在這裡會慢慢累積休息經驗（在這裡登出累積更多）：之後每個敵人給雙倍經驗，直到用完。",
	["Aquí la lees completa: cómo empieza, qué te piden y cómo termina."] = "在這裡讀完整的故事：如何開始、要你做什麼、如何結束。",
	["Aquí no hay nodos que recolectar"] = "這裡沒有可採集的採集點",
	["Aquí sale por qué se activó la habilidad."] = "這裡會顯示技能被觸發的原因。",
	["Aquí verás cuánto llevas descubierto de cada zona de tu continente."] = "在這裡你會看到你所在大陸每個區域已探索了多少。",
	["Aquí ves cuántas llevas, dónde sale y qué hacer con ella."] = "在這裡可以看到你有多少、從哪裡取得以及怎麼處理它。",
	["Aquí ves todo lo que hay que saber, con qué hacer después."] = "這裡顯示你需要知道的一切，以及接下來該做什麼。",
	["Aquí: %s %.1f, %.1f. Se guarda este punto."] = "此處：%s %.1f, %.1f。已儲存此地點。",
	["Arañazo: sangrado con el tiempo."] = "掃擊：持續流血。",
	["Arcano"] = "秘法",
	["Arcano para subir"] = "秘法（練等）",
	["Archimonde subió a Hyjal para robar la energía del Árbol del Mundo; en vez de eso, el árbol fue su final."] = "阿克蒙德登上海加爾山，想奪取世界之樹的能量；結果世界之樹反而成了他的末日。",
	["Arco"] = "弓",
	["Arcos, ballestas y armas de fuego"] = "弓、弩與槍械",
	["Arena"] = "沙色",
	["Arma"] = "武器",
	["Arma con tu ruta lo que necesitas para poder tomarla: el nivel o las misiones de antes."] = "用你的路線安排接取它所需的條件：等級或前置任務。",
	["Arma de asta"] = "長柄武器",
	["Arma de dos manos"] = "雙手武器",
	["Arma de dos manos, sellos y juicios: el paladín que mejor sube en solitario."] = "雙手武器、聖印與審判：單練升級最快的聖騎士。",
	["Arma de fuego"] = "槍械",
	["Arma de puño"] = "拳套",
	["Arma el plan para cerrar las misiones de tu registro y te lleva a cada una."] = "制定完成任務日誌中任務的計畫，並帶你逐一前往。",
	["Arma tu grupo de 5 (buscador de grupos o tu manada)."] = "組好你的 5 人隊伍（尋求組隊或你的狼群）。",
	["Arma tu primer plan"] = "制定你的第一個計畫",
	["Arma una ruta de %s en %s"] = "建立%s路線（%s）",
	["Arma y escudo"] = "武器與盾牌",
	["Armadura"] = "護甲",
	["Armaduras"] = "護甲",
	["Armando"] = "建立中",
	["Armando el circuito de la zona..."] = "正在規劃區域環線…",
	["Armando «Cerrar mis misiones»..."] = "正在建立「完成我的任務」...",
	["Armar la ruta"] = "建立路線",
	["Armar lo que falta"] = "補齊缺少的部分",
	["Armar mi plan"] = "建立我的計畫",
	["Armar un plan nuevo"] = "制定新計畫",
	["Armas"] = "武器",
	["Armas a dos manos"] = "雙手武器流",
	["Armas a muerte"] = "全力輸出武器",
	["Armas contra jugadores"] = "PvP 武器",
	["Armas para grupo"] = "組隊武器",
	["Armas pensado para mazmorras: mucho daño en varios enemigos con Golpes de barrido, Golpe mortal para los jefes y más precisión para no fallar."] = "專為地城設計的武器配點：用橫掃攻擊對多個敵人造成大量傷害，用致死打擊對付首領，並提高命中避免失手。",
	["Armas pensando primero en no morir: paras más golpes, frenas a los que huyen y terminas con un poco de Protección para recibir menos daño."] = "以不死為優先的武器配點：招架更多攻擊、讓逃跑的敵人減速，最後點一些防護以降低受到的傷害。",
	["Armas seguro"] = "穩健武器",
	["Armas, armaduras, materiales, recetas y monturas: quién los suelta y quién los vende."] = "武器、護甲、材料、配方與坐騎：誰掉落、誰販售。",
	["Arrastra cada marco de combate adonde te acomode. Cuando termines, fíjalos para que no estorben."] = "把每個戰鬥框架拖到適合的位置。完成後鎖定，以免礙事。",
	["Arrastra lo que quieras mover. Clic derecho en uno: vuelve a su lugar de siempre."] = "把想移動的東西拖過去。右鍵點一個：它會回到原來的位置。",
	["Arrastra otra bolsa aquí para cambiarla."] = "將另一個背包拖到這裡即可替換。",
	["Arrastra para mover tus marcos. Cambia el tamaño y las columnas en la página Curación."] = "拖曳即可移動框架。大小與欄數請在「治療」頁面調整。",
	["Arrastra para mover tus marcos. Haz clic (con o sin Mayús, Ctrl o Alt) para ver qué lanzaría."] = "拖曳以移動框架。點擊（可搭配 Shift、Ctrl 或 Alt）查看會施放什麼。",
	["Arrastra una bolsa aquí para ponerla."] = "將背包拖到這裡即可裝備。",
	["Arreglos: «Cerrar mis misiones» vuelve a armar tu ruta, la ayuda de rotación vuelve a decirte qué usar y el mapa ya no muestra rectángulos pegados al acercar."] = "修正：「完成我的任務」重新為你規劃路線，循環助手再次告訴你該用什麼，放大地圖時也不再出現貼上去的矩形。",
	["Arriba a la derecha, el ícono de magia, maldición, veneno o enfermedad. Al pasar el ratón te dice qué clic lo quita."] = "右上角顯示魔法、詛咒、中毒或疾病的圖示。滑鼠移上去會告訴你用哪個點擊驅散。",
	["Arriba de la ventana, cada bolsa equipada con su espacio: pasa el ratón para resaltar lo que lleva y arrastra otra bolsa para cambiarla."] = "視窗頂部顯示每個已裝備的背包及其空間：滑鼠移到上面可標示其中的物品，拖入另一個背包即可替換。",
	["Arriba de tus marcos, el maná de quienes curan en tu grupo. Se destaca al terminar cada pelea."] = "在你的框架上方顯示隊伍中治療者的法力。每場戰鬥結束後會醒目顯示。",
	["Arriba en esta ventana está lo último que te dije, con sus botones. Para ver los 20 más recientes: /alfa lya historial."] = "這個視窗頂部是我最後說的話，附帶按鈕。最近 20 則：/alfa lya historial。",
	["Arriba, lo que Alfa recomienda. Un clic y empiezas."] = "上方是 Alfa 的推薦。點一下就能開始。",
	["Arriesgado"] = "冒險",
	["Arrodillarse"] = "跪下",
	["Arrojadiza"] = "投擲武器",
	["Arrástralo para moverlo"] = "拖曳即可移動",
	["Arrástralo para moverlo."] = "拖曳即可移動。",
	["Arrástralo para moverlo. Clic derecho: vuelve a su lugar de siempre."] = "拖曳即可移動。右鍵：回到原來的位置。",
	["Artefacto"] = "神器",
	["Artesano"] = "專家",
	["Artesanía y comercio"] = "製作與商業物品",
	["Arthas mató a Kel'Thuzad en Andorhal, pero después lo revivió como liche con el poder de la Fuente del Sol."] = "阿薩斯在安多哈爾殺了科爾蘇加德，但後來又用太陽之井的力量把他復活成巫妖。",
	["Arthas mató al archimago Antonidas en Dalaran, y después Archimonde destruyó la ciudad."] = "阿薩斯在達拉然殺死了大法師安東尼達斯，之後阿克蒙德摧毀了這座城市。",
	["Arthas purgó Stratholme porque su grano estaba infectado. Esa decisión lo separó para siempre de Uther y de Jaina."] = "阿薩斯屠戮了斯坦索姆，因為那裡的穀物已被感染。這個決定讓他與烏瑟和珍娜永遠決裂。",
	["Arthas tomó la espada Agonía de Escarcha en Rasganorte creyendo que salvaría a su pueblo. La espada le robó el alma."] = "阿薩斯在北裂境拿起了霜之哀傷，以為它能拯救他的子民。這把劍卻奪走了他的靈魂。",
	["Arthas y Jaina se querían antes de que la plaga los separara."] = "在瘟疫拆散他們之前，阿薩斯和珍娜曾經相愛。",
	["Asesinato"] = "刺殺",
	["Asesinato para subir"] = "刺殺（練等）",
	["Aspecto"] = "守護",
	["Astranaar es el pueblo élfico en medio de Vallefresno, en una isla del lago."] = "阿斯特蘭納是梣谷中央的精靈城鎮，坐落在湖中的一座島上。",
	["Asusta a los enemigos cercanos. Cuidado: pueden correr y traer a otros."] = "恐懼附近的敵人。小心：牠們可能會逃跑並引來別的。",
	["Asusta a los enemigos cercanos. Te da tiempo para escapar o curarte."] = "恐懼附近的敵人。為你爭取逃跑或治療的時間。",
	["Asusta a todos los enemigos cercanos."] = "恐懼附近所有敵人。",
	["Asusta a todos los que están cerca: si te asusta, intenta no correr hacia otras celdas."] = "他會恐懼附近所有人：如果你被恐懼，盡量不要跑進其他牢房。",
	["Asusta a un enemigo y lo hace huir. Cuidado: puede traer a otros."] = "讓一個敵人恐懼逃跑。小心：牠可能會引來別的。",
	["Asusta un momento al enemigo y te cura. Tu escape de emergencia."] = "讓敵人恐懼片刻並治療你。你的緊急脫身技。",
	["Asusta y duerme a los jugadores: si te asusta, intenta no correr hacia más enemigos."] = "他會恐懼並催眠玩家：如果你被恐懼，盡量不要跑向更多敵人。",
	["Así la manada se encuentra para cazar juntos. Es tu decisión, y la cambias cuando quieras."] = "狼群就是這樣相聚一起狩獵的。由你決定，隨時可改。",
	["Así queda tu Alfa"] = "這就是你的 Alfa",
	["Así sabes qué hace cada clic antes de tu próxima pelea."] = "這樣在下一場戰鬥前，你就知道每次點擊的作用。",
	["Así se lee tu ayuda de rotación"] = "如何看懂你的輸出循環助手",
	["Así se ven tus avisos"] = "你的提醒會像這樣顯示",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo, en Marcos. Pulsa Listo cuando termines."] = "你的框架會是這個樣子。拖曳來移動它們，並在下方「框架」中調整大小。完成後按「完成」。",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo. Pulsa Listo cuando termines."] = "你的框架會像這樣顯示。拖曳即可移動，並在下方調整大小。完成後請按「完成」。",
	["Así terminó «%s»… ¿Te cuento el final?"] = "「%s」就這樣結束了…要我告訴你結局嗎？",
	["Así: /alfa cita mañana 21:30 Minas de la Muerte"] = "例如：/alfa cita tomorrow 21:30 死亡礦坑",
	["Atacas más rápido según tus puntos de combo. Mantenlo en las peleas largas."] = "依連擊點數提高攻擊速度。長時間戰鬥中保持它。",
	["Atajos"] = "快捷操作",
	["Ataque de tormenta: mucho daño, cada vez que esté listo."] = "風暴打擊：高傷害，冷卻好就用。",
	["Ataques más rápidos después de un crítico."] = "致命一擊後攻擊速度加快。",
	["Atardecer"] = "黃昏",
