	["Atronar fuerte: juntas varios monstruos y los frenas a todos."] = "強力的雷霆一擊：把好幾隻怪聚在一起並讓它們全部減速。",
	["Atronar más barato para agarrar varios."] = "更便宜的雷霆一擊，用來穩住好幾隻怪。",
	["Atronar más fuerte y barato: agarras a varios enemigos a la vez."] = "更強、更便宜的雷霆一擊：同時穩住好幾個敵人。",
	["Atrás"] = "返回",
	["Aturde al enemigo en forma de oso. Úsalo para interrumpir."] = "熊形態下讓敵人昏迷。用來打斷。",
	["Aturde al enemigo unos segundos. Úsalo para interrumpir o para escapar."] = "讓敵人昏迷幾秒。用來打斷或逃跑。",
	["Aturde al tanque con su martillo: mantén la vida del tanque alta."] = "他會用錘子擊昏坦克：讓坦克的生命值保持在高檔。",
	["Aturde según tus puntos de combo. Úsalo para interrumpir o rematar."] = "依連擊點數造成昏迷。用來打斷或收尾。",
	["Aturdes a uno mientras peleas con otro."] = "一邊打一個，一邊擊昏另一個。",
