	["Azeroth"] = "艾澤拉斯",
	["Azeroth tiene dos continentes en el Clásico: Kalimdor al oeste y los Reinos del Este. En medio está el Gran Mar."] = "在經典版中，艾澤拉斯有兩塊大陸：西邊的卡林多和東部王國。兩者之間是無盡之海。",
	["Azshara lleva el nombre de la reina de los elfos que abrió la puerta a la Legión Ardiente. Tras la Gran División se convirtió en la reina de los naga."] = "艾薩拉以精靈女王的名字命名，她曾為燃燒軍團打開大門。大分裂之後，她成了納迦的女王。",
	["Azshara y los Altonato que se hundieron con su palacio no murieron: se transformaron en los naga."] = "艾薩拉和隨她的宮殿一起沉沒的上層精靈並沒有死：他們變成了納迦。",
	["Azul"] = "藍色",
