	["Blizzard no deja que un addon copie tu mapa. Abre su ventana con el botón «Abrir clic para lanzar» o escribe %s en el chat, y arma ahí los mismos clics."] = "Blizzard 不允許插件複製你的點擊配置。請用「開啟點擊施法」按鈕開啟其視窗，或在聊天視窗輸入 %s，然後在那裡設定相同的點擊。",
