	["Bolsas sin errores, conjuntos de equipo, comparar y buscar en todos tus personajes."] = "不出錯的背包、裝備設定、比較裝備，以及搜尋你所有角色。",
	["Bolsas y banco"] = "背包與銀行",
	["Bolsas: %d de %d libres"] = "背包：剩餘 %d / %d",
	["Bolsas: %d objetos en %d de %d casillas"] = "背包：%d 件物品，佔 %d / %d 格",
	["Bolsas: te queda 1 espacio para el botín"] = "背包：只剩 1 格放戰利品",
	["Bolsas: te quedan %d espacios para el botín"] = "背包：剩 %d 格放戰利品",
	["Bolvar Fordragón, hoy regente de Ventormenta, fue paladín de la Mano de Plata."] = "如今的暴風城攝政王柏瓦爾·弗塔根，曾是白銀之手的聖騎士。",
	["Bonus de tu tipo de arma."] = "依你的武器類型獲得加成。",
	["Bonus según tu tipo de arma (hacha, espada o maza): más crítico o más golpes."] = "依你的武器類型（斧、劍或錘）獲得加成：更高的致命一擊或更多次攻擊。",
	["Bonus según tu tipo de arma: más golpes y más críticos."] = "依你的武器類型獲得加成：更多次攻擊與更多致命一擊。",
