	["Borraste esta ruta. Desaparece del menú al recargar la interfaz."] = "你刪除了這條路線。重新載入介面後就會從選單中消失。",
	["Borraste «%s»"] = "你刪除了「%s」",
	["Botones con el estilo"] = "按鈕套用風格",
	["Botones de Alfa en el mapa del juego"] = "遊戲地圖上的 Alfa 按鈕",
	["Botones de acción, experiencia, menú y bolsas con tu estilo. Nunca se tocan en combate."] = "快捷列按鈕、經驗條、選單與背包使用你的風格。戰鬥中絕不變動。",
