	["Botón «Acomodar»"] = "「整理」按鈕",
	["Botón «Buscar cerca» en el rastreador"] = "追蹤器中的「搜尋附近」按鈕",
	["Brasa"] = "餘燼",
	["Brillan los objetos que acabas de conseguir, hasta que cierras las bolsas."] = "剛取得的物品會發光，直到你關閉背包為止。",
	["Brillo"] = "發光",
	["Brillo máximo (nits)"] = "峰值亮度（尼特）",
	["Brillo normal (nits)"] = "一般亮度（尼特）",
	["Brillo: un borde dorado que late y una insignia «!» (llena si el objeto empieza una misión). Marco fijo: el marco dorado del juego. Nada: sin marca."] = "發光：閃動的金色邊框和一個「!」標記（物品能開始任務時為實心）。固定邊框：遊戲內建的金色邊框。無：不做標記。",
	["Brujo"] = "術士",
	["Bruma"] = "薄霧",
	["Buen lanzamiento"] = "拋得好",
	["Buena caza hoy: %s Descansa, que yo cuido tu lugar."] = "今天狩獵得不錯：%s 好好休息，我幫你守著位置。",
	["Buenas noches, lobo. Si te vas a ir pronto, termina en una posada para descansar bien."] = "晚安，狼。如果你快下線了，就在旅店結束，好好休息。",
	["Buenas tardes. Es buena hora para entregar misiones y ver qué hay de nuevo."] = "午安。正適合交任務，看看有什麼新鮮事。",
	["Buff activo"] = "增益效果已生效",
	["Buff fuera de combate"] = "戰鬥外的增益效果",
	["Buffs"] = "增益效果",
	["Build completo"] = "配點已完成",
	["Build importado"] = "匯入的配點",
	["Build importado de una cadena. Alfa lo resuelve en tu árbol y te avisa si algún talento no existe."] = "從字串匯入的配點。Alfa 會對照你的天賦樹解析，若有天賦不存在會提醒你。",
	["Busca %s en: %s."] = "在這些地方找 %s：%s。",
	["Busca addons que chocan con Alfa, partes apagadas y ajustes raros, con el arreglo a un clic. También con /alfa diagnostico."] = "找出與 Alfa 衝突的插件、被關閉的部分和異常設定，一鍵修正。也可用 /alfa diagnostico。",
	["Busca al entrenador de tu clase en la ciudad."] = "到城裡找你的職業訓練師。",
	["Busca cualquier cosa del juego"] = "搜尋遊戲中的任何東西",
	["Busca cualquier cosa, en español o en inglés…"] = "搜尋任何東西，可用西班牙文或英文…",
	["Busca el arma de dos manos con más daño por segundo: es lo que más sube tu daño."] = "找每秒傷害最高的雙手武器：這是提升你傷害最有效的方法。",
	["Busca el arma de dos manos más lenta y fuerte: tus sellos pegan con ella."] = "找攻擊速度最慢、威力最強的雙手武器：你的聖印會依它造成傷害。",
	["Busca la zona de la misión entre las guías de subir de nivel."] = "在練等指南中尋找該任務所在的地區。",
	["Busca lo mejor que puedes usar"] = "尋找你能用的最佳裝備",
	["Busca por aquí"] = "在這附近找找",
	["Busca siempre el arco, arma de fuego o ballesta con más daño por segundo."] = "一律找每秒傷害最高的弓、槍械或弩。",
	["Busca un escudo con valor de bloqueo alto: sube el daño de Embate con escudo."] = "找格擋值高的盾牌：能提高盾牌猛擊的傷害。",
	["Busca un objeto en las bolsas, bancos y equipo de todos tus personajes. Los demás, con lo último que guardó Alfa."] = "在你所有角色的背包、銀行和裝備中尋找物品。其他角色以 Alfa 最後一次儲存的內容為準。",
	["Busca una misión, un PNJ, una zona o una palabra…"] = "搜尋任務、NPC、地區或關鍵字…",
	["Busca una versión nueva de Alfa"] = "檢查 Alfa 新版本",
	["Busca y elige un objeto."] = "搜尋並選擇一件物品。",
	["Busca y elige una misión."] = "搜尋並選擇一個任務。",
	["Buscador"] = "查詢",
	["Buscando a la manada…"] = "正在尋找狼群…",
	["Buscando a un oficial..."] = "正在尋找幹部...",
	["Buscando lo mejor para tu nivel…"] = "正在尋找適合你等級的最佳裝備…",
	["Buscando misiones cerca..."] = "正在尋找附近的任務...",
	["Buscando otras misiones..."] = "正在尋找其他任務...",
	["Buscando otro plano"] = "正在尋找另一個位面",
	["Buscando su rastro..."] = "正在尋找對方的蹤跡...",
	["Buscando..."] = "搜尋中...",
	["Buscar"] = "搜尋",
	["Buscar ajustes"] = "搜尋設定",
	["Buscar cerca"] = "搜尋附近",
	["Buscar cerca (vuelo, posada, reparar...)"] = "搜尋附近（飛行點、旅店、修理...）",
	["Buscar cerca no está disponible."] = "搜尋附近功能無法使用。",
	["Buscar cerca y tus planes"] = "搜尋附近與你的計畫",
	["Buscar cerca..."] = "搜尋附近...",
	["Buscar cerca:"] = "搜尋附近：",
	["Buscar cerca: vuelo, posada, banco…"] = "搜尋附近：飛行點、旅店、銀行…",
	["Buscar en el diario"] = "在圖鑑中搜尋",
	["Buscar en todos tus personajes"] = "搜尋你所有角色",
	["Buscar equipo para mi nivel"] = "搜尋適合我等級的裝備",
	["Buscar guías por nombre o zona"] = "依名稱或地區搜尋指南",
	["Buscar otra vez"] = "重新搜尋",
	["Buscar por nombre, zona o quién lo mandó"] = "依名稱、地區或傳送者搜尋",
	["Buscar un lugar..."] = "搜尋地點…",
	["Buscar «%s» en la Enciclopedia"] = "在百科中搜尋「%s」",
	["Buscar: pasto, niebla, sombras..."] = "搜尋：草、霧、陰影...",
	["Buzones, entrenadores, banco, subasta, reparar..."] = "郵箱、訓練師、銀行、拍賣場、修理...",
	["Buzón"] = "信箱",
	["Básico"] = "基本",
	["Búscalo en %s."] = "去%s找找。",
	["Búscalo en la Enciclopedia: objetos, PNJ, misiones, zonas y raros, con dónde están y el botón «Guíame»."] = "在百科裡搜：物品、NPC、任務、區域和稀有怪，有位置和「帶我去」按鈕。",
	["Búscalo por su nombre; se cumple cuando lo tienes en tus bolsas."] = "依名稱搜尋；當它在你的背包中時即達成。",
	["CPS"] = "HPS",
	["Cabeza"] = "頭部",
	["Cada 2 niveles"] = "每 2 級",
	["Cada Aspecto guía un vuelo de dragones: Alexstrasza el rojo, Ysera el verde, Nozdormu el bronce, Malygos el azul y Neltharion el negro."] = "每位守護巨龍都領導一支龍軍團：雅立史卓莎是紅龍，伊瑟拉是綠龍，諾茲多姆是青銅龍，瑪里苟斯是藍龍，奈薩里奧是黑龍。",
	["Cada ajuste que Alfa cambió vuelve al valor que tenía antes. Los filtros no cambian."] = "Alfa 變更過的每項設定都會恢復為之前的數值。濾鏡不會改變。",
	["Cada aviso y cada porqué sale con texto hasta %d veces y luego solo queda el ícono."] = "每個提示與每條原因最多顯示 %d 次文字，之後只保留圖示。",
	["Cada año, el día que empezaron a cazar juntos, Lya lo festeja. Y también el cumpleaños de Alfa."] = "每年在你們開始一起狩獵的那一天，莉婭都會慶祝。Alfa 的生日也一樣。",
	["Cada bloqueo te da ira: nunca te falta."] = "每次格擋都會給你怒氣：永遠不缺怒氣。",
	["Cada bolsa en su bloque, con su nombre y su espacio."] = "每個背包各自一區，顯示名稱與空間。",
	["Cada botón de acción con el borde y el fondo del estilo, el ícono cuadrado y la letra de Alfa en la tecla y la cuenta."] = "每個快捷列按鈕都使用該風格的邊框與背景、方形圖示，按鍵與數量使用 Alfa 的字型。",
	["Cada casilla en su lugar, como en tus bolsas."] = "每一格都在原位，就像你的背包一樣。",
	["Cada clase da retos del Legado al llegar a 25, 45 y 60: subir otras clases también le suma a tu cuenta."] = "每個職業在 25、45 與 60 級時都會給傳承挑戰：練其他職業也會為你的帳號加分。",
	["Cada clic que cura también selecciona a ese compañero, para seguir con otro poder, un buff o quitarle una maldición o un veneno."] = "每次點擊治療也會選取那名隊友，方便接著用其他技能、加增益效果，或幫他驅散詛咒或中毒。",
	["Cada cofre o tesoro conocido."] = "每個已知的寶箱或寶藏。",
	["Cada crítico hace sangrar."] = "每次致命一擊都會造成流血。",
	["Cada domingo en Tuercespina: el primero en llevar 40 pescados sabrosos de los bancos especiales gana. También salen peces raros que se cambian por premios."] = "每週日在荊棘谷：第一個從特殊魚群中帶回 40 條美味魚的人獲勝。還會釣到稀有魚，可以換取獎品。",
	["Cada entrada de mazmorra y banda con su rango de niveles. Clic: su página; Mayús+clic: la flecha te lleva."] = "每個地城與團隊副本的入口及其等級範圍。點擊：開啟其頁面；Shift+點擊：箭頭帶你前往。",
	["Cada frase sale tres veces como mucho. Con esto vuelven a salir desde el principio."] = "每句話最多出現三次。用這個可以讓它們從頭再次出現。",
	["Cada golpe crítico deja al enemigo sangrando: daño extra sin hacer nada."] = "每次致命一擊都會讓敵人流血：不用多做什麼就有額外傷害。",
	["Cada grupo de la banda en su propia columna (o fila), como en la ventana de banda. Con el orden por grupo."] = "團隊的每個小隊各占一欄（或一列），就像團隊視窗一樣。搭配依小隊排序。",
	["Cada hierba pide más habilidad que la anterior: recoge todo lo que puedas y sube sola. Enciende el rastreo de hierbas."] = "每種草藥需要的技能都比上一種高：能採的都採，技能自己就會漲。記得開啟尋找草藥。",
	["Cada hierba tiene su lugar: unas junto al agua, otras en las montañas o bajo los árboles."] = "每種草藥都有自己的生長地：有的在水邊，有的在山上或樹下。",
	["Cada lugar conocido donde aparece un enemigo raro."] = "每個已知會出現稀有怪的地點。",
	["Cada lunes te pongo tres retos chiquitos: misiones, raros y uno sorpresa. Tu avance está en mi página y cada reto cumplido vale una salchicha de premio."] = "每週一我會給你三個小挑戰：任務、稀有怪和一個驚喜。你的進度在我的頁面上，每完成一個挑戰就能贏得一根獎勵香腸。",
	["Cada lunes, tres retos chiquitos con su salchicha de premio. Tu avance sale arriba, en esta página."] = "每週一，三個小挑戰，獎品是香腸。你的進度顯示在本頁上方。",
	["Cada meseta de Cima del Trueno tiene su función: una para los ancianos y los druidas, otra para los espíritus y otra para los cazadores."] = "雷霆崖的每座台地都有自己的用途：一座給長者與德魯伊，一座給靈魂，一座給獵人。",
	["Cada misión que terminas te hace más fuerte."] = "你完成的每個任務都會讓你更強。",
	["Cada muelle con cuánto falta para que llegue su barco o zepelín."] = "每個碼頭都顯示它的船或飛艇還有多久抵達。",
	["Cada muelle con cuánto falta para que llegue."] = "每個碼頭都顯示還有多久抵達。",
	["Cada nivel"] = "每一級",
	["Cada paso de la bienvenida deja bajar hasta el final, sin cerrar y volver a abrir."] = "歡迎設定的每一步都可以一路往下捲動，不用關掉再重新開啟。",
	["Cada preajuste llena tus clics con los hechizos que ya sabes. Después cambias lo que quieras en la página Curación."] = "每個預設方案都會用你已學會的法術填滿點擊配置。之後可在「治療」頁面隨意變更。",
	["Cada reto da 1 punto. Al salir Forever hay %d retos, y cada personaje puede gastar hasta %d."] = "每個挑戰給 1 點。Forever 推出時共有 %d 個挑戰，每個角色最多可花費 %d 點。",
	["Cada semana guardo una copia de tus ajustes y perfiles. En Ajustes > Estilo y sonido, en «Respaldos», vuelves a una con un clic."] = "每週我都會保存一份你的設定和設定檔。在 設定 > 風格與音效 的「備份」裡，點一下就能還原。",
	["Cada versión nueva te recibe con la intro del lobo y sus notas, como estas."] = "每個新版本都會用狼的開場動畫和更新說明迎接你，就像現在這樣。",
	["Cada vez que aprendes uno de los principales de tu clase te digo en corto para qué sirve y cuándo usarlo."] = "每次你學會職業的主要技能，我都會簡單告訴你它有什麼用、何時使用。",
	["Cada vez que entras al juego, la intro del lobo y la luna te da la bienvenida. Un clic o Esc la saltan."] = "每次進入遊戲，狼與月亮的開場動畫都會歡迎你。點擊或按 Esc 可跳過。",
	["Cada vez: %s."] = "每次：%s。",
	["Cada zona con lobos y cuántos hay en cada guarida. En el mapa del mundo también sale."] = "每個有狼的區域，以及每個巢穴裡有幾隻。世界地圖上也會顯示。",
	["Cada ícono del mapa con su tamaño exacto en tu pantalla, nítido de orilla a orilla."] = "地圖上的每個圖示都以螢幕上的精確尺寸顯示，邊緣清晰銳利。",
	["Cairne Pezuña de Sangre gobierna desde Cima del Trueno, aunque Magatha, de los Tótem Siniestro, no lo quiere tanto como aparenta."] = "凱恩·血蹄在雷霆崖統治，不過恐怖圖騰的瑪加薩並不像她表面上那樣敬愛他。",
	["Cairne Pezuña de Sangre peleó en el Monte Hyjal junto a Thrall contra la Legión."] = "凱恩·血蹄曾和索爾並肩在海加爾山對抗燃燒軍團。",
	["Caja para escribir con el estilo"] = "輸入框套用風格",
	["Calculando"] = "計算中",
	["Calculando la vuelta más corta…"] = "正在計算最短環線…",
	["Calidad"] = "品質",
	["Calidad de la niebla"] = "霧效品質",
	["Calidad de las sombras"] = "陰影品質",
	["Calla las voces de /bailar, /reír, /aplaudir y otros gestos."] = "關閉 /dance、/laugh、/applaud 等表情動作的語音。",
	["Calla los ruidos de las mascotas, como el bostezo de los gatos de cazador."] = "關閉寵物的聲音，例如獵人貓科寵物打哈欠的聲音。",
	["Calma, que la cacería no se va a ningún lado. Come algo, repara y, si es mucho, la manada te echa la mano."] = "別急，獵物跑不了。吃點東西，修理一下，要是太難，狼群會搭把手。",
	["Cambia a «Todo» para ver su botín completo."] = "切換到「全部」即可查看完整戰利品。",
	["Cambia al mapa de Alfa en esta zona: todo el mundo en un solo mapa, con zoom y tus marcadores."] = "在此地區切換到 Alfa 地圖：整個世界在一張地圖上，可縮放並顯示你的標記。",
	["Cambia de plano cuando está lleno, «¿Quién tiene...?» y los festejos de la manada."] = "人多時切換位面、「誰有…？」以及狼群的慶祝。",
	["Cambia el modo limpio del mapa"] = "切換地圖的簡潔模式",
	["Cambia lo que quieras: se guarda al momento."] = "想改什麼都行：會立即儲存。",
	["Cambiar"] = "更換",
	["Cambiar de forma te quita lentitudes y raíces: úsalo para escapar."] = "變換形態會解除減速與定身：用它來脫身。",
	["Cambiar de plano"] = "切換位面",
	["Cambiar de plano si está lleno"] = "人多時切換位面",
