	["Clase"] = "職業",
	["Clases (27): llegar a nivel 25, 45 y 60 con cada una de las 9 clases."] = "職業（27）：用 9 個職業各自達到 25、45 與 60 級。",
	["Clic derecho (o Mayús+clic): un marcador ahí. Ctrl+clic: la flecha y la ruta te llevan ahí sin guardar nada."] = "右鍵（或 Shift+點擊）：在那裡放置標記。Ctrl+點擊：箭頭與路線帶你過去，不儲存任何東西。",
	["Clic derecho en la misión, en tu registro o en el rastreador: «Ver la cadena completa». Te digo cuáles hiciste y el premio del final."] = "在任務日誌或追蹤器中右鍵點擊任務：「查看完整任務鏈」。我會告訴你做過哪些，以及最終獎勵。",
	["Clic derecho en su retrato o en su nombre del chat y elige «Invitar al clan». A tu hermandad le llega con un clic."] = "右鍵他的頭像或聊天裡的名字，選「邀請進氏族」。公會邀請一點就發出。",
	["Clic derecho en un jugador (su retrato, su nombre en el chat o tu grupo) y elige tu hermandad: la invitación le llega sin escribir su nombre. Para una comunidad, Alfa te deja el nombre listo para pegar en la ventana del juego."] = "右鍵點擊一名玩家（頭像、聊天中的名字或你的隊伍），選擇你的公會：不必輸入名字，邀請就會送達。對於社群，Alfa 會準備好名字，讓你貼到遊戲視窗中。",
	["Clic derecho en un jugador y «Invitar al clan»: eliges tu hermandad o tu comunidad y la invitación le llega sin escribir su nombre."] = "右鍵點擊一名玩家並選擇「邀請加入公會或社群」：選好你的公會或社群，不必輸入名字，邀請就會送達。",
	["Clic derecho: dejarla sin acción."] = "右鍵點擊：設為無動作。",
	["Clic derecho: opciones de esta guía"] = "右鍵點擊：此指南的選項",
	["Clic derecho: reiniciar, quitar o llevar a Mis planes."] = "右鍵點擊：重新開始、移除或加入「我的計畫」。",
	["Clic en Llévame: la flecha te lleva"] = "點擊「帶我去」：箭頭會帶你過去",
	["Clic en un marcador: su ficha (cambiarlo, compartirlo, borrarlo o seguirlo). Mayús+clic: seguirlo de una vez. Clic derecho en cualquier otro pin: seguirlo o guardarlo como marcador."] = "點擊標記：開啟其詳細資料（變更、分享、刪除或跟隨）。Shift+點擊：直接跟隨。右鍵點擊其他任何圖釘：跟隨或儲存為標記。",
	["Clic en una casilla para elegir qué hace sobre el compañero bajo tu ratón; clic derecho la deja sin acción. Los cambios se aplican fuera de combate."] = "點擊格子以選擇它對滑鼠下隊友的作用；右鍵點擊則設為無動作。變更會在脫離戰鬥後套用。",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta."] = "點擊其中一個：Alfa 地圖會移到它那裡。「跟隨」會設定箭頭與路線。",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta; la huella del grupo lo comparte con quien use Alfa."] = "點擊其中一個：Alfa 地圖會移到它那裡。「跟隨」會設定箭頭與路線；狼群爪印會把它分享給使用 Alfa 的人。",
	["Clic en uno: el mapa va hasta él. Clic derecho en el mapa: uno nuevo."] = "點擊其中一個：地圖會移到它那裡。在地圖上按右鍵：新增一個。",
