	["Combustión: tus hechizos de fuego hacen más críticos un rato."] = "燃燒：你的火焰法術在一段時間內更容易致命一擊。",
	["Combínala con Encantamiento para desencantar lo que coses y no uses."] = "搭配附魔，就能分解你縫製了卻用不上的東西。",
	["Combínala con Herboristería: así recoges tú lo que necesitas."] = "搭配草藥學：這樣你需要的材料就能自己採。",
