	["Comercio te dice qué vale más en la subasta que con el comerciante, y cuánto pedir."] = "「交易」告訴你哪些東西在拍賣場比賣給商人更值錢，以及該標多少價。",
	["Comida que da aguante o fuerza extra, y comes mientras descansas."] = "能提供額外耐力或力量的食物，休息時順便吃。",
	["Comida y agua"] = "食物和水",
