	["Comisión de la subasta estimada: %d%%."] = "預估拍賣場手續費：%d%%。",
	["Como el juego"] = "遊戲預設",
	["Como espíritu, Lya te dice a cuánto está tu cuerpo, lo que cuesta el ángel a tu nivel y qué conviene. La flecha te lleva."] = "變成靈魂時，莉婭會告訴你屍體有多遠、你這個等級找靈魂醫者要付出什麼代價，以及哪個比較好。箭頭會帶你去。",
	["Como están"] = "保持原樣",
	["Como guerrero no te curas solo: Primeros auxilios y algo de comida te salvan entre peleas."] = "戰士沒辦法治療自己：急救和一些食物能在戰鬥間隙救你一命。",
	["Como juegas, llegas en 1 día."] = "照你的遊戲方式，1 天就能到。",
	["Como juegas, llegas en unos %d días."] = "照你的遊戲方式，大約 %d 天後就能到。",
