	["Completas"] = "完整",
	["Completo"] = "完整",
	["Componentes"] = "施法材料",
	["Compra lo que tu paso necesita si el comerciante lo vende. Nada de más de 50 de oro."] = "如果商人有賣，就購買你目前步驟需要的東西。不超過 50 金幣。",
	["Compra tu montura con %s"] = "向%s購買你的坐騎",
	["Comprar"] = "購買",
	["Comprar comida y bebida"] = "購買食物與飲料",
	["Comprar lo que falta cuesta más de %s (faltan precios)."] = "買齊缺少的東西要花 %s 以上（有些價格未知）。",
	["Comprar lo que falta cuesta unos %s."] = "買齊缺少的東西大約要花 %s。",
	["Comprar lo que pide tu guía"] = "購買指南要求的東西",
	["Comprar otra casilla del banco"] = "購買另一個銀行欄位",
	["Comprar y vender con otros"] = "與其他玩家買賣",
	["Compártela y la hacen juntos."] = "分享它，一起完成。",
	["Comunidad"] = "社群",
	["Común"] = "普通",
	["Con %s salen dos flechas a la vez. Alfa puede usar la de TomTom y esconder la suya."] = "用 %s 會同時出現兩個箭頭。Alfa 可以用 TomTom 的箭頭並隱藏自己的。",
	["Con /alfa reportar: yo ya junté los errores que atrapé, con su versión y cuántas veces salieron. Tú solo lo pegas en el Discord."] = "用 /alfa reportar：我已經收集好捕捉到的錯誤，附上版本和出現次數。你只要貼到 Discord 上。",
	["Con /alfa, con el lobo del minimapa o dándome clic derecho. Para hablar conmigo de todo esto: /alfa ayuda."] = "用 /alfa、小地圖上的狼，或右鍵點我。想和我聊這些：/alfa ayuda。",
	["Con 10 de furia o más lo lanzas."] = "怒氣達到 10 點即可施放。",
	["Con 2 casillas libres o menos, un aviso con lo primero que puedes soltar y un botón para vender o ver tus bolsas."] = "空格子剩 2 個或更少時，提醒你最先可以丟掉的東西，並附上出售或查看背包的按鈕。",
	["Con 2 o más misiones listas, el rastreador ofrece llevarte a entregarlas por el camino más corto."] = "有 2 個或以上已完成的任務時，追蹤器會提議按最短路線帶你去交。",
	["Con Cocina puedes encender tu propia fogata en cualquier lado."] = "學會烹飪後，你在哪裡都能點燃自己的營火。",
	["Con Redención reviven tus compañeros caídos: en una mazmorra vale oro."] = "救贖能復活倒下的同伴：在地城裡非常寶貴。",
	["Con aullido"] = "附狼嚎",
	["Con buena reputación, los vendedores de esa facción te hacen descuento."] = "聲望夠高時，該陣營的商人會給你打折。",
	["Con calma, nos pasa a todos. Mira qué te pegó y vuelve con todo."] = "別急，誰都會這樣。看看是什麼打倒了你，然後全力回來。",
	["Con dos amigos, trae hasta aquí a alguien de tu grupo."] = "和兩位朋友一起，把隊伍裡的某人召喚到你身邊。",
	["Con dos armas pega más rápido: guarda maná para el final."] = "他拿雙武器，攻擊更快：把法力留到最後。",
	["Con el correo puedes enviar contra reembolso: mandas el objeto y cobras al entregarlo."] = "郵件可以貨到付款：你寄出物品，對方收貨時你就收到錢。",
	["Con el cuadro oculto en combate, mantén presionado Mayús para verlo."] = "戰鬥中滑鼠提示隱藏時，按住 Shift 即可查看。",
	["Con el cursor encima no se cierra."] = "游標停在上面時不會關閉。",
	["Con el entrenador más cercano en tu camino."] = "並標出你路上最近的訓練師。",
	["Con el mapa de vuelos abierto, marca el destino más cerca de tu paso de ahora."] = "開啟飛行地圖時，標出離你目前步驟最近的目的地。",
	["Con el mapa de vuelos abierto, marco con una huella el destino más cerca de tu paso de ahora."] = "開啟飛行地圖時，我會用爪印標出離你目前步驟最近的目的地。",
	["Con el modo pesca abierto y alguna meta, la ventanita de metas se ve sola."] = "開啟釣魚模式並設有目標時，目標小視窗會自動顯示。",
	["Con el modo pesca abierto, esta tecla lo hace todo: equipo, cebo, lanzar y recoger. Al cerrarlo vuelve a ser la de siempre."] = "開啟釣魚模式時，這個按鍵包辦一切：裝備、魚餌、拋竿與收竿。關閉後，按鍵恢復原本功能。",
	["Con el modo pesca abierto, un aviso suave para volver a lanzar."] = "開啟釣魚模式時，用輕柔的提示提醒你重新拋竿。",
	["Con el tiempo, los magos humanos se reunieron en Dalaran, que se volvió la ciudad de la magia de los Reinos del Este."] = "後來，人類法師們聚集到達拉然，這裡成了東部王國的魔法之城。",
	["Con la interfaz de mando el mapa del juego se abre con su tecla."] = "使用控制器介面時，遊戲地圖用它自己的按鍵開啟。",
	["Con la interfaz para mando, Alfa deja las bolsas del juego. Igual puedes abrir la ventana de Alfa desde aquí."] = "使用控制器介面時，Alfa 會保留遊戲原本的背包。你仍然可以從這裡開啟 Alfa 的視窗。",
	["Con la tecla en Espacio, Mayús+Espacio salta mientras el modo está abierto."] = "按鍵設為空白鍵時，模式開啟期間按 Shift+空白鍵 跳躍。",
	["Con las de Alfa ves todo en una ventana: tres vistas, búsqueda, la barra de tus bolsas y qué vender cuando se llenan."] = "使用 Alfa 的背包，一個視窗就能看到全部：三種檢視、搜尋、背包列，以及背包滿時該賣什麼。",
	["Con lo que gastaste: %s."] = "扣除花費：%s。",
	["Con lo que tienes haces %d: +%s en total"] = "用你現有的材料能做 %d 個：共 +%s",
	["Con mando, se quedan las bolsas del juego"] = "使用控制器時保留遊戲背包",
	["Con o sin Mayús, Ctrl o Alt. No lanza nada: aquí ves qué lanzaría sobre tu compañero."] = "可搭配 Shift、Ctrl 或 Alt。不會施放任何法術：這裡只顯示會對隊友施放什麼。",
	["Con poca vida llama a dos ayudantes: si a él le queda poco, terminen con él; si no, maten a los ayudantes."] = "生命值低時他會叫來兩個幫手：如果他快死了就直接解決他，不然就先殺幫手。",
	["Con poca vida se convierte en serpiente y pega más fuerte: guarda tus mejores ataques para ese momento."] = "生命值低時他會變成蛇，攻擊更猛：把你最強的攻擊留到那個時候。",
	["Con qué prioridad sugiere Alfa. Automática: la de tus talentos o, mientras subes, la de tu clase."] = "Alfa 依哪種優先順序給出建議。自動：依你的天賦，升級期間則依你的職業。",
	["Con reputación %s"] = "聲望達到%s",
	["Con sonido"] = "附音效",
	["Con tu build, Alfa sabe qué estadísticas te sirven y qué equipo buscar."] = "有了配點，Alfa 就知道哪些屬性對你有用、該找什麼裝備。",
	["Con tu punto libre se compra 1 rango de %s:"] = "用你的未分配點數點出 1 級%s：",
	["Con tu ritual de invocación y la ayuda de dos compañeros, traes a otro miembro del grupo hasta donde estés."] = "藉助召喚儀式和兩名同伴的幫助，你可以把另一名隊友召喚到你身邊。",
	["Con tus %d puntos libres se compran %d rangos de %s:"] = "用你的 %d 點未分配點數，點出 %d 級%s：",
	["Con un brillo suave"] = "帶柔和光芒",
	["Con un comerciante abierto vende tu chatarra; con un banquero guarda tus materiales."] = "開啟商人時賣掉垃圾；在銀行職員處存放材料。",
	["Con un comerciante o un banquero abierto, «Acomodar» en tus bolsas vende tu chatarra o guarda tus materiales en el banco. Un clic, y otro para detenerlo."] = "開啟商人或銀行職員時，背包裡的「整理」會賣掉垃圾，或把材料存進銀行。點一下開始，再點一下停止。",
	["Con un enemigo elegido, antes de empezar la pelea, y transparente para que no estorbe."] = "選取敵人後、戰鬥開始前顯示，並且半透明以免礙事。",
	["Con una tecla escondes lo del juego que no necesitas y quedan Alfa, tu rastreador y Lya. Otra pulsación lo devuelve todo."] = "一個按鍵就能隱藏遊戲裡用不到的東西，只留下 Alfa、你的追蹤器和莉婭。再按一次就全部回來。",
	["Con él tu tope sube a %d."] = "學了之後你的上限會提高到 %d。",
	["Concurso"] = "大賽",
	["Concurso de pesca de Tuercespina"] = "荊棘谷釣魚大賽",
	["Configura tu Alfa"] = "設定你的 Alfa",
	["Configuración terminada"] = "設定完成",
	["Configuración y ayuda"] = "設定與說明",
	["Configurar"] = "設定",
	["Configurar con el asistente"] = "使用設定引導",
	["Confirmado por Blizzard (su noticia del sistema de Legado de WoW Forever): los 65 retos de 1 punto, el tope de 16 por personaje, los tres árboles, los cuatro premios del registro y lo del modo extremo."] = "經 Blizzard 確認（其 WoW Forever 傳承系統公告）：65 個各 1 點的挑戰、每個角色 16 點上限、三棵樹、進度的四個獎勵，以及專家模式的規則。",
	["Conflagrar: consume tu Inmolar para un golpe fuerte."] = "燃燒：消耗你的獻祭，打出一記重擊。",
	["Congela a los que están cerca: si peleas de lejos, aléjate."] = "他會冰凍靠近的人：遠程職業請保持距離。",
	["Congela a un enemigo un rato. Ideal para controlar a uno extra en mazmorras."] = "把一個敵人冰凍一段時間。在地城控制多出來的敵人很棒。",
	["Congela al monstruo con Nova de escarcha y aléjate antes de seguir lanzando."] = "用冰霜新星凍住怪物，拉開距離後再繼續施法。",
	["Congela en el lugar y lanza rayos: si peleas de lejos, sepárate del grupo."] = "她會把玩家定身並施放閃電：遠程職業請和隊伍分散站位。",
	["Congela en su lugar a los enemigos cercanos. Aléjate y sigue lanzando."] = "把附近的敵人凍結在原地。拉開距離繼續施法。",
	["Congelas y frenas a los monstruos para que nunca te alcancen: el mago más seguro para subir."] = "凍結並減速怪物，讓它們永遠碰不到你：練等最安全的法師。",
	["Conjuntos de equipo"] = "裝備設定",
	["Conjúralas fuera de combate."] = "請在戰鬥外製造。",
	["Conocerlo"] = "帶我看看",
	["Conocido"] = "熟悉",
	["Conozco la clase y el nivel de %d lobos conectados. Si levantas algo que les sirve, te lo digo."] = "我知道 %d 隻線上狼的職業和等級。你拾取到他們用得上的東西時，我會告訴你。",
	["Conseguir %d de %s"] = "取得 %d 個%s",
	["Conseguir %d × %s"] = "取得 %d × %s",
	["Conseguir %s"] = "取得%s",
	["Conseguir un objeto"] = "取得一件物品",
	["Consejo en el cuadro de los objetos"] = "在物品滑鼠提示中顯示建議",
	["Consejos"] = "提示",
	["Consejos al entrar a una mazmorra"] = "進入地城時的建議",
	["Consejos de equipo apagados."] = "裝備建議已關閉。",
	["Consejos del juego"] = "遊戲建議",
	["Consejos para jugarlo"] = "玩法提示",
	["Consejos que callaste"] = "已關閉的建議",
	["Consejos vistos"] = "已看過的建議",
	["Consejos: muchos"] = "建議：多",
	["Consejos: pocos"] = "建議：少",
	["Consejos: solo importantes"] = "建議：只看重要的",
	["Conserva %s: vale más de otra forma."] = "保留%s：用其他方式更值錢。",
	["Considerar desencantar"] = "考慮分解",
	["Consigue %s"] = "收集%s",
	["Consigue bolsas más grandes en cuanto puedas: más espacio, más botín."] = "盡快弄到更大的背包：空間更多，戰利品更多。",
	["Consigue una caña de pescar"] = "弄一根魚竿",
	["Consumibles"] = "消耗品",
	["Contar tu avance en el chat del grupo"] = "在隊伍聊天中回報你的進度",
	["Contenta"] = "滿足",
	["Contestar «¿Quién tiene...?»"] = "回應「誰有…？」",
	["Contigo"] = "在身邊",
	["Continuar"] = "繼續",
	["Continuar mi ruta"] = "繼續我的路線",
	["Contra jefes de nivel alto fallas mucho: esto lo arregla."] = "打高等級首領時你很容易失手：這個能解決問題。",
	["Contra jefes fallas mucho: esto te ayuda."] = "打首領時你很容易失手：這個能幫上忙。",
	["Contra lo que llevas:"] = "與身上裝備相比：",
	["Contra lo que llevas: lo mismo."] = "與身上裝備相比：相同。",
	["Contra no-muertos y demonios: Exorcismo pega muy fuerte."] = "對付不死族與惡魔：驅邪術傷害非常高。",
	["Control de animación"] = "動作控制",
	["Contármela"] = "說給我聽",
	["Contármelo"] = "說給我聽",
	["Convierte a un enemigo en oveja un rato. El mejor control en mazmorras."] = "把一個敵人變成綿羊一段時間。地城裡最好的控制技。",
	["Coordenadas en el mapa"] = "地圖座標",
	["Coordenadas en el minimapa"] = "小地圖座標",
	["Copia este texto (Ctrl+C) y pásalo a tu manada. Lo pegan en Importar."] = "複製這段文字（Ctrl+C）傳給你的狼群。對方在「匯入」中貼上即可。",
	["Copia la cadena de abajo y pásala por el chat o por Discord: con Alfa la pegan en Importar y tienen tu mismo build."] = "複製下方的字串，透過聊天或 Discord 傳給別人：對方用 Alfa 在「匯入」貼上，就能得到和你一樣的配點。",
	["Copiar"] = "複製",
	["Copiar el Discord"] = "複製 Discord 連結",
	["Copiar y editar"] = "複製並編輯",
	["Coral"] = "珊瑚色",
	["Corre hacia el enemigo y lo aturde un momento. Úsala para empezar la pelea, desde lejos."] = "衝向敵人並讓牠昏迷片刻。從遠處用來開打。",
	["Correr"] = "跑步",
	["Corres mucho más rápido un momento. Para huir o para alcanzar a alguien."] = "片刻內跑得快很多。用來逃跑或追人。",
	["Corres más rápido, pero si te pegan te aturdes. Solo para viajar."] = "跑得更快，但被擊中會暈眩。只在趕路時用。",
	["Cortar"] = "打斷",
	["Cortar hechizos, amenaza, el tablón de la manada, mentor y dos estilos nuevos."] = "打斷法術、仇恨、狼群公告板、導師和兩種新風格。",
	["Cortar, amenaza y recargas"] = "打斷、仇恨和冷卻",
	["Costa Oscura está llena de ruinas élficas, como Ameth'Aran, de una época mucho más antigua."] = "黑海岸到處是精靈遺跡，例如亞米薩蘭，它們來自一個古老得多的年代。",
	["Costasur y Molino Tarren están a un paso uno del otro, y la Alianza y la Horda se miran feo desde siempre."] = "南海鎮與塔倫米爾近在咫尺，聯盟與部落在這裡向來互相敵視。",
	["Costuras, una abominación enorme, ataca Villa Oscura en una de las misiones más famosas del bosque."] = "巨大的憎惡斯迪克斯襲擊夜色鎮，是這片森林裡最有名的任務之一。",
	["Crear %s ≈ %s"] = "製作%s ≈ %s",
	["Crear ruta"] = "建立路線",
	["Crecen hacia"] = "延伸方向",
	["Criatura peligrosa"] = "危險生物",
	["Criaturas de nivel %d a %d"] = "%d 到 %d 級的生物",
	["Criaturas raras y tesoros: dónde aparecen y lo que sueltan."] = "稀有生物與寶藏：出現地點與掉落物。",
	["Cristal"] = "玻璃",
	["Créditos y licencias"] = "致謝與授權條款",
	["Crítico"] = "致命一擊",
	["Crítico con hechizos"] = "法術致命一擊",
	["Críticos enormes: matas antes de que te curen."] = "超高致命一擊：在對方被治療前就把他打死。",
	["Críticos más fuertes."] = "致命一擊傷害更高。",
	["Críticos un poco más fuertes."] = "致命一擊傷害稍微提高。",
	["Ctrl"] = "Ctrl",
	["Cuadro de información"] = "滑鼠提示",
	["Cualquier criatura de su nivel"] = "同等級的任何生物",
	["Cualquier habilidad tuya que el juego resalte por un efecto."] = "遊戲因某個效果而標示的任何技能。",
	["Cualquier instructor de pesca te la enseña. Luego compra una caña y unas lombrices: con eso empiezas."] = "任何釣魚訓練師都能教你。然後買一根魚竿和一些蚯蚓魚餌：這樣就能開始了。",
	["Cualquier profesión"] = "任何專業",
	["Cualquiera"] = "任何",
	["Cuando al monstruo le quede poca vida, usa Ejecutar (Alfa te avisa)."] = "怪物生命值低時，使用斬殺（Alfa 會提醒你）。",
	["Cuando alguien de tu grupo sube de nivel, Lya aúlla, lo felicita y te deja felicitarlo en el chat con un clic."] = "隊友升級時，莉婭會嚎叫並祝賀，還能讓你一鍵在聊天裡祝賀。",
	["Cuando aprendas %s, también."] = "學會%s後也會提醒。",
	["Cuando aprendas %s, te avisa al momento de usarlas."] = "學會%s後，會在該使用時提醒你。",
	["Cuando aprendas a cortar, aquí sale tu habilidad y su tecla."] = "學會打斷技能後，這裡會顯示你的技能和它的按鍵。",
	["Cuando aprendas una habilidad para cortar hechizos, te avisa en cuanto tu objetivo empiece a lanzar."] = "學會能打斷法術的技能後，你的目標一開始施法就會提醒你。",
	["Cuando aprendes un hechizo importante de tu clase, Lya te dice para qué sirve y cuándo usarlo."] = "當你學會重要的職業技能時，莉婭會告訴你它有什麼用、何時使用。",
	["Cuando aprendes un rango nuevo, un aviso ofrece cambiarlo en tus barras."] = "學會新等級時，會提示你在快捷列上替換。",
	["Cuando buscas algo en la subasta, Alfa guarda el precio más bajo que ves."] = "你在拍賣場搜尋時，Alfa 會記下你看到的最低價格。",
	["Cuando caes"] = "當你倒下時",
	["Cuando el Pozo de la Eternidad explotó, el gran continente antiguo se partió en pedazos. A eso le llaman la Gran División."] = "永恆之井爆炸時，古老的大陸四分五裂。人們稱之為大分裂。",
	["Cuando el juego termina de cargar, Alfa revisa lo que elegiste aquí y lo vuelve a poner si algo lo cambió. Si después los cambias en el menú del juego, Alfa se queda con lo nuevo."] = "遊戲載入完成時，Alfa 會檢查你在這裡的選擇，如果有東西變動了它們，就重新套用。如果你之後在遊戲選單中變更，Alfa 會保留新的設定。",
	["Cuando entras a una posada o ciudad, y cuando tu XP descansada se acaba."] = "進入旅店或城鎮時，以及休息經驗用完時。",
	["Cuando hay un festival, vale la pena darse una vuelta: casi siempre trae mascotas, ropa o comida que no salen el resto del año."] = "有節日的時候很值得去逛逛：幾乎總會有一年中其他時候拿不到的寵物、服裝或食物。",
	["Cuando hay varias para elegir, toma la que más te sirve."] = "有多個可選時，選對你最有用的那個。",
	["Cuando huelo salchichas se me olvida todo. Bueno, menos tú."] = "一聞到香腸的味道我就什麼都忘了。嗯，除了你。",
	["Cuando la Legión volvió en la Tercera Guerra, Malfurion y Tyrande hicieron sonar el Cuerno de Cenarius para despertar a los druidas dormidos."] = "燃燒軍團在第三次戰爭中捲土重來時，瑪法里恩和泰蘭妲吹響了塞納留斯之角，喚醒沉睡的德魯伊。",
	["Cuando la meta de ahora de tu plan es un lugar, la flecha lo toma sin que hagas clic."] = "當計畫的目前目標是一個地點時，箭頭會自動指向它，無需點擊。",
	["Cuando le baja la vida aturde a todos y corre a su cofre a cambiar de arma: espérenlo, no lo persigan."] = "生命值下降時他會擊昏所有人，跑到箱子那裡換武器：等他回來，不要追。",
	["Cuando levantes algo que le sirve a un lobo conectado, te lo digo aquí. Ellos comparten su clase y nivel en los ajustes."] = "當你拾取到線上的狼用得上的東西時，我會在這裡告訴你。他們會在設定中分享自己的職業和等級。",
	["Cuando lleves algo, Alfa te dice si conviene venderlo, subastarlo o transformarlo, y cuánto ganas."] = "當你攜帶物品時，Alfa 會告訴你該賣給商人、拍賣還是加工，以及能賺多少。",
	["Cuando los orcos se volvieron brujos, dejaron de oír a los elementos. Thrall les devolvió ese camino."] = "獸人變成術士之後，就聽不見元素的聲音了。是索爾把這條道路還給了他們。",
	["Cuando no sepas algo de Alfa, dame clic derecho y elige «¿En qué te ayudo?»: te explico cada cosa y te llevo a ella. También te cuento historias del lugar donde estás."] = "不懂 Alfa 的什麼，就右鍵點我選「我能幫你什麼？」：我逐一講解並帶你過去。我還會講你所在之地的故事。",
	["Cuando otro lobo con Alfa comparta su ubicación, aparece aquí y en tu mapa. Para que la manada crezca, invita a tus amigos: que instalen Alfa, acepten compartir y entren al Discord de La Jauría."] = "當其他使用 Alfa 的狼分享位置時，會出現在這裡與你的地圖上。想讓狼群壯大，就邀請你的朋友：安裝 Alfa、同意分享並加入 La Jauría 的 Discord。",
	["Cuando sales como espíritu te digo a cuánto está tu cuerpo, lo que cuesta el ángel a tu nivel y qué conviene. La flecha te lleva."] = "你釋放靈魂後，我會告訴你屍體有多遠、你這個等級找靈魂醫者要付出什麼代價，以及哪個比較好。箭頭會帶你去。",
	["Cuando se abre una misión de clase para ti, te ofrece su guía."] = "有適合你的職業任務開放時，提供其指南。",
	["Cuando se escapa"] = "魚跑掉時",
	["Cuando se llenan"] = "背包滿時",
	["Cuando se te acaban te digo qué te conviene a tu nivel y te llevo al vendedor más cercano. El agua solo si usas maná."] = "快用完時我會告訴你適合你等級的食物，並帶你去最近的商人。只有用法力的才需要水。",
	["Cuando te llega equipo mejor que lo que llevas puesto, un aviso con un botón para ponértelo (solo con tu clic y fuera de combate)."] = "拿到比身上更好的裝備時，跳出附按鈕的提醒讓你裝備上（只在你點擊時且不在戰鬥中）。",
	["Cuando te quedes sin maná, cambia a forma felina para terminar la pelea."] = "法力用完時，切換成獵豹形態把戰鬥打完。",
	["Cuando tengas las guías de tu facción, aquí sale tu ruta al 60."] = "有了你陣營的指南後，你通往 60 級的路線會顯示在這裡。",
	["Cuando tengas pescado que sepas cocinar, aparece aquí."] = "當你有會烹飪的魚時，就會顯示在這裡。",
	["Cuando termine el combate."] = "戰鬥結束時。",
	["Cuando tu guía dice «Sube al nivel», el rastreador te dice cuánta experiencia te falta y dónde rinde más: enemigos de tu nivel que también cuentan para tus misiones. «Llévame» y la flecha te lleva."] = "當你的指南說「升到等級」時，追蹤器會告訴你需要多少經驗，以及哪裡收益最高：和你同等級、又算在你任務裡的敵人。點「帶我去」，箭頭帶你過去。",
	["Cuando tu objetivo lance algo que se puede cortar, te avisa con %s y su tecla."] = "當你的目標施放可以打斷的法術時，會用 %s 和它的按鍵提醒你。",
	["Cuando tu objetivo lanza algo que se puede cortar: tu habilidad para cortar, su tecla y si está lista."] = "當你的目標施放可以打斷的法術時：你的打斷技能、它的按鍵，以及是否已就緒。",
	["Cuando tu objetivo o tu foco empieza a lanzar algo que se puede cortar, Alfa te avisa con tu habilidad para cortar, su tecla y si ya está lista. En mazmorras el juego a veces lo oculta: ahí avisa igual que está lanzando."] = "當你的目標或專注目標開始施放可以打斷的法術時，Alfa 會提醒你用哪個打斷技能、它的按鍵，以及是否已就緒。在地城裡遊戲有時會隱藏這些資訊：那時仍會提醒你對方正在施法。",
	["Cuando tu paso lo pide y hablas con su posadero. Nunca en otra posada."] = "當你的步驟需要、且你與對應的旅店老闆交談時。絕不在其他旅店。",
	["Cuando tus bolsas se llenan, Hoy te dice qué puedes vender y cuánto te dan."] = "背包快滿時，「今天」會告訴你可以賣什麼、能賣多少錢。",
	["Cuando tú o tu grupo peleen, aquí sale quién hace más daño."] = "當你或你的隊伍戰鬥時，這裡會顯示誰的傷害最高。",
	["Cuando un elfo de la noche muere, su espíritu toma forma de fuego fatuo y corre más rápido hasta su cuerpo."] = "夜精靈死後，靈魂會化為小精靈，更快地跑回屍體。",
	["Cuando un lobo de la manada encuentra un raro, te aviso en qué guarida está y te dejo pedir entrar con un clic."] = "狼群裡有狼發現稀有怪時，我會告訴你在哪個巢穴，並讓你一鍵請求進入。",
	["Cuando un lobo de tu zona pide ayuda, te avisa dónde está con «¡Voy!»: la flecha te lleva y le dice que vas."] = "區域裡的狼求助時，會告訴你牠在哪，並附帶「我來了！」：箭頭帶你過去，並告訴對方你要來。",
	["Cuando un lobo encuentra un raro o un tesoro en tu zona, te avisa en qué guarida está. Si es la tuya, «Ir de caza»; si es otra, «Pedir entrar»."] = "當狼在你的區域發現稀有怪或寶藏，你會知道它在哪個巢穴。在你的巢穴就「去狩獵」；在別的就「請求進入」。",
	["Cuando un oficio llega al tope de su rango, Lya te dice que ya puedes aprender el siguiente y dónde está tu instructor."] = "當專業達到目前等級的上限時，莉婭會告訴你可以學下一級了，以及訓練師在哪裡。",
	["Cuando una pieza baja de este porcentaje."] = "當某件裝備的耐久度低於此百分比時。",
	["Cuando una zona se llena, el juego la parte en guaridas (capas): el mismo lugar con otra gente, otros raros y otros minerales. Pide entrar a la de alguien de la manada y el juego te pasa al unirte a su grupo."] = "區域人多時，遊戲會把它分成巢穴（位面）：同一個地方，但人、稀有怪和礦都不同。請求進入狼群夥伴的巢穴，加入他的隊伍後遊戲就會帶你過去。",
	["Cuando usas una habilidad que tarda 30 segundos o más en volver, Alfa la pone en una barra discreta con lo que le falta. En Combate eliges cuáles no quieres ver."] = "當你使用冷卻 30 秒或更久的技能時，Alfa 會把它放進一條低調的計時條，顯示剩餘時間。在「戰鬥」中可以選擇不想看到哪些。",
	["Cuando venzas a tu primer jefe, tu progreso aparecerá aquí."] = "擊敗第一個首領後，你的進度就會顯示在這裡。",
	["Cuando ves caer a un raro, me acuerdo: en su cuadro y en La Jauría te digo hace cuánto lo cazaron y si pudo volver ya (a la media hora, más o menos)."] = "看到稀有怪倒下時，我會記住：在它的滑鼠提示和 La Jauría 中，我會告訴你它多久前被擊殺，以及是否可能已重生（大約半小時後）。",
	["Cuando ya casi se rompe."] = "快要損壞時。",
	["Cuando ya entregaste todo o cerraste tu zona, te dice qué sigue (la flecha la pones tú con «Llévame»)."] = "當你交完所有任務或做完這個區域時，它會告訴你下一步做什麼（用「帶我去」設定箭頭）。",
	["Cuarenta. ¡Hora de correr más rápido!"] = "四十級。該跑得更快了！",
	["Cuello"] = "頸部",
	["Cuenta:"] = "帳號：",
	["Cuero"] = "皮甲",
	["Cuerpo a cuerpo con tótems y golpes elementales: el chamán que mejor sube."] = "近戰搭配圖騰與元素打擊：升級最快的薩滿。",
	["Cuesta %s."] = "費用 %s。",
	["Cuestan %s: te alcanza."] = "需要 %s：你的錢夠。",
	["Cuestan %s; llevas %s."] = "需要 %s；你有 %s。",
	["Cuida bien a %s, que la manada lo necesita."] = "好好照顧 %s，狼群需要牠。",
	["Cuidado al nadar mar adentro: en aguas profundas te cansas y te puedes ahogar."] = "游到遠海時要小心：在深水中你會疲勞，還可能溺水。",
	["Cuidado con atraer varios a la vez: Fuego no tiene tanto control."] = "小心一次拉到好幾隻：火焰的控場能力沒那麼強。",
	["Cuidado: aquí los enemigos son nivel %s."] = "小心：這裡的敵人是 %s 級。",
	["Cumpleaños"] = "生日",
	["Cumpliste todas sus metas."] = "你達成了它的所有目標。",
	["Cumpliste todas sus metas. Elige otro plan o arma uno nuevo."] = "你達成了它的所有目標。選擇另一個計畫或制定一個新的。",
	["Cumpliste tu plan en %s."] = "你在 %s 內完成了計畫。",
	["Cura"] = "治療者",
	["Cura a quien tenga el dolor de sombras; la pelea es corta."] = "治療中了暗影痛苦的人；這場戰鬥很短。",
	["Cura a sus ayudantes y a sí misma: interrúmpanla."] = "她會治療幫手和自己：打斷她。",
	["Cura a todo tu grupo a la vez. Perfecta cuando a todos les pegan."] = "一次治療你的整個隊伍。大家都在挨打時完美。",
	["Cura a tu grupo con un clic."] = "一鍵治療你的隊友。",
	["Cura a tu mascota poco a poco. Mantenla viva: ella te cuida."] = "持續治療你的寵物。讓牠活著：牠在保護你。",
	["Cura con un clic y ese compañero queda seleccionado; limpia maldiciones y venenos con otro clic."] = "點一下治療，並且選取那名隊友；再點一下就能驅散詛咒和中毒。",
	["Cura de golpe y luego un rato más."] = "立即治療，之後再持續治療一段時間。",
	["Cura poco a poco. Ideal para alguien que recibe daño sin parar."] = "持續治療。很適合持續受到傷害的人。",
	["Cura poco a poco. Ponla en quien recibe daño."] = "持續治療。給正在受傷的人加上。",
	["Curación"] = "治療",
	["Curación con clic"] = "點擊治療",
	["Curación: arrastra para mover"] = "治療：拖曳以移動",
	["Curandero"] = "治療者",
	["Curar con un clic"] = "點擊治療",
	["Curar y seleccionar"] = "治療並選取",
	["Curas"] = "你負責治療",
	["Curas que van llegando"] = "即將到達的治療",
	["Cursor"] = "游標",
	["Cuándo"] = "時間",
	["Cuándo vuelve sola detrás de tu personaje."] = "何時自動轉回你的角色身後。",
	["Cuánta lluvia, nieve y polvo se ve cuando hay mal tiempo."] = "天氣惡劣時能看到多少雨、雪與塵土。",
	["Cuánta memoria usa cada parte de Alfa ahora, y suelta la que ya no ocupa. También con /alfa rendimiento."] = "查看 Alfa 各部分目前使用多少記憶體，並釋放不再需要的部分。也可以用 /alfa rendimiento。",
	["Cuántas capas de sombra se dibujan: con más capas, las sombras nítidas llegan más lejos."] = "繪製多少層陰影：層數越多，清晰的陰影延伸得越遠。",
	["Cuántas casillas caben en cada fila."] = "每一列放幾格。",
	["Cuántas casillas libres quedan cuando Alfa te avisa."] = "剩餘幾個空格時 Alfa 會提醒你。",
	["Cuántas habilidades después"] = "後續顯示幾個技能",
	["Cuánto daño quita cada bloqueo; también sube el daño de Embate con escudo."] = "每次格擋能減免多少傷害；也會提高盾牌猛擊的傷害。",
	["Cuánto dura un aviso en pantalla"] = "提醒在畫面上停留的時間",
	["Cuánto falta para tu siguiente golpe automático, con cada mano. Ayuda a meter Embate o Golpe heroico sin perder golpes."] = "顯示每隻手距離下次自動攻擊還有多久。有助於插入猛擊或英勇打擊而不浪費攻擊。",
	["Cuánto más brillan las luces que en una pantalla normal. El juego no pasa del máximo de tu monitor."] = "光源比一般螢幕亮多少。遊戲不會超過你螢幕的最大亮度。",
	["Cuánto oro"] = "多少金幣",
	["Cuánto pasto, flores y hierbas cubren el suelo."] = "地面上覆蓋多少草、花與雜草。",
	["Cuánto por debajo de lo que vale tiene que estar tu precio para avisarte."] = "你的價格要比價值低多少才提醒你。",
	["Cuánto se ve el fondo de las ventanas de chat; en cero solo queda el borde."] = "聊天視窗背景的可見程度；為零時只剩邊框。",
	["Cuánto te ayuda Alfa"] = "Alfa 幫多少",
	["Cuánto te falta para el 60 a tu ritmo, qué guías y mazmorras te tocan y cuánto avanzas cada día."] = "照你的節奏離 60 級還有多遠、哪些指南和地城適合你，以及你每天升了多少。",
	["Cuántos"] = "數量",
	["Cuántos consejos"] = "建議數量",
	["Cuántos en el top"] = "排行顯示人數",
	["Cuántos se anuncian"] = "通報人數",
	["Cuántos tienes, en el cuadro de cada objeto"] = "在每件物品的滑鼠提示中顯示持有數量",
	["Cuántos van en cada columna (o fila) antes de empezar otra. 5 es un grupo por columna."] = "每欄（或每列）放幾人後再開新的一欄。5 表示每欄一個小隊。",
	["Cuéntame algo"] = "跟我說點什麼",
	["Cuéntame algo de aquí"] = "跟我說說這裡",
	["Cuéntanos qué te parece en La Jauría."] = "歡迎在 La Jauría 告訴我們你的想法。",
	["Cálido"] = "暖色",
	["Cámara"] = "鏡頭",
	["Cámbialo en el menú del juego: Opciones > %s > «%s». Alfa no lo cambia por ti: el juego lo lee en combate y fallaría."] = "請在遊戲選單中變更：選項 > %s > 「%s」。Alfa 不會替你變更：遊戲會在戰鬥中讀取它，改了會出錯。",
	["Cólera de las bestias: tu mascota pega mucho más un rato."] = "野獸狂怒：你的寵物在一段時間內傷害大增。",
	["Cómo cambiarlo"] = "如何變更",
	["Cómo conseguir cualquier objeto, misión o PNJ, y qué guía te lleva ahí."] = "如何取得任何物品、任務或找到 NPC，以及哪個指南能帶你過去。",
	["Cómo conseguir cualquier objeto, montura, PNJ, misión o lugar."] = "如何取得任何物品、坐騎，或找到 NPC、任務與地點。",
	["Cómo conseguirla"] = "如何取得",
	["Cómo conseguirlo"] = "取得方式",
	["Cómo decide Alfa"] = "Alfa 如何判斷",
	["Cómo encenderlo"] = "如何開啟",
