	["Cómo hacer oro"] = "如何賺金幣",
	["Cómo juego"] = "我的玩法",
	["Cómo se consigue"] = "如何取得",
	["Cómo se ganan"] = "如何賺取",
	["Cómo se mueve"] = "移動方式",
	["Cómo se usa"] = "使用方式",
	["Cómo se ven las zonas sin descubrir"] = "未探索區域的顯示方式",
	["Cómo subir"] = "如何升級",
	["Cómo subirla"] = "如何提升",
	["Cómo trabaja tu ruta"] = "你的路線如何運作",
	["Cómo ves Alfa"] = "Alfa 的顯示方式",
	["Cómprala con un vendedor."] = "向商人購買。",
	["Cópialo con Ctrl+C y guárdalo, o pásaselo a la manada. Para traerlo de vuelta: «Importar»."] = "用 Ctrl+C 複製並保存，或分享給狼群。要恢復它：「匯入」。",
	["Cópialo con Ctrl+C. Luego abre «Hermandad y comunidades», elige %s, pulsa «Invitar a miembro» y pégalo con Ctrl+V."] = "用 Ctrl+C 複製。然後打開「公會與社群」，選擇%s，點擊「邀請成員」並用 Ctrl+V 貼上。",
	["Cópialos con Ctrl+C y pégalos en tu reporte. «Reportar» ya los lleva."] = "用 Ctrl+C 複製並貼到你的回報裡。「回報」裡已經包含了。",
	["DPS"] = "DPS",
	["DPS del arma"] = "武器 DPS",
	["Daga"] = "匕首",
	["Dale de comer a tu mascota para que esté contenta y pegue más."] = "餵食你的寵物，讓牠保持開心、打得更痛。",
	["Dale de comer para que esté feliz: pega más fuerte."] = "餵食讓牠保持高興：牠的攻擊會更強。",
	["Dame clic derecho y elige «¿En qué te ayudo?» cuando quieras. ¡Buena caza, lobo!"] = "隨時右鍵點我，選擇「我能幫你什麼？」。狩獵愉快，狼！",
	["Dar a las barras el estilo de Alfa"] = "讓快捷列使用 Alfa 風格",
	["Dar al chat el estilo de Alfa"] = "讓聊天使用 Alfa 風格",
	["Dar al minimapa el estilo de Alfa"] = "讓小地圖使用 Alfa 風格",
	["Darle una salchicha"] = "給她一根香腸",
	["Darnassus está en las ramas de Teldrassil. La suma sacerdotisa Tyrande Susurravientos gobierna desde el Templo de la Luna."] = "達納蘇斯位於泰達希爾的枝幹上。大祭司泰蘭妲·語風在月神殿統治。",
	["Dath'Remar Caminante del Sol guió a los altos elfos hasta Quel'Thalas. De su linaje viene el príncipe Kael'thas."] = "達斯雷瑪·逐日者帶領高等精靈來到奎爾薩拉斯。凱爾薩斯王子就是他的後裔。",
	["Datos"] = "資料",
	["Datos curiosos"] = "趣聞",
	["Datos curiosos de Lya, escritos por Alfa."] = "Lya 的趣聞，由 Alfa 撰寫。",
	["Daño"] = "傷害輸出",
	["Daño a distancia"] = "遠程傷害",
	["Daño a todos los que están cerca de ti. Para cuando te rodean."] = "傷害你身邊的所有敵人。被包圍時用。",
	["Daño arcano al instante y un rato más. Bueno para empezar o mientras corres."] = "瞬發秘法傷害，並持續造成更多傷害。適合開怪或移動時用。",
	["Daño con el tiempo: ponla al empezar la pelea."] = "持續傷害：戰鬥開始時施放。",
	["Daño de arcos, armas de fuego y ballestas."] = "弓、槍械與弩的傷害。",
	["Daño de escarcha que deja lento al enemigo. Perfecto si huye."] = "緩速敵人的冰霜傷害。牠想逃跑時完美。",
	["Daño de escarcha que deja lento al enemigo. Tu hechizo para mantenerlo lejos."] = "緩速敵人的冰霜傷害。讓牠離你遠一點的法術。",
	["Daño de fuego al instante. Úsalo para rematar o mientras te mueves."] = "瞬發火焰傷害。用來收尾或移動中使用。",
	["Daño de fuego con el tiempo."] = "持續火焰傷害。",
	["Daño de fuego que quema un rato. Bueno para empezar la pelea."] = "持續燃燒的火焰傷害。適合開場使用。",
	["Daño de sombra durante un buen rato. Ponla al inicio."] = "持續很久的暗影傷害。先上這個。",
	["Daño de sombra durante un rato. Ponla al inicio y sigue con otra cosa."] = "持續的暗影傷害。先上這個，再去做別的。",
	["Daño de sombra fuerte. Buen golpe para empezar o para rematar."] = "強力的暗影傷害。適合開場或收尾。",
	["Daño de sombra que hace lento al enemigo. Canalízalo mientras se acerca."] = "緩速敵人的暗影傷害。在牠衝向你時引導。",
	["Daño del arma"] = "武器傷害",
	["Daño directo de fuego y sombras: matas antes de que el monstruo llegue."] = "火焰與暗影的直接傷害：在怪物靠近前就把它打死。",
	["Daño directo de tus armas y habilidades."] = "你的武器與技能造成的直接傷害。",
	["Daño en grupo de cinco: pegar fuerte sin robarle los monstruos al tanque."] = "五人隊伍的輸出：打得痛，但不搶坦克的仇恨。",
	["Daño extra después de recibir críticos."] = "受到致命一擊後造成額外傷害。",
	["Daño extra después de recibir un golpe crítico."] = "受到致命一擊後造成額外傷害。",
	["Daño o curas"] = "傷害或治療",
	["Daño periódico"] = "週期性傷害",
	["Daño por segundo"] = "每秒傷害",
	["Daño rápido que también interrumpe hechizos. Úsalo con quien lanza magia."] = "快速的傷害，還能打斷法術。對施法者使用。",
	["Daño sagrado fuerte contra no-muertos y demonios."] = "對不死族和惡魔造成強力神聖傷害。",
	["Daño sobre tus enemigos"] = "敵人身上的傷害",
	["De %d a %d"] = "從 %d 到 %d",
	["De %s"] = "來自 %s",
	["De %s, %s"] = "來自 %s，%s",
	["De 1 a 300"] = "從 1 到 300",
	["De 1 a 300, dónde pescar cerca de ti, equipo, cebos, misiones y el concurso."] = "從 1 到 300、你附近哪裡能釣魚、裝備、魚餌、任務與大賽。",
	["De 1 a 300: qué hacer, con qué y dónde aprender"] = "從 1 到 300：做什麼、用什麼、去哪學",
	["De 15 minutos a 4 horas."] = "從 15 分鐘到 4 小時。",
	["De Forever"] = "來自 Forever",
	["De La Jauría"] = "La Jauría 成員",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono. Lo que el juego hace brillar pasa al frente; las de área salen con varios enemigos peleando. Solo aparecen las que ya aprendiste."] = "由上到下：遊戲允許你使用的第一個就是圖示上顯示的那個。遊戲點亮的技能會排到最前面；多個敵人參戰時會出現範圍技能。只顯示你已學會的技能。",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono; las de área, solo con 3 o más enemigos peleando."] = "從上到下：遊戲允許你使用的第一個技能會顯示在圖示上；範圍技能只在 3 個以上敵人參戰時使用。",
	["De clase"] = "職業",
	["De clase: %s"] = "職業：%s",
	["De donde estés a cualquier lugar, con vuelos, barcos, zepelines, portales y a pie, y la lista de tramos."] = "從你所在的地方去任何地方：飛行、船隻、飛艇、傳送門和步行，並列出每一段。",
	["De este lugar Lya todavía no sabe datos curiosos. Elige una misión de la lista para leer su historia."] = "Lya 還不知道這個地方的趣聞。從清單中選一個任務來讀它的故事吧。",
	["De este lugar todavía no sé mucho. ¿Vemos tus historias?"] = "這個地方我還不太了解。要看看你的故事嗎？",
	["De fábrica el seguimiento muestra solo lo que estás haciendo; encendido, muestra el paso completo con sus notas."] = "預設情況下追蹤器只顯示你正在做的事；開啟後會顯示完整步驟及其備註。",
	["De la base de datos incluida"] = "來自內建資料庫",
	["De la otra facción"] = "另一陣營",
	["De los que se presumen"] = "值得炫耀的一條",
	["De misión"] = "任務物品",
	["De nivel %.1f a %.1f, con unos %s de oro. Solo misiones que ya puedes tomar; lo que pide más nivel va después de un paso que lo espera."] = "從 %.1f 級到 %.1f 級，約可賺 %s 金幣。只包含你現在就能接的任務；需要更高等級的任務會放在等待升級的步驟之後。",
	["De noche Durotar refresca y se ven muchas estrellas desde Orgrimmar."] = "杜洛塔的夜裡涼了下來，從奧格瑪能看到滿天星星。",
	["De noche Teldrassil se llena de luciérnagas. Los elfos de la noche están en su hora."] = "泰達希爾的夜裡滿是螢火蟲。這是夜精靈的時刻。",
	["De noche Un'Goro ruge. Los diablosaurios del cráter no duermen nunca."] = "安戈洛的夜裡一片咆哮。環形山裡的魔暴龍從不睡覺。",
	["De noche Vallefresno brilla con luz de luna. Los furbolg duermen... casi todos."] = "夜裡的梣谷在月光下閃閃發亮。熊怪都睡著了…差不多全都睡了。",
	["De noche en Cuna del Invierno la aurora pinta el cielo. Vale la pena verla un ratito."] = "冬泉谷的夜裡，極光把天空染上顏色。值得停下來看一會兒。",
	["De noche en Dun Morogh la nieve cruje bajo las patas. Me encanta ese sonido."] = "丹莫洛的夜裡，雪在我腳掌下嘎吱作響。我好喜歡那個聲音。",
	["De noche en Elwynn se oyen los lobos del bosque. Tranquilo: son primos lejanos."] = "艾爾文森林的夜裡能聽到森林狼的聲音。別擔心：牠們是我的遠房親戚。",
	["De noche en Los Humedales croan las ranas y los raptores acechan entre los juncos."] = "濕地的夜裡青蛙呱呱叫，迅猛龍潛伏在蘆葦叢裡。",
	["De noche en Mulgore el viento canta entre las mesetas. Los tauren dicen que es la Madre Tierra."] = "莫高雷的夜裡，風在台地之間歌唱。牛頭人說那是大地之母。",
	["De noche en Tanaris la arena se enfría rápido. Cuidado con los escorpiones."] = "塔納利斯的夜裡，沙子涼得很快。小心蠍子。",
	["De noche en el Bosque del Ocaso los worgen salen a cazar. No te separes de mí."] = "暮色森林的夜裡狼人會出來狩獵。待在我身邊。",
	["De noche en las Tierras de la Peste los muertos caminan más. Quédate junto a la luz."] = "瘟疫之地的夜裡，亡者走動得更多。待在亮光附近。",
	["De noche los Defias se mueven por los Páramos. Mira bien antes de entrar a una granja."] = "夜裡迪菲亞會在西部荒野活動。進農場前仔細看看。",
	["De todo %s, ¿qué rincón te gusta más?"] = "整個%s，你最喜歡哪個角落？",
	["De tu gente todavía no sé mucho. ¿Te cuento otra cosa?"] = "關於你的族人，我知道的還不多。要我說點別的嗎？",
	["De tu nivel al 60, a tu ritmo"] = "照你的節奏，從現在的等級到 60 級",
	["De vez en cuando Lya te pide una. Te las tiene bien contadas."] = "莉婭時不時會向你要一根。她數得清清楚楚。",
	["Debajo del ícono: útil mientras aprendes."] = "顯示在圖示下方：學習時很實用。",
	["Dedo"] = "手指",
	["Defensa"] = "防禦",
	["Deja Alt abajo y pasa el ratón por cualquier cosa de Alfa: te digo para qué sirve. La tecla se cambia en Estilo y sonido."] = "按住 Alt，把滑鼠移到 Alfa 的任何東西上：我會告訴你它有什麼用。按鍵可以在「風格與音效」中變更。",
	["Deja esta tecla abajo y pasa el ratón por cualquier cosa de Alfa: te digo para qué sirve."] = "按住這個鍵，把滑鼠移到 Alfa 的任何東西上：我會告訴你它有什麼用。",
	["Deja que el tanque golpee primero unos segundos antes de usar tus golpes fuertes."] = "先讓坦克打幾秒，再使用你的強力攻擊。",
	["Deja que la manada te vea en el mapa"] = "讓狼群在地圖上看到你",
	["Deja que tu mascota empiece la pelea y dispara cuando el monstruo la esté atacando."] = "讓寵物先開打，等怪物在攻擊牠時再射擊。",
	["Deja solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "只保留必要內容：你、你的隊伍、你的標記與指南的下一步。",
	["Deja una nota en tu mapa donde estás (/alfa nota <texto>)"] = "在你站的位置的地圖上留筆記（/alfa nota <內容>）",
	["Dejar"] = "停止",
	["Dejar de seguir"] = "停止跟隨",
	["Dejar de seguirlo"] = "停止跟隨它",
	["Dejar el chat"] = "保留聊天",
	["Dejar el minimapa"] = "保留小地圖",
	["Dejar el plan"] = "放棄計畫",
	["Dejar la vuelta"] = "退出交任務路線",
	["Dejarlo como recomienda Alfa"] = "使用 Alfa 的建議設定",
	["Dejarlo ir"] = "放它走",
	["Dejaste la vuelta: la flecha vuelve a tu guía."] = "你退出了路線：箭頭回到你的指南。",
	["Dejaste una nota en tu mapa: «%s»."] = "你在地圖上留了一則筆記：「%s」。",
	["Dejé %d cartas que se abren a mano (pago contra entrega o de un MJ)."] = "留下了 %d 封需要手動開啟的郵件（貨到付款或來自 GM）。",
	["Dejé 1 carta que se abre a mano (pago contra entrega o de un MJ)."] = "留下了 1 封需要手動開啟的郵件（貨到付款或來自 GM）。",
	["Del Legado"] = "來自傳承",
	["Del agua"] = "來自水中",
	["Del color del estilo"] = "使用風格顏色",
	["Del motor de Alfa: al subir de nivel te muestra qué aprender y cuánto cuesta."] = "來自 Alfa 的核心：升級時顯示可以學什麼、要花多少錢。",
	["Del motor de Alfa: con el entrenador más cercano en tu camino."] = "來自 Alfa 的核心：並標出你路上最近的訓練師。",
	["Del preajuste"] = "來自預設方案",
	["Demonología"] = "惡魔學識",
	["Demonología para subir"] = "惡魔學識（練等）",
	["Densidad de partículas"] = "粒子密度",
	["Dentro"] = "副本內",
	["Dentro de"] = "位於",
	["Dentro de %s (mazmorra)"] = "在%s內（地城）",
	["Dentro de la mazmorra"] = "在地城內",
	["Dentro de mazmorras y ciudades no hay nodos. Sal al mundo y tu ruta se arma en un clic."] = "地城與城市中沒有採集點。去野外，點一下就能建立你的路線。",
	["Dentro de una instancia el juego no deja compartir: sale solo cuando salgas."] = "在副本中遊戲不允許分享：離開後會自動傳送。",
	["Dentro de una instancia no hay planos."] = "副本裡沒有位面。",
	["Dentro de una instancia no se puede seguir a nadie."] = "在副本中無法跟隨任何人。",
	["Dentro de una mazmorra, al apuntar a un jefe sale una tarjeta chica con lo que te toca según tu papel y cómo van tus misiones de ahí. No atrapa clics."] = "在地城裡選取首領時，會顯示一張小卡片，告訴你該職責要做什麼，以及你在這裡的任務進度。它從不擋住點擊。",
	["Dentro de una mazmorra, apunta al jefe: arriba te sale una tarjeta con lo que te toca según tu papel y cómo van tus misiones de ahí."] = "在地城裡選取首領：頂部會顯示一張卡片，告訴你該職責要做什麼，以及你在這裡的任務進度。",
	["Depositar"] = "存放",
	["Depositar rápido"] = "快速存放",
	["Depósito detenido: guardaste %d."] = "存放已停止：你存入了 %d 件。",
	["Derecho"] = "右鍵",
	["Derrota a %s"] = "擊敗%s",
	["Derrotar al último jefe de todas las mazmorras de un rango de niveles da un punto del Legado por cada rango."] = "擊敗某個等級段內所有地城的最終首領，每個等級段可獲得一點傳承點數。",
	["Desapareces y vuelves al sigilo, aun en combate. Tu escape de emergencia."] = "你重新進入潛行，即使在戰鬥中也行。你的緊急脫身技。",
	["Desarmar más seguido: quitas el arma a los enemigos que pegan fuerte."] = "更常繳械：卸下那些打很痛的敵人的武器。",
	["Desbloquear %s"] = "解鎖%s",
	["Desbloquear posición"] = "解鎖位置",
	["Descansa en una posada o una ciudad para juntar más."] = "在旅店或城鎮中休息可以累積更多。",
	["Descansa hasta que la llames"] = "休息中，等你召喚",
	["Descansando"] = "休息中",
	["Descansando%s%d%% de un nivel"] = "休息中%s已累積一級的 %d%%",
	["Descansando: %d %%"] = "休息中：%d %%",
	["Descanso"] = "休息",
	["Descanso %d %%"] = "休息經驗 %d %%",
	["Desconectado"] = "離線",
	["Descontenta"] = "不高興",
	["Descubrir aquí te dio %d de experiencia la última vez."] = "上次在這裡探索給了你 %d 點經驗。",
	["Descubrirlo te da experiencia."] = "探索它能獲得經驗。",
	["Descubriste a %s"] = "你發現了%s",
	["Descubriste a %s (%s)."] = "你發現了%s（%s）。",
	["Desde Auberdine sale un barco al muelle de Rut'theran, al pie de Teldrassil."] = "從奧伯丁有船開往泰達希爾腳下的魯瑟蘭碼頭。",
	["Desde cero"] = "從頭開始",
	["Desde cuántas habilidades"] = "達到幾個技能時提醒",
	["Desde cuántos segundos"] = "從多少秒起",
	["Desde el nivel 10"] = "10 級開放",
	["Desde el nivel 20"] = "20 級開放",
	["Desde el nivel 20, desuellas bestias de hasta tu habilidad dividida entre 5. Necesitas un cuchillo de desollar."] = "從 20 級開始，你能剝皮的野獸等級最高為技能值除以 5。需要一把剝皮小刀。",
	["Desde el sigilo y por la espalda: lo hace sangrar un buen rato."] = "潛行時從背後使用：讓牠流血好一陣子。",
	["Desde el sigilo y por la espalda: un golpe enorme para empezar."] = "潛行時從背後使用：威力巨大的開場一擊。",
	["Desde el sigilo: aturde al enemigo unos segundos para empezar con ventaja."] = "潛行時使用：讓敵人昏迷幾秒，讓你搶先一步。",
	["Desde hoy apunto cada paso grande que demos juntos."] = "從今天起，我會記下我們一起邁出的每一大步。",
	["Desde nivel %d"] = "%d 級起",
	["Desde siempre"] = "累計",
	["Desde tu última visita también hubo cambios en %s: los ves en «Ver todo lo nuevo»."] = "自你上次來訪後，%s也有了變化：可以在「查看所有新內容」中看到。",
	["Desencanta los objetos verdes y azules que no uses para sacar polvos, esencias y fragmentos."] = "分解用不上的綠色和藍色物品，可以得到粉塵、精華和碎片。",
	["Desencantar ≈ %s"] = "分解 ≈ %s",
	["Desencantar: ≈ %s por objeto%s. Pide Encantamiento %d."] = "分解：每件約 %s%s。需要附魔 %d。",
	["Deseo de muerte: mucho más daño un rato; úsalo en peleas largas."] = "死亡之願：一段時間內傷害大增；在持久戰中使用。",
	["Desgarrar hace más daño mientras el monstruo sangra; lo necesitas para Heridas profundas."] = "怪物流血時撕裂造成更多傷害；點重傷需要它。",
	["Desgarrar hace más daño; lo necesitas para Heridas profundas."] = "撕裂造成更多傷害；點重傷需要它。",
	["Desgarrar te prepara más Abrumar: más golpes que no se pueden esquivar."] = "撕裂讓你有更多機會使用壓制：更多無法被閃躲的攻擊。",
	["Deshacer"] = "復原",
	["Deshacer preajuste"] = "復原預設",
	["Desmarca las metas hechas de este personaje (las que ya se cumplen se vuelven a marcar solas)."] = "取消此角色已完成目標的勾選（已經達成的會自動重新勾選）。",
	["Desmarcar"] = "取消標記",
	["Desollar es de las formas más fáciles de hacer oro mientras subes de nivel."] = "剝皮是升級時最容易賺金幣的方法之一。",
	["Desollar y Peletería van de la mano: tú consigues el cuero y tú lo trabajas."] = "剝皮和製皮相輔相成：自己剝皮，自己加工。",
	["Despojar más rápido"] = "更快拾取",
	["Después"] = "稍後",
	["Después de"] = "之後",
	["Después de cada golpe, regresa a tu lugar rápido."] = "每次被擊退後，盡快回到原位。",
	["Después de estos siguen %d más."] = "之後還有 %d 個。",
	["Después de otra"] = "需先完成另一個",
	["Después de tu segunda pelea, aquí ves la de antes."] = "第二場戰鬥後，這裡會顯示上一場。",
	["Después de un crítico atacas más rápido: más golpes, más ira."] = "致命一擊後攻擊速度加快：攻擊更多次、怒氣更多。",
	["Después de él se encienden los braseros del altar y llegan oleadas de enemigos: prepárense antes."] = "打完他之後，點燃祭壇的火盆會引來一波波敵人：先做好準備。",
	["Después del combate"] = "戰鬥結束後",
	["Después del primer jefe, un prisionero de tu facción abre la puerta: háblale."] = "打完第一個首領後，你陣營的囚犯會打開大門：和他交談。",
	["Después sigue"] = "接下來",
	["Después: %d %% del nivel %d"] = "之後：%d %%（%d 級）",
	["Después: nivel %d"] = "之後：%d 級",
	["Destierra a un demonio o elemental un rato. Buen control en mazmorras."] = "放逐一個惡魔或元素一段時間。地城裡很好的控制技。",
	["Destino"] = "目的地",
	["Destrucción"] = "毀滅",
	["Destrucción para subir"] = "毀滅（練等）",
	["Desuellas lo que matas y lo conviertes en armaduras de cuero para ti; lo que sobra se vende."] = "剝下你擊殺獵物的皮，做成自己穿的皮甲；多的拿去賣。",
	["Desuello"] = "剝皮",
	["Desuello es su mejor pareja. Los hilos y la sal los venden los proveedores de peletería."] = "剝皮是它最好的搭檔。製皮用品商人出售線和鹽。",
	["Desvanecer objetos lejanos"] = "淡化遠處物體",
	["Desvías golpes con tu arma."] = "用你的武器招架攻擊。",
	["Detalle al pasar el ratón"] = "滑鼠指向時顯示詳細資訊",
	["Detalle de la guía"] = "指南詳情",
	["Detalle de los edificios"] = "建築細節",
	["Detalle de los objetos"] = "物體細節",
	["Detalle del agua"] = "水面細節",
	["Detalle del terreno"] = "地形細節",
	["Detalle fino"] = "精細細節",
	["Detener"] = "停止",
	["Detener (%d/%d)"] = "停止（%d/%d）",
	["Detrás de «%s» hay más de lo que parece. ¿Te la cuento?"] = "「%s」背後比看起來的還要多。要我說給你聽嗎？",
	["Devolver"] = "復位",
	["Devolver los avisos a su lugar"] = "將提醒移回原位",
	["Devolverlos todos"] = "全部恢復",
	["Devuelve cada ajuste que Alfa tocó al valor que tenía antes y deja de mantenerlos."] = "把 Alfa 變動過的每項設定恢復為之前的數值，並停止保留它們。",
	["Devuelve los valores que tenías antes del último preajuste."] = "恢復上一次套用預設之前的數值。",
	["Diario"] = "日誌",
	["Diario de mazmorras"] = "地城導覽手冊",
	["Diario de pesca"] = "釣魚圖鑑",
	["Dibuja el arte completo de cada zona recortado a su forma, con las texturas de detalle incluidas. Sin ellas el mapa sigue completo, solo más suave entre zona y zona."] = "使用內建的細節材質，依各地區的形狀繪製完整的地圖美術。沒有這些材質時地圖依然完整，只是地區之間的交界較模糊。",
	["Dibuja la ruta hasta tu objetivo: por dónde caminar, volar o navegar."] = "繪製前往目標的路線：在哪裡步行、飛行或搭船。",
	["Dice en el chat qué misión perderías y te deja aceptarla a ti."] = "在聊天中說明你會失去哪個任務，並由你決定是否接受。",
	["Dicen que el Bosque del Ocaso se oscureció por estar tan cerca de Karazhan, y desde entonces vive en penumbra."] = "據說暮色森林因為離卡拉贊太近而變暗，從此一直籠罩在昏暗之中。",
	["Dicen que en Thelsamar venden morcilla. ¡Es casi una salchicha! Solo digo."] = "聽說塞爾薩瑪有賣血腸。那差不多就是香腸嘛！我只是說說。",
	["Dices cuánto vas a jugar y Alfa arma tu plan: entregar, cerrar misiones, una mazmorra si cabe y lo demás."] = "告訴 Alfa 你要玩多久，它會幫你擬定計畫：交任務、完成任務、時間夠的話來個地城，以及其他。",
	["Diestro"] = "熟練",
	["Diez mil años atrás, Illidan creó en la cima de Hyjal un nuevo Pozo de la Eternidad, y sobre él se plantó Nordrassil."] = "一萬年前，伊利丹在海加爾山頂創造了一口新的永恆之井，諾達希爾就種在它上面。",
	["Diez niveles juntos. Ya hueles a aventura."] = "一起升了十級。你身上已經有冒險的味道了。",
	["Dinero de toda la cuenta"] = "整個帳號的金錢",
	["Dinero de tus personajes"] = "你各角色的金錢",
	["Disciplina"] = "戒律",
	["Disciplina para subir"] = "戒律（練等）",
	["Dispara desde lejos: alguien debe ir por él."] = "他會從遠處射擊：要有人過去把他拉過來。",
	["Disparas mucho más rápido un rato. Guárdalo para los jefes."] = "一段時間內射擊速度大幅提高。留給首領用。",
	["Disparo apuntado: tu disparo más fuerte."] = "瞄準射擊：你最強的射擊。",
	["Disparo arcano: instantáneo, úsalo cuando esté listo."] = "秘法射擊：瞬發，冷卻好就用。",
	["Disponible a nivel %d"] = "%d 級可接",
	["Distancia"] = "遠程",
	["Distancia a la que ciudades, torres y cuevas conservan su detalle."] = "城市、塔樓與洞穴保留細節的距離。",
	["Distancia a la que el suelo conserva su forma completa."] = "地面保留完整形狀的距離。",
	["Distancia de las placas"] = "名條距離",
	["Distancia de visión"] = "視距",
	["Distancia del pasto"] = "草地距離",
	["Distancia y velocidad"] = "距離與速度",
	["Doble clic derecho"] = "右鍵雙擊",
	["Doble clic derecho para lanzar"] = "右鍵雙擊即可拋竿",
	["Doble clic mientras pescas vuelve a lanzar"] = "釣魚時雙擊會再次拋竿",
	["Dolanaar es la aldea élfica en el camino a Darnassus; su posada huele a bosque."] = "多蘭納爾是通往達納蘇斯路上的精靈村莊；那裡的旅店聞起來有森林的味道。",
	["Domestica una bestia para que sea tu compañera. Elige una de tu nivel o menos."] = "馴服一隻野獸當你的夥伴。選等級跟你一樣或更低的。",
	["Domingo"] = "星期日",
	["Domingo de concurso"] = "大賽週日",
	["Dominio de bestias"] = "野獸控制",
	["Dominio de bestias para subir"] = "野獸控制（練等）",
	["Donde antes estaba el Pozo de la Eternidad hoy gira el Maelstrom, un remolino eterno en medio del Gran Mar."] = "永恆之井原來所在的地方，如今是大漩渦，在無盡之海中央永不停歇地旋轉。",
	["Donde lo sacas: %s."] = "在哪裡釣到：%s。",
	["Donde más rinde"] = "收益最高的地方",
	["Donde más rinde: %s (nivel %d), y cuenta para %s."] = "收益最高的地方：%s（%d 級），而且算在%s裡。",
	["Donde puedes seguir en varias zonas, toma la recomendada sin preguntar."] = "可以在多個地區繼續時，不詢問直接選擇推薦的那個。",
	["Dormir"] = "睡覺",
	["Dos armas"] = "雙武器",
	["Dos armas y mucha ira. Furia pega más que Armas cuando tiene buen equipo, y Sed de sangre llega al nivel 40. Necesitas dos armas de una mano desde el nivel 20."] = "雙武器與大量怒氣。裝備好的時候，狂怒打得比武器更痛，嗜血在等級 40 解鎖。從等級 20 起需要兩把單手武器。",
	["Dos clics y Alfa te lleva"] = "點兩下，Alfa 就會帶你去",
	["Dos manos"] = "雙手",
	["Dos monstruos a la vez dejan de ser un problema."] = "同時面對兩隻怪不再是問題。",
	["Dos profesiones de recolección: oro constante sin perder tiempo, justo cuando más lo necesitas."] = "兩個採集專業：在你最需要錢的時候，不浪費時間也能穩定賺金幣。",
	["Drek'Thar, el viejo chamán ciego del clan Lobo Gélido, le enseñó a Thrall a hablar con los espíritus. ¡Un sabio de los lobos!"] = "霜狼氏族年邁的盲眼薩滿德雷克塔爾教會了索爾與靈魂交談。狼族的智者！",
	["Drenar alma al rematar te da uno."] = "以吸取靈魂完成擊殺可獲得一個。",
	["Druida"] = "德魯伊",
	["Druidas, guerreros y pícaros: si tu barra de forma o de actitud está vacía, Alfa te avisa y la llena con un clic."] = "德魯伊、戰士與盜賊：如果你的形態或姿態快捷列是空的，Alfa 會提醒你，並一鍵幫你填滿。",
	["Duelos"] = "決鬥",
	["Duerme a un enemigo sin pelear. Perfecto para controlar uno en las mazmorras."] = "不用戰鬥就讓敵人失去知覺。在地城控制一個敵人的完美選擇。",
	["Duerme a un jugador y lanza sombras: interrúmpelo."] = "他會催眠一名玩家並施放暗影法術：打斷他。",
	["Duerme a una bestia o a un dragón. Buen control en mazmorras."] = "讓一隻野獸或龍類沉睡。地城裡很好的控制技。",
	["Dun Algaz es el túnel enano que une Los Humedales con Loch Modan."] = "丹阿加茲是連接濕地和洛克莫丹的矮人隧道。",
	["Duplicar"] = "複製",
	["Durabilidad"] = "耐久度",
	["Duración"] = "持續時間",
	["Durante la pelea despierta a guardianes de piedra: alguien debe tanquearlos o mátenlos rápido."] = "戰鬥中他會喚醒石頭守衛：要有人去坦它們，或是盡快殺掉。",
	["Durante siglos los druidas durmieron en el Sueño Esmeralda mientras las Centinelas cuidaban el bosque."] = "數百年來，德魯伊在翡翠夢境中沉睡，哨兵們則守護著森林。",
	["Durotan y su clan Lobo Gélido se negaron a beber la sangre de Mannoroth. Gul'dan nunca se lo perdonó."] = "杜洛坦和他的霜狼氏族拒絕飲下瑪諾洛斯之血。古爾丹從未原諒他。",
	["Durotar lleva el nombre de Durotan, el padre de Thrall y jefe del clan Lobo Gélido. Thrall honró su memoria al nombrar así la tierra de los orcos."] = "杜洛塔以杜洛坦命名，他是索爾的父親，也是霜狼氏族的酋長。索爾用父親的名字為獸人的土地命名，以紀念他。",
	["Dónde"] = "地點",
	["Dónde anda la manada"] = "狼群在哪裡",
	["Dónde aprender Pesca y sus rangos. Se llenan al abrir la guía de pesca."] = "在哪裡學習釣魚及其等級。開啟釣魚指南後就會填入。",
	["Dónde empieza el paisaje lejano simplificado."] = "簡化遠景從哪裡開始。",
	["Dónde entregar"] = "繳交地點",
	["Dónde está"] = "位置",
	["Dónde está cada uno, lo que vende, lo que suelta y sus misiones."] = "每個人的位置、販售的物品、掉落物與任務。",
	["Dónde está lo que pide cada misión de tu grupo y quién la lleva."] = "你隊伍每個任務要做的地方，以及誰接了它。",
	["Dónde mandarlo"] = "傳送到哪裡",
	["Dónde sale"] = "來源",
	["Dónde se entrega"] = "交付地點",
	["Dónde se ven"] = "顯示位置",
	["Editar"] = "編輯",
	["Edwin VanCleef, el jefe Defias, era maestro cantero. Cuando la nobleza no pagó la reconstrucción de Ventormenta, juró venganza."] = "迪菲亞的首領艾德溫·范克里夫曾是石匠大師。貴族們不肯支付重建暴風城的工錢時，他發誓要復仇。",
	["Efecto activo"] = "效果生效中",
	["Efecto del vacío"] = "虛空效果",
	["Efectos"] = "特效",
	["Efectos de pantalla del juego"] = "遊戲的畫面效果",
	["Ej.: Comprar bolsas de 10 casillas"] = "例如：購買 10 格背包",
	["Ejecutar cuesta menos ira: rematas antes."] = "斬殺消耗的怒氣更少：更早收尾。",
	["Ejecutar más barato para rematar jefes."] = "更便宜的斬殺，用來收掉首領。",
	["El Alba Argenta pelea contra la Plaga sin el fanatismo de los Escarlatas, y recibe por igual a la Alianza y a la Horda."] = "銀色黎明與天譴軍團作戰，卻沒有血色十字軍那樣的狂熱，同樣歡迎聯盟和部落。",
	["El Bastión Plumaluna, en una isla frente a la costa, es el puesto de las centinelas élficas."] = "位於近海小島上的羽月要塞，是精靈哨兵的據點。",
	["El Bosque del Ocaso y las Montañas Crestagrana también son tierras del reino, y piden ayuda porque los soldados no alcanzan."] = "暮色森林和赤脊山也是王國的領土，那裡的人們在求援，因為士兵不夠用。",
	["El Campamento Mojache es el hogar de la Horda en Feralas."] = "莫沙徹營地是部落在菲拉斯的家園。",
	["El Castillo de Colmillo Oscuro fue de Arugal, un mago de Dalaran que convocó a los worgen para pelear contra la Plaga y terminó perdiendo la razón."] = "影牙城堡曾屬於阿魯高，他是一位達拉然法師，召喚了狼人來對抗天譴軍團，最後卻失去了理智。",
	["El Claro de la Luna es un santuario de druidas; ahí se reúne el Círculo Cenarion."] = "月光林地是德魯伊的聖地；塞納里奧議會在那裡聚會。",
	["El Codex no sabe de dónde sale; si ya la tienes, la ves en tu diario de monturas."] = "Codex 不知道它從哪裡取得；如果你已擁有，可以在坐騎收藏中看到。",
	["El Cruce es un puesto de la Horda justo en medio de Los Baldíos, donde se juntan los caminos principales. De ahí su nombre."] = "十字路口是部落位於貧瘠之地正中央的據點，幾條主要道路在這裡交會。它的名字就是這麼來的。",
	["El Culto de los Malditos lo fundó Kel'Thuzad: les prometía a los campesinos de Lordaeron una vida eterna y más justa."] = "詛咒神教是科爾蘇加德創立的：他向洛丹倫的農民許諾永恆而更公平的生活。",
	["El Discord de La Jauría"] = "La Jauría 的 Discord",
	["El Festival de Invierno me pone de buenas. Busca al Abuelo Invierno: siempre trae algo para ti."] = "冬幕節讓我心情很好。去找冬天爺爺：他總有東西給你。",
	["El Fuerte Cenarion es la base del Círculo Cenarion en Silithus, frente a los qiraji."] = "塞納里奧城堡是塞納里奧議會在希利蘇斯的基地，正面對著其拉蟲人。",
	["El Gran Manitas Gelbin Mekkatorque es el líder de los gnomos."] = "大工匠格爾賓·梅卡托克是地精的領袖。",
	["El Guardián Remulos, hijo de Cenarius, cuida el Claro de la Luna desde su santuario."] = "塞納留斯之子守護者雷姆洛斯在他的神殿守護著月光林地。",
	["El Horado Rajacieno y la Zahúrda Rajacieno son guaridas de los jabaespines, entre Los Baldíos y Las Mil Agujas."] = "剃刀沼澤和剃刀高地是野豬人的巢穴，位於貧瘠之地和千針石林之間。",
	["El Legado se abre con tu primer punto (casi siempre, al llegar a nivel 25), con la tecla Y o con su botón del menú."] = "獲得第一點後（通常在達到 25 級時）傳承就會開啟，可以按 Y 鍵或透過選單按鈕開啟。",
	["El Loto negro crece solo en zonas de nivel muy alto, y es tan raro que vale una fortuna."] = "黑蓮花只生長在等級很高的地區，稀有到價值連城。",
	["El Loto negro es rarísimo: crece en Cuna del Invierno, las Estepas Ardientes, las Tierras de la Peste del Este y Silithus."] = "黑蓮花極為稀有：生長在冬泉谷、燃燒平原、東瘟疫之地和希利蘇斯。",
	["El Martillo Crepuscular tiene campamentos en Silithus, donde intenta invocar a los señores elementales."] = "暮光之錘在希利蘇斯設有營地，企圖在那裡召喚元素領主。",
	["El Núcleo de Magma, en el fondo de la Montaña Roca Negra, es el hogar de Ragnaros, el Señor del Fuego."] = "熔火之心位於黑石山深處，是炎魔之王拉格納羅斯的家。",
	["El Paso de la Muerte no tiene ni un pueblo: solo ogros, bestias y la sombra de Karazhan."] = "逆風小徑連一個村莊都沒有：只有巨魔、野獸和卡拉贊的陰影。",
	["El Paso de la Muerte une el Bosque del Ocaso con el Pantano de las Penas."] = "逆風小徑連接暮色森林和悲傷沼澤。",
	["El Portal Oscuro está apagado en el Clásico. En Burning Crusade vuelve a abrirse rumbo a Terrallende."] = "黑暗之門在經典版中處於沉寂狀態。到了燃燒的遠征，它會再次開啟，通往外域。",
	["El Portal Oscuro lo abrieron Medivh y Gul'dan juntos, cada uno desde su lado."] = "黑暗之門是麥迪文和古爾丹各自從兩邊一起打開的。",
	["El Puente Thandol, al norte, une Khaz Modan con Arathi; los Hierro Negro lo dejaron medio destruido."] = "北邊的薩多爾大橋連接卡茲莫丹和阿拉希；黑鐵矮人把它毀掉了一半。",
	["El Puerto de Menethil lleva el apellido de la familia real de Lordaeron. De ahí salen barcos a Theramore y a Auberdine."] = "米奈希爾港以洛丹倫王室的姓氏命名。從那裡有船開往塞拉摩和奧伯丁。",
	["El Puesto Hachazo es el campamento de la Horda que tala Vallefresno."] = "碎木崗哨是部落在梣谷伐木的營地。",
	["El Refugio Roca del Sol es el hogar de los tauren en estas montañas."] = "烈日石居是牛頭人在這片山區的家園。",
	["El Refugio de la Zaga es el campamento de la Alianza en Arathi, entre ruinas, trols y ogros."] = "避難谷地是聯盟在阿拉希的營地，周圍是廢墟、食人妖和巨魔。",
	["El Refugio del Mariscal es el único campamento del cráter, y lo comparten todos."] = "馬紹爾營地是火山口裡唯一的營地，所有人共用。",
	["El SI:7 de Ventormenta y Ravenholdt son nombres que todo pícaro conoce."] = "暴風城的軍情七處和拉文霍德是每個盜賊都知道的名字。",
	["El Sepulcro es el puesto de los Renegados en el bosque; desde ahí vigilan a los worgen y a los magos de Dalaran."] = "瑟伯切爾是被遺忘者在森林中的據點；他們從那裡監視狼人與達拉然的法師。",
	["El Sindicato, los nobles caídos de Alterac, también asalta caminos y granjas por estas tierras."] = "辛迪加——奧特蘭克的沒落貴族們——也在這一帶襲擊道路與農場。",
	["El Sueño Esmeralda se está volviendo pesadilla: algo corrompe a los dragones verdes que lo cuidan."] = "翡翠夢境正在變成夢魘：有什麼東西正在腐化守護它的綠龍。",
	["El Tranvía Subterráneo une Forjaz con Ventormenta por debajo de la tierra. Lo construyeron los gnomos."] = "礦道地鐵在地下連接鐵爐堡與暴風城。它是地精建造的。",
	["El Trono Helado es la armadura de hielo donde quedó atrapado Ner'zhul, en lo alto de la Corona de Hielo."] = "冰封王座是囚禁耐奧祖的冰之鎧甲，位於寒冰皇冠之巔。",
	["El Valle Calcinado, al sur de la sierra, quedó quemado y lleno de elementales de fuego."] = "山脈南邊的焦炭谷被燒得焦黑，到處是火元素。",
	["El Vigía de Morgan es el puesto de la Alianza en las estepas, desde donde vigilan la Montaña Roca Negra."] = "摩根的崗哨是聯盟在平原上的據點，他們從那裡監視黑石山。",
	["El aguante es tu mejor amigo: más vida para más Transfusión de vida."] = "耐力是你最好的朋友：生命值越多，就能用越多次生命分流。",
	["El alfa de La Jauría anda cerca"] = "La Jauría的頭狼就在附近",
	["El almirante Daelin Valiente, padre de Jaina, cayó en Theramore tras atacar a la Horda. Su hija eligió la paz."] = "珍娜的父親戴林·普勞德摩爾上將攻擊部落後，戰死在塞拉摩。他的女兒選擇了和平。",
	["El archidruida Fandral Corzocelada enseña en el Enclave Cenarion de Darnassus."] = "大德魯伊范達爾·鹿盔在達納蘇斯的塞納里奧區授課。",
	["El archidruida Fandral Corzocelada plantó Teldrassil con la esperanza de recuperar la inmortalidad que los elfos perdieron en el Monte Hyjal."] = "大德魯伊范達爾·鹿盔種下了泰達希爾，希望找回精靈們在海加爾山失去的永生。",
	["El archidruida Hamuul Tótem de Runa enseña a los druidas tauren, y fue de los primeros tauren aceptados en el Círculo Cenarion."] = "大德魯伊哈繆·符文圖騰教導牛頭人德魯伊，他是最早被塞納里奧議會接納的牛頭人之一。",
	["El arma principal debe ser la más lenta y fuerte; la secundaria, la más rápida."] = "主手武器要選最慢、最強的；副手則選最快的。",
	["El aro y la cabecera del minimapa con tu estilo."] = "小地圖的外框與標題列使用你的風格。",
	["El banco está lleno: compra otra casilla o pon una bolsa más grande en el banco."] = "銀行已滿：購買另一個欄位，或在銀行放一個更大的背包。",
	["El barco a %s ya viene"] = "前往%s的船來了",
	["El barco goblin une Bahía del Botín con Trinquete, y lo pueden usar los dos bandos."] = "哥布林的船往返於藏寶海灣和棘齒城之間，兩個陣營都能搭乘。",
	["El barón Osahendido manda en Stratholme como caballero de la muerte de la Plaga."] = "瑞文戴爾男爵以天譴軍團死亡騎士的身分統治著斯坦索姆。",
	["El blanco de la interfaz y del cielo de día."] = "介面與白天天空的白色。",
	["El bonus de tu arma al máximo."] = "武器類型加成點滿。",
	["El borde del minimapa, redondo o cuadrado («Minimapa cuadrado», arriba), y la barra con la zona y la hora toman el estilo que elijas, como la ventana del mapa. Al apagarlo vuelve el de siempre."] = "小地圖的外框（圓形或方形，見上方「方形小地圖」）以及顯示地區與時間的列會採用你選擇的風格，就像地圖視窗一樣。關閉後恢復原樣。",
	["El borde toma el color del perjuicio (magia, maldición, enfermedad o veneno) cuando tú lo puedes quitar."] = "當你能驅散減益效果時，邊框會顯示其顏色（魔法、詛咒、疾病或中毒）。",
	["El botón «Escanear con Alfa» bajo la ventana de la subasta."] = "拍賣場視窗下方的「用 Alfa 掃描」按鈕。",
	["El brillo más alto que da tu monitor; viene en su caja o su ficha."] = "你的螢幕能達到的最高亮度；可以在包裝盒或規格表上找到。",
	["El brillo suave de luces y cielo en toda la pantalla."] = "整個畫面上燈光與天空的柔和光暈。",
	["El brujo Zalazane les robó las Islas del Eco a los Lanza Negra con su vudú."] = "巫醫札拉贊恩用巫毒術從暗矛部族手中奪走了回音群島。",
	["El buscador"] = "搜尋框",
	["El buscador de Ajustes ya encuentra todo: también Pesca, Comercio, Ruta, Bolsas, Combate, Curación, Lya y Estilo y sonido."] = "設定搜尋現在能找到所有內容：包括釣魚、交易、路線、背包、戰鬥、治療、Lya 以及風格與聲音。",
	["El buscador del motor está apagado (Ajustes > Descubrir): enciéndelo para que Alfa arme guías."] = "核心的查詢已關閉（設定 > 探索）：請開啟，讓 Alfa 能建立指南。",
	["El buscador no está disponible."] = "搜尋功能無法使用。",
	["El buzón"] = "信箱",
	["El calendario de la manada"] = "狼群日曆",
	["El camino a Entrañas pasa por las ruinas de la Ciudad Capital de Lordaeron, donde Arthas mató a su padre."] = "通往幽暗城的路要經過洛丹倫首都的廢墟，阿薩斯就是在那裡殺死了他的父親。",
	["El camino a la meta en el mapa del mundo y el minimapa: una línea o puntos donde caminas, líneas donde vuelas, navegas o montas, y los tramos que siguen más tenues."] = "在世界地圖與小地圖上顯示通往目標的路線：步行處為線條或圓點，飛行、航行或搭乘處為線條，之後的路段較淡。",
	["El camino en el mapa y el minimapa"] = "地圖與小地圖上的路線",
	["El camino hasta el destino dibujado en el mapa."] = "在地圖上畫出前往目的地的路徑。",
	["El camino más sencillo para subir: un arma grande, golpes que hacen sangrar y Golpe mortal al nivel 40. Aguantas bien y matas rápido."] = "最簡單的練等方式：一把大武器、造成流血的攻擊，以及等級 40 的致死打擊。耐打又殺得快。",
	["El camino que baja de la sierra hacia Los Baldíos está lleno de arañas. ¡Brrr!"] = "從山上下到貧瘠之地的路上到處是蜘蛛。嗚！",
	["El chat"] = "聊天",
	["El chat usa la letra de Alfa (la de Ajustes > Apariencia). El tamaño se sigue cambiando en el menú de la pestaña."] = "聊天使用 Alfa 的字型（設定 > 外觀中的那個）。字體大小仍在分頁的選單中變更。",
	["El clan"] = "公會介紹",
	["El clan Lobo Gélido monta lobos de verdad. Por eso es mi clan favorito, no lo voy a negar."] = "霜狼氏族騎的是真正的狼。所以那是我最喜歡的氏族，我不否認。",
	["El clan Lobo Gélido vive exiliado en el valle de Alterac. Thrall, hijo de su antiguo jefe, los encontró ahí después de escapar de Durnholde."] = "霜狼氏族流亡在奧特蘭克山谷。索爾是他們前任酋長的兒子，從敦霍爾德逃出後在那裡找到了他們。",
	["El clic derecho solo sigue alejando el mapa del juego, como siempre."] = "單純按右鍵仍然會像往常一樣縮小遊戲地圖。",
	["El clic izquierdo solo selecciona"] = "左鍵只用來選取目標",
	["El clásico para pelear contra jugadores: Golpe mortal corta las curas del rival, Seccionar mejorado lo deja quieto y Cargar mejorado te da ira para empezar."] = "經典的 PvP 配點：致死打擊降低對手受到的治療，強化斷筋讓他無法動彈，強化衝鋒讓你一開場就有怒氣。",
	["El color de mi clase"] = "我的職業顏色",
	["El comerciante no lo compra"] = "商人不收購",
	["El contenido va en una columna centrada y se acomoda solo si cambias la resolución o la escala."] = "內容顯示在置中的一欄中，改變解析度或介面縮放時會自動調整。",
	["El corcho quedó lejos · relanza con %s"] = "魚漂落得太遠 · 按 %s 重新拋竿",
	["El corcho quedó lejos · vuelve a lanzar"] = "魚漂落得太遠 · 重新拋竿",
	["El cuadro del jugador al pasar el ratón. En combate no sale, para no estorbar."] = "滑鼠指向時顯示玩家的滑鼠提示。戰鬥中不顯示，以免礙事。",
	["El cártel Bonvapor controla Bahía del Botín, Trinquete, Gadgetzan y Vista Eterna. Por eso esos puertos reciben a todos."] = "熱砂港掌控著藏寶海灣、棘齒城、加基森和永望鎮。所以這些港口歡迎所有人。",
	["El daño por segundo de tu arma a distancia."] = "你的遠程武器的每秒傷害。",
	["El daño por segundo del arma: para el guerrero, lo que más cuenta al subir."] = "武器的每秒傷害：對戰士來說，這是練等時最重要的。",
	["El daño se lo come tu maná en vez de tu vida."] = "用你的法力代替生命值承受傷害。",
	["El de tu juego"] = "遊戲本身的",
	["El demosaurio es el gran depredador del cráter: si oyes pasos que retumban, escóndete."] = "魔暴龍是火山口裡最兇猛的掠食者：如果聽到轟隆隆的腳步聲，趕快躲起來。",
	["El destino de la flecha y sus zonas en el minimapa."] = "在小地圖上顯示箭頭的目的地與其區域。",
	["El destino de la flecha, su camino y las otras metas del paso, en el mapa."] = "在地圖上顯示箭頭的目的地、路徑與此步驟的其他目標。",
	["El diario de mazmorras del motor está apagado (Ajustes > Descubrir > Mazmorras)."] = "核心的地城導覽手冊已關閉（設定 > 探索 > 地城）。",
	["El diario de mazmorras está apagado"] = "地城導覽手冊已關閉",
	["El diario está apagado. Préndelo abajo, en «Lo que Lya nota»."] = "日記已關閉。在下方「莉婭注意到的事」中開啟。",
	["El dragón azul Azuregos ronda Azshara, cuidando la magia antigua que quedó en sus ruinas."] = "藍龍艾索雷苟斯在艾薩拉遊蕩，守護著遺跡中殘存的古老魔法。",
	["El druida hace de todo: puedes tanquear, curar o pegar según lo que pida el grupo."] = "德魯伊什麼都能做：可以依隊伍的需要坦怪、治療或輸出。",
	["El emperador Dagran Thaurissan gobierna la Ciudad de Hierro Negro, en las Profundidades de Roca Negra."] = "達格蘭·索瑞森大帝統治著黑石深淵裡的黑鐵之城。",
	["El enemigo esquivó: Abrumar no se puede esquivar y pega fuerte."] = "敵人閃躲了：壓制無法被閃躲，而且傷害很高。",
	["El enemigo esquivó: este golpe cuerpo a cuerpo está listo."] = "敵人閃躲了：這個近戰攻擊已可使用。",
	["El enemigo esquivó: este golpe está listo."] = "敵人閃躲了：這個攻擊已就緒。",
	["El enemigo está encima: golpéalo cuerpo a cuerpo."] = "敵人貼身了：用近戰攻擊它。",
	["El enemigo está lanzando un hechizo: Choque de tierra lo corta."] = "敵人正在施法：地震術可以打斷它。",
	["El enemigo está lanzando un hechizo: aturdirlo lo corta."] = "敵人正在施法：擊暈它就能打斷。",
	["El enemigo está lanzando un hechizo: córtalo con tu escudo."] = "敵人正在施法：用你的盾牌打斷它。",
	["El enemigo está lanzando un hechizo: córtalo."] = "敵人正在施法：打斷它。",
	["El enemigo está lanzando un hechizo: el golpe lo corta."] = "敵人正在施法：這一擊可以打斷它。",
	["El enemigo está por caer: drénale el alma y gana un fragmento."] = "敵人快倒下了：吸取它的靈魂，獲得一個碎片。",
	["El enemigo pega menos. Útil cuando te pega a ti o a tu demonio."] = "敵人的攻擊變弱。牠在打你或你的惡魔時很好用。",
	["El enlace del Discord ya está elegido: cópialo con Ctrl+C y pégalo en tu navegador."] = "Discord 連結已選取：用 Ctrl+C 複製，然後貼到瀏覽器中。",
	["El entrenador de oficio más cercano"] = "最近的專業訓練師",
	["El espíritu te devuelve maná rápido: descansas muy poco."] = "精神讓你快速回復法力：幾乎不用休息。",
	["El estilo del mapa (terreno como el minimapa, o el arte clásico) y las opciones de Mundo."] = "地圖風格（像小地圖一樣的地形，或經典手繪）以及世界的選項。",
	["El estilo que elegiste también puede vestir el chat, el minimapa, las barras de abajo y el mapa. Se apaga cuando quieras y todo vuelve a como estaba."] = "你選擇的風格也可以用在聊天、小地圖、底部的列與地圖上。隨時可以關閉，一切都會恢復原樣。",
	["El final"] = "結局",
	["El final de cada misión"] = "每個任務的結局",
	["El final de la cadena no da objetos."] = "任務鏈的最後不給物品。",
	["El final lo verás al entregarla."] = "交付任務時你就會看到結局。",
	["El fondo se ve deformado a través del agua."] = "透過水面看，水底會變形扭曲。",
	["El fuego pega a todos los de cerca: mantén la vida alta de quienes pelean cuerpo a cuerpo."] = "火焰會打到附近所有人：讓近戰隊友的生命值保持在高檔。",
	["El fundente débil lo venden los proveedores de comercio. Minería te da las piedras y las barras."] = "商業用品商人出售弱效助熔劑。採礦能給你石頭和金屬錠。",
	["El general Drakkisath guarda la entrada a la Guarida Alanegra, en lo alto de la Cumbre de Roca Negra."] = "達基薩斯將軍守衛著黑石塔上層通往黑翼之巢的入口。",
	["El globo de Lya en una sola línea, con sus botones. Pasa el ratón encima para leerlo completo."] = "莉婭的對話泡泡只占一行，帶著按鈕。滑鼠移到上面即可讀完整內容。",
	["El gran cruzado de la Cruzada Escarlata, Saidan Dathrohan, es en realidad el demonio Balnazzar. Lo encuentras en Stratholme."] = "血色十字軍的大十字軍戰士達索漢其實是惡魔巴納札爾。你可以在斯坦索姆找到他。",
	["El guerrero que más daño hace en mazmorras. Con un tanque delante, tus dos armas no paran, y Ejecutar mejorado remata a los jefes."] = "地城中傷害最高的戰士。有坦克在前面時，你的雙武器停不下來，強化斬殺負責收掉首領。",
	["El hacha de Grom Grito Infernal tiene nombre propio, y dicen que aúlla cuando corta el aire. ¡Aullar es cosa seria!"] = "葛羅姆·地獄吼的斧頭有自己的名字，據說它劈開空氣時會發出嚎叫。嚎叫可是很嚴肅的事！",
	["El hierro negro solo se funde en la Forja Negra de las Profundidades de Roca Negra."] = "黑鐵只能在黑石深淵的黑熔爐中熔煉。",
	["El hijo de Cairne, Baine, cuida el poblado Pezuña de Sangre en Mulgore."] = "凱恩的兒子貝恩在莫高雷照看血蹄村。",
	["El idioma, el estilo, lo que Alfa hace sola por ti y La Jauría, con «Cambiar» en cada cosa. También con /alfa bienvenida."] = "語言、風格、Alfa 替你自動做的事以及 La Jauría，每一項都有「變更」。也可以用 /alfa bienvenida。",
	["El izquierdo selecciona y el derecho abre el menú."] = "左鍵選取目標，右鍵開啟選單。",
	["El izquierdo selecciona y el derecho abre el menú. Tus buffs para otros se suman aquí al aprenderlos."] = "左鍵選取目標，右鍵開啟選單。你給別人的增益效果學會後會加到這裡。",
	["El izquierdo selecciona y el derecho abre el menú. Tú eliges el resto."] = "左鍵選取目標，右鍵開啟選單。其餘由你決定。",
	["El izquierdo selecciona y el derecho abre el menú: lo básico, porque tu clase no lanza hechizos sobre sus compañeros."] = "左鍵選取目標，右鍵開啟選單：只有基本設定，因為你的職業不會對隊友施放法術。",
	["El juego elige entre estas según la situación; el ícono te muestra cuál conviene ahora."] = "遊戲會依情況在這些技能中選擇；圖示會顯示現在最適合的那個。",
	["El juego la hizo brillar: es buen momento para usarla."] = "遊戲讓它發光了：現在正是使用的好時機。",
	["El juego manda la imagen en HDR."] = "遊戲以 HDR 輸出畫面。",
	["El juego no aceptó el lote."] = "遊戲沒有接受這一批。",
	["El juego no aceptó esa tecla."] = "遊戲不接受這個按鍵。",
	["El juego no aceptó la prueba."] = "遊戲不接受這次測試。",
	["El juego no da tu posición aquí (en una instancia, por ejemplo)."] = "遊戲在這裡不提供你的位置（例如在副本中）。",
	["El juego no deja cambiar talentos ahora mismo"] = "遊戲目前不允許變更天賦",
	["El juego no deja cocinar desde aquí."] = "遊戲不允許從這裡烹飪。",
	["El juego no deja enviar mensajes en este momento (un encuentro o una partida). Tu rastro vuelve a salir solo cuando termine."] = "遊戲現在不允許傳送訊息（首領戰或比賽中）。結束後你的蹤跡會自動恢復傳送。",
	["El juego no deja que las cuentas de prueba envíen mensajes de addon ni usen canales propios. Tu grupo sí se ve."] = "遊戲不允許試玩帳號傳送插件訊息或使用自訂頻道。你的隊伍仍然看得到。",
	["El juego no dejó cambiar las demás."] = "遊戲不允許變更其餘選項。",
	["El juego no dejó compartir el marcador ahora. Prueba en un momento."] = "遊戲現在不允許分享標記。請稍後再試。",
	["El juego no dejó comprar ese rango."] = "遊戲不允許點這一級。",
	["El juego no dejó entrar al canal oculto de Alfa y, sin hermandad, no hay otro camino para compartir. Alfa lo vuelve a intentar sola en unos minutos. Tu grupo sí se ve."] = "遊戲不允許進入 Alfa 的隱藏頻道，而沒有公會就沒有其他分享方式。Alfa 會在幾分鐘後自動重試。你的隊伍仍然看得到。",
	["El juego no dice si la tienes"] = "遊戲沒有告知你是否擁有",
	["El juego no dio tus puntos todavía: se ven desde que ganas el primero."] = "遊戲還沒有給出你的點數：獲得第一點後就能看到。",
	["El juego no la ofrece ahora mismo."] = "遊戲現在沒有提供它。",
	["El juego no lo dice ahora."] = "遊戲目前沒有提供這項資訊。",
	["El juego no permite usar el medidor ahora."] = "遊戲現在不允許使用傷害統計。",
	["El juego no trae la ayuda de Blizzard, así que Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus efectos y lo que el juego te deja usar. Con 3 o más enemigos cambia a las de área. Tú decides qué presionar."] = "遊戲沒有 Blizzard 的戰鬥輔助，所以 Alfa 依它為%s制定的優先順序給出建議，只讀取你的角色：你的資源、你身上的效果以及遊戲允許你使用的技能。3 個以上敵人時會改用範圍技能。按什麼由你決定。",
	["El juego oculta los números exactos mientras peleas: la barra y la cifra se ven, el detalle al salir de combate."] = "戰鬥中遊戲會隱藏精確數字：可以看到計量條與數值，詳細資訊在脫離戰鬥後顯示。",
	["El juego rechazó confirmar los cambios. Se deshicieron para que tu árbol quede como estaba."] = "遊戲拒絕確認變更。已復原，讓你的天賦樹維持原狀。",
	["El juego solo deja cambiarla fuera de combate."] = "遊戲只允許在非戰鬥狀態下變更它。",
	["El juego te pasó a la %s. Otra gente, otros raros, otros minerales."] = "遊戲把你移到了%s。別的人、別的稀有怪、別的礦。",
	["El juego todavía no carga tu árbol"] = "遊戲還沒載入你的天賦樹",
	["El juego todavía no carga tu árbol."] = "遊戲還沒載入你的天賦樹。",
	["El juego todavía no cargó tus talentos. Espera unos segundos o abre la ventana de talentos (tecla N) una vez."] = "遊戲還沒載入你的天賦。請稍等幾秒，或開啟一次天賦視窗（N 鍵）。",
	["El juego todavía no dio la lista de retos: ábrelo con la tecla Y."] = "遊戲還沒有給出挑戰清單：按 Y 鍵開啟它。",
	["El juego todavía no la abre: se abre con tu primer punto del Legado (casi siempre, al llegar a nivel 25)."] = "遊戲還沒有開放它：獲得第一點傳承點數後開啟（通常在達到 25 級時）。",
	["El juego todavía no tiene los datos de algunos objetos. En un momento aparecen."] = "遊戲還沒有某些物品的資料。稍後就會顯示。",
	["El juego todavía oculta los números o los nombres (pasa en combate y dentro de mazmorras). Inténtalo al salir."] = "遊戲仍在隱藏數字或名稱（戰鬥中與地城內會這樣）。離開後再試。",
	["El lago Lordamere separa el Bosque de Argénteos de las Laderas de Trabalomas y de las Montañas de Alterac."] = "洛丹米爾湖把銀松森林與希爾斯布萊德丘陵和奧特蘭克山脈隔開。",
	["El lago de Loch Modan existe gracias a una enorme presa enana. Si se rompiera, el agua arrasaría las tierras de abajo."] = "洛克莫丹的湖泊靠一座巨大的矮人水壩才得以存在。要是水壩崩塌，洪水會沖毀下游的土地。",
	["El lago del Claro de la Luna se llama Elune'ara, en honor a la diosa de la luna."] = "月光林地的湖叫做伊露恩艾拉湖，以紀念月亮女神。",
	["El lago helado de Kel'Theril guarda ruinas de los Altonato."] = "冰封的凱斯利爾湖保存著上層精靈的遺跡。",
	["El lobo de la intro aúlla de pie sobre la peña, con un aullido largo que otro lobo contesta; y al entrar, Lya llega corriendo a decirte que te extrañó."] = "開場動畫裡的狼站在岩石上長嚎，遠處另一隻狼回應；進入遊戲時，Lya 會跑過來告訴你她很想你。",
	["El lobo te recibe al entrar"] = "進入遊戲時狼來迎接你",
	["El lobo te recibe cada vez que entras al juego, redibujado: cabeza, orejas y hocico de lobo de verdad."] = "每次進入遊戲，重新繪製的狼都會迎接你：真正狼的頭、耳朵和口鼻。",
	["El maestro de vuelo, la posada, reparar, el banco y más, con la flecha."] = "飛行管理員、旅店、修理、銀行等，箭頭帶你去。",
	["El maestro de vuelo, la posada, reparar, el banco y más: el más cercano, con la flecha y la ruta."] = "飛行管理員、旅店、修理、銀行等：最近的那個，附箭頭與路線。",
	["El maestro de vuelo, la posada, reparar, el banco... el más cercano (/alfa cerca ayuda)."] = "飛行管理員、旅店、修理、銀行...最近的那個（/alfa cerca ayuda）。",
	["El mago Rhonin y el dragón Korialstrasz ayudaron a liberar a Alexstrasza en Grim Batol, y ahí quedó destruida el Alma de Demonio."] = "法師羅寧和巨龍克拉蘇斯幫助在格瑞姆巴托解救了雅立史卓莎，惡魔之魂也在那裡被摧毀。",
	["El mago que más daño hace: hechizos de fuego y críticos que queman."] = "傷害最高的法師：火焰法術與會造成灼燒的致命一擊。",
	["El mapa a tu gusto"] = "隨心打造地圖",
	["El mapa abre sin errores con M y se arrastra suave, aunque empieces encima de un ícono."] = "按 M 開啟地圖不再出錯，拖曳也很順暢，即使從圖示上開始拖也一樣。",
	["El mapa de Alfa"] = "Alfa 地圖",
	["El mapa de Alfa muestra el terreno real, con puntos de vuelo, mazmorras, barcos, zepelines y portales."] = "Alfa 的地圖顯示真實地形，並標出飛行點、地城、船隻、飛艇與傳送門。",
	["El mapa de Alfa, el del juego y el minimapa. Si algo te estorba, apágalo aquí; los otros módulos de Alfa agregan sus capas a esta misma lista."] = "Alfa 地圖、遊戲地圖與小地圖。如果有什麼礙事，就在這裡關閉；Alfa 的其他模組也會把它們的圖層加入這個清單。",
	["El mapa del mundo entero con zoom, tus marcadores y un solo control para todo lo que se pinta."] = "可縮放的整個世界地圖、你的標記，以及統一控制地圖上所有內容的開關。",
	["El mapa no se abre en combate."] = "戰鬥中無法開啟地圖。",
	["El mapa se ve más limpio: sin líneas finas entre sus pedazos ni halos oscuros en las orillas de las zonas."] = "地圖更乾淨了：拼塊之間不再有細線，區域邊緣也不再有暗色光暈。",
	["El mar paga"] = "大海有回報",
	["El marco de las barras de experiencia y reputación; el relleno conserva sus colores."] = "經驗條與聲望條的邊框；填充部分保留原本的顏色。",
	["El marco del menú del juego y de las bolsas, abajo a la derecha."] = "右下角遊戲選單與背包的邊框。",
	["El marco del tanque late en rojo cuando le queda menos del 40 % de vida."] = "坦克生命值低於 40 % 時，他的框架會閃紅光。",
	["El mariscal Dughan cuida Villadorada y siempre anda buscando quien le eche la mano con los problemas de Elwynn."] = "治安官杜漢守護著閃金鎮，總在找人幫忙解決艾爾文森林的麻煩。",
	["El medallón bajo cada marca del mapa y del minimapa: el de Alfa o solo el símbolo, sin medallón."] = "地圖與小地圖上每個標記下方的徽章：Alfa 的樣式，或只顯示圖形、不帶徽章。",
	["El medidor de daño aguanta en combate y la ayuda de rotación ya no te pide interrumpir lo que no se puede."] = "傷害統計在戰鬥中不再出問題，輸出循環助手也不再要你打斷無法打斷的東西。",
	["El medidor del juego no tiene números de esta pelea."] = "遊戲的統計沒有這場戰鬥的數據。",
	["El medidor no está disponible"] = "傷害統計無法使用",
	["El mejor que tengas"] = "你最好的那個",
	["El mekigeniero Termochufe, el traidor de Gnomeregan, sigue escondido dentro de la ciudad: es su último jefe."] = "諾姆瑞根的叛徒機械大師瑟瑪普拉格仍躲在城裡：他是那裡的最終首領。",
	["El mentor está apagado (Ajustes de La Jauría)."] = "導師已關閉（La Jauría 設定）。",
	["El menú de la lupa del mapa del juego tiene también todas las capas de Alfa."] = "遊戲地圖的放大鏡選單中也會列出所有 Alfa 圖層。",
	["El menú y las bolsas del juego"] = "遊戲的選單和背包",
	["El mineral se funde en barras en cualquier forja."] = "礦石可以在任何熔爐熔煉成錠。",
	["El minimapa"] = "小地圖",
	["El minimapa de Recolección descansa cuando no tiene nada que mostrar."] = "沒有可顯示的內容時，採集的小地圖會休息。",
	["El minimapa pasa de redondo a cuadrado, con un borde fino. No se recomienda junto con girar el minimapa."] = "小地圖由圓形改為方形，並加上細邊框。不建議與「旋轉小地圖」一起使用。",
	["El mismo arreglo llegó a los asistentes de Ruta y de Curación."] = "同樣的修正也用在了路線與治療助手上。",
	["El mitril abunda en las Tierras Inhóspitas, las Tierras del Interior y Tanaris."] = "荒蕪之地、辛特蘭和塔納利斯有大量秘銀。",
	["El modelo no lleva nada aquí."] = "模型這個欄位沒有裝備。",
	["El modo pesca se abre al salir de combate."] = "脫離戰鬥後會開啟釣魚模式。",
	["El modo prueba se usa fuera de combate."] = "測試模式只能在戰鬥外使用。",
	["El motor no aceptó la guía."] = "核心不接受這個指南。",
	["El motor no puede armar guías ahora."] = "核心現在無法建立指南。",
	["El mundo entero en un mapa"] = "整個世界盡在一張地圖",
	["El mundo pierde el color mientras eres espíritu."] = "你處於靈魂狀態時，世界會失去色彩。",
	["El más bajo que viste, %s."] = "你見過的最低價：%s。",
	["El más cercano cuando le toque, por tiempo de camino."] = "輪到它時依路程時間選最近的。",
	["El más cercano, por tiempo de camino"] = "最近的，依路程時間",
	["El más cercano: %s"] = "最近的：%s",
	["El más reciente"] = "最新的",
	["El módulo Curación no está cargado."] = "「治療」模組未載入。",
	["El nombre de cada zona sobre el mapa de Alfa."] = "在 Alfa 地圖上顯示各地區的名稱。",
	["El número abajo a la izquierda de cada pieza de equipo."] = "每件裝備左下角的數字。",
	["El número es el orden en que se toma. Pasa el ratón por un talento para ver qué hace."] = "數字是點天賦的順序。滑鼠移到天賦上可查看效果。",
	["El número que cuenta hacia atrás. Apagado, solo la barra."] = "倒數計時數字。關閉時只顯示進度條。",
	["El objeto"] = "物品",
	["El objeto que usa el paso actual, o el objeto de misión que junta, brilla en tus bolsas. Un objeto que necesita un paso más adelante lleva un candado, para que no lo vendas."] = "目前步驟使用的物品，或它要收集的任務物品，會在你的背包中發光。之後步驟需要的物品會加上鎖頭，讓你不會賣掉它。",
	["El orden importa más que los números: busca piezas con las primeras de la lista."] = "順序比數字更重要：找有清單前幾項屬性的裝備。",
	["El paisaje lejano deja de perderse en la niebla espesa."] = "遠處的風景不再消失在濃霧中。",
	["El paisaje lejano deja de perderse en la niebla espesa. A veces se nota dónde termina lo que está cargado."] = "遠處的風景不再消失在濃霧中。有時能看出已載入區域的邊界。",
	["El paquete de datos de Alfa (Alfa_Codex) está desactivado: actívalo en la lista de addons y recarga."] = "Alfa 的資料包（Alfa_Codex）已停用：請在插件清單中啟用並重新載入。",
	["El paso de ahora de tu guía te lleva a entrenar."] = "你指南的目前步驟會帶你去訓練。",
	["El pequeño rey Anduin Wrynn lleva su nombre en honor a Anduin Lothar, el héroe que salvó a su pueblo."] = "年幼的國王安度因·烏瑞恩以安度因·洛薩命名，以紀念這位拯救了他人民的英雄。",
	["El primer clic abre la Cocina del juego; el siguiente cocina el lote. Tienes que estar junto a un fuego."] = "第一次點擊開啟遊戲的烹飪視窗；下一次點擊烹飪這一批。你必須在火堆旁邊。",
	["El primer jefe de guerra de la Horda fue Mano Negra. Su hijo Rend Mano Negra hoy sirve a Nefarian en la Cumbre de Roca Negra."] = "部落的第一位大酋長是黑手。他的兒子雷德·黑手如今在黑石塔為奈法利安效力。",
	["El primer punto del Legado suele llegar al nivel 25, y con él se abre el Legado."] = "第一點傳承點數通常在 25 級獲得，傳承也隨之開啟。",
	["El próximo: %s"] = "下一個：%s",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "最容易練等的盜賊：可以正面攻擊、閃躲很多，也比其他配點耐打。",
	["El rango Experto viene en un libro de Deneb Walker (Tierras Altas de Arathi) o de Balai Lok'Wein (Marjal Revolcafango); el Artesano, con la misión «Triaje» en Theramore o en Sentencia."] = "專家級的書由德尼布·沃克（阿拉希高地）或巴萊·洛克維（塵泥沼澤）出售；大師級要完成塞拉摩或落錘鎮的任務「分類救治」。",
	["El rango Experto viene en un libro que vende el pescador de Bahía del Botín, en Tuercespina."] = "高級釣魚要靠一本書來學，由荊棘谷藏寶海灣的漁夫販售。",
	["El rango Experto viene en un libro que venden los proveedores de cocina; el Artesano, con una misión de Dirge Quikcleave en Gadgetzan."] = "專家級的書由烹飪用品商人出售；大師級要完成加基森迪爾格·奎克利弗的任務。",
	["El rango de niveles de cada zona, con color según tu nivel."] = "各地區的等級範圍，依你的等級著色。",
	["El rastreador te avisa si tu plan se quedó sin paso y lo rearma con un clic."] = "追蹤器會在你的計畫沒有步驟時提醒你，並一鍵重新規劃。",
	["El rastreador te dice el siguiente paso y la flecha te lleva."] = "追蹤器會告訴你下一步，箭頭會帶你過去。",
	["El recorrido por Alfa"] = "Alfa 導覽",
	["El registro de daño del juego está apagado"] = "遊戲的傷害記錄已關閉",
	["El registro de daño del juego está apagado: enciéndelo para ver el top de tu grupo."] = "遊戲的傷害記錄已關閉：開啟後即可查看你隊伍的排行。",
	["El registro del Legado"] = "傳承獎勵進度",
	["El reino humano de Alterac traicionó a la Alianza en la Segunda Guerra: su rey, Aiden Perenolde, se alió con la Horda. Por eso el reino desapareció."] = "人類王國奧特蘭克在第二次戰爭中背叛了聯盟：國王艾登·佩瑞諾德投靠了部落。王國因此滅亡。",
	["El reino limita los mensajes de addon salientes: %s"] = "伺服器限制了發出的插件訊息：%s",
	["El reloj de Alfa mueve %d tareas. La que más tarda: %s (%.1f ms en %d veces)."] = "Alfa 的時鐘在執行 %d 個工作。最慢的：%s（%.1f 毫秒，共 %d 次）。",
	["El resumen se ve al salir de combate."] = "脫離戰鬥後顯示總結。",
	["El rey Llane Wrynn murió en la Primera Guerra a manos de Garona, la espía de la Horda."] = "萊恩·烏瑞恩國王在第一次戰爭中死於部落間諜迦羅娜之手。",
	["El rey Magni Barbabronce gobierna Forjaz; sus hermanos son Muradin y Brann, el explorador."] = "國王麥格尼·銅鬚統治著鐵爐堡；他的兄弟是穆拉丁和探險家布萊恩。",
	["El rey Thoradin unió a las tribus humanas en Arathor, y los altos elfos les enseñaron magia para vencer juntos a los trols Amani."] = "索拉丁國王在阿拉索統一了人類部族，高等精靈教會他們魔法，一起擊敗了阿曼尼食人妖。",
	["El rey Varian Wrynn es hijo de Llane, el rey que murió en la Primera Guerra."] = "瓦里安·烏瑞恩國王是萊恩之子，萊恩就是在第一次戰爭中喪生的那位國王。",
	["El rey Varian desapareció camino a una reunión de paz. Mientras tanto reina su hijo Anduin, todavía niño, con el alto señor Bolvar Fordragón como regente."] = "瓦里安國王在前往和平會議的途中失蹤了。在此期間，由他年幼的兒子安度因即位，大領主柏瓦爾·弗塔根擔任攝政王。",
	["El saludo de la manada"] = "狼群的問候",
	["El sanador de los chamanes: curas en cadena y tótems que ayudan a todo el grupo."] = "薩滿的治療專精：鏈狀治療與幫助整個隊伍的圖騰。",
	["El sanador de los druidas: curas a cualquier grupo y sobrevives bien, aunque en solitario matas lento."] = "德魯伊的治療專精：能治療任何隊伍且很能活，不過單練時殺怪較慢。",
	["El sanador de los paladines: curas fuertes y mucha armadura, ideal para grupos."] = "聖騎士的治療專精：強力的治療與厚重的護甲，非常適合組隊。",
	["El sanador puro: curas grandes y curas para todo el grupo."] = "純粹的治療者：大量治療，以及給整個隊伍的治療。",
	["El servicio"] = "服務",
	["El sistema de equipo de Alfa no está disponible."] = "無法使用 Alfa 的裝備系統。",
	["El sol aquí no perdona: las Tierras Inhóspitas son tierra de coyotes, buitres y basiliscos."] = "這裡的太陽毫不留情：荒蕪之地是土狼、禿鷹和蜥蜴的天下。",
	["El sol de Durotar quema la tierra roja. Por algo los orcos son tan duros."] = "杜洛塔的太陽烤著紅土地。難怪獸人那麼強悍。",
	["El suelo y los muros se ven nítidos aunque estén lejos o de lado."] = "即使在遠處或斜著看，地面與牆壁也很清晰。",
	["El tablón de la manada"] = "狼群公告板",
	["El tablón está apagado (Ajustes de La Jauría)."] = "公告板已關閉（La Jauría 設定）。",
	["El talento que toca"] = "該點的天賦",
	["El tanque clásico: bloqueas mucho, generas amenaza con Revancha y Embate con escudo, y tienes Último recurso para cuando todo sale mal."] = "經典的坦克：大量格擋，用復仇與盾牌猛擊產生仇恨，情況失控時還有破釜沉舟。",
	["El tanque más difícil de matar: todos los talentos de defensa, Muro de escudo mejorado y Último recurso pronto. Perfecto para empezar a tanquear."] = "最難被打死的坦克：點滿所有防禦天賦、強化盾牆，並及早點出破釜沉舟。非常適合剛開始當坦克的人。",
	["El terreno real en el mapa"] = "地圖上的真實地形",
	["El texto es demasiado largo."] = "文字太長了。",
	["El texto llegó cortado o cambiado: cópialo otra vez."] = "文字不完整或被更改：請重新複製。",
	["El tipo de nodos que une la ruta."] = "路線要串連的採集點類型。",
	["El tono de los fondos: Grafito es el de Alfa, Noche el más oscuro y Pizarra un gris neutro."] = "背景的色調：石墨是 Alfa 的預設色調，夜晚最暗，石板為中性灰。",
	["El top de DPS de tu grupo o banda en una ventana pequeña, con la pelea actual y la anterior."] = "在一個小視窗中顯示你隊伍或團隊的 DPS 排行，包括目前與上一場戰鬥。",
	["El torio abunda en el Cráter de Un'Goro y en Cuna del Invierno."] = "安戈洛環形山和冬泉谷有大量瑟銀。",
	["El tranvía a %s ya viene"] = "前往%s的地鐵來了",
	["El velo de pantalla de algunas zonas y hechizos de las sombras."] = "某些地區與暗影法術的畫面籠罩效果。",
	["El vendedor más cercano"] = "最近的商人",
	["El verdadero nombre de Thrall es Go'el, el que le dieron sus padres."] = "索爾的真名是古伊爾，那是他父母給他取的名字。",
	["El viejo ermitaño Abercrombie parece amable... hasta que descubres a quién intenta revivir."] = "老隱士亞伯克隆比看起來很和善…直到你發現他想復活的是誰。",
	["El zepelín a %s ya viene"] = "前往%s的飛艇來了",
	["El «?» de cada página"] = "每頁的「?」",
	["El «zug zug» de los peones quiere decir algo así como «de acuerdo». ¡Zug zug, jefe!"] = "苦工說的「zug zug」大概是「好的」的意思。zug zug，老大！",
	["El ángel te revive ya y a tu nivel no quedas débil, pero tu equipo pierde %d %% de durabilidad."] = "靈魂醫者能馬上復活你，以你的等級不會變虛弱，但你的裝備會損失 %d %% 耐久度。",
	["El ángel te revive ya, pero tu equipo pierde %d %% de durabilidad y quedas débil %s."] = "靈魂醫者能馬上復活你，但你的裝備會損失 %d %% 耐久度，而且你會虛弱 %s。",
	["El árbol de ruta de Alfa, misiones que se liberan y un catálogo de objetos."] = "Alfa 的路線樹、陸續解鎖的任務，以及物品目錄。",
	["El ícono grande es lo que conviene presionar ahora y los pequeños, lo que sigue. Si late, el juego activó esa habilidad; el barrido oscuro es su recarga. Tú decides: Alfa nunca aprieta nada."] = "大圖示是現在最該按的，小圖示是接下來的。如果它在跳動，表示遊戲點亮了該技能；深色轉圈是它的冷卻。由你決定：Alfa 絕不會替你按任何鍵。",
	["El último punto: paras un poco más."] = "最後一點：招架稍微再多一些。",
	["Elegida por ti en los ajustes."] = "由你在設定中選擇。",
	["Elegida por tus talentos."] = "由你的天賦決定。",
	["Elegido"] = "已選擇",
	["Elegido por ti"] = "你自選的",
	["Elegir"] = "選擇",
	["Elegir capas"] = "選擇圖層",
	["Elegir la siguiente guía"] = "選擇下一個指南",
	["Elegir lo que pide tu paso"] = "選擇你的步驟所需的選項",
	["Elegir mi camino"] = "選擇我的方向",
	["Elegir mi primera guía"] = "選擇我的第一個指南",
	["Elegir mi tecla"] = "選擇我的按鍵",
	["Elegir otra guía"] = "選擇其他指南",
	["Elegir para copiar"] = "選取以複製",
	["Elegir qué sigue"] = "選擇接下來做什麼",
	["Elegir todo"] = "全選",
	["Elegir una guía"] = "選擇指南",
	["Elegir una guía por ti"] = "替你選擇指南",
	["Elegiste: %s"] = "已選擇：%s",
	["Elemental"] = "元素",
	["Elemental para subir"] = "元素（練等）",
	["Elfos de la noche"] = "夜精靈",
	["Elige a dónde ir: Alfa arma el camino con vuelos, barcos, zepelines, portales y a pie."] = "選擇要去哪裡：Alfa 會用飛行、船隻、飛艇、傳送門和步行幫你規劃路線。",
	["Elige abajo qué cocinar y cuánto: la cola espera tu clic para cada lote."] = "在下方選擇要烹飪什麼、烹飪多少：佇列會等你點擊每一批。",
	["Elige algo de la lista"] = "從清單中選擇一項",
	["Elige el objeto"] = "選擇物品",
	["Elige el objeto en la Enciclopedia."] = "在百科中選擇物品。",
	["Elige la opción que nombra tu guía, o abre la tienda o el entrenamiento que necesitas."] = "選擇指南指定的選項，或開啟你需要的商店或訓練。",
	["Elige para qué, escribe qué buscas y pulsa «Publicar»: lo ven los lobos de tu hermandad con Alfa. Se quita solo en una hora."] = "選擇用途，寫下你要找什麼，然後點「發佈」：公會裡用 Alfa 的狼都能看到。一小時後會自動撤下。",
	["Elige qué guardar: lo que ya tienes en el banco, los materiales, una categoría o todo lo que no sea equipo. Se mueve de una vez, fuera de combate."] = "選擇要存放的東西：銀行裡已有的物品、材料、某個分類，或所有非裝備物品。脫離戰鬥時一次移動。",
	["Elige qué quieres hacer y Alfa te lleva paso a paso."] = "選擇你想做的事，Alfa 會一步步帶你。",
	["Elige qué se ve en el mapa: guía, misiones, raros, viajes, zonas y lo que agregan otros módulos."] = "選擇地圖上顯示的內容：指南、任務、稀有、旅行、地區以及其他模組加入的內容。",
	["Elige sola la única opción de los PNJ sin misiones."] = "對沒有任務的 NPC，自動選擇其唯一的選項。",
	["Elige solo misiones que ya puedes tomar."] = "只選擇你現在就能接的任務。",
	["Elige tu camino. Si no sabes, empieza por subir de nivel: Alfa te dice qué conviene."] = "選擇你的方向。如果不確定，就從練等開始：Alfa 會告訴你怎麼做最划算。",
	["Elige tu estilo"] = "選擇你的風格",
	["Elige tu tecla para pescar"] = "選擇你的釣魚按鍵",
	["Elige tus clics"] = "選擇你的點擊",
	["Elige tus clics, acomoda tus marcos y pruébalos. Te toma un minuto."] = "選擇你的點擊、擺放框架並測試。只需一分鐘。",
	["Elige tus extras"] = "選擇你的額外功能",
	["Elige tus minutos con la barra de abajo."] = "用下面的滑桿選擇分鐘數。",
	["Elige tú la zona."] = "由你選擇地區。",
	["Elige un camino: Alfa arma tu plan y te guía paso a paso."] = "選擇一條路線：Alfa 會制定你的計畫並一步步帶你。",
	["Elige un día y una hora que aún no pasen (hasta una semana)."] = "選一個還沒過去的日期和時間（一週以內）。",
	["Elige un marcador."] = "選擇一個標記。",
	["Elige un servicio."] = "選擇一項服務。",
	["Elige una captura"] = "選擇一種漁獲",
	["Elige una guía para empezar"] = "選擇一個指南開始",
	["Elige una mazmorra."] = "選擇一個地城。",
	["Elige una misión"] = "選擇一個任務",
	["Elige una profesión"] = "選擇一項專業",
	["Elige una profesión."] = "選擇一項專業。",
	["Elige una receta o un oficio y Alfa te dice qué materiales te faltan y de dónde sale cada uno. También desde la Enciclopedia."] = "選一個配方或專業，Alfa 會告訴你缺哪些材料以及每種從哪來。也可以從百科裡加。",
	["Elige una y listo: Alfa ajusta tus misiones, tu guía, los comerciantes y los viajes. Mantén presionado Mayús en el juego para decidir tú en el momento."] = "選一個就好：Alfa 會調整你的任務、指南、商人和旅行。遊戲中按住 Shift 可當場自己決定。",
	["Elige uno y lo ves al instante en esta ventana y en todas las de Alfa, también la flecha."] = "選擇一個，就能立即在此視窗與 Alfa 的所有視窗中看到效果，箭頭也一樣。",
	["Eliges una"] = "任選一個",
	["Ella duerme a todo el grupo y luego resucita a Mograine: es normal, no se asusten."] = "她會催眠整個隊伍，然後復活莫格萊尼：這是正常的，別慌。",
	["Elune, la diosa de la luna, es la fe de los elfos de la noche. Sus sacerdotisas son las Hermanas de Elune, y Tyrande es su suma sacerdotisa."] = "月亮女神伊露恩是夜精靈的信仰。她的女祭司們組成伊露恩姊妹會，泰蘭妲是她們的大祭司。",
	["Elwynn de día es pura paz: el río, los campos y el olor a pan de Villadorada."] = "白天的艾爾文森林一片寧靜：河流、田野，還有閃金鎮飄來的麵包香。",
	["Embate con escudo: mucho daño y amenaza."] = "盾牌猛擊：高傷害與高仇恨。",
	["Embate deja de reiniciar tu ataque: un golpe extra entre golpe y golpe."] = "猛擊不再重置你的攻擊計時：在兩次攻擊之間多打一下。",
	["Embate sin perder tu ataque automático."] = "使用猛擊而不損失自動攻擊。",
	["Embate sin perder tu ataque."] = "使用猛擊而不損失攻擊。",
	["Embate sin perder tu golpe automático."] = "使用猛擊而不損失自動攻擊。",
	["Embate sin reiniciar tu ataque: un golpe extra."] = "使用猛擊而不重置攻擊計時：多打一下。",
	["Embate: un golpe fuerte entre golpe y golpe."] = "猛擊：在兩次攻擊之間打出一記重擊。",
	["Empezamos a escribir (nivel %d)"] = "我們開始書寫（%d 級）",
	["Empezar"] = "開始",
	["Empezar de cero"] = "從頭開始",
	["Empezar de nuevo"] = "重新開始",
	["Empezar otra"] = "再開始一次",
	["Empezar otra sesión"] = "開始新的釣魚記錄",
	["Empezó %s"] = "開始於%s",
	["Empezó %s."] = "開始於%s。",
	["Empieza al usar este objeto"] = "使用此物品後開始",
	["Empieza aquí"] = "從這裡開始",
	["Empieza con %s, que se consigue en la mazmorra."] = "從%s開始，可在地城中取得。",
	["Empieza con %s, que suelta %s."] = "從%s開始，由%s掉落。",
	["Empieza con tu hechizo más lento desde lejos y termina con los instantáneos."] = "從遠處用你施法最慢的法術開場，再用瞬發法術收尾。",
	["Empieza de cero, por ejemplo después de mandar tu reporte."] = "從頭開始，例如在傳送回報之後。",
	["Empieza dentro"] = "在副本內開始",
	["Empieza una misión"] = "開始一個任務",
	["Empiezas a juntar XP descansada"] = "開始累積休息經驗",
	["Empiezas: nivel %d"] = "起始：%d 級",
	["En %s"] = "在%s",
	["En 9 idiomas"] = "支援 9 種語言",
	["En Ajustes > Estilo y sonido prende «Letra más grande» y, si confundes el rojo con el verde, «Colores para daltonismo»."] = "在「設定 > 風格與音效」中開啟「更大的字體」；如果你分不清紅色和綠色，再開啟「色盲友善配色」。",
	["En Bolsas, «Buscar en todos tus personajes» revisa bolsas, bancos y equipo de todos, con filtros de tipo, calidad y personaje."] = "在背包中，「搜尋你所有角色」會檢查每個角色的背包、銀行和裝備，可依類型、品質和角色篩選。",
	["En Bolsas, «Qué guardar» te dice lo que sirve más en el banco: materiales de las recetas de tus otros personajes, lo que piden sus misiones y equipo que tu clase no usa. Con un banquero, «Al banco» y listo."] = "在背包的「存什麼」裡會告訴你哪些放銀行更有用：你其他角色配方用的材料、他們任務需要的東西，以及你職業用不到的裝備。在銀行職員旁，點「存入銀行」就好。",
	["En Burning Crusade, Karazhan abre sus puertas como banda."] = "到了燃燒的遠征，卡拉贊會作為團隊副本開放。",
	["En Burning Crusade, el Vuelo Bronce pide ayuda en las Cavernas del Tiempo contra dragones que quieren cambiar la historia."] = "到了燃燒的遠征，青銅龍軍團會在時光之穴求助，對抗企圖改變歷史的巨龍。",
	["En Burning Crusade, las Cavernas del Tiempo te regresan a estas laderas para ver la huida de Thrall de Durnholde."] = "到了燃燒的遠征，時光之穴會把你送回這片丘陵，見證索爾從敦霍爾德逃脫。",
	["En Caer Darrow, junto al lago, todavía rondan los fantasmas de sus antiguos vecinos."] = "在湖邊的凱爾達隆，昔日居民的鬼魂仍在遊蕩。",
	["En Ciudad Manitas, dentro de Forjaz, viven los gnomos que escaparon de Gnomeregan."] = "鐵爐堡裡的地精區住著從諾姆瑞根逃出來的地精。",
	["En Combate tienes el medidor de daño del grupo y la ayuda de rotación para tu clase."] = "「戰鬥」裡有全隊傷害統計和你職業的循環助手。",
	["En Comercio ves precios de la subasta y qué te conviene vender. Yo vendo lo gris por ti con el comerciante."] = "在「交易」裡看拍賣價格和值得賣的東西。灰色物品我在商人那裡幫你賣。",
	["En Comercio, en «Oficios», cada uno tiene su guía de 1 a 300: qué hacer en cada tramo, lo que te falta y dónde aprender el siguiente rango."] = "在交易的「專業」裡，每個專業都有 1 到 300 的指南：每一段做什麼、還缺什麼、去哪學下一個等級。",
	["En Comercio, en «Tu lista de compras», agrega una receta o un oficio: te digo cuánto tienes, cuánto te falta y de dónde sale. Se va llenando sola mientras juntas."] = "在交易的「你的購物清單」裡加入一個配方或專業：我會告訴你有多少、還缺多少、從哪裡來。你採集時它會自動更新。",
	["En Comercio, «Tus recetas que dejan ganancia» te dice cuánto deja cada receta con los precios de tu reino, y primero las que ya puedes hacer con lo que llevas."] = "在交易中，「你能賺錢的配方」會依你所在伺服器的價格告訴你每個配方能賺多少，現在就能做的排在最前面。",
	["En Costa Oscura la Liga de Expedicionarios desentierra fósiles gigantes."] = "探險者協會正在黑海岸挖掘巨大的化石。",
	["En Costa Oscura viven lechúcicos, criaturas mitad búho y mitad oso que veneran la luna."] = "黑海岸住著梟獸，這種半梟半熊的生物崇拜月亮。",
	["En Cuna del Invierno la nieve no se acaba. Los osos y los yetis andan de buen humor."] = "冬泉谷的雪永遠下不完。熊和雪人心情都不錯。",
	["En Curación, «Curar y seleccionar» viene prendido: cada clic que cura en tus marcos también deja a ese compañero como tu objetivo, para seguir con un buff o quitarle una maldición. En «Tus clics» eliges qué hace cada clic."] = "在治療中，「治療並選取」預設開啟：在你的框架上每次點擊治療，也會把那名隊友設為你的目標，方便接著加增益效果或驅散詛咒。在「你的點擊」中選擇每種點擊的作用。",
	["En Desolace está el cementerio de los kodos, donde los viejos kodos van a morir."] = "淒涼之地有科多獸墳場，年老的科多獸會去那裡等待死亡。",
	["En Dun Morogh la nieve brilla con el sol. Abrígate, que aquí hasta los osos tienen frío."] = "丹莫洛的雪在陽光下閃閃發光。穿暖和點：這裡連熊都會冷。",
	["En Durotar ya te topas con el Filo Ardiente, un culto de brujos orcos que sigue adorando a los demonios."] = "在杜洛塔你就會遇到火刃，一個仍在崇拜惡魔的獸人術士邪教。",
	["En Elwynn, una señora vende gatitos de compañía. ¡Yo me llevo bien con los gatos... casi siempre!"] = "艾爾文森林有位女士在賣小貓寵物。我跟貓處得很好…大多數時候！",
	["En Entrañas venden cucarachas de mascota. Cada quien sus gustos."] = "幽暗城有賣蟑螂寵物。蘿蔔青菜，各有所愛。",
	["En Feralas está uno de los grandes árboles por los que los dragones verdes entran al Sueño Esmeralda."] = "菲拉斯有一棵巨樹，綠龍經由它進入翡翠夢境。",
	["En Forever, Onyxia, la Cumbre Hyjal y Barrow Deeps dan retos del Legado al vencerlas."] = "在 Forever 中，擊敗奧妮克希亞、海加爾山與古墓深淵都會獲得傳承挑戰。",
	["En Forever, el banco vende casillas de bolsa una tras otra: más espacio para tus tesoros."] = "在 Forever 中，銀行會一格接一格地販售背包欄位：給你的寶貝更多空間。",
	["En Forever, los rangos de honor y la reputación de los campos de batalla también dan retos del Legado."] = "在 Forever 中，榮譽階級和戰場聲望也會帶來傳承挑戰。",
	["En Forever, los retos del Legado dan puntos a toda tu cuenta, y cada personaje los gasta en sus árboles. Ábrelo con la tecla Y."] = "在 Forever 中，傳承挑戰會給你整個帳號點數，每個角色把點數花在自己的天賦樹上。按 Y 鍵開啟。",
	["En Forjaz, la sala de la Liga de Expedicionarios tiene un museo con fósiles enormes. Brann Barbabronce es su explorador más famoso."] = "在鐵爐堡，探險者協會的大廳裡有一座陳列巨大化石的博物館。布萊恩·銅鬚是協會最有名的探險家。",
	["En Gadgetzan, el cocinero Dirge enseña una de las mejores recetas del Clásico, con carne de quimerok."] = "在加基森，廚師迪爾格教授經典版中最好的配方之一，用的是奇美拉的肉。",
	["En Hoy, en «¿Cuánto tiempo tienes?», elige 30 minutos, 1 hora, 2 o los que quieras. Armo tu plan con tu ritmo y, con «Empezar», la flecha te lleva paso por paso."] = "在「今天」的「你有多少時間？」裡，選 30 分鐘、1 小時、2 小時或任意時長。我會照你的節奏擬定計畫，點「開始」後箭頭一步步帶你走。",
	["En Jaedenar se esconde el Consejo de la Sombra, brujos que sirven a la Legión Ardiente."] = "暗影議會藏身在加德納爾，他們是效忠燃燒軍團的術士。",
	["En Jardín Noble se esconden huevos de colores por los pueblos iniciales; dentro hay dulces y a veces ropa de primavera."] = "貴族花園期間，新手城鎮各處都藏著彩蛋；裡面有糖果，有時還有春裝。",
	["En Kharanos, la posada y la destilería Cebatruenos son la parada obligada para calentarse... por dentro y por fuera."] = "在卡拉諾斯，旅店和雷酒釀酒廠是取暖必去的地方…從裡暖到外。",
	["En La Jauría > Guaridas te digo en cuál estás y en cuáles anda la manada. Con «Pedir entrar» te pasas a la de un lobo con la puerta abierta."] = "在 La Jauría > 巢穴 裡，我告訴你在哪個巢穴、狼群在哪。用「請求進入」去開著門的狼那裡。",
	["En La Jauría > Guaridas toca «Llamar a la manada» (o escribe /alfa manada llamar): los lobos de tu zona reciben tu lugar y te aviso quién viene."] = "在 La Jauría > 巢穴 點「呼喚狼群」（或 /alfa manada llamar）：區域裡的狼會收到你的位置，我會告訴你誰來了。",
	["En La Jauría está «El tablón de la manada»: pon qué buscas y a tu hermandad le llega. Se quita solo en una hora."] = "La Jauría 裡有「狼群公告板」：寫下你要找什麼，公會就會收到。一小時後會自動撤下。",
	["En La Jauría está «La semana de la manada»: misiones, raros, mazmorras y niveles de los lobos que la comparten. Nadie compite: todo suma."] = "La Jauría 有「狼群的一週」：分享的狼的任務、稀有怪、地城和等級。沒人競爭：大家一起累計。",
	["En La Jauría ves a tu grupo y a los lobos que se dejan ver en el mapa. Puedes seguirlos con la flecha o invitarlos."] = "在 La Jauría 裡能看到你的隊伍和在地圖上現身的狼。可以用箭頭跟隨或邀請他們。",
	["En La Jauría ves cómo va. Si se atora, te aviso."] = "在 La Jauría 中可以看他的進展。他卡住時我會告訴你。",
	["En La Jauría, en «Citas de la manada», escribe qué, elige día y hora y pulsa «Proponer». A tu hermandad le llega con «Voy» y yo te recuerdo 15 minutos antes."] = "在 La Jauría 的「狼群集合」中寫下做什麼，選好日期和時間，按「提議」。你的公會會收到並附「我去」按鈕，我會提前 15 分鐘提醒你。",
	["En La Jauría, en «¿Quién tiene...?», escribe el objeto y pulsa «Buscar». Te contestan los lobos de tu hermandad que lo permiten, con «Susurrar» para pedírselo."] = "在 La Jauría 的「誰有…？」裡輸入物品並點「搜尋」。公會裡允許回應的狼會回答你，還有「密語」按鈕可以找他們要。",
	["En La Jauría, «El calendario de la manada» acomoda las citas de los próximos siete días."] = "在 La Jauría 中，「狼群日曆」會排好未來七天的集合。",
	["En La Jauría, «Las guaridas de la manada» dice cuántos lobos hay en cada guarida de cada zona. En el mapa también sale."] = "在 La Jauría 中，「狼群的巢穴」會顯示每個區域每個巢穴裡有幾隻狼。地圖上也會顯示。",
	["En Los Baldíos el sol pega duro. Las cebras corren por todos lados y yo quiero perseguirlas."] = "貧瘠之地的太陽很毒。斑馬到處跑，我好想去追牠們。",
	["En Los Humedales siempre está húmedo. Mis patas terminan llenas de lodo."] = "濕地總是濕答答的。我的腳掌最後都沾滿了泥巴。",
	["En Mazmorras ves cuáles van con tu nivel, sus jefes, su botín, sus misiones y cómo llegar a la entrada."] = "在「地城」裡能看到適合你等級的副本、首領、掉落、任務和入口路線。",
	["En Molino Ámbar se refugian magos de Dalaran, y no les gustan nada las visitas de los Renegados."] = "達拉然的法師們躲在安伯米爾，他們一點也不歡迎被遺忘者來訪。",
	["En Mundo pones tus marcadores, los compartes con tu grupo y la flecha te lleva a ellos."] = "在「世界」裡放置標記、分享給隊伍，箭頭會帶你過去。",
	["En Naxxramas, el gran Alexandros Mograine reaparece como uno de los Cuatro Jinetes de la Plaga. Qué triste destino para un héroe."] = "在納克薩瑪斯，偉大的亞歷山德羅·莫格萊尼以天譴軍團四騎士之一的身分重新出現。英雄落得這種下場，真令人難過。",
	["En Nethergarde, unos magos de sangre te cambian partes de las bestias de aquí por elixires que te potencian un buen rato."] = "在守望堡，幾位血法師會用這裡野獸的身體部位跟你換藥劑，能長時間強化你。",
	["En Orgrimmar, el Valle de la Sabiduría guarda la fortaleza de Thrall, y el Valle del Honor reúne a guerreros y cazadores."] = "在奧格瑪，智慧谷裡有索爾的要塞，榮譽谷則聚集著戰士與獵人。",
	["En Paisaje y gráficos hay un paisaje más bonito con un clic, y cada ajuste gráfico explicado."] = "「風景與畫面」裡一鍵獲得更美的風景，每項畫面設定都有說明。",
	["En Pesca tienes una sola tecla para equiparte, lanzar y recoger, un diario de lo que sacas y una guía de 1 a 300."] = "「釣魚」有一個鍵完成裝備、拋竿和收竿，還有漁獲日誌和 1-300 指南。",
	["En Pico Nidal manda el thane Falstad Martillo Salvaje, señor de los jinetes de grifo."] = "統治鷹巢山的是領主弗斯塔德·蠻錘，獅鷲騎士的首領。",
	["En Pico Nidal viven los enanos Martillo Salvaje, famosos por volar sobre grifos."] = "蠻錘矮人住在鷹巢山，他們以騎乘獅鷲聞名。",
	["En Recolección eliges qué buscar y te marco en el mapa los puntos de tus profesiones, con los que ya encontraste."] = "在「採集」裡選要找什麼，我在地圖上標出你專業的採集點，以及你已找到的。",
	["En Ruta eliges a dónde ir y yo te armo el camino. La flecha te lleva paso a paso y el rastrador te dice qué toca."] = "在「路線」裡選去哪，我幫你規劃。箭頭一步步帶路，追蹤器告訴你下一步。",
	["En Seradane hay uno de los grandes árboles que llevan al Sueño Esmeralda, y los dragones verdes lo custodian."] = "瑟拉丹有一棵通往翡翠夢境的巨樹，由綠龍守護。",
	["En Talentos te digo qué punto poner y por qué, según tu clase y cómo juegas."] = "在「天賦」裡，我會依你的職業和玩法告訴你點哪裡、為什麼。",
	["En Tanaris el sol del desierto no perdona. Gadgetzan es el único lugar con sombra."] = "塔納利斯的沙漠太陽毫不留情。加基森是唯一有陰涼的地方。",
	["En Tanaris están las Cavernas del Tiempo, donde el Vuelo Bronce de Nozdormu vigila la historia."] = "塔納利斯有時光之穴，諾茲多姆的青銅龍軍團在那裡守望歷史。",
	["En Tirisfal casi nunca sale el sol. A los Renegados ni les importa."] = "提里斯法林地幾乎見不到太陽。被遺忘者倒是一點都不在乎。",
	["En Tirisfal está la entrada al Monasterio Escarlata, uno de los lugares más visitados por los aventureros de nivel medio."] = "提里斯法林地有血色修道院的入口，那是中等級冒險者最常去的地方之一。",
	["En Tuercespina hace un calor de lobo. Toma agua y cuidado con los tigres entre la hierba."] = "荊棘谷熱得像狼的嘴裡一樣。多喝水，小心草叢裡的老虎。",
	["En Uldaman están los Discos de Norgannon, registros de los titanes que cuentan cómo crearon a los terráneos, los antepasados de piedra de los enanos."] = "奧達曼裡有諾甘農圓盤，這些泰坦的記錄講述了他們如何創造土靈——矮人的岩石祖先。",
	["En Vallefresno, Grom Grito Infernal mató al semidiós Cenarius cuando la Horda empezó a talar el bosque."] = "在梣谷，部落開始砍伐森林時，葛羅姆·地獄吼殺死了半神塞納留斯。",
	["En Vallefresno, Grom volvió a beber sangre demoníaca; Thrall lo rescató y Grom pudo redimirse antes de morir."] = "在梣谷，葛羅姆再次飲下了惡魔之血；索爾救出了他，葛羅姆在死前得以自我救贖。",
	["En Ventormenta hay un barrio de enanos, uno de magos y un parque donde se reúnen los elfos de la noche."] = "暴風城有矮人區、法師區，還有一座夜精靈聚集的公園。",
	["En Warcraft III, si le das muchos clics a una unidad empieza a decir cosas chistosas. Yo, en cambio, te doy consejos."] = "在魔獸爭霸 III 中，一直點同一個單位，它就會開始說些好笑的話。而我呢，會給你建議。",
	["En arco"] = "弧線",
	["En bancos de peces de: %s."] = "在以下魚群中：%s。",
	["En banda, un grupo por columna"] = "團隊中，每欄一個小隊",
	["En camino"] = "前往中",
	["En cero los números suben derechos; más alto, salen disparados hacia los lados."] = "設為零時數字筆直上升；數值越高，數字越往兩側飛散。",
	["En combate"] = "戰鬥中",
	["En combate el juego oculta los números exactos: las barras y las cifras se ven igual, el detalle y el anuncio, al salir."] = "戰鬥中遊戲會隱藏精確數字：計量條與數值照常顯示，詳細資訊與通報在脫離戰鬥後才能使用。",
	["En combate el mapa del juego no se abre desde Alfa: usa el de Alfa."] = "戰鬥中無法從 Alfa 開啟遊戲地圖：請使用 Alfa 地圖。",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "戰鬥中不顯示遊戲世界中角色與生物的滑鼠提示（框架上的仍會顯示）。",
	["En combate no hay prueba: sal de la pelea y vuelve a este paso."] = "戰鬥中無法測試：脫離戰鬥後再回到這一步。",
	["En combate no puedo buscar: inténtalo al terminar la pelea."] = "戰鬥中無法搜尋：請在戰鬥結束後再試。",
	["En combate no se puede cambiar el equipo: te lo pongo al terminar."] = "戰鬥中不能換裝備：戰鬥結束後我幫你穿上。",
	["En combate no se puede cambiar el equipo: te pongo «%s» al terminar."] = "戰鬥中無法更換裝備：結束後我會幫你穿上「%s」。",
	["En combate no se puede: espera a terminar."] = "戰鬥中無法進行：請等戰鬥結束。",
	["En combate · la pesca espera"] = "戰鬥中 · 釣魚暫停",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard y las %d que siguen. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "戰鬥中，圖示會顯示 Blizzard 戰鬥輔助建議的技能，以及接下來的 %d 個。按什麼由你決定：Alfa 絕不會替你按任何鍵。",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "戰鬥中，圖示會顯示 Blizzard 戰鬥輔助建議的技能。按什麼由你決定：Alfa 絕不會替你按任何鍵。",
	["En combate: espera a terminar"] = "戰鬥中：請等戰鬥結束",
	["En curso"] = "進行中",
	["En el Casco Antiguo está el SI:7, los espías y pícaros al servicio del reino."] = "舊城區裡有軍情七處，為王國效力的間諜與盜賊都在那裡。",
	["En el Clásico mandan Thrall en Orgrimmar, Cairne en Cima del Trueno, Sylvanas en Entrañas y Vol'jin con los Lanza Negra."] = "在經典版中，索爾統治奧格瑪，凱恩統治雷霆崖，希瓦娜斯統治幽暗城，沃金領導暗矛部族。",
	["En el Clásico nadie sabe dónde anda Alamuerte; los que dan la cara son sus hijos, Onyxia y Nefarian."] = "在經典版中，沒人知道死亡之翼在哪裡；露面的是他的子女，奧妮克希亞和奈法利安。",
	["En el Clásico necesitas flechas o balas: lleva siempre de más en tu carcaj o tu bolsa de munición."] = "在經典版中你需要箭或子彈：箭袋或彈藥袋裡一定要多帶一些。",
	["En el Clásico necesitas un cuchillo de desollar en tus bolsas."] = "在經典版中，你的背包裡需要一把剝皮小刀。",
	["En el Clásico solo puedes tener dos profesiones principales, pero Cocina, Pesca y Primeros auxilios se aprenden aparte."] = "在經典版中，你只能學兩個主要專業，但烹飪、釣魚和急救可以另外學。",
	["En el Clásico, Costasur contra Molino Tarren era la pelea entre bandos más famosa del mundo."] = "在經典版中，南海鎮對塔倫米爾是全世界最有名的陣營之戰。",
	["En el Clásico, a nivel 20 aprendes a teletransportarte a las capitales, y a 40 a abrir portales para los demás."] = "在經典版中，20 級時你能學會傳送到主城，40 級時能為別人開傳送門。",
	["En el Clásico, a nivel 20 haces la misión de los venenos; después los mejoras con tu entrenador."] = "在經典版中，20 級時你要做毒藥任務；之後可以找訓練師提升毒藥。",
	["En el Clásico, a nivel 40 haces la misión de tu caballo de guerra, y a 60 la cadena épica del destrero."] = "在經典版中，40 級時你要做戰馬的任務，60 級時則是戰駒的史詩任務鏈。",
	["En el Clásico, a nivel 40 recibes un corcel vil, y a 60 una cadena épica en La Masacre te da uno aún más temible."] = "在經典版中，40 級時你會得到一匹地獄戰馬，60 級時厄運之槌的史詩任務鏈會給你一匹更可怕的坐騎。",
	["En el Clásico, abrir las puertas de Ahn'Qiraj pidió un esfuerzo de guerra de todo el servidor: montañas de materiales y una cadena larguísima."] = "在經典版中，開啟安其拉之門需要全伺服器的戰爭動員：堆積如山的材料和一條超長的任務鏈。",
	["En el Clásico, algunos peces solo pican de noche o de día."] = "在經典版中，有些魚只在晚上或白天才會上鉤。",
	["En el Clásico, cada raza de sacerdote tiene un hechizo propio. Pregúntale a tu entrenador cuál te toca."] = "在經典版中，每個種族的牧師都有自己的專屬法術。問問你的訓練師你的是哪一個。",
	["En el Clásico, después de vendarte queda un rato en que no puedes usar otra venda."] = "在經典版中，用過繃帶後會有一段時間不能再用另一條繃帶。",
	["En el Clásico, el Cetro de las Arenas Movedizas abrió las puertas de Ahn'Qiraj tras una larguísima cadena de misiones."] = "在經典版中，流沙節杖在一條超長的任務鏈之後開啟了安其拉之門。",
	["En el Clásico, el arco épico de los cazadores sale de una cadena contra demonios que empieza en el Claro de la Luna."] = "在經典版中，獵人的史詩弓來自一條對抗惡魔的任務鏈，從月光林地開始。",
	["En el Clásico, el chat de Los Baldíos era famoso por sus pláticas eternas... y por preguntar dónde estaba la esposa de Mankrik."] = "在經典版中，貧瘠之地的聊天頻道以沒完沒了的閒聊聞名…還有大家都在問曼克里克的老婆在哪裡。",
	["En el Clásico, el nivel máximo es 60 y llegar lleva su tiempo. Por eso cada nivel se festeja."] = "在經典版中，等級上限是 60 級，要達到得花不少時間。所以每升一級都值得慶祝。",
	["En el Clásico, el rango de honor 14 es Gran Mariscal para la Alianza y Gran Señor de la Guerra para la Horda."] = "在經典版中，榮譽階級 14 級在聯盟是大元帥，在部落是大將軍。",
	["En el Clásico, la Feria de la Luna Negra a veces se instala en Mulgore, cerca del poblado Pezuña de Sangre."] = "在經典版中，暗月馬戲團有時會在莫高雷的血蹄村附近紮營。",
	["En el Clásico, la Feria de la Luna Negra a veces se instala junto a Villadorada."] = "在經典版中，暗月馬戲團有時會在閃金鎮旁邊紮營。",
	["En el Clásico, la Horda la forman orcos, trols Lanza Negra, tauren y Renegados; la Alianza, humanos, enanos, gnomos y elfos de la noche."] = "在經典版中，部落由獸人、暗矛食人妖、牛頭人和被遺忘者組成；聯盟則是人類、矮人、地精和夜精靈。",
	["En el Clásico, la Plaga invadió el mundo con necrópolis flotantes antes de que se abriera Naxxramas."] = "在經典版中，納克薩瑪斯開放之前，天譴軍團曾用漂浮的死靈之塔入侵世界。",
	["En el Clásico, la actitud defensiva se gana con una misión al nivel 10, y la rabiosa con otra al nivel 30."] = "在經典版中，防禦姿態要在 10 級做任務獲得，狂暴姿態要在 30 級做另一個任務。",
	["En el Clásico, la casa de subastas de Forjaz es la más movida de toda la Alianza."] = "在經典版中，鐵爐堡的拍賣場是整個聯盟最熱鬧的。",
	["En el Clásico, la forma de oso se gana con una misión a nivel 10 y la acuática con otra a nivel 16; luego vienen la felina y la de viaje."] = "在經典版中，熊形態要在 10 級做任務獲得，水棲形態在 16 級做另一個任務；之後是獵豹形態和旅行形態。",
	["En el Clásico, la montura de nivel 40 es mucho más rápida que correr, y la épica de nivel 60 todavía más."] = "在經典版中，40 級的坐騎比跑步快得多，60 級的史詩坐騎更快。",
	["En el Clásico, la tela se puede donar en tu capital a cambio de reputación."] = "在經典版中，你可以在主城捐獻布料來換取聲望。",
	["En el Clásico, las bandas grandes son de 40 jugadores, y Zul'Gurub y las Ruinas de Ahn'Qiraj, de 20."] = "在經典版中，大型團隊副本是 40 人，祖爾格拉布和安其拉廢墟是 20 人。",
	["En el Clásico, los Renegados se quitan el miedo, el encanto y el sueño con su voluntad."] = "在經典版中，被遺忘者能靠意志擺脫恐懼、魅惑和睡眠效果。",
	["En el Clásico, los domingos por la tarde Bahía del Botín organizaba un concurso de pesca: ganaba quien entregara primero cuarenta peces de una especie especial."] = "在經典版中，每週日下午藏寶海灣都會舉辦釣魚大賽：最先交出四十條特殊魚的人獲勝。",
	["En el Clásico, los enanos pueden buscar tesoros con un rastreo propio. ¡Ideal para encontrar cofres!"] = "在經典版中，矮人有專屬的尋找財寶技能。找寶箱最合適了！",
	["En el Clásico, los enanos se convierten en piedra para quitarse venenos y sangrados, y son buenos con las armas de fuego."] = "在經典版中，矮人能化為石頭來擺脫毒藥和流血效果，而且擅長使用槍械。",
	["En el Clásico, los gnomos pueden ser guerreros, pícaros, magos o brujos."] = "在經典版中，地精可以當戰士、盜賊、法師或術士。",
	["En el Clásico, los gnomos son más listos que el resto, tienen talento para la ingeniería y se zafan de lo que los inmoviliza."] = "在經典版中，地精比其他種族更聰明，擅長工程學，還能掙脫定身效果。",
	["En el Clásico, los humanos ganan reputación más rápido gracias a su diplomacia, y tienen buen ojo para ver a los sigilosos."] = "在經典版中，人類憑藉外交才能獲得聲望更快，而且善於發現潛行的敵人。",
	["En el Clásico, los maestros de armas de las capitales te enseñan a usar armas nuevas."] = "在經典版中，主城的武器大師會教你使用新武器。",
	["En el Clásico, los orcos resisten mejor los aturdimientos y sus mascotas pegan más fuerte."] = "在經典版中，獸人更能抵抗昏迷效果，他們的寵物也打得更痛。",
	["En el Clásico, los tauren tienen más vida, un pisotón que aturde a los enemigos cercanos y mano verde con las hierbas."] = "在經典版中，牛頭人生命力更高，有一記能擊暈附近敵人的踐踏，還特別擅長採草藥。",
	["En el Clásico, los trols se regeneran rápido, entran en frenesí, pegan más fuerte a las bestias y son buenos con arcos y armas arrojadizas."] = "在經典版中，食人妖恢復得快，能進入狂暴，對野獸傷害更高，而且擅長弓和投擲武器。",
	["En el Clásico, muchas comidas te dejan bien alimentado y te suben estadísticas un buen rato."] = "在經典版中，許多食物會讓你進入「充分進食」狀態，在一段時間內提升屬性。",
	["En el Clásico, para pasar de 225 hay una misión de triaje en Theramore o en Sentencia."] = "在經典版中，要超過 225 點，需要在塞拉摩或落錘鎮完成一個急救任務。",
	["En el Clásico, quienes terminaron la cadena del cetro y tocaron el gong de Ahn'Qiraj ganaron un título y una montura únicos."] = "在經典版中，完成節杖任務鏈並敲響安其拉之鑼的人獲得了獨一無二的頭銜和坐騎。",
	["En el Clásico, solo elfos de la noche y tauren pueden ser druidas."] = "在經典版中，只有夜精靈和牛頭人能當德魯伊。",
	["En el Clásico, solo humanos y enanos pueden ser paladines."] = "在經典版中，只有人類和矮人能當聖騎士。",
	["En el Clásico, solo orcos, trols y tauren pueden ser chamanes."] = "在經典版中，只有獸人、食人妖和牛頭人能當薩滿。",
	["En el Clásico, tu Reencarnación te revive a ti mismo, pero necesita un ankh en tus bolsas."] = "在經典版中，轉生可以讓你自己復活，但背包裡需要有一個十字章。",
	["En el Enclave Cenarion los druidas enseñan a los suyos el camino de la naturaleza."] = "在塞納里奧區，德魯伊們向同伴傳授自然之道。",
	["En el Festival Lunar, la gente viene al Claro de la Luna a honrar a sus ancestros."] = "春節期間，人們來到月光林地祭拜祖先。",
	["En el Festival Lunar, un emisario en las capitales te puede llevar al Claro de la Luna para celebrar con los druidas."] = "春節期間，主城的使者可以帶你去月光林地和德魯伊們一起慶祝。",
	["En el Festival de Fuego del Solsticio de Verano hay hogueras en muchos pueblos: honrar las de tu bando da premios, y apagar las del otro también."] = "仲夏火焰節期間，許多城鎮都有營火：向自己陣營的營火致敬能獲得獎勵，熄滅對方的營火也可以。",
	["En el Festival de Invierno venden bolas de nieve. ¡Lánzaselas a tus amigos, que yo las atrapo!"] = "冬幕節期間有賣雪球。扔向你的朋友吧，我來接！",
	["En el Festival de Invierno, el Gran Padre Invierno reparte regalos en Forjaz y Orgrimmar, y bajo el árbol aparecen paquetes el día 25."] = "冬幕節期間，冬天爺爺會在鐵爐堡和奧格瑪發禮物，25 日那天樹下還會出現禮包。",
	["En el Festival de la Cosecha, la Horda honra a Grom Grito Infernal y la Alianza a Uther, en sus monumentos."] = "收穫節期間，部落在紀念碑前緬懷葛羅姆·地獄吼，聯盟則緬懷烏瑟。",
	["En el Núcleo de Magma se desuellan perros del núcleo para un cuero muy especial."] = "在熔火之心可以剝熔火惡犬的皮，得到一種非常特別的皮革。",
	["En el Santuario Esmeralda, los druidas intentan sanar el bosque enfermo."] = "在翡翠聖地，德魯伊們努力治癒生病的森林。",
	["En el Solsticio cada pueblo prende su hoguera. Me encanta el olor a leña... y a salchicha asada."] = "仲夏時每個城鎮都會點起營火。我好喜歡柴火的味道…還有烤香腸。",
	["En el Valle de Alterac pelean la Guardia Pico Tormenta de los enanos y el clan Lobo Gélido. Yo ya sé a quién le voy."] = "在奧特蘭克山谷，矮人的雷矛衛隊與霜狼氏族交戰。我早就知道我要支持誰了。",
	["En el Valle de la Fuerza están el banco y la casa de subastas: el corazón del comercio de la Horda."] = "力量谷有銀行和拍賣場：部落貿易的中心。",
	["En el camino"] = "順路",
	["En el centro de aquel Kalimdor estaba el Pozo de la Eternidad, un lago de pura magia. Unos trols que vivían a su orilla cambiaron con los siglos y se volvieron los elfos de la noche."] = "在遠古的卡林多中心，有一片純粹魔法構成的湖泊：永恆之井。住在湖畔的一些食人妖經過數百年的變化，成了夜精靈。",
	["En el centro de la garganta hay un enorme pozo de lava, la Caldera, donde trabajan esclavos de los Hierro Negro."] = "峽谷中央有一個巨大的熔岩坑，叫做大熔爐，黑鐵矮人的奴隸在那裡勞作。",
	["En el centro del cráter humea un volcán donde viven elementales de fuego."] = "火山口中央有一座冒著煙的火山，裡面住著火元素。",
	["En el chat"] = "在聊天視窗",
	["En el corazón del Templo de la Luna hay un pozo lunar, donde las sacerdotisas rezan a Elune."] = "月神殿的中心有一口月井，女祭司們在那裡向伊露恩祈禱。",
	["En el cráter, un tal Linken perdió la memoria y busca su espada y su escudo: un guiño a cierto héroe de orejas puntiagudas."] = "在火山口裡，一個叫林肯的傢伙失去了記憶，正在尋找他的劍和盾：這是在向某位尖耳朵英雄致敬。",
	["En el cuadro de cada pieza de equipo: lo que ganas y lo que pierdes contra lo que llevas puesto, con números."] = "在每件裝備的提示框裡：用數字顯示與身上裝備相比得到和失去什麼。",
	["En el este de las Tierras Inhóspitas viven dragones negros y sus siervos. Pasa lejitos si no llevas compañía."] = "荒蕪之地東部住著黑龍和牠們的僕從。如果你獨自一人，就離遠點。",
	["En el este del lago viven ogros que les hacen la vida difícil a los enanos de Thelsamar."] = "湖的東邊住著巨魔，讓塞爾薩瑪的矮人們日子很不好過。",
	["En el gran salar del este, goblins y gnomos organizan carreras; la rivalidad es feroz."] = "在東邊的大鹽灘上，哥布林與地精舉辦賽車；競爭非常激烈。",
	["En el juego"] = "在遊戲中",
	["En el lago de Villa del Lago hay múrlocs, ¡como en casi todo lago de Azeroth!"] = "湖畔鎮的湖裡有魚人，艾澤拉斯幾乎每個湖裡都有！",
	["En el mapa"] = "在地圖上",
	["En el mapa de Alfa, clic: seguirla con la flecha o guardarla como marcador."] = "在 Alfa 的地圖上點擊：用箭頭跟隨它，或將其儲存為標記。",
	["En el mapa de Alfa, la capa «Peligros» marca los élites y los raros de tu zona que te pueden ganar: en rojo los que te pasan por mucho. Se arma al abrir el mapa."] = "在 Alfa 的地圖上，「危險」圖層會標出你區域裡能打敗你的精英和稀有怪：遠高於你等級的以紅色顯示。開啟地圖時產生。",
	["En el mapa de Alfa, la capa «Por descubrir» marca los rincones de tu zona que no has pisado, y «Vuelos que te faltan» los maestros de vuelo que aún no conoces. Clic en un vuelo y la flecha te lleva."] = "在 Alfa 的地圖上，「未探索」圖層標出你區域裡還沒去過的角落，「缺少的飛行點」標出你還不認識的飛行管理員。點一個飛行點，箭頭就帶你去。",
	["En el mapa del mundo"] = "在世界地圖上",
	["En el mapa del mundo, cada zona con lobos dice cuántos hay en cada guarida."] = "在世界地圖上，每個有狼的區域都會顯示每個巢穴裡有幾隻狼。",
	["En el marco del objetivo"] = "目標框架",
	["En el menú de una misión: toda su cadena, lo que ya hiciste y el premio del final."] = "在任務的選單中：它的完整任務鏈、你已完成的部分和最終獎勵。",
	["En el minimapa"] = "在小地圖上",
	["En el muelle: sale en %s hacia %s"] = "在碼頭：%s 後開往 %s",
	["En el mundo"] = "野外",
	["En el nivel 10 domas tu bestia."] = "10 級時可以馴服你的野獸。",
	["En el nivel 20 aprendes venenos."] = "20 級時學會毒藥。",
	["En el norte de estas tierras, la Cruzada Escarlata domina un pueblo amurallado y lo defiende con fanatismo."] = "在這片土地的北部，血色十字軍佔據著一座有城牆的城鎮，狂熱地守衛著它。",
	["En el oeste de Las Mil Agujas anidan dracoleones salvajes."] = "千針石林西部棲息著野生的雙足飛龍。",
	["En el pueblo de los druidas del Claro de la Luna conviven Alianza y Horda: el Círculo Cenarion recibe a todos."] = "在月光林地的德魯伊村莊裡，聯盟與部落和平共處：塞納里奧議會歡迎所有人。",
	["En el sur de Desolace, demonios y sátiros se reúnen en un aquelarre."] = "在淒涼之地南部，惡魔與薩特聚在一起舉行集會。",
	["En el sur de Tanaris hay colmenas de silítidos, primos de los de Silithus."] = "塔納利斯南部有異種蟲的巢穴，跟希利蘇斯的是親戚。",
	["En el sureste, la Mano de Tyr es la ciudad más fuerte que le queda a la Cruzada Escarlata."] = "在東南方，提爾之手是血色十字軍僅存的最強城市。",
	["En espera"] = "等待中",
	["En esta página, cuánto llevas descubierto de cada zona de tu continente y lo que te falta."] = "在這個頁面中，查看你所在大陸每個區域已探索了多少、還剩多少。",
	["En esta página, lo que te sirve más en el banco o con otro personaje: materiales de sus recetas, lo que piden sus misiones y equipo que tu clase no usa."] = "這一頁顯示放在銀行或給其他角色更有用的東西：他們配方用的材料、他們任務需要的東西，以及你職業用不到的裝備。",
	["En esta página, un buscador por las bolsas, bancos y equipo de todos tus personajes, con filtros de tipo, calidad y personaje."] = "在這個頁面中，可以搜尋你所有角色的背包、銀行和裝備，並依類型、品質和角色篩選。",
	["En esta zona"] = "在此地區",
	["En estas laderas está Durnholde, donde Aedelas Blackmoore crió a Thrall como gladiador."] = "敦霍爾德就在這些山坡上，艾德拉斯·黑摩爾在那裡把索爾培養成角鬥士。",
	["En estas tierras cayó Anduin Lothar, el León de Azeroth, durante la Segunda Guerra."] = "「艾澤拉斯之獅」安度因·洛薩在第二次戰爭中倒在了這片土地上。",
	["En estas tierras estuvo Strom, la capital de Arathor, el primer gran reino humano."] = "這片土地上曾經矗立著斯托姆，那是第一個偉大的人類王國阿拉索的首都。",
	["En este pantano se hundió el Templo de Atal'Hakkar: los dragones verdes lo hundieron para frenar a los sacerdotes de Hakkar."] = "阿塔哈卡神廟沉入了這片沼澤：綠龍讓它沉沒，以阻止哈卡的祭司。",
	["En estos días las calles se llenan de calabazas y velas. A mí me dan un poquito de miedo."] = "這些天街上到處是南瓜和蠟燭。它們讓我有一點點害怕。",
	["En forma de felino te vuelves sigiloso. Acércate sin que te vean."] = "獵豹形態下進入潛行。悄悄靠近不被發現。",
	["En forma de felino y por la espalda: mucho daño."] = "獵豹形態下從背後攻擊：傷害很高。",
	["En forma de felino, un arañazo que hace sangrar."] = "獵豹形態下的一記爪擊，讓敵人流血。",
	["En forma de oso, golpea a varios enemigos cerca."] = "熊形態下攻擊附近的多個敵人。",
	["En grifo, la línea de tu vuelo en el mapa: por dónde vas, dónde aterrizas y el tiempo que falta."] = "乘坐獅鷲時，地圖上會顯示你的飛行路線：你現在在哪裡、在哪裡降落，以及剩餘時間。",
	["En grupo"] = "組隊時",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "組隊時幾乎總是有好幾個敵人：你一次打兩個。",
	["En grupo o con tu mascota: tu amenaza sobre tu objetivo. Te avisa antes de quitárselo al tanque, o si eres tanque, antes de perderlo."] = "組隊或帶著寵物時：你對目標的仇恨。在你搶走坦克的仇恨之前提醒你；如果你是坦克，則在你失去仇恨之前提醒。",
	["En grupo y aguantando: Furia justa te da más amenaza."] = "組隊坦怪時：正義之怒讓你產生更多仇恨。",
	["En grupo, Alfa muestra una barra pequeña con tu amenaza sobre tu objetivo. Se pone amarilla antes de que se lo quites al tanque y roja si ya te ataca a ti. Si eres tanque, te avisa cuando están por quitártelo."] = "組隊時，Alfa 會顯示一條小橫條，表示你對目標的仇恨。在你從坦克那裡搶到仇恨之前變黃，如果牠已經在攻擊你則變紅。如果你是坦克，有人快搶走仇恨時會提醒你。",
	["En grupo, al seleccionar un raro sin marca, Alfa te ofrece ponerle la calavera con un clic: todo tu grupo la ve. En banda, si eres líder o ayudante."] = "在隊伍中選取沒有標記的稀有怪時，Alfa 會讓你一鍵給它標上骷髏：全隊都看得到。在團隊中需要你是團長或助理。",
	["En grupo, cura al tanque antes que a nadie."] = "組隊時，優先治療坦克。",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "組隊時，先治療坦克，也不要自己去拉怪。",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "組隊時，在生命值掉太多之前就治療：比較省法力。",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "組隊時，把法力與治療圖騰放在隊伍附近。",
	["En grupo, dónde está lo que pide cada misión y quién la lleva."] = "組隊時，顯示每個任務要做的地方，以及誰接了它。",
	["En grupo, si alguien no tiene una misión que tú llevas, el rastreador te lo dice con «Compartir». Un clic y se la ofreces."] = "組隊時，如果有人沒有你身上的任務，追蹤器會用「分享」提醒你。點一下就能分享。",
	["En grupo, si alguien no tiene una misión tuya, un botón para compartírsela."] = "組隊時，如果有人沒有你的某個任務，會出現分享按鈕。",
	["En la %s"] = "在%s",
	["En la Arena Gurubashi aparece de vez en cuando un cofre que todos se pelean. ¡Sálvese quien pueda!"] = "古拉巴什競技場時不時會出現一個寶箱，大家都搶著要。各憑本事吧！",
	["En la Enciclopedia"] = "在百科中",
	["En la Feria canjeas vales por premios; los vales se ganan entregando cosas que hiciste con tu profesión o que juntaste cazando."] = "在馬戲團裡可以用獎券兌換獎品；交出你用專業製作或狩獵收集的東西就能賺獎券。",
	["En la Feria de la Luna Negra, la adivina Sayge te hace unas preguntas y te da una fortuna que sube tus estadísticas un buen rato."] = "在暗月馬戲團，算命師塞吉會問你幾個問題，然後給你一份運勢，在一段時間內提升你的屬性。",
	["En la Fortaleza de Grommash, Thrall recibe a quien venga; muy cerca está Eitrigg, el viejo orco amigo de Tirion."] = "在格羅瑪什要塞，索爾接見所有來訪者；附近站著艾崔格，那位和提里奧結為好友的老獸人。",
	["En la Guerra de las Arenas Movedizas, el archidruida Fandral perdió a su hijo Valstann a manos de los qiraji."] = "在流沙之戰中，大德魯伊范達爾的兒子瓦斯坦死於其拉蟲人之手。",
	["En la Segunda Guerra, la Horda sumó a los trols Amani, a los ogros y a dragones rojos esclavizados."] = "第二次戰爭中，阿曼尼食人妖、巨魔和被奴役的紅龍加入了部落。",
	["En la Semana de los Niños, los huérfanos de Ventormenta y Orgrimmar te piden que los lleves de paseo; al final te dan una mascota."] = "兒童週期間，暴風城和奧格瑪的孤兒會請你帶他們出去玩；最後他們會送你一隻寵物。",
	["En la Tercera Guerra, orcos, humanos y elfos se unieron aquí contra Archimonde, y Nordrassil sacrificó su energía para destruirlo."] = "第三次戰爭中，獸人、人類與精靈在這裡聯手對抗阿克蒙德，諾達希爾犧牲了自己的能量摧毀了他。",
	["En la Terraza de los Artesanos de Darnassus están los maestros de profesiones."] = "達納蘇斯的工匠區有各專業的訓練師。",
	["En la Vega se encuentran páginas sueltas de un libro de Nesingwary; junta un capítulo completo y llévaselo."] = "在荊棘谷可以找到奈辛瓦里一本書的散頁；湊齊完整的一章交給他。",
	["En la batalla de Hyjal, Malfurion hizo sonar el Cuerno de Cenarius y miles de fuegos fatuos rodearon a Archimonde hasta destruirlo."] = "在海加爾山之戰中，瑪法里恩吹響了塞納留斯之角，成千上萬的小精靈包圍了阿克蒙德，直到將他摧毀。",
	["En la casa de subastas, mira los precios unos días antes de vender: cambian según la hora y quién esté jugando."] = "在拍賣場賣東西之前，先觀察幾天價格：價格會隨時段和線上的人而變化。",
	["En la cima del Monte Hyjal crece Nordrassil, el Árbol del Mundo, que los dragones bendijeron."] = "世界之樹諾達希爾生長在海加爾山頂，受過巨龍的祝福。",
	["En la costa de Durotar, soldados de Kul Tiras ocupan el Fuerte Tiragarde: una espina clavada en la tierra de la Horda."] = "在杜洛塔的海岸，庫爾提拉斯士兵佔據著提拉加德城堡：這是扎在部落土地上的一根刺。",
	["En la costa de Tanaris se esconden piratas de los Mares del Sur."] = "塔納利斯的海岸上藏著南海海盜。",
	["En la costa del pantano hay naga, y no reciben bien a los curiosos."] = "沼澤的海岸上有納迦，他們不歡迎好奇的人。",
	["En la costa este vive una tribu trol amiga de la Horda, enemiga de los trols de Jintha'Alor."] = "東海岸住著一個與部落友好的食人妖部族，他們與辛薩羅的食人妖為敵。",
	["En la costa oeste de Vallefresno, las Cavernas de Brazanegra fueron un templo de Elune; hoy están hundidas y llenas de naga."] = "在梣谷西海岸，黑澗深淵曾是一座伊露恩神殿；如今它已沉沒，到處是納迦。",
	["En la costa se ven ruinas de antiguos palacios élficos, medio hundidos en el mar."] = "沿著海岸可以看到古代精靈宮殿的遺跡，一半沉在海裡。",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "船艙洞穴裡有很多海盜：不要全部一起跳下碼頭。",
	["En la excavación de Ironband, los troggs salieron de la tierra y se quedaron con todo."] = "在鐵環挖掘場，穴居人從地底鑽出來，把一切都佔了。",
	["En la ficha de cada mazmorra está el botín de cada jefe y lo que mejora tu equipo."] = "每個地城的資料裡有每個首領的掉落和能提升你裝備的東西。",
	["En la granja de los Saldean, la vieja yegua Blanchy necesita avena. Es de las misiones más tiernitas de los Páramos."] = "在薩丁農場，老馬布蘭契需要燕麥。這是西部荒野最溫馨的任務之一。",
	["En la guarida de Onyxia, a los lados hay nidos con huevos: si alguien los pisa salen dragoncitos... muchísimos."] = "在奧妮克希亞的巢穴兩側有滿是蛋的巢：要是有人踩到，就會冒出幼龍…非常多。",
	["En la pelea, el juego te avisa"] = "戰鬥中，遊戲會提醒你",
	["En la sala de la Liga de Expedicionarios de Forjaz hay biblioteca, mapas y un museo con fósiles gigantes."] = "鐵爐堡的探險者協會大廳有圖書館、地圖和一座陳列巨大化石的博物館。",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "第二階段先殺她：她的治療量很大。",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "拍賣以看到的最低價格計算，並扣除手續費（%d%%，估計值）。分解則使用經典版遊戲的資料表，同樣是估計值。",
	["En la subasta, unos %s."] = "拍賣場大約 %s。",
	["En la ventana y aquí. Si no estás entre ellos, tu fila sale al final."] = "在視窗與這裡顯示。如果你不在其中，你的那一列會顯示在最後。",
	["En las Cuevas de los Lamentos, el druida Naralex soñó con devolverle el verdor a Los Baldíos, y su sueño se volvió pesadilla."] = "在哀嚎洞穴，德魯伊納拉雷克斯夢想讓貧瘠之地重現綠意，他的夢卻變成了惡夢。",
	["En las Guerras Trol, los altos elfos enseñaron magia a cien humanos para vencer juntos a los Amani. Fueron los primeros magos de la humanidad."] = "在食人妖戰爭中，高等精靈把魔法教給一百名人類，一起擊敗阿曼尼。他們是人類最早的法師。",
	["En las Mazmorras de Ventormenta los presos se amotinaron, y la guardia pide ayuda para calmar el desastre."] = "暴風城監獄的囚犯發動了暴亂，衛兵正在找人幫忙平息亂局。",
	["En las Pozas de la Visión, bajo una de las mesetas, entrenan los magos y sacerdotes Renegados."] = "在其中一座台地下方的預見之池，被遺忘者的法師和牧師在那裡訓練。",
	["En las cuevas de Cuna del Invierno viven yetis peludos y gruñones."] = "冬泉谷的洞穴裡住著毛茸茸、脾氣暴躁的雪人。",
	["En las cuevas de Feralas viven yetis, y los ogros Gordunni tienen sus campamentos en el norte."] = "菲拉斯的洞穴裡住著雪人，戈杜尼巨魔在北邊紮營。",
	["En las cuevas nevadas de Dun Morogh viven trols de las nieves que no quieren a los enanos ni tantito."] = "丹莫洛的雪洞裡住著冰霜食人妖，他們一點也不喜歡矮人。",
	["En las dos armas"] = "兩把武器都有",
	["En las granjas del oeste hay calderos de la Plaga que siguen esparciendo la peste; la Alianza manda aventureros a destruirlos."] = "西邊的農場裡有天譴軍團的瘟疫大鍋，仍在散播瘟疫；聯盟派冒險者去摧毀它們。",
	["En las ruinas de la ciudad de Alterac hoy mandan los ogros y el Sindicato, la banda de nobles caídos del viejo reino."] = "如今統治奧特蘭克城廢墟的是巨魔和辛迪加，後者是舊王國沒落貴族組成的幫派。",
	["En lo alto de la sierra hay un pico sagrado para los druidas elfos, donde anidan aves enormes."] = "山脈高處有一座精靈德魯伊的聖峰，巨大的鳥在那裡築巢。",
	["En lo más alto de la Montaña Roca Negra manda Nefarian, hijo de Alamuerte."] = "統治黑石山最高處的是死亡之翼之子奈法利安。",
	["En los Páramos de Poniente el viento mueve los molinos. Ojo con los Defias en las granjas."] = "西部荒野的風吹動著風車。小心農場裡的迪菲亞。",
	["En los mapas"] = "在地圖上",
	["En lugar de las del juego"] = "取代遊戲背包",
	["En marcha"] = "進行中",
	["En marcha hacia %s"] = "正在前往%s",
	["En mazmorra"] = "在地城中",
	["En mazmorras y bandas"] = "在地城與團隊副本中",
	["En mazmorras y en combate Lya se hace chiquita, se calla y no estorba tus clics. Al terminar vuelve."] = "在地城和戰鬥中，莉婭會變小、保持安靜，也不會擋住你的點擊。之後她就回來。",
	["En memoria"] = "紀念",
	["En memoria de una gran perrita"] = "紀念一隻很棒的小狗",
	["En mi zona"] = "在我的地區",
	["En movimiento"] = "動態",
	["En orco, «Lok'tar ogar» quiere decir «victoria o muerte»."] = "在獸人語中，「Lok'tar ogar」的意思是「不勝利，毋寧死」。",
	["En otra zona: %s"] = "在其他地區：%s",
	["En pantalla"] = "顯示中",
	["En pausa"] = "已暫停",
	["En pausa dentro de la instancia"] = "副本中暫停",
	["En pausa por ahora"] = "暫時暫停",
	["En pausa: hay otro addon de pesca activo"] = "已暫停：另一個釣魚插件正在啟用",
	["En plena Segunda Guerra, Gul'dan abandonó a la Horda para buscar la Tumba de Sargeras. Ahí lo despedazaron los demonios que encontró."] = "第二次戰爭正激烈時，古爾丹拋下部落去尋找薩格拉斯之墓。他在那裡被遇到的惡魔撕成了碎片。",
	["En posadas y ciudades acumulas XP descansada: ganas el doble de XP por enemigo hasta gastarla. Si cierras sesión aquí, también se acumula."] = "在旅店和城鎮中會累積休息經驗：擊殺敵人可獲得雙倍經驗值，直到用完為止。在這裡登出也會累積。",
	["En posadas y ciudades juntas XP descansada: ganas el doble por enemigo hasta gastarla."] = "在旅店與城市中會累積休息經驗：每個敵人獲得雙倍經驗，直到用完。",
	["En qué orden aparecen."] = "顯示的順序。",
	["En qué se gastan"] = "用在哪裡",
	["En silencio"] = "靜音",
	["En solitario es lento: usa la varita para rematar."] = "單練時殺怪較慢：用魔杖收尾。",
	["En solitario, deja curas que duran en el tiempo y pelea con Cólera."] = "單練時，先上持續治療，再用憤怒術戰鬥。",
	["En solitario, pelea con choques y cúrate entre monstruos."] = "單練時，用震擊戰鬥，並在兩隻怪之間治療自己。",
	["En su ficha toca «Agregar a mi ruta»."] = "在它的詳細頁面點擊「加入我的路線」。",
	["En sus inicios, una batalla del Valle de Alterac podía durar horas... ¡y hasta días!"] = "早期的奧特蘭克山谷，一場戰鬥能打上好幾個小時…甚至好幾天！",
	["En todo Alfa"] = "在整個 Alfa 中",
	["En total, %d cosas por unos %s."] = "共 %d 件，約 %s。",
	["En total: %s"] = "總計：%s",
	["En tu arma"] = "武器上已有",
	["En tu marco"] = "你的框架",
	["En tu plan"] = "在你的計畫中",
	["En tu registro"] = "在你的任務日誌中",
	["En tus bolsas"] = "在你的背包裡",
	["En tus bolsas, el botín, el chat o cualquier enlace: Alt+clic abre la guía para conseguirlo o, si no hay, su ficha en la enciclopedia."] = "在背包、戰利品、聊天或任何連結中：Alt+點擊可開啟取得它的指南；如果沒有，則開啟它在百科中的詳細頁面。",
	["En tus bolsas: con un comerciante vende tu chatarra; con un banquero guarda tus materiales. Con tu clic."] = "在你的背包裡：在商人處賣掉垃圾；在銀行職員處存放材料。由你點擊執行。",
	["En tus bolsas: úsala para aprenderla"] = "在你的背包中：使用它來學會",
	["En tus recetas que dejan ganancia, primero las que ya puedes hacer con lo que llevas, y cuánto ganarías haciéndolas todas."] = "在你能賺錢的配方中，用身上材料現在就能做的排在最前面，並顯示全部做完能賺多少。",
	["En un aviso"] = "以提醒顯示",
	["En un aviso y en el chat"] = "以提醒顯示並發到聊天視窗",
	["En un cañón de Vallefresno, Grom mató al señor demonio Mannoroth y liberó a los orcos de su sangre maldita."] = "在梣谷的一處峽谷中，葛羅姆殺死了惡魔領主瑪諾洛斯，讓獸人擺脫了他被詛咒的血液。",
	["En un paso de «Sube al nivel», cuánta experiencia te falta y dónde rinde más: enemigos de tu nivel que cuentan para tus misiones."] = "在「升到等級」的步驟上，顯示需要多少經驗以及哪裡收益最高：和你同等級、又算在你任務裡的敵人。",
	["En un valle de Frondavil cayeron infernales del cielo, y todavía se ven sus cráteres."] = "費伍德森林的一座山谷裡曾有地獄火從天而降，至今還能看到它們砸出的坑。",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "搭乘有中途站的航線時，計時器下方會顯示下一站在哪裡、還要多久抵達。需要開啟飛行計時器。",
	["En una aldea del sur del bosque, los vecinos parecen normales de día... y de noche se convierten en worgen."] = "在森林南部的一座村莊，村民白天看起來很正常…到了晚上就會變成狼人。",
	["En una de las mesetas, los tauren honran a los espíritus de sus ancestros."] = "在其中一座台地上，牛頭人祭拜祖先的靈魂。",
	["En una instancia: la flecha vuelve al salir"] = "在副本中：離開後箭頭就會回來",
	["En una isla de Azshara vive el duque Hydraxis, señor del agua; su gente te ayuda a apagar las runas del Núcleo de Magma."] = "水元素領主海達克西斯公爵住在艾薩拉外海的一座島上；他的手下會幫你熄滅熔火之心的符文。",
	["En una mazmorra no hay guaridas."] = "地城裡沒有巢穴。",
	["En una pestaña nueva"] = "在新分頁中",
	["En unos segundos aparece tu build."] = "幾秒後就會顯示你的配點。",
	["En uso"] = "使用中",
	["En uso, a tu gusto"] = "使用中，依你的喜好",
	["En vivo"] = "即時",
	["En vivo si estás con un banquero; si no, la última foto."] = "在銀行職員旁時即時顯示；否則顯示最新快照。",
	["En vuelo a %s"] = "飛往%s",
	["En vuelo: la flecha sigue al bajar"] = "飛行中：降落後箭頭會繼續",
	["En vuelo: la flecha sigue al bajar."] = "飛行中：降落後箭頭會繼續指引。",
	["Enanos"] = "矮人",
	["Encanta tu arma antes de pelear."] = "戰鬥前為武器附魔。",
	["Encanta tu arma para pegar más fuerte. Renuévalo cuando se acabe."] = "附魔你的武器讓它打得更重。效果消失時重新施放。",
	["Encantada"] = "已附魔",
	["Encantamiento"] = "附魔",
	["Encantamientos con Polvo de almas y Esencia astral."] = "用靈魂之塵和星界精華的附魔。",
	["Encantamientos con Polvo de ilusión y Esencia eterna."] = "用幻影之塵和永恆精華的附魔。",
	["Encantamientos con Polvo de sueño y Esencia abisal."] = "用夢境之塵和虛空精華的附魔。",
	["Encantamientos con Polvo de visión y Esencia mística."] = "用幻象之塵和祕法精華的附魔。",
	["Encantamientos de brazales y capas con Polvo extraño y Esencia mágica mayor."] = "用奇異之塵和強效魔法精華附魔護腕和披風。",
	["Encantamientos menores de brazales y pecheras con Polvo extraño."] = "用奇異之塵的初級護腕和胸甲附魔。",
	["Encantar a otros es un servicio: anúnciate en el chat de comercio de la ciudad."] = "為別人附魔是一項服務：在城裡的交易頻道打廣告吧。",
	["Encender el registro"] = "開啟記錄",
	["Encender la pesca"] = "開啟釣魚",
	["Encender las recomendadas"] = "開啟推薦項目",
	["Encender una fogata"] = "點燃營火",
	["Encenderla"] = "開啟",
	["Encenderlos"] = "開啟",
	["Encendida: entra al plan aunque el filtro la deje fuera. Apagada: queda fuera."] = "開啟：即使被篩選條件排除也會加入計畫。關閉：不加入。",
	["Encendido"] = "已開啟",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "開啟：釣魚時雙擊會再次拋竿，按住 Shift、Ctrl 或 Alt 雙擊則收竿。關閉：兩者相反。",
	["Enciclopedia"] = "百科",
	["Enciende las comodidades recomendadas"] = "開啟推薦的便利功能",
	["Enciende los cambios de abajo en el cuadro que sale al pasar el ratón por un personaje o criatura."] = "對滑鼠移到角色或生物上時出現的提示，啟用下方的各項調整。",
	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "在試衣間（Ctrl+點擊物品）啟用下方的各項調整。",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "啟用下方的各項調整，每一項都可以單獨關閉。部分插件會在 /reload 後才把按鈕對齊方形小地圖。",
	["Enciende primero la guía en el minimapa."] = "請先開啟「小地圖上的指南」。",
	["Enciende primero los servicios."] = "請先開啟「服務」。",
	["Enciéndela para ver en combate qué habilidad conviene ahora y cuáles siguen, en un ícono pequeño que puedes mover."] = "開啟後，戰鬥中會在一個可移動的小圖示裡顯示現在該用哪個技能以及接下來用哪些。",
	["Enciéndelo en el menú del juego: Opciones > %s > «%s». Alfa no lo cambia por ti: el medidor del juego lo lee en combate y fallaría."] = "請在遊戲選單中開啟：選項 > %s > 「%s」。Alfa 不會替你變更：遊戲的傷害統計會在戰鬥中讀取它，改了會出錯。",
	["Enciéndelos abajo, en Marcos, para ver a tu grupo con su vida y curar con un clic."] = "在下方「框架」中開啟，就能看到隊友的生命值並一鍵治療。",
	["Enciéndelos en la página Curación."] = "請在「治療」頁面開啟。",
	["Enciéndelos para ver a tu grupo con su vida y curar con un clic."] = "開啟後可查看隊伍的生命值，並一鍵治療。",
	["Encontré %d cosas que revisar."] = "我發現了 %d 處需要檢查。",
	["Encontré 1 cosa que revisar."] = "我發現了 1 處需要檢查。",
	["Encuentra %d raro"] = "找到 %d 隻稀有怪",
	["Encuentra %d raros"] = "找到 %d 隻稀有怪",
	["Enemigo raro"] = "稀有敵人",
	["Enemigos menores"] = "次要敵人",
	["Enfermedad"] = "疾病",
	["Enfoque interno: tu siguiente hechizo es gratis y más crítico."] = "心靈專注：你的下一個法術免費且更容易致命一擊。",
	["Enraíza al monstruo y aléjate antes de lanzar tus hechizos largos."] = "定住怪物並拉開距離，再施放施法時間長的法術。",
	["Entendido"] = "了解",
	["Entereza"] = "真言術：韌",
	["Entorno"] = "環境",
	["Entra a %d mazmorra"] = "進入 %d 個地城",
	["Entra a %d mazmorras"] = "進入 %d 個地城",
	["Entra al juego con él una vez."] = "用它登入遊戲一次。",
	["Entra con el registro limpio: entrega lo que ya tienes."] = "帶著整潔的任務日誌進去：先交付你已有的任務。",
	["Entra en el plan que termina y entrega tus misiones por el camino más corto, con lo que pide antes."] = "加入以最短路線完成並繳交你的任務的計畫，連同它需要先做的事。",
	["Entrada"] = "入口",
	["Entrada enemiga"] = "敵方入口",
	["Entradas de mazmorras"] = "地城入口",
	["Entradas en el minimapa"] = "小地圖上的入口",
	["Entradas y salidas"] = "入口與出口",
	["Entramos a %s. Antes de cada pelea, espera a que quien cura tenga maná."] = "我們進入了%s。每場戰鬥前，等治療者有法力。",
	["Entramos juntos a lo oscuro. Yo te cuido la espalda."] = "我們一起走進了黑暗。我守著你的背後。",
	["Entraron %s, con lo que piden antes de entregarlas."] = "已加入 %s，以及繳交前需要先做的事。",
	["Entraste a %s"] = "你進入了%s",
	["Entraste a %s."] = "你進入了%s。",
	["Entrañas son las criptas y catacumbas bajo la antigua capital de Lordaeron."] = "幽暗城是洛丹倫舊都地下的墓穴與地下墓窟。",
	["Entrañas tiene barrios para magos, pícaros, guerreros y boticarios, y en el anillo central están el banco y la casa de subastas."] = "幽暗城有法師、盜賊、戰士與藥劑師各自的區域，中央環區有銀行和拍賣場。",
	["Entre Entrañas y Grom'gol también hay zepelín: así bajas al sur sin cruzar todo el continente."] = "幽暗城和格羅姆高之間也有飛艇：這樣不用橫穿整片大陸就能南下。",
	["Entre los druidas están los de la Garra, que se vuelven osos, y los del Espolón, que toman forma de cuervo."] = "德魯伊中有會變成熊的利爪德魯伊，也有會化身烏鴉的猛禽德魯伊。",
	["Entrega %d de %d: %s."] = "第 %d 個，共 %d 個：%s。",
	["Entrega %d misiones"] = "交 %d 個任務",
	["Entrega %d misión"] = "交 %d 個任務",
	["Entrega 1 de %d: %s."] = "第 1 個，共 %d 個：%s。",
	["Entrega lo que terminaste"] = "交掉已完成的",
	["Entrega tus %d misiones listas"] = "交付你已完成的 %d 個任務",
	["Entrega tus misiones listas"] = "交掉已完成的任務",
