	["Entregaste todo en %d parada."] = "共停靠 %d 處，全部交完。",
	["Entregaste todo en %d paradas."] = "共停靠 %d 處，全部交完。",
	["Entrenador"] = "訓練師",
	["Entrenador al día"] = "訓練已是最新",
	["Entrenador de %s"] = "%s訓練師",
