	["Entrenador: %s, en %s."] = "訓練師：%s，位於%s。",
	["Entrenador: %s."] = "訓練師：%s。",
	["Entrenadores de profesión"] = "專業訓練師",
	["Entrenar"] = "訓練",
	["Entrenar la rápida"] = "學習快速騎術",
	["Entrégala a %s."] = "交給%s。",
	["Entró %s, con lo que pide antes de entregarla."] = "已加入 %s，以及繳交前需要先做的事。",
	["Envenena al enemigo un rato. Ponla al inicio de cada pelea."] = "讓敵人中毒一段時間。每場戰鬥開始時加上。",
	["Envenena y lanza rayos: quita el veneno si puedes."] = "他會施毒並施放閃電：能解毒的話就解毒。",
	["Equilibrada"] = "均衡",
	["Equilibrado"] = "均衡",
	["Equilibrado: se ve bien y corre bien en casi cualquier equipo."] = "均衡：畫面好看，幾乎在任何電腦上都執行順暢。",
	["Equilibrio"] = "平衡",
	["Equilibrio para subir"] = "平衡（練等）",
	["Equipa tu caña de pescar"] = "裝備你的魚竿",
	["Equipo"] = "裝備",
	["Equipo %d %%"] = "裝備 %d %%",
	["Equipo a punto de romperse."] = "裝備快要損壞了。",
	["Equipo de pesca"] = "釣魚裝備",
	["Equipo reparado, comida, espacio y lo de tu clase: a cazar con la manada."] = "裝備修好了，食物、空間和職業材料都備齊：和狼群一起去狩獵吧。",
	["Equipo y banco"] = "裝備與銀行",
	["Equipo y cebos"] = "裝備與魚餌",
	["Equipo y estadísticas"] = "裝備與屬性",
	["Equipo, bolsas, comida y lo de tu clase"] = "裝備、背包、食物和職業材料",
	["Equipo, consumibles, misiones, materiales... con encabezados que se pliegan."] = "裝備、消耗品、任務物品、材料……標題可摺疊。",
	["Equitación"] = "騎術",
	["Equitación de aprendiz (nivel 40)"] = "初級騎術（40 級）",
	["Equitación de oficial (la rápida, nivel 60)"] = "中級騎術（快速，60 級）",
	["Eranikus, el consorte de Ysera, quedó atrapado en la pesadilla; su sombra ronda el Templo de Atal'Hakkar."] = "伊瑟拉的配偶伊蘭尼庫斯被困在夢魘中；他的陰影在阿塔哈卡神廟中徘徊。",
	["Eres de la manada"] = "你是狼群的一員",
	["Eres nivel %d"] = "你的等級是 %d",
	["Eres nivel %d y se recomienda el %d: desde ahí cuenta así."] = "你是 %d 級，建議 %d 級：從那裡開始這樣計算。",
	["Eres nivel %d."] = "你的等級是 %d。",
	["Error"] = "錯誤",
	["Errores atrapados"] = "捕捉到的錯誤",
	["Errores de Alfa"] = "Alfa 的錯誤",
	["Errores de Lua de Alfa en esta sesión:"] = "本次遊戲中 Alfa 的 Lua 錯誤：",
	["Errores de Lua de Alfa en esta sesión: ninguno"] = "本次遊戲中 Alfa 的 Lua 錯誤：無",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "這個地城很短，位於暴風城內。囚犯關在兩側的牢房裡：慢慢推進。",
	["Es de la otra facción"] = "屬於另一陣營",
	["Es de una misión."] = "這是任務物品。",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "聯盟有任務需要擊敗這個首領：進去前先檢查你的任務。",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "第一個首領，很簡單。他死後，你陣營的囚犯會打開通往庭院的門。",
	["Es el primer reto: con él se abre el Legado."] = "這是第一個挑戰：完成後傳承就會開啟。",
	["Es el punto %d de %d de tu build."] = "這是你配點的第 %d/%d 點。",
	["Es el que toca ahora."] = "現在該點這個。",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "墓地的最後一個首領。他會在周圍釋放火焰：遠程職業請保持距離。",
	["Es el único lobo a la vista."] = "視野中只有這一隻狼。",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "這裡很大，很容易迷路：跟著同一個人走，不要自己亂跑。",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "這是斯尼德的機器：把它打壞，他就會出來戰鬥。",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "部落的第一個地城：很短，適合學習團隊合作。",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "聯盟的第一個大型地城：慢慢推進，一次拉一群怪。",
	["Es la que más vale al venderla."] = "這是賣價最高的。",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "這個地城很長，有兩個入口。很多敵人是石頭做的，攻擊很痛。",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "這個地城很長，有很多機器人：有些會放炸彈，或拉響警報引來更多敵人。",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "他動作很慢：遠程職業可以趁他靠近時攻擊。",
	["Es muy veloz: frénalo si tu clase puede."] = "他速度很快：你的職業能減速的話就減速他。",
	["Es opcional. Si dices que sí, los lobos de La Jauría que usan Alfa ven a tu personaje en el mapa de WoW, como ves a tu grupo, y pueden llegar a donde estás con la flecha; y tú a ellos. Alfa solo comparte dónde anda tu personaje dentro del juego: la zona, el punto en el mapa, su nivel y su clase. Nada de tu ubicación real, tu computadora ni tu cuenta."] = "這是可選的。如果你同意，使用 Alfa 的 La Jauría 狼群成員就能在 WoW 地圖上看到你的角色，就像你看到自己的隊伍一樣，還能用箭頭找到你；你也能找到他們。Alfa 只分享你的角色在遊戲中的位置：地區、地圖上的點、等級與職業。絕不涉及你的真實位置、你的電腦或你的帳號。",
	["Es opcional: tu personaje aparece en el mapa de WoW de los lobos de La Jauría que usan Alfa, y ellos en el tuyo, para encontrarse y llegar con la flecha. Solo se comparte dónde anda tu personaje dentro del juego (zona, punto en el mapa, nivel y clase), nunca tu ubicación real ni nada de tu computadora, y nunca dentro de mazmorras. Va por un canal oculto que no sale en el chat, aunque alguien que entre a él con otro addon podría verlo. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "這是選擇性的：你的角色會出現在使用 Alfa 的 La Jauría 狼群的 WoW 地圖上，他們也會出現在你的地圖上，方便互相找到並用箭頭前往。只分享你的角色在遊戲中的位置（區域、地圖上的點、等級和職業），絕不分享你的真實位置或電腦裡的任何東西，在地城中也不會分享。它透過一個不會顯示在聊天中的隱藏頻道傳送，不過用其他插件加入該頻道的人可能會看到。你的隊伍始終可見。可以隨時在 La Jauría 中更改。",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "適合 %s 級，你是 %d 級：還差 %d 級。",
	["Es para otra raza."] = "適用於其他種族。",
	["Es raro del Cementerio y no siempre aparece."] = "墓地的稀有首領，不一定會出現。",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "墓地的稀有首領，不一定會出現。會施毒：記得解毒。",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "墓地的稀有首領，不一定會出現。會沉默施法者。",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "稀有首領，很少出現。會在周圍施放火焰。",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "稀有首領，位於隱藏的洞穴中。是一隻攻擊很快的蝙蝠。",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "稀有首領，不一定會出現。以他的等級來說攻擊非常痛：拉怪時要小心。",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "稀有首領，不一定會出現。會重擊面前所有人。",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "稀有首領。會放置大地圖騰：把它打掉。",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "稀有首領：不一定會出現。會催眠玩家，並在周圍引發魔法爆炸。",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "這個很簡單：是在最後一個首領前喝水回魔的好時機。",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "他是施法者：你的職業能打斷的話就打斷他（腳踢、盾擊、地震術...）。",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "他是會放圖騰的薩滿：把圖騰打掉，很容易打死。",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "一個拿盾牌的矮人：很耐打，但沒有特別的技巧。",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "礦坑裡的強敵：把他當成小首領來打。",
	["Es un grupo: cada uno suelta su propio botín."] = "這是一組敵人：每個都會掉落自己的戰利品。",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "他是聖騎士，會用聖光術治療自己。打斷他的治療。",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "一個速度很快、會施毒的薩特：你的職業能解毒的話就解毒。",
	["Es un trogg que lanza rayos: interrúmpelo."] = "一個會施放閃電的穴居人：打斷他。",
	["Es una mejora para ti"] = "對你是提升",
	["Es una mejora para ti."] = "這對你是提升。",
	["Es una montura de tu clase: pregunta a tu instructor de clase cuándo y cómo se consigue."] = "這是你職業專屬的坐騎：問問你的職業訓練師何時以及如何取得。",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "一隻護甲很厚的巨大烏龜：攻擊慢但很痛。",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "一隻非常耐打的烏龜，但只會普通攻擊：沒有特別的技巧。",
	["Es viejo: escanea para tenerlo al día."] = "資料舊了：掃描一下保持更新。",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "該字串中沒有 Alfa 會計分的屬性。",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "那一排還沒解鎖：該系的點數不夠。",
	["Esa tecla ya tiene dueño"] = "這個按鍵已被佔用",
	["Esa ya me la diste, ¡gracias! Guárdame la siguiente."] = "這根你已經給過我了，謝謝！下一根留給我吧。",
	["Esbirros enemigos"] = "敵方僕從",
	["Escala de estadísticas"] = "屬性權重",
	["Escalas:"] = "中途站：",
	["Escaneando..."] = "掃描中...",
	["Escanear ahora"] = "立即掃描",
	["Escanear con Alfa"] = "用 Alfa 掃描",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "完整掃描：%s 件物品有價格（%s 筆拍賣）。",
	["Escarcha"] = "冰霜",
	["Escarcha en cono frente a ti que hace lentos a los enemigos."] = "在你前方噴出一片冰霜，緩速敵人。",
	["Escarcha para subir"] = "冰霜（練等）",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "釣魚時隱藏名條與 NPC 名稱（敵對目標仍會顯示名稱），讓浮標更容易看到、也更好點擊。",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "隱藏需要比你目前更高技能的採集點。關閉時會以灰色淡化顯示。",
	["Escribe %s o haz clic en el lobo del minimapa para abrirla. Empieza en Hoy, con lo que toca a tu clase; %s muestra u oculta la ventana de guía."] = "輸入 %s 或點擊小地圖上的狼即可開啟。視窗會先顯示「今天」，列出你的職業需要的東西；%s 可顯示或隱藏指南視窗。",
	["Escribe %s y cuéntanos en el Discord de La Jauría."] = "輸入 %s，然後在 La Jauría 的 Discord 告訴我們。",
	["Escribe /alfa diagnostico: reviso si otro addon choca con Alfa, si falta una parte o si un ajuste quedó raro, y te doy el arreglo a un clic."] = "輸入 /alfa diagnostico：我會檢查是否有其他插件與 Alfa 衝突、是否缺少部分或設定異常，並給你一鍵修正。",
	["Escribe /alfa teclas: ahí están todas, y con un clic pulsas la que quieras."] = "輸入 /alfa teclas：所有按鍵都在那裡，點一下就能按下你想要的那個。",
	["Escribe al menos 3 letras del objeto."] = "至少輸入物品名稱的 3 個字。",
	["Escribe al menos dos letras."] = "請至少輸入兩個字。",
	["Escribe algo y pulsa «Nota aquí»: queda en tu mapa donde estás parado. Un clic en la marca y la flecha te lleva."] = "寫點什麼，然後按「在這裡記筆記」：筆記會留在你站的位置的地圖上。點一下標記，箭頭就會帶你過去。",
	["Escribe algo y pulsa «Nota aquí»: queda en tu mapa donde estás parado. «Spot aquí» marca un buen lugar para farmear, en dorado. Un clic en la marca y la flecha te lleva."] = "寫點東西，然後點「在這裡記筆記」：它會留在你地圖上你站的位置。「此處刷點」會用金色標出一個適合刷的好地方。點擊標記，箭頭就會帶你去。",
	["Escribe arriba el nombre de una mazmorra para buscarla."] = "在上方輸入地城名稱進行搜尋。",
	["Escribe cuánto oro (1 o más)."] = "輸入多少金幣（1 或以上）。",
	["Escribe el número que quieras y presiona Enter."] = "輸入你想要的數字，然後按 Enter。",
	["Escribe el top %d en el chat de tu grupo o banda."] = "在你的隊伍或團隊聊天中發布前 %d 名。",
	["Escribe en el chat del grupo cuando terminas un objetivo de una misión compartida. Viene apagado para no llenar el chat de nadie."] = "完成共享任務的一個目標時，在隊伍聊天中發言。預設關閉，以免洗頻。",
	["Escribe lo que buscas: un ajuste, o algo del juego, y te lo busco en la Enciclopedia."] = "輸入你要找的：一個設定，或遊戲裡的東西，我幫你在百科裡找。",
	["Escribe qué buscas: «Minas de la Muerte, falta sanador»."] = "寫下你要找什麼：「死亡礦坑，缺治療」。",
	["Escribe qué dice la nota: /alfa nota Aquí sale el mineral"] = "寫下筆記內容：/alfa nota 這裡會出礦",
	["Escribe qué se farmea ahí: /alfa spot Lobos para pieles"] = "寫下那裡刷什麼：/alfa spot 刷狼皮",
	["Escribe qué van a hacer (una mazmorra, una misión, lo que sea)."] = "寫下要做什麼（地城、任務，什麼都行）。",
	["Escribe tu nota."] = "寫下你的備註。",
	["Escribe un nivel (2 o más)."] = "輸入一個等級（2 或以上）。",
	["Escribe un nombre corto para reconocerla."] = "輸入一個簡短的名稱方便辨識。",
	["Escribe un objeto y pulsa «Buscar»: te contestan los lobos de tu hermandad que lo permiten."] = "輸入物品並點「搜尋」：公會裡允許回應的狼會回答你。",
	["Escribir a %s"] = "密語 %s",
	["Escuchar"] = "試聽",
	["Escuchar el aullido"] = "試聽狼嚎",
	["Escudo"] = "盾牌",
	["Escudo de relámpagos"] = "閃電之盾",
