	["Esto te sirve más en el banco o con otro de tus personajes (mándaselo por correo). Con un banquero, se guarda con un clic."] = "這個放在銀行或給你的其他角色更有用（用郵件寄給他）。在銀行職員旁邊，點一下就能存入。",
	["Estos filtros los dibuja Alfa, no el juego: quedan detrás de toda la interfaz (nunca la tapan) y también se ven con la interfaz oculta (Alt+Z), para tus capturas."] = "這些濾鏡由 Alfa 繪製，而不是遊戲：它們位於整個介面後方（絕不遮擋介面），隱藏介面（Alt+Z）時也能看到，方便你截圖。",
	["Está en combate. Prueba en un momento."] = "他正在戰鬥。稍後再試。",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "他在墓地。會施放持續造成傷害的暗影痛苦。",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "他在瀑布旁的水中：先把他拉到陸地上再打。",
