	["Están encendidas pero el juego no las cargó: %s. Recarga; si siguen así, reinstala Alfa completo."] = "它們已開啟但遊戲沒有載入：%s。重新載入一下；如果還是這樣，重新安裝整個 Alfa。",
	["Están por quitártelo"] = "快被搶走了",
