	["Forjaz está tallada dentro de la montaña: los enanos Barbabronce la construyeron alrededor de la Gran Forja."] = "鐵爐堡雕鑿在山體內部：銅鬚矮人圍繞著大熔爐建造了它。",
	["Forma"] = "形態",
	["Forma felina para matar rápido y forma de oso para las peleas difíciles; casi nunca necesitas beber."] = "用獵豹形態快速殺怪，用熊形態應付困難的戰鬥；幾乎不用喝水。",
	["Forma normal"] = "一般形態",
	["Foto: %s"] = "快照：%s",
	["Fragmento de alma"] = "靈魂碎片",
	["Fragmentos de alma"] = "靈魂碎片",
	["Frases dichas"] = "已說過的話",
	["Frena a los que huyen y te deja escapar de una mala pelea."] = "讓逃跑的敵人減速，也能讓你脫離不利的戰鬥。",
	["Frena a los que huyen y te salva de malas peleas."] = "讓逃跑的敵人減速，幫你脫離不利的戰鬥。",
	["Frena a todos los rivales cercanos."] = "讓附近所有對手減速。",
	["Frondavil era parte del bosque de Vallefresno hasta que los demonios y sus sátiros lo corrompieron."] = "費伍德森林原本是梣谷森林的一部分，直到惡魔和他們的薩特將它腐化。",
	["Frío"] = "冷色",
	["Fuego"] = "火焰",
	["Fuego en un área. Bueno contra grupos que no se mueven."] = "對一片區域施放火焰。對付站著不動的成群敵人很好用。",
	["Fuego en un área. Para grupos de enemigos."] = "對一片區域施放火焰。對付成群的敵人。",
	["Fuego estelar: tu hechizo más fuerte."] = "星火術：你最強的法術。",
	["Fuego feérico: el enemigo recibe más daño."] = "精靈之火：敵人受到更多傷害。",
	["Fuego interno"] = "心靈之火",
	["Fuego para subir"] = "火焰（練等）",
	["Fuego rápido: disparas mucho más rápido un rato."] = "急速射擊：一段時間內射擊速度大幅提升。",
	["Fuego sagrado: abre la pelea con mucho daño."] = "神聖之火：以高傷害開場。",
	["Fuentes: Blizzard (news.blizzard.com), warcraft.wiki.gg (Legacy System), Icy Veins y Method. Lo que ves arriba con tus números sale del juego."] = "來源：Blizzard（news.blizzard.com）、warcraft.wiki.gg（Legacy System）、Icy Veins 與 Method。上方顯示的你的數字來自遊戲。",
	["Fuera de Cerrar mis misiones"] = "已移出「完成我的任務」",
	["Fuera de combate es el mejor momento"] = "戰鬥外是最好的時機",
	["Fuera de combate, tamaño, tecla, nombre, explicaciones, barrido y de dónde sale la sugerencia."] = "非戰鬥時顯示、大小、按鍵、名稱、說明、冷卻轉圈動畫，以及建議的來源。",
	["Fuera de combate; necesita las placas de enemigos encendidas."] = "非戰鬥中；需要開啟敵方名條。",
	["Fuera de este plan: %s (%s)."] = "未加入此計畫：%s（%s）。",
	["Fuera del plan"] = "不在配點中",
	["Fuerza"] = "力量",
	["Fuerza del HDR"] = "HDR 強度",
	["Fuerza del tinte"] = "色調強度",
	["Funciona también fuera del modo pesca. Está en el menú de atajos del juego, en Alfa."] = "在釣魚模式之外也能用。在遊戲的按鍵設定中，位於 Alfa 下。",
	["Funde lo que sacas en una forja: también sube Minería. Necesitas un pico de minero y encender el rastreo de minerales."] = "在熔爐把挖到的礦熔煉：採礦也會跟著漲。需要一把礦工鋤並開啟尋找礦物。",
	["Furia"] = "狂怒",
	["Furia con dos armas"] = "雙武器狂怒",
	["Furia con todo el daño posible: más precisión, Ejecutar mejorado y críticos enormes. Muy rápido matando, pero frágil."] = "追求最大傷害的狂怒：更高命中、強化斬殺與超高致命一擊。殺怪非常快，但比較脆弱。",
	["Furia contra jugadores"] = "PvP 狂怒",
	["Furia desatada"] = "釋放怒火",
	["Furia para grupo"] = "組隊狂怒",
	["Furia para pelear contra jugadores: muchísimo daño, Ira rabiosa mejorada contra el miedo e Interceptar más seguido para no soltar al rival."] = "PvP 用的狂怒：極高的傷害、對付恐懼的強化狂暴之怒，以及更常使用的攔截，讓對手跑不掉。",
	["Furia sangrienta te da más ira para empezar peleas difíciles."] = "血性狂暴讓你在困難的戰鬥開始時有更多怒氣。",
	["Fíjate en lo que brilla en el suelo: ahí suele estar."] = "留意地上發光的東西：通常就在那裡。",
	["Gadgetzan es la ciudad goblin del desierto: ahí todo se compra y todo se vende, hasta el agua."] = "加基森是沙漠中的哥布林城市：在那裡什麼都能買賣，連水也不例外。",
	["Gadgetzan tiene una de las casas de subastas neutrales, donde comercian Alianza y Horda."] = "加基森有一座中立拍賣場，聯盟和部落都在那裡交易。",
	["Gana un poco de XP y Alfa calcula cuánto te falta."] = "先獲得一些經驗值，Alfa 就會算出還要多久。",
	["Gana un poco de XP y Alfa lo calcula"] = "獲得一點經驗後 Alfa 就能計算",
	["Ganado"] = "收入",
	["Ganado %s"] = "已獲得 %s",
	["Ganado: %s. Gastado: %s. Suma tus sesiones de hoy con este personaje."] = "收入：%s。支出：%s。此角色今天所有遊戲的總和。",
	["Ganados"] = "已獲得",
	["Ganas de más"] = "多賺的金額",
	["Ganaste %s en %s: unos %s por hora."] = "賺了 %s，用時 %s：每小時約 %s。",
	["Ganaste %s. En un minuto te digo cuánto ganas por hora."] = "你賺了 %s。一分鐘後我告訴你每小時賺多少。",
	["Ganaste: %s"] = "收入：%s",
	["Garra"] = "利爪",
	["Garra: suma puntos de combo."] = "爪擊：累積連擊點數。",
	["Gasta la ira sobrante en Golpe heroico; si llegas a 100 de ira, la estás desperdiciando."] = "多餘的怒氣就用在英勇打擊上；如果怒氣到了 100，就是在浪費。",
	["Gastado"] = "支出",
	["Gastados"] = "已花費",
	["Gastaste: %s"] = "花費：%s",
	["General, por categorías o por bolsa, y depósito rápido al banco."] = "總覽、依分類或依背包顯示，並可快速存入銀行。",
	["Giro inteligente"] = "智慧轉向",
	["Globo compacto"] = "精簡泡泡",
	["Gnomos"] = "地精",
	["Golpe"] = "命中",
	["Golpe con hechizos"] = "法術命中",
	["Golpe crítico"] = "致命一擊",
	["Golpe fantasmal: daño y esquivas más, cada vez que esté listo."] = "鬼魅攻擊：造成傷害並提高閃躲，一就緒就用。",
	["Golpe fuerte que además reduce las curas del rival."] = "強力攻擊，還能降低對手受到的治療。",
	["Golpe heroico cuesta menos ira: lo usarás en cada pelea."] = "英勇打擊消耗的怒氣更少：每場戰鬥都會用到。",
	["Golpe heroico más barato."] = "更便宜的英勇打擊。",
	["Golpe heroico más barato: amenaza extra con la ira que sobra."] = "更便宜的英勇打擊：用多餘的怒氣產生額外仇恨。",
	["Golpe heroico más barato: la ira sobrante se vuelve amenaza."] = "更便宜的英勇打擊：多餘的怒氣化為仇恨。",
	["Golpe heroico: tu golpe más fuerte mientras subes."] = "英勇打擊：練等時你最強的攻擊。",
	["Golpe mental: mucho daño, cada vez que esté listo."] = "心靈震爆：高傷害，冷卻好就用。",
	["Golpe mortal: tu golpe más fuerte, cada vez que esté listo."] = "致死打擊：你最強的攻擊，冷卻好就用。",
	["Golpe siniestro: suma puntos de combo."] = "邪惡攻擊：累積連擊點數。",
	["Golpea a los que tiene alrededor: gíralo lejos del grupo."] = "他會攻擊周圍的人：把他轉向背對隊伍。",
	["Golpea a todos los de alrededor y los hace atacar más lento. Ideal cuando te rodean varios."] = "攻擊你周圍的所有敵人並減慢牠們的攻擊速度。被多個敵人包圍時很棒。",
	["Golpea a todos los que están cerca y los avienta: si peleas cuerpo a cuerpo, cuida tu vida."] = "他會攻擊並擊退附近所有人：近戰職業要注意自己的生命值。",
	["Golpea a todos los que tiene enfrente: ataca desde su espalda si peleas cuerpo a cuerpo."] = "他會攻擊面前所有人：近戰職業請從他背後攻擊。",
	["Golpea a todos los que tiene enfrente: si peleas cuerpo a cuerpo, ataca por detrás."] = "他會攻擊面前所有人：近戰職業請從背後攻擊。",
	["Golpea a tu objetivo y a otro cercano. Para cuando pelean dos o más."] = "攻擊你的目標和附近的另一個敵人。有兩個以上敵人打你時用。",
	["Golpea a varios enemigos a tu alrededor."] = "攻擊你周圍的多個敵人。",
	["Golpea a varios enemigos cerca de ti. Perfecto contra grupos."] = "攻擊你附近的多個敵人。對付成群敵人完美。",
	["Golpea fuerte con su cuchilla y hace sangrar: vigila la vida del tanque."] = "他會用切肉刀重擊並造成流血：注意坦克的生命值。",
	["Golpea y avienta al tanque: regresa a tu lugar rápido."] = "他會把坦克擊飛：盡快回到原位。",
	["Golpea y frena a todos los enemigos que tienes cerca."] = "攻擊並緩速你附近的所有敵人。",
	["Golpeas a dos a la vez: puedes juntar monstruos de dos en dos."] = "一次打兩個：你可以兩隻兩隻地拉怪。",
	["Golpes cuerpo a cuerpo"] = "近戰攻擊",
	["Golpes de tu mascota"] = "你寵物的近戰攻擊",
	["Gracias a quienes apoyan y construyen Polestar, el motor de Alfa"] = "感謝所有支持和開發 Alfa 引擎 Polestar 的人",
	["Gracias por dejarme acompañarte."] = "謝謝你讓我陪著你。",
	["Gracias por hacer posible el motor de Alfa."] = "感謝你們讓 Alfa 的引擎成為可能。",
	["Grafito"] = "石墨",
	["Grafito con esquinas cortadas y el verde de La Jauría. El de siempre."] = "石墨色搭配切角，以及 La Jauría 的綠色。熟悉的經典樣式。",
	["Gran aumento de daño para los jefes."] = "對首領大幅提升傷害。",
	["Gran aumento de daño y te libra del miedo."] = "大幅提升傷害，還能讓你免疫恐懼。",
	["Gran aumento de daño."] = "大幅提升傷害。",
	["Gran daño por la espalda con daga. Colócate detrás del enemigo."] = "用匕首從背後造成大量傷害。繞到敵人背後。",
	["Gran golpe de escudo con mucha amenaza."] = "強力的盾牌攻擊，產生大量仇恨。",
	["Grande"] = "大",
	["Grano"] = "顆粒",
	["Grano de película"] = "底片顆粒",
	["Gratis"] = "免費",
	["Gratis tras vencer a un enemigo, y te cura."] = "擊敗敵人後免費使用，還能治療你。",
	["Grifos"] = "獅鷲",
	["Grim Batol fue una ciudad enana. Después, los orcos Faucedraco la usaron para tener presa a Alexstrasza, la Reina Dragón."] = "格瑞姆巴托曾是一座矮人城市。後來，龍喉獸人利用它囚禁了巨龍女王雅立史卓莎。",
	["Grito de batalla"] = "戰鬥怒吼",
	["Grito de batalla para el guerrero; Intelecto Arcano y una armadura para el mago; Entereza y Fuego interno para el sacerdote; y lo suyo para cada clase."] = "戰士的戰鬥怒吼；法師的秘法智慧與護甲法術；牧師的真言術：韌與心靈之火；每個職業都有各自的增益。",
	["Grom Grito Infernal fue el primer jefe orco en beber la sangre de Mannoroth, y así ató a su pueblo a los demonios."] = "葛羅姆·地獄吼是第一個飲下瑪諾洛斯之血的獸人酋長，從此把他的族人和惡魔綁在了一起。",
	["Grom Grito Infernal y Varian Wrynn son guerreros legendarios de la historia."] = "葛羅姆·地獄吼和瓦里安·烏瑞恩都是歷史上的傳奇戰士。",
	["Grom'gol es el campamento de la Horda en la Vega, con zepelines a Orgrimmar y a Entrañas."] = "格羅姆高是部落在荊棘谷的營地，有飛艇開往奧格瑪和幽暗城。",
	["Grupo"] = "隊伍",
	["Grupo de %d"] = "%d 人隊伍",
	["Grupo de 5"] = "5 人隊伍",
	["Guarda %d misiones: las entregas en una guía que sigue."] = "保留 %d 個任務：在後面的指南中交付。",
	["Guarda Grito intimidador para cuando estés en peligro."] = "把破膽怒吼留到危急時使用。",
	["Guarda Muro de escudo para los peores momentos del jefe."] = "把盾牆留到首領最危險的時候使用。",
	["Guarda cómo tienes Alfa ahora con el nombre de tu personaje, para volver a ella con un clic. Útil si juegas con varios personajes."] = "用角色名稱儲存你現在的 Alfa 設定，一鍵就能回來。適合玩多個角色的你。",
	["Guarda en el banco los materiales que todavía no usas, y deja las bolsas libres para el botín."] = "還用不到的材料先存進銀行，把背包空出來裝戰利品。",
	["Guarda lo que llevas como un conjunto (curar, daño, pesca...) desde el botón de tus bolsas o en Bolsas, y póntelo con un clic. En combate te lo pongo al terminar."] = "從背包的按鈕或在背包頁面，把身上的裝備存成一套設定（治療、輸出、釣魚…），點一下就能穿上。戰鬥中我會在結束後幫你換上。",
	["Guarda lo que llevas puesto con un nombre (curar, daño, pesca...) y póntelo con un clic, fuera de combate."] = "替身上的裝備取個名字儲存（治療、輸出、釣魚…），戰鬥外點一下就能穿上。",
	["Guarda lo que llevas puesto con un nombre (curar, daño, pesca...) y vuelve a ponértelo con un clic. También desde el botón de tus bolsas."] = "替身上的裝備取個名字儲存（治療、輸出、釣魚…），點一下就能再穿上。也可以從背包的按鈕使用。",
	["Guarda o cambia tu mascota"] = "寄放或更換你的寵物",
	["Guarda tu configuración como perfil primero."] = "請先把你的設定儲存為設定檔。",
	["Guarda tus materiales en el banco (%d)."] = "把你的材料存進銀行（%d）。",
	["Guarda un poco de tela para vendas: Primeros auxilios también la usa."] = "留一些布料做繃帶：急救也要用到。",
