	["Guerrero"] = "戰士",
	["Guiarme"] = "帶我去",
	["Gul'dan fue el primer brujo orco, y su historia no terminó nada bien. Tú úsalo con más cabeza."] = "古爾丹是第一個獸人術士，他的結局可一點都不好。你可要更聰明地運用這股力量。",
	["Gul'dan fundó el Consejo de la Sombra, un grupo de brujos que movía a la Horda desde las sombras."] = "古爾丹創立了暗影議會，這群術士在幕後操縱著部落。",
