	["Habilidades más baratas."] = "技能消耗更低。",
	["Habilidades más baratas: más golpes de amenaza."] = "技能消耗更低：更多製造仇恨的攻擊。",
	["Habilidades nuevas por aprender: %d. Tu entrenador te espera."] = "有 %d 個新技能可以學習。你的訓練師在等你。",
	["Habilidades por entrenar"] = "可訓練的技能",
	["Habilidades que vigila la ayuda de Blizzard"] = "Blizzard 戰鬥輔助監控的技能",
	["Habitual"] = "常見",
	["Habla con %s"] = "與%s交談",
	["Habla con el maestro de vuelo de cada pueblo nuevo: así aprendes la ruta."] = "每到一個新城鎮都和飛行管理員談談：這樣就能學會航線。",
	["Habla con un banquero para comprarla."] = "與銀行職員交談即可購買。",
	["Hablar"] = "說話",
	["Hace heridas que sangran: vigila la vida del tanque."] = "他會造成流血傷口：注意坦克的生命值。",
	["Hace lento al enemigo cuerpo a cuerpo. Después aléjate y dispara."] = "減緩近戰敵人。然後拉開距離射擊。",
	["Hace mil años, en la Guerra de las Arenas Movedizas, los elfos y los dragones encerraron a los qiraji tras el Muro del Escarabajo."] = "一千年前的流沙之戰中，精靈與巨龍把其拉蟲人封印在甲蟲之牆後面。",
	["Hace más de diez mil años todas las tierras eran un solo continente: Kalimdor, que en élfico quiere decir «tierra de la eterna luz de las estrellas»."] = "一萬多年前，所有的土地都是一塊大陸：卡林多，在精靈語中意為「永恆星光之地」。",
	["Hace más lento al enemigo. Gana distancia para seguir disparando."] = "緩速敵人。拉開距離繼續射擊。",
	["Hace más lento al enemigo. Úsala con los que huyen para que no traigan ayuda."] = "緩速敵人。對逃跑的敵人使用，免得牠們叫來朋友。",
	["Hace sangrar al enemigo un rato. Ponla al inicio de las peleas largas."] = "讓敵人流血一段時間。長時間戰鬥開始時加上。",
	["Hace sangrar al enemigo: ponlo al empezar la pelea."] = "讓敵人流血：戰鬥開始時施放。",
	["Hace sangrar mucho: vale la pena con enemigos que duran."] = "造成大量流血：對付耐打的敵人很值得。",
	["Hace siglos, Aegwynn venció a un avatar de Sargeras y escondió su cuerpo en la Tumba de Sargeras, en las Islas Abruptas."] = "幾個世紀前，艾格文擊敗了薩格拉斯的化身，把他的軀體藏在破碎群島的薩格拉斯之墓中。",
	["Hacen %d misiones contigo"] = "和你一起做 %d 個任務",
	["Hacen 1 misión contigo"] = "和你一起做 1 個任務",
	["Hacen falta al menos 3 lugares distintos de ese recurso en la zona."] = "此地區至少需要有 3 個不同位置的該資源。",
	["Hacer mazmorras con tu grupo da botín, misiones y reputación: es farmeo con plática incluida."] = "和隊伍一起打地城能獲得戰利品、任務和聲望：一邊刷一邊聊天。",
	["Hacer oro"] = "賺錢",
	["Haces daño"] = "你負責輸出",
	["Haces de luz entre árboles, nubes y montañas."] = "穿過樹木、雲層與山脈的光束。",
	["Hacha de dos manos"] = "雙手斧",
	["Hacha de una mano"] = "單手斧",
	["Hacia %s"] = "前往%s",
	["Hacia %s (niv. %s)"] = "前往%s（%s 級）",
	["Hacia abajo"] = "向下",
	["Hacia arriba"] = "向上",
	["Hacia dónde se acomodan tus compañeros."] = "隊友框架的排列方向。",
	["Hacia:"] = "前往：",
	["Hacia: %s"] = "前往：%s",
	["Halloween de Azeroth"] = "萬鬼節",
	["Halloween recuerda el día en que los Renegados se liberaron del Rey Exánime: por eso queman al Hombre de Mimbre."] = "萬鬼節紀念被遺忘者擺脫巫妖王控制的那一天：所以他們會燒掉柳條人。",
	["Hamuul Tótem de Runa, el archidruida de Cima del Trueno, fue de los primeros tauren aceptados en el Círculo Cenarion."] = "雷霆崖的大德魯伊哈繆·符文圖騰是最早被塞納里奧議會接納的牛頭人之一。",
	["Hasta dónde llegan las montañas lejanas."] = "遠處山脈顯示的距離。",
	["Hasta dónde puedes alejar la cámara con la rueda. El juego puede limitarlo: Alfa muestra el valor que de verdad quedó."] = "用滾輪能把鏡頭拉多遠。遊戲可能會限制：Alfa 顯示的是實際生效的數值。",
	["Hasta dónde se dibuja el mundo. Es lo que más FPS cuesta."] = "世界的繪製距離。這項最耗 FPS。",
	["Hasta dónde se dibuja el pasto. Más lejos, menos «alfombra» que aparece al caminar."] = "草地的繪製距離。越遠，走路時冒出來的「草毯」就越少。",
	["Hasta el alfa se cae. Lo importante es levantarse. ¡Vamos!"] = "就算是頭狼也會倒下。重要的是重新站起來。走吧！",
	["Hasta el nivel 20 usa un arma de dos manos; luego cambia a dos armas de una mano."] = "等級 20 以前用雙手武器；之後改用兩把單手武器。",
	["Hasta mi nivel"] = "不超過我的等級",
	["Hasta qué distancia se ven las placas de nombre. El juego puede limitarlo."] = "名條能在多遠的距離顯示。遊戲可能會限制。",
	["Hasta qué nivel"] = "到幾級為止",
	["Hay enemigos que se convierten en lobos y otros que asustan: no corran si los asustan, esperen."] = "有些敵人會變成狼，有些會施放恐懼：被恐懼時別慌，等效果結束。",
	["Hay mucha agua: si nadas bajo el agua, mira tu barra de respiración y sube a tomar aire."] = "這裡有很多水：在水下游泳時，注意你的呼吸條，記得浮上去換氣。",
	["Hay muchas tribus trol: Amani, Gurubashi, Furiarena, Zandalar... y casi todas pelean entre sí."] = "食人妖部族有很多：阿曼尼、古拉巴什、沙怒、贊達拉…而且幾乎彼此都在打仗。",
	["Hay muchos no-muertos y jabaespines: lleven algo para quitar enfermedades si su grupo puede."] = "這裡有很多不死生物和野豬人：如果隊伍能驅散疾病，記得做好準備。",
	["Hay muchos troggs y elementales de fuego juntos: tiren de uno o dos grupos a la vez, no más."] = "穴居人和火元素擠在一起：一次只拉一到兩群，不要再多。",
	["Hay nueve clases en el Clásico, pero solo la Alianza tiene paladines y solo la Horda tiene chamanes."] = "經典版有九個職業，但只有聯盟有聖騎士，只有部落有薩滿。",
	["Hay que llevar el recado y hablar con quien te espera."] = "把口信送到，和等你的人談談。",
	["Hay una guía de Alfa"] = "有 Alfa 指南",
	["Haz %s: unas %d veces"] = "製作 %s：大約 %d 次",
	["Haz Pociones de sanación menores de más para este tramo."] = "這一段多做一些初級治療藥水。",
	["Haz clic derecho (o Mayús+clic) en el mapa donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras."] = "在地圖上想要的位置按右鍵（或 Shift+點擊）：設定名稱、圖示與顏色，箭頭隨時都能帶你過去。",
	["Haz clic en un atajo y pulsa la tecla que quieras; Esc cancela y el clic derecho lo quita. Se guardan fuera de combate."] = "點一個快捷鍵，再按下你想要的鍵；Esc 取消，右鍵清除。會在戰鬥外儲存。",
	["Haz clic en un marco de ejemplo"] = "點擊一個範例框架",
	["Haz clic y pulsa la tecla que quieras (Esc cancela). Clic derecho la quita."] = "點擊後按下你想要的按鍵（Esc 取消）。右鍵清除。",
	["Haz clic y pulsa la tecla, un botón del ratón o la rueda (con Mayús, Ctrl o Alt si quieres). Esc cancela; clic derecho la quita."] = "點擊後按下按鍵、滑鼠按鍵或滾輪（可以搭配 Shift、Ctrl 或 Alt）。Esc 取消；右鍵點擊清除。",
	["Haz doble clic derecho en el mundo para lanzar la caña, sin usar la tecla. Nunca en combate ni en vuelo."] = "在遊戲世界中右鍵雙擊即可拋竿，不必使用按鍵。戰鬥中或飛行中不會觸發。",
	["Haz misiones de tu registro o caza enemigos de tu nivel (los grises no dan nada)."] = "做你日誌裡的任務，或獵殺和你同等級的敵人（灰色的不給經驗）。",
	["Haz tu propia agua. Así no gastas oro en bebida."] = "自己造水。不用再花金幣買飲料了。",
	["Haz tu propia comida para recuperar vida."] = "自己做食物來恢復生命值。",
	["Hazlo ya"] = "現在就做",
	["Hecha"] = "已完成",
	["Hecha %d veces"] = "已完成 %d 次",
	["Hechas"] = "已完成",
	["Hechizo del preajuste"] = "預設方案的法術",
	["Hechizo desconocido"] = "未知的法術",
	["Hechizo elegido por ti"] = "你選擇的法術",
	["Hechizo nuevo para tus clics de Curación. Ábrelo en /alfa curacion."] = "有適合你治療點擊配置的新法術。請用 /alfa curacion 開啟。",
	["Hechizos de sombras que hacen daño con el tiempo: el sacerdote que mejor sube en solitario, casi sin descansar."] = "造成持續傷害的暗影法術：單練升級最快的牧師，幾乎不用休息。",
	["Hechizos de tu mascota"] = "你寵物的法術",
	["Hechizos desde lejos y raíces para que el monstruo no te alcance. Al final llega la forma de lechúcico."] = "從遠處施法並用定身讓怪物碰不到你。最後會點出梟獸形態。",
	["Hecho"] = "已完成",
	["Hemet Nesingwary organiza safaris por toda la Vega: sus encargos de cazar panteras, tigres y raptores son famosos."] = "赫米特·奈辛瓦里在整個荊棘谷組織狩獵之旅：他獵殺豹子、老虎與迅猛龍的委託遠近馳名。",
	["Hemorragia: suma puntos de combo y el enemigo recibe más daño."] = "出血：累積連擊點數，並讓敵人受到更多傷害。",
	["Hender armadura más barato."] = "更便宜的破甲攻擊。",
	["Hender armadura más barato: amenaza constante."] = "更便宜的破甲攻擊：穩定的仇恨。",
	["Hender armadura más barato: más amenaza a varios enemigos."] = "更便宜的破甲攻擊：對多個敵人產生更多仇恨。",
	["Hender armadura: amenaza constante y el enemigo recibe más daño."] = "破甲攻擊：穩定的仇恨，敵人受到的傷害提高。",
	["Herboristería"] = "草藥學",
	["Herboristería combina bien con Alquimia, y también con Desollar o Minería para recolectar el doble."] = "草藥學和鍊金術很搭，也可以搭配剝皮或採礦，採集量翻倍。",
	["Herramienta"] = "工具",
	["Herramientas"] = "工具",
	["Herrería"] = "鍛造",
	["Herrería fabrica armas y armadura de placas muy buenas para tu nivel, y Minería te da el material gratis."] = "鍛造能打造適合你等級的優秀武器與鎧甲，採礦則免費提供材料。",
	["Herrería fabrica escudos y piezas resistentes."] = "鍛造能打造盾牌與耐打的裝備。",
	["Herrería fabrica escudos y placas con defensa y aguante, justo lo que un tanque necesita."] = "鍛造能打造帶有防禦與耐力的盾牌與鎧甲，正是坦克需要的。",
	["Herrería y Minería van de la mano: tú sacas el metal y tú lo forjas."] = "鍛造和採礦相輔相成：自己挖礦，自己鍛造。",
	["Hiciste lo que pedía antes. Búscala con su «!» y tómala, o elige qué sigue."] = "你完成了它之前的要求。找到它的「!」接取，或選擇接下來做什麼。",
	["Hielo"] = "冰藍",
	["Hierbas"] = "草藥",
	["Historias"] = "故事",
	["Historias de las misiones"] = "任務故事",
	["Historias de tus misiones"] = "你的任務故事",
	["Historias guardadas"] = "已保存的故事",
	["Historias y datos curiosos"] = "故事與趣聞",
	["Hogger es un gnoll de Elwynn tan temido que, para muchos aventureros, fue su primer gran reto."] = "霍格是艾爾文森林裡一隻令人聞風喪膽的豺狼人，對許多冒險者來說，他是第一個大挑戰。",
	["Hombros"] = "肩部",
	["Honor"] = "榮譽",
	["Horarios de barcos y zepelines"] = "船隻與飛艇時刻表",
	["Horarios de barcos y zepelines en el mapa"] = "地圖上的船隻與飛艇時刻表",
	["Horda"] = "部落",
	["Hoy"] = "今天",
	["Hoy avanzaste %s niveles"] = "今天你升了 %s 級",
	["Hoy avanzaste 1 nivel"] = "今天你升了 1 級",
	["Hoy en Azeroth hay fiesta: %s. ¿Vamos a ver qué hay?"] = "今天艾澤拉斯有慶祝活動：%s。我們去看看？",
	["Hoy en números"] = "今日數據",
	["Hoy está difícil, ¿verdad? No pasa nada. Descansa un poco, repara y volvemos con más fuerza."] = "今天很難熬，對吧？沒關係。休息一下，修理一下，我們會更強地回來。",
	["Hoy llevas %s"] = "今天你已有：%s",
	["Hoy te guía"] = "「今天」為你指路",
	["Hoy te pone tu siguiente paso primero, y en combate ninguna ventana de Alfa te deja atrapado."] = "「今天」頁面會先顯示你的下一步，而且戰鬥中不會再有 Alfa 視窗把你困住。",
	["Hoy todavía no avanzas: ¡a cazar!"] = "今天還沒有進度：去狩獵吧！",
	["Hoy todavía no cazamos nada. ¿Salimos?"] = "今天還沒狩獵呢。出發嗎？",
	["Hoy, Aventura, Personaje, Mundo, Oficios y Manada en una sola ventana: %s o el lobo del minimapa."] = "今天、冒險、角色、世界、專業與狼群，盡在一個視窗：%s 或小地圖上的狼。",
	["Hoy, a tu clase"] = "「今天」依職業量身打造",
	["Huele a pan recién hecho por aquí… se me antoja."] = "這裡有剛出爐的麵包香味……好想吃。",
	["Huele a salchichas asadas por aquí… ¿o es mi imaginación?"] = "這裡有烤香腸的味道……還是我想太多了？",
	["Huella"] = "爪印",
	["Huelo a botín... y a una que otra salchicha."] = "我聞到了戰利品…還有一兩根香腸。",
	["Humanos"] = "人類",
	["Humo, agua y efectos se funden con lo que tocan en lugar de cortarse en seco."] = "煙霧、水與特效會與接觸的物體自然融合，而不是生硬地截斷。",
	["Huracán: golpea a todos a tu alrededor."] = "旋風斬：攻擊你周圍的所有敵人。",
	["Háblame de mi gente"] = "跟我說說我的族人",
	["Iconos de viaje en el minimapa"] = "小地圖上的旅行圖示",
	["Idioma"] = "語言",
	["Igual que Alfa"] = "與 Alfa 相同",
	["Igual que lo tuyo"] = "和你的一樣",
	["Igual que los otros señores: lanza rayos y se cura. Interrumpe su curación."] = "和其他領主一樣：會施放閃電並治療自己。打斷他的治療。",
	["Illidan absorbió el poder del Cráneo de Gul'dan y se volvió mitad demonio. Por eso Malfurion lo desterró."] = "伊利丹吸收了古爾丹之顱的力量，變成了半個惡魔。所以瑪法里恩放逐了他。",
	["Illidan guardó agua del Pozo antes de su caída y creó uno nuevo en Hyjal. Por eso Malfurion lo encerró bajo tierra durante diez mil años."] = "永恆之井毀滅之前，伊利丹偷偷留下了井水，在海加爾山造了一口新的。所以瑪法里恩把他囚禁在地底一萬年。",
	["Illidan se fue a Terrallende, lo que quedó de Draenor, y ahí se hizo de un ejército propio."] = "伊利丹去了德拉諾的殘餘——外域，在那裡建立了自己的軍隊。",
	["Illidan, el gemelo de Malfurion, amaba a Tyrande, pero ella eligió a su hermano. Esa herida lo acompañó por diez mil años."] = "瑪法里恩的孿生兄弟伊利丹愛著泰蘭妲，但她選擇了他的哥哥。這道傷痕伴隨了他一萬年。",
	["Imagen HDR"] = "HDR 輸出",
	["Importa una cadena de escala de estadísticas y usa, renombra, exporta o borra las escalas que tienes."] = "匯入屬性權重字串，並使用、重新命名、匯出或刪除你已有的權重。",
	["Importado"] = "已匯入",
	["Importado: %s. Ya puedes seguirlo."] = "已匯入：%s。現在就可以跟隨它了。",
	["Importar"] = "匯入",
	["Importar ajustes"] = "匯入設定",
	["Importar un build"] = "匯入配點",
	["Importar una ruta"] = "匯入路線",
	["Importar..."] = "匯入...",
	["Incapacita al enemigo un momento. Úsalo para ponerte a su espalda."] = "讓敵人短暫失去行動能力。趁機繞到牠背後。",
	["Inclina la cámara al subir y bajar cuestas."] = "上下坡時鏡頭隨之傾斜。",
	["Ingeniería"] = "工程學",
	["Ingeniería da aturdimientos y trucos que ganan duelos; Minería da el material."] = "工程學提供能贏得決鬥的擊昏與小道具；採礦提供材料。",
	["Ingeniería da granadas y redes para controlar al rival; Minería da el material."] = "工程學提供控制對手的手榴彈與網；採礦提供材料。",
	["Ingeniería da granadas, redes y bombas que deciden peleas contra jugadores; Minería da el material."] = "工程學提供能左右 PvP 勝負的手榴彈、網與炸彈；採礦提供材料。",
	["Ingeniería te salva con trucos de escape; Sastrería hace tu ropa."] = "工程學用脫身道具救你一命；裁縫幫你做衣服。",
	["Inicio"] = "首頁",
	["Inicio de Alfa"] = "Alfa 首頁",
	["Inicio del horizonte"] = "地平線起點",
	["Insignias de La Jauría: los Alfas y los miembros llevan su lobo en el cuadro, en La Jauría y en el mapa; y quienes comparten se ven con una huella."] = "La Jauría 徽章：阿爾法和成員會在滑鼠提示、La Jauría 和地圖上帶著他們的狼；分享位置的人會顯示為爪印。",
	["Instantánea: úsala cada vez que esté lista."] = "瞬發：冷卻好就用。",
	["Instructor"] = "訓練師",
	["Instructor de %s"] = "%s訓練師",
	["Instructor de Herboristería"] = "草藥學訓練師",
	["Instructor de Minería"] = "採礦訓練師",
	["Instructor de equitación"] = "騎術訓練師",
	["Instructor de pesca"] = "釣魚訓練師",
	["Instructores"] = "訓練師",
