	["Instructores de pesca"] = "釣魚訓練師",
	["Instructores y vendedores"] = "訓練師與商人",
	["Intelecto"] = "智力",
	["Intelecto Arcano"] = "秘法智慧",
	["Intentar ahora"] = "立即重試",
	["Intentar otra vez"] = "重試",
	["Interceptar más seguido: el rival no se escapa."] = "更常使用攔截：對手跑不掉。",
	["Interfaz"] = "介面",
	["Interfaz del juego"] = "遊戲介面",
	["Interrumpe un hechizo con tu escudo. Úsalo con magos y curanderos enemigos."] = "用盾牌打斷一個法術。對敵方施法者和治療者使用。",
	["Interrumpe un hechizo y bloquea esa magia un rato."] = "打斷一個法術，並在一段時間內封鎖該系法術。",
	["Interrumpe un hechizo. Guárdalo para cuando el enemigo lance algo peligroso."] = "打斷一個法術。留到敵人施放危險法術時用。",
	["Interrumpe un hechizo. Úsalo con magos y curanderos enemigos."] = "打斷一個法術。對敵方施法者和治療者使用。",
	["Interrumpes hechizos y los silencias."] = "打斷法術並使其沉默。",
	["Interrumpes y silencias hechizos."] = "打斷並沉默法術。",
	["Intimidación: tu mascota aturde al enemigo."] = "脅迫：你的寵物擊暈敵人。",
	["Invita a tu clan con un clic, y arreglos"] = "一鍵邀請加入你的公會，以及修正",
	["Invitaciones a hermandades"] = "公會邀請",
	["Invitaciones de grupo de desconocidos"] = "陌生人的組隊邀請",
	["Invitación a %s para %s enviada. Si no puede unirse, el juego te dirá por qué."] = "已送出加入%s的邀請給%s。如果對方無法加入，遊戲會告訴你原因。",
	["Invitar"] = "邀請",
	["Invitar a %s"] = "邀請加入%s",
	["Invitar a una comunidad sin bloqueos"] = "邀請加入社群不再被阻擋",
	["Invitar al clan"] = "邀請加入公會或社群",
	["Invitar al grupo"] = "邀請組隊",
	["Invitar, comerciar, susurrar…"] = "邀請、交易、密語…",
	["Invitarlos"] = "邀請他們",
	["Invitaste a %s a tu grupo."] = "你邀請了 %s 加入隊伍。",
	["Invoca un espíritu de jabalí: mátenlo o que alguien lo tanquee."] = "他會召喚野豬之靈：把它殺掉，或讓人去坦它。",
	["Invócalo antes de pelear."] = "戰鬥前先召喚它。",
	["Ir"] = "前往",
	["Ir a la zona recomendada"] = "前往推薦地區",
	["Ir a reparar"] = "去修理",
	["Ir a un lugar"] = "前往某個地點",
	["Ir a: %s"] = "前往：%s",
	["Ir al mapa del juego"] = "前往遊戲地圖",
	["Ir al resumen"] = "前往摘要",
	["Ir de caza"] = "去狩獵",
	["Ir por el camino es más seguro que cortar por en medio: los caminos tienen menos enemigos."] = "走大路比抄近路安全：路上的敵人比較少。",
	["Ir por él"] = "去拿",
	["Ira al romper un miedo: los rivales te asustan mucho."] = "解除恐懼時獲得怒氣：對手很常恐懼你。",
	["Ira aunque el rival huya o te frene."] = "即使對手逃跑或讓你減速，也能獲得怒氣。",
	["Ira constante en peleas largas contra jefes."] = "在漫長的首領戰中穩定獲得怒氣。",
	["Ira constante."] = "穩定獲得怒氣。",
	["Ira constante: nunca te quedas sin poder usar habilidades."] = "穩定獲得怒氣：永遠不會沒技能可用。",
	["Ira gratis cada pocos segundos, aunque nadie te pegue."] = "每隔幾秒免費獲得怒氣，即使沒人打你。",
	["Izquierdo"] = "左鍵",
	["Jaina Valiente fue alumna de Antonidas antes de fundar Theramore."] = "珍娜·普勞德摩爾在建立塞拉摩之前是安東尼達斯的學生。",
	["JcJ"] = "PvP",
	["JcJ (12): rangos de honor 3, 7, 10, 13 y 14; exaltado con las 4 facciones de los campos de batalla; las semanas 4, 7 y 10 del viaje de temporada Campo de Honor."] = "PvP（12）：榮譽階級 3、7、10、13 與 14；4 個戰場陣營達到崇拜；榮譽之地賽季旅程的第 4、7 與 10 週。",
	["Jefe"] = "首領",
	["Jefe %d por descubrir"] = "首領 %d（尚未發現）",
	["Jefe final"] = "最終首領",
	["Jefes"] = "首領",
	["Jefes vencidos"] = "已擊敗的首領",
	["Jefes vencidos, mazmorras hechas y botín anotado de este personaje. No toca tus ajustes."] = "此角色已擊敗的首領、完成的地城與記錄的戰利品。不會影響你的設定。",
	["Jefes, botín y la entrada de cada mazmorra y banda."] = "每個地城與團隊副本的首領、戰利品與入口。",
	["Juega con cada personaje una vez y Alfa recordará sus bolsas y su banco."] = "每個角色玩一次，Alfa 就會記住它的背包與銀行。",
	["Juega siempre en actitud defensiva con escudo."] = "一律在防禦姿態下持盾作戰。",
	["Juega un rato y Alfa calcula cuánto te falta a tu ritmo."] = "玩一會兒，Alfa 就會照你的節奏算出還剩多少。",
	["Jueves"] = "星期四",
	["Jugo de baya lunar"] = "月莓汁",
	["Jugo de melón"] = "甜瓜汁",
	["Juguetes y consumibles de pesca"] = "釣魚玩具與消耗品",
	["Junta %d de %s"] = "採集 %d 個%s",
	["Junta 100 capturas."] = "累計 100 次漁獲。",
	["Junta 1000 capturas."] = "累計 1000 次漁獲。",
	["Junta 500 capturas."] = "累計 500 次漁獲。",
	["Junta a la manada para salir de caza"] = "召集狼群去狩獵",
	["Junta dos monstruos y usa Golpes de barrido: así subes más rápido."] = "一次拉兩隻怪並使用橫掃攻擊：這樣升級更快。",
	["Junta dos o tres monstruos, usa Atronar y Revancha: subes seguro y sin descansar."] = "一次拉兩三隻怪，使用雷霆一擊與復仇：升級又安全又不用休息。",
	["Junta lo gris y lo blanco para vender: suma más de lo que parece."] = "把灰色和白色物品攢起來賣：加起來比你想的還多。",
	["Junta los montones y acomoda tus objetos con un clic."] = "點一下就能合併堆疊並整理物品。",
	["Junta los montones y acomoda tus objetos. No funciona en combate."] = "合併堆疊並整理物品。戰鬥中無法使用。",
	["Junta materiales de tu profesión donde más hay."] = "到最多的地方採集你的專業材料。",
	["Junta materiales de tu profesión, con unas misiones de XP en medio."] = "採集你的專業材料，中間穿插一些經驗值任務。",
	["Junta misiones de la misma zona: haces varias en un solo viaje."] = "把同一地區的任務湊在一起：一趟就能做好幾個。",
	["Junta varios monstruos: tus golpes sagrados alcanzan a todos."] = "一次拉好幾隻怪：你的神聖攻擊會打到每一隻。",
	["Juntando todo lo del juego. Es solo la primera vez que la abres."] = "正在彙整遊戲中的所有內容。只有第一次開啟時需要。",
	["Juntar %s"] = "存夠%s",
	["Juntar los materiales de mi profesión"] = "收集我專業所需的材料",
	["Juntar materiales para vender"] = "收集材料出售",
	["Juntar nodos cercanos al alejar"] = "縮小地圖時合併相近的採集點",
	["Juntar oro"] = "存金幣",
	["Junto a la lupa del mapa del juego: las capas, el modo limpio y «Mapa de Alfa» para cambiar al de Alfa."] = "在遊戲地圖的放大鏡旁：圖層、簡潔模式，以及切換到 Alfa 地圖的「Alfa 地圖」按鈕。",
	["Junto a tu guía hay un botón para buscar lo que tienes cerca: vuelo, banco, subasta, reparar, comerciantes y entrenadores."] = "你的指南旁邊有一個按鈕，可以搜尋附近的東西：飛行點、銀行、拍賣場、修理、商人和訓練師。",
	["Junto al botón, el nombre del objeto y cuánto llevas; una huella late cuando ya lo puedes usar."] = "按鈕旁顯示物品名稱和你的進度；可以使用時會有一個爪印閃動。",
	["Junto al título de cada página. Tócalo y te explico esa página con sus preguntas."] = "在每頁標題旁邊。點一下，我就帶著問題為你講解這一頁。",
	["Kael'thas fue miembro del Kirin Tor de Dalaran antes de guiar a los elfos de sangre."] = "凱爾薩斯在領導血精靈之前，是達拉然祈倫托的成員。",
	["Karazhan, la torre de Medivh, el último Guardián, se levanta sobre un cruce de líneas de magia natural."] = "卡拉贊是最後的守護者麥迪文的高塔，矗立在天然魔力線的交會處。",
	["Kargath, el campamento de la Horda, lleva el nombre de un viejo caudillo orco del clan Mano Destrozada."] = "部落營地卡加斯以碎手氏族一位老獸人酋長的名字命名。",
	["Kel'Thuzad era un archimago de Dalaran. Lo expulsaron por estudiar nigromancia y acabó al servicio del Rey Exánime."] = "科爾蘇加德曾是達拉然的大法師。他因研究死靈法術被驅逐，最終投靠了巫妖王。",
	["Kel'Thuzad tiene un gato, el señor Bigglesworth, que lo acompaña en Naxxramas. ¡Ni se te ocurra hacerle daño!"] = "科爾蘇加德有一隻貓，叫比格沃斯先生，在納克薩瑪斯陪著他。你可千萬別傷害牠！",
	["Khadgar fue el aprendiz de Medivh. Al pelear contra su maestro poseído envejeció de golpe y se quedó con el pelo blanco."] = "卡德加是麥迪文的學徒。與被附身的導師戰鬥時，他一下子變老了，頭髮也全白了。",
	["Khaz Modan es la tierra de los enanos, desde las nieves de Dun Morogh hasta los valles de Loch Modan."] = "卡茲莫丹是矮人的土地，從丹莫洛的冰雪一直到洛克莫丹的山谷。",
	["Kil'jaeden encerró el alma de Ner'zhul en un bloque de hielo y lo arrojó a Rasganorte: así nació el Rey Exánime."] = "基爾加丹把耐奧祖的靈魂封進一塊冰裡，扔到了北裂境：巫妖王就是這樣誕生的。",
	["Kil'jaeden engañó a Ner'zhul, el chamán más sabio de Draenor, y su aprendiz Gul'dan terminó de entregar a los orcos a la Legión."] = "基爾加丹欺騙了德拉諾最睿智的薩滿耐奧祖，而他的學徒古爾丹則徹底把獸人交給了燃燒軍團。",
	["Korialstrasz, el consorte de Alexstrasza, anduvo entre los mortales como Krasus, un mago del consejo de Dalaran."] = "雅立史卓莎的配偶克拉蘇斯曾化身為達拉然議會的法師，行走於凡人之間。",
	["Kul Tiras es un reino isleño de marineros. Su gran almirante, Daelin Valiente, era el padre de Jaina."] = "庫爾提拉斯是一個水手的島國。它的大將軍戴林·普勞德摩爾是珍娜的父親。",
	["La %s también está en el menú del juego."] = "%s也在遊戲選單中。",
	["La Abadía de Villanorte es de las más antiguas del reino; ahí empiezan su camino muchos aventureros humanos."] = "北郡修道院是王國中最古老的修道院之一；許多人類冒險者都從這裡啟程。",
	["La Alianza nació en la Segunda Guerra, cuando los reinos humanos, los enanos y los altos elfos se unieron contra la Horda."] = "聯盟誕生於第二次戰爭，當時人類諸王國、矮人與高等精靈聯合起來對抗部落。",
	["La B, Mayús+B, la tecla de cada bolsa y los comerciantes abren la ventana de Alfa. Apágalo para volver a las del juego."] = "按 B、Shift+B、各背包的按鍵或與商人交談時會開啟 Alfa 的視窗。關閉此選項即可改回遊戲背包。",
	["La Capilla de la Esperanza de la Luz resistió a la Plaga en una batalla legendaria; hoy es el gran refugio del Alba Argenta."] = "聖光之願禮拜堂在一場傳奇戰役中抵擋住了天譴軍團；如今它是銀色黎明的重要據點。",
	["La Catedral de la Luz es el corazón de la fe en Ventormenta; sus sacerdotes atienden a toda la Alianza."] = "光明大教堂是暴風城的信仰核心；那裡的牧師為整個聯盟服務。",
	["La Cresta de la Llama es el puesto de la Horda en las estepas, en lo alto de las rocas."] = "烈焰峰是部落在平原上的據點，位於高高的岩石上。",
	["La Cruzada Escarlata nació del dolor de Lordaeron tras la plaga, pero su odio la volvió tan cruel como lo que combate."] = "血色十字軍誕生於洛丹倫遭受瘟疫後的傷痛，但仇恨讓它變得和它所對抗的東西一樣殘忍。",
	["La Cruzada Escarlata tiene aquí su monasterio. Para ellos todo no-muerto debe arder, también los Renegados."] = "血色十字軍的修道院就在這裡。在他們看來，所有不死族都該被燒掉，被遺忘者也不例外。",
	["La Cuenca de Arathi, el campo de batalla, está en estas tierras: se pelea por la granja, la mina, el aserradero, los establos y la herrería."] = "戰場阿拉希盆地就在這片土地上：爭奪的是農場、礦坑、伐木場、獸欄和鐵匠鋪。",
	["La Feria de la Luna Negra tiene su propia reputación, y se sube con sus vales y sus encargos."] = "暗月馬戲團有自己的聲望，可以用獎券和委託來提升。",
	["La Fortaleza de Grommash, en Orgrimmar, lleva el nombre de Grom Grito Infernal, el héroe que liberó a los orcos de la sangre demoníaca."] = "奧格瑪的格羅瑪什要塞以葛羅姆·地獄吼命名，正是這位英雄讓獸人擺脫了惡魔之血。",
	["La Fuente del Sol, el corazón de Quel'Thalas, nació de un frasco de agua del Pozo de la Eternidad que los altos elfos se llevaron."] = "奎爾薩拉斯的核心太陽之井，源自高等精靈帶走的一瓶永恆之井之水。",
	["La Garganta de Fuego quedó así por culpa del Hierro Negro: su hechicero-thane Thaurissan invocó a Ragnaros y la tierra se incendió."] = "灼熱峽谷變成這樣都是黑鐵矮人的錯：他們的術士領主索瑞森召喚了拉格納羅斯，大地因此燃燒起來。",
	["La Gran Forja nunca se apaga: es el corazón de Forjaz y el orgullo de tu gente."] = "大熔爐從未熄滅：它是鐵爐堡的核心，也是你族人的驕傲。",
	["La Gran Forja, en el corazón de Forjaz, nunca se apaga."] = "鐵爐堡中心的大熔爐從未熄滅。",
	["La Guardia Nocturna es la milicia de Villa Oscura: protege el pueblo de lobos, no-muertos y worgen."] = "守夜人是夜色鎮的民兵：保護城鎮免受狼、不死族與狼人的侵擾。",
	["La Guerra de los Ancestros fue la primera invasión de la Legión Ardiente a Azeroth, hace unos diez mil años."] = "上古之戰是燃燒軍團對艾澤拉斯的第一次入侵，大約發生在一萬年前。",
	["La Hermandad del Torio son enanos Hierro Negro que se separaron de su clan. Son maestros herreros y negocian con quien los respete."] = "瑟銀兄弟會是脫離了自己氏族的黑鐵矮人。他們是鍛造大師，願意和任何尊重他們的人做生意。",
	["La Hermandad del Torio, en La Garganta de Fuego, enseña planos que muchos herreros sueñan."] = "灼熱峽谷的瑟銀兄弟會傳授許多鐵匠夢寐以求的設計圖。",
	["La Horda arrasó Ventormenta en la Primera Guerra. Los albañiles que la reconstruyeron no recibieron su pago, y de ese enojo nació la Hermandad Defias."] = "第一次戰爭中部落摧毀了暴風城。重建它的石匠們沒有拿到工錢，迪菲亞兄弟會就是從這股怒火中誕生的。",
	["La Horda tiene su propio pueblo al norte del marjal, para vigilar Theramore de cerca."] = "部落在沼澤北邊有自己的村子，就近監視塞拉摩。",
	["La Horda tiene una aldea en la costa de Desolace, y la Alianza un campamento en las montañas del norte."] = "部落在淒涼之地的海岸有一座村莊，聯盟則在北部山區有一座營地。",
	["La Jauría"] = "La Jauría",
	["La Jauría en Discord"] = "La Jauría 的 Discord",
	["La Jauría en el mapa"] = "地圖上的 La Jauría",
	["La Jauría está de fiesta"] = "La Jauría 在慶祝",
	["La Jauría más cuidadosa y Alfa más ligero: el mapa del grupo, los barcos y tus bolsas trabajan menos."] = "更謹慎的 La Jauría，更輕巧的 Alfa：隊伍地圖、船隻和背包都更省力。",
	["La Jauría nocturno"] = "La Jauría 夜色",
	["La Jauría: estado"] = "La Jauría：狀態",
	["La Jauría: tu manada en el mapa, Seguir y el clan (/alfa manada ayuda)"] = "La Jauría：地圖上的狼群、跟隨功能與公會（/alfa manada ayuda）",
	["La Jauría: tus comandos"] = "La Jauría：你的指令",
	["La Legión Ardiente es el ejército de demonios de Sargeras, un titán caído que quiere quemar toda la creación."] = "燃燒軍團是薩格拉斯的惡魔大軍，他是一位墮落的泰坦，想要焚盡一切造物。",
	["La Liga de Arathor y los Rapiñadores se pelean la Cuenca de Arathi; las Centinelas Ala de Plata y la Escolta Grito de Guerra, la Garganta Grito de Guerra."] = "阿拉索聯軍和污染者爭奪阿拉希盆地；銀翼哨兵和戰歌偵察騎兵爭奪戰歌峽谷。",
	["La Liga de Expedicionarios, los arqueólogos de Forjaz, busca por todo el mundo las ruinas que cuenten el origen de los enanos."] = "探險者協會是鐵爐堡的考古學家，他們走遍世界，尋找能揭示矮人起源的遺跡。",
	["La Luz para los humanos y enanos, Elune para los elfos de la noche y las sombras para muchos Renegados: cada sacerdote sirve a algo distinto."] = "人類和矮人信奉聖光，夜精靈信奉伊露恩，許多被遺忘者則追隨暗影：每位牧師侍奉的東西各不相同。",
	["La Lya de %s dice algo. Yo le contesto: «%s»"] = "%s 的莉婭說了些什麼。我回答她：「%s」",
	["La Mano de Plata la fundó el arzobispo Alonsus Faol, y Uther fue su primer paladín."] = "白銀之手由大主教阿隆索斯·法奧創立，烏瑟是它的第一位聖騎士。",
	["La Mano de Plata, la orden de paladines, la fundó el arzobispo Alonsus Faol, y Uther fue el primero de sus caballeros."] = "聖騎士騎士團白銀之手由大主教阿隆索斯·法奧創立，烏瑟是其中第一位騎士。",
	["La Masacre fue Eldre'Thalas, una ciudad de los elfos Altonato de antes de la Gran División."] = "厄運之槌曾是艾德雷斯拉斯，一座大分裂之前上層精靈的城市。",
	["La Milicia Popular de la Colina del Centinela la formaron los propios granjeros cuando Ventormenta dejó de mandar soldados."] = "哨兵嶺的人民軍是暴風城不再派兵後，由農民們自己組建的。",
	["La Montaña Roca Negra se alza entre esta garganta y las Estepas Ardientes. Dentro viven los Hierro Negro, Ragnaros y los dragones negros."] = "黑石山聳立在這座峽谷與燃燒平原之間。裡面住著黑鐵矮人、拉格納羅斯與黑龍。",
	["La Muralla de Thoradin separa Arathi de las Laderas de Trabalomas; lleva el nombre del rey que unió a los humanos."] = "索拉丁之牆把阿拉希與希爾斯布萊德丘陵隔開；它以統一人類的那位國王命名。",
	["La Orden de Tirisfal, los magos secretos que elegían al Guardián de Azeroth, tomó su nombre de estos claros. Medivh fue el último Guardián."] = "提瑞斯法議會是負責選出艾澤拉斯守護者的秘密法師組織，它的名字就來自這片林地。麥迪文是最後一位守護者。",
	["La Plaga es el ejército no-muerto del Rey Exánime. Kel'Thuzad la extendió por Lordaeron con grano infectado."] = "天譴軍團是巫妖王的不死大軍。科爾蘇加德用染疫的穀物把它散播到整個洛丹倫。",
	["La Polimorfia convierte al enemigo en oveja. Yo me portaría muy bien con esa oveja, palabra de loba."] = "變形術會把敵人變成綿羊。我會對那隻羊非常友善的，狼的承諾。",
	["La Segadora de arcanita es una de las armas más famosas que puede forjar un herrero."] = "奧金斧是鐵匠能鍛造的最有名的武器之一。",
	["La Sima Ígnea está bajo Orgrimmar: ahí se esconden brujos de un culto junto con troggs."] = "怒焰裂谷位於奧格瑪地下：一個邪教的術士和穴居人一起躲在那裡。",
	["La Sociedad Real de Boticarios trabaja en Entrañas en una plaga nueva. Mejor no preguntes para quién."] = "皇家藥劑師協會正在幽暗城研製一種新的瘟疫。最好別問是給誰用的。",
	["La Sociedad Real de Boticarios trabaja en secreto en una plaga nueva... y no precisamente para los humanos solamente."] = "皇家藥劑師協會正秘密研製一種新的瘟疫…而且目標恐怕不只是人類。",
	["La Tercera Guerra empezó con la plaga del grano en Lordaeron y terminó en Hyjal con la caída de Archimonde."] = "第三次戰爭始於洛丹倫的穀物瘟疫，終於海加爾山上阿克蒙德的殞落。",
	["La Torre de Azora, en el este de Elwynn, es la casa de Theocritus, un mago al servicio del reino."] = "艾爾文森林東部的阿祖拉之塔是塞歐克瑞圖斯的家，他是一位為王國效力的法師。",
	["La aldea Sen'jin, en la costa de Durotar, lleva el nombre del líder que dio su vida por su pueblo."] = "杜洛塔海岸的森金村以那位為族人獻出生命的首領命名。",
	["La ayuda de rotación está apagada"] = "輸出循環助手已關閉",
	["La barra con el nombre de la zona y la hora toma los colores y la letra del estilo. Los botones de rastreo, calendario y correo quedan como siempre."] = "顯示地區名稱與時間的列會使用該風格的顏色與字型。追蹤、行事曆與郵件按鈕保持原樣。",
	["La barra de acción, las barras extra, la de experiencia, el menú y las bolsas toman el estilo que elijas. Solo cambia su aspecto, fuera de combate; al apagarlo vuelven las del juego."] = "快捷列、額外快捷列、經驗條、選單與背包會使用你選擇的風格。只在非戰鬥中改變外觀；關閉後恢復遊戲原本的樣子。",
	["La barra de pesca"] = "釣魚條",
	["La barra de tu vuelo con sus paradas sale siempre al despegar."] = "起飛時一定會顯示帶有中途站的飛行條。",
	["La barra de vida con el color de la clase de cada uno. Apagado: barra verde y el nombre con su color."] = "生命條使用每個人的職業顏色。關閉時：生命條為綠色，名字使用職業顏色。",
	["La base incluida trae %s lugares en %d zonas. Tú descubriste %s."] = "內建資料庫有 %s 個位置，分布在 %d 個地區。你發現了 %s 個。",
	["La bienvenida con las novedades de esta versión."] = "包含此版本新功能的歡迎頁面。",
	["La bienvenida ocupa toda la pantalla, con el juego oscurecido detrás."] = "歡迎設定佔滿整個畫面，遊戲畫面在後方變暗。",
	["La básica la venden los instructores y los vendedores de suministros de pesca."] = "基礎款由訓練師與釣魚用品商人販售。",
	["La búsqueda de lugares cercanos no está disponible."] = "無法使用附近地點搜尋。",
	["La cadena completa"] = "完整任務鏈",
	["La cadena de los Defias te lleva de Villadorada a los Páramos de Poniente y termina en las Minas de la Muerte, frente a VanCleef."] = "迪菲亞任務鏈會帶你從閃金鎮到西部荒野，最後在死亡礦坑與范克里夫正面交鋒。",
	["La cadena no trae talentos válidos."] = "這段字串中沒有有效的天賦。",
	["La caja donde escribes toma el estilo, con el borde de acento mientras escribes. En Clásico WoW queda la del juego."] = "輸入框會使用該風格，輸入時顯示強調色邊框。在經典 WoW 中保留遊戲原本的輸入框。",
	["La cambiaste fuera de Alfa (menú del juego o consola)."] = "你在 Alfa 之外變更了它（遊戲選單或主控台）。",
	["La capa de escamas de Onyxia protege del aliento de Nefarian, y en su banda la piden todos."] = "奧妮克希亞鱗片披風能抵擋奈法利安的龍息，在他的團隊副本裡人人都需要。",
	["La cerveza es casi sagrada para tu gente: en Kharanos está la destilería Cebatruenos."] = "啤酒對你的族人來說幾乎是神聖的：雷酒釀酒廠就在卡拉諾斯。",
	["La cola está vacía."] = "佇列是空的。",
	["La configuración es más visual: tres tarjetas para decidir cuánto te ayuda Alfa y tus extras en un mosaico."] = "設定更直觀了：用三張卡片決定 Alfa 幫多少，額外功能用拼圖選。",
	["La cura de ese clic pasa al botón central."] = "該點擊的治療會移到中鍵。",
	["La cámara no salta hacia ti por cada árbol o poste entre ella y tu personaje."] = "鏡頭不會因為你和角色之間的每棵樹或每根柱子而猛然拉近。",
	["La cámara se mece un poco con tus pasos."] = "鏡頭會隨你的步伐輕微晃動。",
	["La cámara se queda sobre el agua en lugar de meterse."] = "鏡頭停留在水面上，而不會進入水下。",
	["La cámara te sigue"] = "鏡頭跟隨你",
	["La de ahora pasa a tus sesiones anteriores."] = "目前這次會移到你以前的記錄中。",
	["La de ahora pasa a tus sesiones anteriores. Tu diario y tus logros no cambian."] = "目前這次會移到你以前的記錄中。你的圖鑑與成就不會改變。",
	["La de tu clase mientras subes: cambia sola cuando pongas talentos."] = "升級時使用你職業的優先順序：分配天賦後會自動切換。",
	["La de tu nivel. Antes, revisa que lleves todo."] = "適合你等級的。先確認東西都帶齊了。",
	["La derecha"] = "向右",
	["La dirección del texto sobre tu personaje."] = "你角色上方文字的方向。",
	["La empieza un objeto"] = "由物品開始",
	["La enciclopedia de La Jauría"] = "La Jauría 百科",
	["La enciclopedia no puede abrir todavía"] = "百科暫時無法開啟",
	["La entrada de %s"] = "%s的入口",
	["La entrada de cada mazmorra en el minimapa, en verde las que ya hiciste. El mapa del mundo ya las marca con «Entradas de mazmorras»."] = "在小地圖上顯示每個地城的入口，已完成的會以綠色顯示。世界地圖已經用「地城入口」標記了它們。",
	["La familia Barov le entregó su castillo de Caer Darrow al Culto a cambio de vida eterna. Así nació Scholomance, y así les fue."] = "巴羅夫家族為了永生，把凱爾達隆的城堡交給了詛咒神教。通靈學院就這樣誕生了，他們的下場你也看到了。",
	["La flecha"] = "箭頭",
	["La flecha con el estilo de La Jauría, y «¿Cuánto tiempo tienes?» arma tu plan paso a paso."] = "La Jauría 風格的箭頭，「你有多少時間？」一步步幫你擬定計畫。",
	["La flecha no está disponible ahora."] = "箭頭目前無法使用。",
	["La flecha que te guía"] = "為你指路的箭頭",
	["La flecha se mueve con su rastro y se detiene al llegar."] = "箭頭會隨著對方的蹤跡移動，抵達後停止。",
	["La flecha sigue caminos por el suelo alrededor de acantilados, agua y muros, con los mapas para caminar de Alfa. Apagado: apunta directo a cada parada."] = "箭頭會依 Alfa 的步行地圖，沿地面繞過懸崖、水域與牆壁前進。關閉：直接指向每一站。",
	["La flecha te lleva a %s."] = "箭頭會帶你去%s。",
	["La flecha te lleva a este paso, no al de ahora."] = "箭頭會帶你去這一步，而不是目前步驟。",
	["La flecha te lleva a su entrada."] = "箭頭會帶你去它的入口。",
	["La flecha te lleva al primer paso. En Hoy ves cuánto llevas y «Siguiente» pasa al que sigue."] = "箭頭會帶你去第一步。「今天」會顯示你的進度，「下一步」繼續前進。",
	["La flecha te lleva aquí."] = "箭頭會帶你到這裡。",
	["La flecha te lleva de un lugar al siguiente."] = "箭頭會帶你從一個地點到下一個地點。",
	["La flecha tomó otro destino: dejaste de seguir a %s."] = "箭頭已改指向其他目的地：你已停止跟隨 %s。",
	["La flecha usa vuelos y tu piedra de hogar cuando conviene."] = "箭頭會在划算時使用飛行與爐石。",
	["La flecha y el camino"] = "箭頭與路線",
	["La flecha ya no sigue tu ruta de farmeo."] = "箭頭已不再跟隨你的採集路線。",
	["La fuerza se cambia en la ventana, en Filtros."] = "強度在視窗的「濾鏡」中調整。",
	["La gran cacería"] = "大狩獵",
	["La guarida de Onyxia está en este marjal. Onyxia, hija de Alamuerte, se hace pasar por una noble humana en Ventormenta."] = "奧妮克希亞的巢穴就在這片沼澤裡。死亡之翼的女兒奧妮克希亞在暴風城假扮成一位人類貴婦。",
	["La guía de Pesca te dice a qué agua ir según tu nivel de pesca, y la flecha te lleva."] = "釣魚指南會依你的釣魚技能告訴你去哪片水域，箭頭帶你過去。",
	["La guía en el minimapa"] = "小地圖上的指南",
	["La guía que mejor te queda por tu nivel y donde estás."] = "依你的等級與所在位置最適合你的指南。",
	["La guía que sigues, tu paso de ahora y todo lo de las guías a un clic."] = "你正在跟隨的指南、目前的步驟，以及一鍵可及的所有指南功能。",
	["La guía te lleva a entrenar en %d pasos."] = "指南會在 %d 個步驟後帶你去訓練。",
	["La guía te lleva a quien recibe cada una."] = "指南會帶你去找每個任務的交付人。",
	["La haces de paso: abre %s."] = "順路完成：它會開啟%s。",
	["La haré"] = "我會做",
	["La historia"] = "故事",
	["La historia de Alfa"] = "Alfa 的故事",
	["La historia de Alfa y de La Jauría, el Discord, los comandos y los créditos."] = "Alfa 和 La Jauría 的故事、Discord、指令和致謝。",
	["La historia se guarda cuando el juego te muestra la misión."] = "遊戲向你顯示任務時，故事就會被保存。",
	["La hora, la fiesta y el lugar"] = "時間、節慶和地點",
	["La lengua de la Alianza es el común y la de la Horda, el orco. Por eso lo que le dices al otro bando le llega como palabras raras."] = "聯盟說通用語，部落說獸人語。所以你對另一個陣營說的話，他們聽來就是一串怪詞。",
	["La letra del aspecto (Inter en el de Alfa, Fira Sans en Halo, la del juego en los demás) o la que elijas."] = "皮膚的字型（Alfa 皮膚用 Inter，光環用 Fira Sans，其他皮膚用遊戲字型），或你選擇的字型。",
	["La lista está apagada: enciende «Tu lista de sonidos» en Comodidades (/alfa comodidades)."] = "清單已關閉：請在便利功能（/alfa comodidades）中開啟「你的聲音清單」。",
	["La lista por nivel y tu progreso."] = "依等級排列的清單與你的進度。",
	["La llegada de la flecha, nueva; circuito de la zona y «Llévame a…» con vuelos y barcos."] = "全新的箭頭抵達效果；區域環線，以及包含飛行、船隻的「帶我去…」。",
	["La llevan: %s"] = "接了這個任務的：%s",
	["La luna ya va bajando. Si cabeceas, descansa en una posada y ganas experiencia de descanso."] = "月亮要落下了。如果你在打瞌睡，就去旅店休息，攢點休息經驗。",
	["La lupa de la cabecera del rastreador abre el menú. También: /alfa cerca o tu tecla."] = "點擊追蹤器標題列的放大鏡可開啟選單。也可以用 /alfa cerca 或你的按鍵。",
	["La línea de tiempo de Blizzard dice qué ataque viene y cuándo, y los mensajes grandes, lo peligroso. Alfa no inventa avisos: los prendes y ajustas en Ajustes."] = "Blizzard 的時間軸會顯示接下來是什麼攻擊、何時到來，大字訊息會告訴你危險所在。Alfa 不會自創警報：你可以在設定中開啟與調整。",
	["La línea de tu personaje ya no se corta: si no cabe, quita partes y nunca tu nombre ni tu nivel."] = "你的角色資訊行不再被截斷：放不下時會省略部分內容，但絕不會省略你的名字和等級。",
	["La línea del camino también en el minimapa."] = "也在小地圖上顯示路徑線。",
	["La manada a la vista"] = "視野中的狼群",
	["La manada afinada"] = "默契的狼群",
	["La manada aúlla contigo."] = "狼群與你一起嚎叫。",
	["La manada aúlla por ti."] = "狼群為你嚎叫。",
	["La manada caza junta"] = "狼群一起狩獵",
	["La manada crece"] = "狼群在壯大",
	["La manada desembarca en %s"] = "狼群將在%s後上岸",
	["La manada en el mapa, cazar juntos, el saludo al entrar y la calavera para el raro con un clic."] = "地圖上的狼群、一起狩獵、登入問候，以及一鍵給稀有怪標骷髏。",
	["La manada es fuerte porque cada lobo lo es. Y tú lo eres."] = "狼群強大，是因為每一匹狼都強大。你也是。",
	["La manada no te ve en el mapa"] = "狼群在地圖上看不到你",
	["La manada no ve a tu personaje en el mapa."] = "狼群在地圖上看不到你的角色。",
	["La manada sabe qué misiones llevas (solo cuáles son) y tú las suyas. Si un lobo de tu zona hace una contigo, su tarjeta lo dice y Lya te propone invitarlo."] = "狼群知道你接了哪些任務（只知道是哪些），你也知道他們的。如果同區域的狼和你做同一個任務，他的卡片會顯示，莉婭也會建議你邀請他。",
	["La manada sana"] = "狼群治療",
	["La manada se organiza"] = "狼群集結",
	["La manada se organiza y tu historia"] = "狼群集結，還有你的故事",
	["La manada también la ve."] = "狼群也看得到。",
	["La manada te saluda"] = "狼群向你問好",
	["La manada te ve en el mapa"] = "狼群可以在地圖上看到你",
	["La manada te ve en el mapa: %s"] = "狼群可以在地圖上看到你：%s",
	["La manada unida"] = "狼群齊心",
	["La manada viaja"] = "狼群出行",
	["La manada ya no ve a tu personaje en el mapa."] = "狼群在地圖上不再能看到你的角色。",
	["La manada ya ve a tu personaje en el mapa del juego."] = "狼群現在可以在遊戲地圖上看到你的角色了。",
	["La manada ya ve a tu personaje en el mapa del juego. Lo cambias cuando quieras en /alfa manada."] = "狼群現在可以在遊戲地圖上看到你的角色了。隨時可以在 /alfa manada 中變更。",
	["La mazmorra"] = "地城",
	["La mazmorra en vivo"] = "即時地城",
	["La mazmorra para mi nivel"] = "適合我等級的地城",
	["La mazmorra para tu nivel, sus jefes, botín, misiones y consejos."] = "適合你等級的地城，以及它的首領、戰利品、任務與提示。",
	["La mazmorra para tu nivel, sus misiones y cómo llegar."] = "適合你等級的地城、它的任務以及如何前往。",
	["La mazmorra para tu nivel; con un nombre, esa mazmorra (también: progreso, ajustes)"] = "適合你等級的地城；加上名稱則顯示該地城（也可用：progreso、ajustes）",
	["La mañana huele a pan recién hecho en las posadas. ¿Empezamos con las misiones fáciles?"] = "早上的旅店飄著新鮮麵包的香味。我們從簡單的任務開始？",
	["La mejor de tus bolsas"] = "背包裡最好的",
	["La mezcla de texturas del terreno."] = "地形材質的混合。",
	["La misión"] = "任務",
	["La montura"] = "坐騎",
	["La niebla con cuerpo de valles, pantanos y amaneceres."] = "山谷、沼澤與清晨裡濃厚的霧氣。",
	["La noche en Los Baldíos es enorme y callada. Se oyen las hienas a lo lejos."] = "貧瘠之地的夜晚遼闊又安靜。能聽到遠處的鬣狗聲。",
	["La noche en Tirisfal es más fría que el día. Huele a hojas mojadas y a cripta."] = "提里斯法的夜晚比白天更冷。聞起來是濕葉子和墓穴的味道。",
	["La pantalla se pone negra uno o dos segundos mientras el juego vuelve a arrancar los gráficos. No sales del juego ni pierdes nada."] = "遊戲重新啟動圖形時畫面會黑一兩秒。你不會離開遊戲，也不會遺失任何東西。",
	["La pesca de Alfa está apagada"] = "Alfa 釣魚功能已關閉",
	["La pesca se rehízo: una sola tecla para equiparte, lanzar y recoger, con diario, logros y una guía de 1 a 300."] = "釣魚功能已重做：一個鍵就能換裝備、拋竿和拾取，還有圖鑑、成就和 1 到 300 的指南。",
	["La piel verde de los orcos es una huella de la magia vil que usaron sus brujos en Draenor."] = "獸人的綠色皮膚是他們的術士在德拉諾使用邪能魔法留下的印記。",
	["La plática: lore y datos"] = "閒聊：背景故事和趣聞",
	["La precisión es lo más importante: con dos armas fallas mucho sin ella."] = "命中最重要：用雙武器時沒有它會常常打不中。",
	["La primera vence en %s. Tómala antes de que regrese a quien te la mandó o se pierda."] = "第一封將在 %s 後到期。在它退回寄件人或遺失前拿走吧。",
	["La primera vez: %s%s."] = "第一次：%s%s。",
	["La princesa Moira, hija de Magni Barbabronce, vive en las Profundidades de Roca Negra como esposa del emperador Thaurissan."] = "麥格尼·銅鬚的女兒茉艾拉公主住在黑石深淵，是索瑞森大帝的妻子。",
	["La profesión"] = "專業",
	["La página de Bolsas; «abrir» abre tus bolsas y «banco» tu banco"] = "背包頁面；加上「abrir」開啟背包，加上「banco」開啟銀行",
	["La página de Bolsas; «abrir», «banco», «conjunto <nombre>» y «guardar <nombre>»"] = "背包頁面；「abrir」（開啟）、「banco」（銀行）、「conjunto <名稱>」（穿上設定）和「guardar <名稱>」（儲存設定）",
	["La que te toca, con sus misiones y su botín."] = "適合你的那個，附帶任務與戰利品。",
	["La recoges ahora"] = "現在接取",
	["La recomendada para ti y todas las demás"] = "為你推薦的以及其他所有",
	["La recomendada para ti y todas las demás."] = "為你推薦的以及其他所有。",
	["La ruta más rápida desde tu nivel, misión por misión."] = "從你的等級出發的最快路線，一個任務接一個任務。",
	["La ruta no trae tramos."] = "這條路線沒有任何路段。",
	["La ruta te lleva a %s. La flecha está apagada: enciéndela en Ajustes > Guía para verla."] = "路線會帶你去%s。箭頭已關閉：請在「設定 > 指南」中開啟才能看到。",
	["La ruta ya no se salta para siempre una misión que todavía no puede revisar."] = "路線不會再永久跳過暫時無法檢查的任務。",
	["La sabes"] = "已學會",
	["La sacas de tu plan."] = "你把它從計畫中移除。",
	["La sastrería usa la tela que sueltan los humanoides: lino, lana, seda, tejido mágico y tela rúnica."] = "裁縫使用人型生物掉落的布料：亞麻布、毛料、絲綢、魔紋布和符文布。",
	["La selva de Tuercespina de noche suena a mil bichos. Los trols sí ven en la oscuridad."] = "荊棘谷的叢林夜裡像有一千隻蟲子在叫。食人妖在黑暗中看得可清楚了。",
	["La semana de caza"] = "狩獵週",
	["La semana de la manada"] = "狼群的一週",
	["La siguiente casilla cuesta %s y no te alcanza todavía."] = "下一個欄位需要 %s，你的錢還不夠。",
	["La siguiente casilla cuesta %s: cómprala con el botón del banco del juego, que ya está a la vista."] = "下一個欄位需要 %s：請用遊戲銀行的按鈕購買，它已經顯示出來了。",
	["La subasta deja escanear todo cada 15 minutos. Falta %s."] = "拍賣場每 15 分鐘才能完整掃描一次。還要 %s。",
	["La subasta no aceptó el escaneo. Intenta de nuevo más tarde."] = "拍賣場不接受這次掃描。請稍後再試。",
	["La subasta no envió subastas. Intenta de nuevo más tarde."] = "拍賣場沒有傳回任何拍賣。請稍後再試。",
	["La subasta no respondió. Puede que aún esté en espera: intenta en unos minutos."] = "拍賣場沒有回應。可能還在冷卻中：請過幾分鐘再試。",
	["La suma de lo que guardó Alfa de cada personaje (el tuyo, al día)."] = "Alfa 為每個角色儲存的總和（你目前的角色為即時資料）。",
	["La tarde se presta para una mazmorra con la manada. Hay más gente conectada a estas horas."] = "下午最適合和狼群一起下地城。這個時間在線上的人更多。",
	["La tecla del botón de tu barra con esa habilidad, sobre el ícono."] = "圖示上顯示快捷列中該技能按鈕的按鍵。",
	["La tecla del mapa abre este mapa"] = "地圖鍵開啟此地圖",
	["La tecla que abre el mapa del juego (M) abre el de Alfa; en él, un botón te lleva al del juego. Apágalo y la tecla vuelve a abrir el del juego. También puedes darle una tecla propia en Opciones > Teclado > Alfa."] = "開啟遊戲地圖的按鍵（M）會開啟 Alfa 地圖；其中有一個按鈕可前往遊戲地圖。關閉此選項，按鍵會恢復開啟遊戲地圖。你也可以在「選項 > 按鍵設定 > Alfa」中為它設定專屬按鍵。",
	["La tecla que usabas en tu otro addon de pesca (%s) ahora pesca con Alfa."] = "你在其他釣魚插件使用的按鍵（%s）現在改用 Alfa 釣魚。",
	["La tela rúnica sale de humanoides de nivel 50 o más: los trols de las Tierras del Interior o los sátiros de Frondavil son buena opción."] = "符文布來自 50 級以上的人型生物：辛特蘭的食人妖或費伍德森林的薩特都是好選擇。",
	["La tela sale de los enemigos humanoides de tu nivel. Los hilos los venden los proveedores de sastrería."] = "和你同等級的人型敵人會掉布料。裁縫用品商人出售線。",
	["La tela vil sale de sátiros y demonios de Frondavil y Azshara."] = "惡魔布來自費伍德森林和艾薩拉的薩特與惡魔。",
	["La tomo otra vez"] = "我再接一次",
	["La tribu Zandalar se considera la primera de todos los trols. Sus sacerdotes acampan en la Isla de Yojamba para frenar a Hakkar."] = "贊達拉部族自認為是所有食人妖中的第一支。他們的祭司在尤亞姆巴島紮營，以阻止哈卡。",
	["La trituradora tira a la gente: vuelve a llamar su atención rápido."] = "伐木機會把人擊退：盡快把仇恨拉回來。",
	["La tuya tiene %d semanas: salen seguido."] = "你的版本已有 %d 週：更新很頻繁。",
	["La varilla de cobre la venden los proveedores de encantamiento."] = "附魔用品商人出售銅棒。",
	["La venta se detuvo: vendiste %d de %d."] = "出售已停止：你賣出了 %d/%d 件。",
	["La ventana"] = "視窗",
	["La ventana de talentos del juego"] = "遊戲的天賦視窗",
	["La ventana del Legado del juego"] = "遊戲的傳承視窗",
	["La última vez cazamos %s"] = "上次我們狩獵了：%s",
	["La última: %s."] = "最近一次：%s。",
	["Lady Sylvanas Brisaveloz gobierna a los Renegados. Fue general forestal de Quel'Thalas antes de que Arthas la matara."] = "希瓦娜斯·風行者女士統治著被遺忘者。被阿薩斯殺死之前，她是奎爾薩拉斯的遊俠將軍。",
	["Lady Vashj, que fue dama de compañía de Azshara, ahora guía a sus naga al servicio de Illidan."] = "瓦許女士曾是艾薩拉的侍女，如今率領她的納迦為伊利丹效力。",
	["Lanza bolas de fuego y fuego a su alrededor: interrúmpelo y, si peleas de lejos, aléjate."] = "他會施放火球術並在周圍釋放火焰：打斷他，遠程職業請保持距離。",
	["Lanza bombas de humo que aturden: sal del humo."] = "他會丟出會擊昏人的煙霧彈：離開煙霧。",
	["Lanza enredaderas que tumban a todos los que están cerca: si peleas de lejos, quédate lejos."] = "他會施放藤蔓，擊倒附近所有人：遠程職業請保持距離。",
	["Lanza fuego a su alrededor: si peleas de lejos, aléjate de él."] = "他會在周圍釋放火焰：遠程職業請離他遠一點。",
	["Lanza hechizos de tierra y pone tótems: rompan los tótems primero."] = "他會施放大地法術並放置圖騰：先把圖騰打掉。",
	["Lanza metal fundido: si no tanqueas, no te quedes pegado a él."] = "他會潑灑熔化的金屬：如果你不是坦克，不要貼在他身邊。",
	["Lanza rayos y se puede curar: interrumpe sus hechizos."] = "她會施放閃電，也會治療自己：打斷她的法術。",
	["Lanza ráfagas arcanas: interrúmpelo."] = "他會施放秘法衝擊：打斷他。",
	["Lanza sombras: interrúmpelo."] = "他會施放暗影法術：打斷他。",
	["Lanza telarañas y una maldición: quita la maldición si puedes."] = "他會吐蛛網並施放詛咒：能解除詛咒的話就解除。",
	["Lanza tormentas de arena que se mueven por la sala: no te pares en ellas."] = "他會製造在房間內移動的沙暴：不要站在裡面。",
	["Lanza tu hechizo más fuerte desde lejos y remata con los instantáneos."] = "從遠處施放你最強的法術，再用瞬發法術收尾。",
	["Lanza tu hechizo más fuerte primero y remata con un choque."] = "先施放你最強的法術，再用震擊收尾。",
	["Lanza una nube de veneno hacia adelante: gíralo lejos del grupo."] = "她會向前噴出毒雲：把她轉向背對隊伍。",
	["Lanza una red que deja quieto a un jugador: no es grave, sigue atacando."] = "他會丟出網子定住一名玩家：不要緊，繼續攻擊。",
	["Lanza veneno a todos: quita el veneno si puedes."] = "他會對所有人施毒：能解毒的話就解毒。",
	["Lanzado"] = "已拋竿",
	["Lanzamientos"] = "拋竿次數",
	["Lanzamientos: %d de %d"] = "拋竿：%d / %d",
	["Las Cavernas del Tiempo guardan los momentos más importantes de la historia, y el Vuelo Bronce no deja que nadie los cambie."] = "時光之穴保存著歷史上最重要的時刻，青銅龍軍團不允許任何人改變它們。",
	["Las Estepas Ardientes se incendiaron cuando Ragnaros despertó, y sus brasas siguen sin apagarse."] = "拉格納羅斯甦醒時燃燒平原燃起了大火，餘燼至今仍未熄滅。",
	["Las Islas del Eco eran el hogar de los Lanza Negra, hasta que el brujo Zalazane sometió a muchos con su vudú y los demás tuvieron que mudarse a tierra firme."] = "回音群島曾是暗矛部族的家園，直到巫醫札拉贊恩用巫毒術控制了許多族人，其餘的人只好遷到大陸上。",
	["Las Lyas de tu grupo"] = "你隊伍裡的莉婭們",
	["Las Minas de la Muerte esconden el refugio de VanCleef... y hasta un barco pirata."] = "死亡礦坑裡藏著范克里夫的巢穴…甚至還有一艘海盜船。",
	["Las Montañas Crestagrana deben su nombre a sus rocas rojizas."] = "赤脊山因其泛紅的岩石而得名。",
	["Las Profundidades de Roca Negra son una ciudad enana entera bajo la montaña: la capital de los Hierro Negro."] = "黑石深淵是一整座位於山下的矮人城市：黑鐵矮人的首都。",
	["Las Rocas Rojas de Mulgore son un lugar sagrado: ahí descansan los ancestros de los tauren."] = "莫高雷的紅石是一處聖地：牛頭人的祖先安息在那裡。",
	["Las Rocas Rojas son el lugar más sagrado de Mulgore: ahí descansan los ancestros de tu gente."] = "紅石是莫高雷最神聖的地方：你族人的祖先安息在那裡。",
	["Las Tierras de la Peste del Este siguen tristes aun de día. Aquí la Plaga no descansa."] = "東瘟疫之地白天也一樣悲涼。天譴軍團在這裡從不休息。",
	["Las aguas de nivel 20 a 35. El rango Experto se aprende con el libro que vende el pescador de Bahía del Botín."] = "20 到 35 級的水域。高級釣魚要用藏寶海灣漁夫販售的書來學。",
	["Las barras de abajo"] = "底部的列",
	["Las barras de acción"] = "快捷列",
	["Las barras y retratos vuelven al terminar el combate."] = "快捷列和頭像會在戰鬥結束後回來。",
	["Las bendiciones mayores duran más y cubren a toda una clase del grupo. ¡Ahorran mucho maná!"] = "強效祝福持續時間更長，能覆蓋隊伍中某個職業的所有人。非常省法力！",
	["Las bolsas de Alfa acomodan todo por categorías, marcan lo nuevo y lo de misión, y depositan rápido en el banco."] = "Alfa 背包按分類整理，標出新物品和任務物品，還能快速存銀行。",
	["Las bolsas que coses siempre se venden: todo el mundo quiere más espacio."] = "你縫製的背包永遠賣得出去：每個人都想要更多空間。",
	["Las bombas y granadas te salvan en mazmorras y en peleas contra el otro bando."] = "炸彈和手榴彈能在地城裡和對抗另一個陣營時救你一命。",
	["Las cajas cerradas las abren los pícaros; ofrécelas en el chat y a veces hasta te regalan el servicio."] = "上鎖的箱子由盜賊來開；在聊天裡問問，有時他們甚至免費幫你開。",
	["Las cartas de la Luna Negra caen de enemigos por todo el mundo; un mazo completo se cambia en la Feria por un abalorio poderoso."] = "暗月卡片會從世界各地的敵人身上掉落；集齊一整套可以在馬戲團換一件強力飾品。",
	["Las casas de subastas neutrales de Bahía del Botín, Gadgetzan y Vista Eterna cobran más comisión, pero te dejan comerciar con el otro bando."] = "藏寶海灣、加基森和永望鎮的中立拍賣場手續費更高，但能和另一個陣營交易。",
	["Las centinelas de Vallefresno pelean sin descanso contra los leñadores orcos de Grito de Guerra."] = "梣谷的哨兵們不停地與戰歌氏族的獸人伐木工作戰。",
	["Las centinelas domestican sables de hielo en Cuna del Invierno, y se los confían solo a quien se gana su respeto."] = "哨兵們在冬泉谷馴養霜刃豹，只託付給贏得她們尊重的人。",
	["Las citas de la manada en los próximos siete días. Propón una arriba, en «Citas de la manada»."] = "狼群未來七天的集合。在上方的「狼群集合」中發起一個。",
	["Las citas de la manada están apagadas (Ajustes de La Jauría)."] = "狼群集合已關閉（La Jauría 設定）。",
	["Las citas de los próximos siete días, acomodadas por día."] = "未來七天的集合，依日期排好。",
	["Las citas van a los lobos de tu hermandad: necesitas una."] = "集合會發給你公會的狼：你需要一個公會。",
	["Las criaturas que invocan los enemigos por un rato."] = "敵人暫時召喚出來的生物。",
	["Las cuentas"] = "計算明細",
	["Las cuentas de prueba no pueden compartir: el juego no lo permite."] = "試玩帳號無法分享：遊戲不允許。",
	["Las de tu ruta que tienes cerca"] = "附近你路線上的",
	["Las de tu ruta, las de la guía o todas: se eligen en Ajustes > Misiones, con lo demás de las misiones."] = "你的路線、指南的任務或全部：在「設定 > 任務」中與其他任務設定一起選擇。",
	["Las demás"] = "其他",
	["Las demás ranuras"] = "其他欄位",
	["Las dos se suben solas mientras matas y viajas, y lo que juntas se vende bien: oro para tu montura y tus habilidades."] = "這兩個專業會在你殺怪與旅行時自然提升，採到的東西也很好賣：賺錢買坐騎與學技能。",
	["Las dríades son hijas de Cenarius, y los guardianes de la arboleda, sus hijos."] = "樹精是塞納留斯的女兒，林地守護者則是他的兒子。",
	["Las especias y el agua las venden los taberneros y proveedores de cocina. Pesca te da mucho de lo que cocinas."] = "旅店老闆和烹飪用品商人出售調味料和水。你烹飪的很多東西都來自釣魚。",
	["Las esquinas de la pantalla se oscurecen poco a poco, como en una foto."] = "畫面四角逐漸變暗，就像照片一樣。",
	["Las excavaciones de los enanos despertaron a los troggs, y ahora Thelsamar tiene que cuidarse de ellos."] = "矮人的挖掘驚醒了穴居人，現在塞爾薩瑪得提防他們。",
	["Las explicaciones vuelven a salir."] = "說明會重新顯示。",
	["Las flores cantoras corrompidas de Frondavil se pueden purificar; al hacerlo te dan una bendición que dura un buen rato."] = "費伍德森林被腐化的歌唱花可以被淨化；淨化後你會獲得一個持續很久的祝福。",
	["Las fronteras entre zonas ya no parpadean al mover el mapa."] = "移動地圖時，區域之間的邊界不再閃爍。",
	["Las gafas de ingeniero solo las pueden usar ingenieros: ¡lúcelas con orgullo!"] = "工程護目鏡只有工程師能戴：驕傲地戴上吧！",
	["Las guaridas de la manada"] = "狼群的巢穴",
	["Las guías y mazmorras de tu nivel al 60, y cuánto avanzas cada día."] = "從你的等級到 60 級的指南和地城，以及你每天升了多少。",
	["Las hierbas de nivel alto se venden muy bien en la casa de subastas."] = "高等級草藥在拍賣場賣得很好。",
	["Las líneas que escribe Anunciar en el chat de tu grupo o banda."] = "「通報」在你的隊伍或團隊聊天中發布的內容。",
	["Las marca con una flecha."] = "會用箭頭標出提升。",
	["Las marcas de la manada también en el minimapa, no solo en el mapa del mundo."] = "狼群的標記也顯示在小地圖上，而不只是世界地圖。",
	["Las marcas en el suelo de hechizos y áreas. Apagarlas esconde avisos de combate: mejor dejarlas encendidas."] = "法術與區域在地面上的標記。關閉會隱藏戰鬥警示：最好保持開啟。",
	["Las mejores misiones que ya puedes tomar cerca de ti, en el orden más corto."] = "你附近現在就能接的最佳任務，依最短順序。",
	["Las mesetas de Cima del Trueno están unidas por puentes, y a la ciudad se sube en elevadores."] = "雷霆崖的各座台地之間由橋梁相連，要搭升降梯才能上到城裡。",
	["Las metas se cumplen solas al hacerlas; las notas las marcas tú. Ordénalas como quieras."] = "目標在你完成時會自動達成；備註由你自己勾選。可以隨意排序。",
	["Las misiones avisan otra vez"] = "任務通報回來了",
	["Las misiones de Molino Tarren mandan a la Horda contra las granjas humanas de las laderas."] = "塔倫米爾的任務派部落去攻打丘陵上的人類農場。",
	["Las misiones del juego"] = "遊戲的任務追蹤",
	["Las misiones grises dan poca XP. Entrégalas y sigue adelante."] = "灰色任務給的經驗很少。交掉然後繼續前進吧。",
	["Las misiones previas y el nivel que pide, para poder tomarla."] = "前置任務與所需等級，讓你能接取它。",
	["Las misiones que más experiencia dan cerca de ti."] = "你附近經驗值最多的任務。",
	["Las misiones repetibles de reputación, como entregar tela, también son una forma de farmeo."] = "可重複的聲望任務，比如上交布料，也是一種刷法。",
	["Las monturas de los gnomos son mecazancudos, aves mecánicas que ellos mismos inventaron."] = "地精的坐騎是機械陸行鳥，那是他們自己發明的機械鳥。",
	["Las monturas de otra raza de tu bando pueden pedir reputación con su ciudad: la de tu raza siempre se puede."] = "你陣營中其他種族的坐騎可能需要其主城的聲望：你自己種族的坐騎隨時都能用。",
	["Las monturas de tu raza"] = "你種族的坐騎",
	["Las monturas épicas del Clásico cuestan bastante oro; juntarlo poco a poco es parte de la aventura."] = "經典版的史詩坐騎要花不少金幣；一點一點存錢也是冒險的一部分。",
	["Las notas del lobo están apagadas (Ajustes de La Jauría)."] = "狼的筆記已關閉（La Jauría 設定）。",
	["Las ondas al caminar o nadar en el agua."] = "在水中行走或游泳時的漣漪。",
	["Las orillas de la pantalla un poco más oscuras."] = "畫面邊緣稍微暗一些。",
	["Las pestañas toman la letra y los colores del estilo; la elegida lleva la línea de acento. En Clásico WoW quedan las del juego."] = "分頁會使用該風格的字型與顏色；選取的分頁帶有強調色線條。在經典 WoW 中保留遊戲原本的分頁。",
	["Las piedras de afilar y los contrapesos que haces le sirven a guerreros y pícaros: siempre tienen compradores."] = "你做的磨刀石和平衡石對戰士和盜賊很有用：永遠有人買。",
	["Las piedras de salud que creas le salvan la vida a todo tu grupo."] = "你製造的治療石能救全隊的命。",
	["Las placas de nombre de los enemigos."] = "敵人的名條。",
	["Las plantas de herboristería."] = "草藥學的植物。",
	["Las pociones de vida y maná siempre se venden: toda mazmorra las pide."] = "治療藥水和法力藥水永遠賣得出去：每個地城都需要。",
	["Las primeras misiones de un humano en Villanorte van de kóbolds, bandidos Defias... y lobos. No todos somos buenos, ¿eh?"] = "人類在北郡的第一批任務是對付地狗、迪菲亞強盜…還有狼。我們狼也不全是好狼，懂吧？",
	["Las profesiones de fabricación dan retos del Legado al llegar a 150, 225 y 300."] = "製造類專業達到 150、225 與 300 時會獲得傳承挑戰。",
	["Las profesiones de recolección dan oro desde el nivel 1. ¡Hierbas o minería!"] = "採集專業從 1 級起就能賺金幣。草藥學還是採礦！",
	["Las que Lya ya te dijo sus tres veces. Con «Volver a mostrarlos» salen otra vez."] = "Lya 已經各說滿三次的話。點「重新顯示它們」就會再次出現。",
	["Las que me faltan"] = "我缺少的",
	["Las que se hacen una sola vez."] = "只能完成一次的任務。",
