	["Las que ya hiciste no cuentan."] = "已完成的任務不計入。",
	["Las que ya no te dan casi nada y no abren otra que valga la pena. En la página Ruta, «Misiones grises»: cada una con su «Abandonar»."] = "幾乎沒什麼收益、也不會開啟值得做的後續任務的那些。在路線頁面的「灰色任務」中：每個都有「放棄」。",
	["Las que ya usaste y tardan en volver. Apaga las que no quieras ver en la barra."] = "你已經用過、需要較長時間冷卻的技能。關掉你不想在計時條上看到的。",
	["Las ranuras que tu tecla nunca cambia: cabeza, manos, pies, abalorios y las demás."] = "你的按鍵從不更換的欄位：頭部、手、腳、飾品等。",
	["Las recetas se compran a vendedores de comida y algunas caen de enemigos."] = "配方可以向食物商人購買，有些會從敵人身上掉落。",
	["Las ruinas de Eldarath fueron una ciudad élfica; hoy están llenas de naga."] = "艾達拉斯廢墟曾是一座精靈城市；如今滿是納迦。",
	["Las rutas y los planes que armas en la página Ruta de Alfa."] = "你在 Alfa 的「路線」頁面建立的路線與計畫。",
	["Las sacerdotisas de Elune guían a tu pueblo, y Tyrande lo gobierna desde el Templo de la Luna."] = "伊露恩的女祭司們引導著你的族人，泰蘭妲在月神殿統治他們。",
	["Las sesiones guardadas de este personaje."] = "此角色已儲存的遊戲記錄。",
	["Las sesiones, las zonas y los objetos de este personaje."] = "此角色的採集記錄、地區與物品。",
	["Las vendas suben de lino a lana, seda, tejido mágico y tela rúnica."] = "繃帶從亞麻布升級到毛料、絲綢、魔紋布和符文布。",
	["Las ventanas de chat, sus pestañas y la caja para escribir toman el estilo que elijas abajo y cambian con él. Al apagarlo vuelve el chat de siempre, sin /reload."] = "聊天視窗、分頁與輸入框會使用你在下方選擇的風格，並隨之變化。關閉後恢復原本的聊天，無需 /reload。",
	["Lavanda"] = "薰衣草色",
	["Le baja la armadura al enemigo y genera mucha amenaza. El golpe básico del tanque."] = "降低敵人護甲並產生大量仇恨。坦克的家常便飯。",
	["Le baja la armadura al enemigo y no lo deja volverse invisible."] = "降低敵人的護甲，並讓牠無法隱形。",
	["Le das mucho maná a un aliado. Dáselo a quien cura o úsalo en ti."] = "給一個盟友大量法力。給你的治療者，或對自己使用。",
