	["Lee el precio más bajo de cada objeto en toda la subasta. No compra ni publica nada. Se puede usar cada 15 minutos."] = "讀取整個拍賣場中每件物品的最低價格。不會購買或上架任何東西。每 15 分鐘可使用一次。",
