	["Lo pequeño que hace el juego más cómodo: el minimapa, el chat y las barras con el estilo de Alfa, marcos, cuadro de información, probador, cámara y sonidos; y en sus pestañas, viajes, invitaciones, comerciantes y más."] = "讓遊戲更舒適的小功能：Alfa 風格的小地圖、聊天和快捷列、框架、滑鼠提示、試衣間、鏡頭和聲音；在其分頁中還有旅行、邀請、商人等。",
	["Lo pequeño que hace el juego más cómodo: misiones, vuelos, minimapa, chat y barras con el estilo de Alfa, marcos, cuadro de información, probador, cámara y sonidos."] = "讓遊戲更舒適的小功能：任務、飛行、小地圖、使用 Alfa 風格的聊天與快捷列、框架、滑鼠提示、試衣間、鏡頭與音效。",
