	["Lo piden estas misiones"] = "需要它的任務",
	["Lo pones al empezar a pelear."] = "戰鬥開始時施放。",
	["Lo primero que puedes soltar: %s (%s)."] = "最先可以丟掉的：%s（%s）。",
	["Lo que Alfa acepta, rechaza o comparte sola. Mantén presionado Mayús para decidir tú en el momento."] = "Alfa 自動接受、拒絕或分享的內容。按住 Shift 可以當場由你決定。",
	["Lo que Lya nota"] = "莉婭注意到的事",
	["Lo que Lya sabe de aquí"] = "Lya 對這裡的了解",
	["Lo que buscas en la Enciclopedia"] = "你在百科中查詢的內容",
	["Lo que choca con Alfa y cómo arreglarlo"] = "什麼與 Alfa 衝突以及如何解決",
	["Lo que comparte alguien de tu grupo con Alfa llega a tus marcadores, con su nombre, y te avisa para seguirlo."] = "隊伍中有人用 Alfa 分享的內容會進入你的標記，附帶其名稱，並提醒你跟隨。",
	["Lo que conoce Alfa"] = "Alfa 已知的",
	["Lo que cuentan las misiones que vas tomando"] = "你接下的任務講述的故事",
	["Lo que da"] = "提供的東西",
	["Lo que dice el diario de monturas"] = "坐騎收藏中的說明",
	["Lo que el menú del juego no enseña, a tu gusto"] = "遊戲選單裡沒有的設定，隨你調整",
	["Lo que elegiste al configurarlo: aceptar y entregar misiones, vender lo gris, reparar, tomar vuelos... Lo cambias cuando quieras."] = "你設定時選的：接交任務、賣灰色物品、修理、搭飛行……隨時可改。",
	["Lo que encuentras en la manada"] = "在狼群中你會找到什麼",
	["Lo que este personaje lleva en las mazmorras: se guarda solo al vencer jefes y recoger botín."] = "此角色在地城中的進度：擊敗首領與拾取戰利品時自動儲存。",
	["Lo que falta para subir %s"] = "提升 %s 還缺的東西",
	["Lo que ganaste la última vez que jugaste con este personaje."] = "你上次用這個角色遊玩時的收穫。",
	["Lo que gastan tus hechizos"] = "你的法術消耗的材料",
	["Lo que hay dentro"] = "內含物品",
	["Lo que le sirve a otro lobo"] = "別的狼用得上的東西",
	["Lo que llevas"] = "隨身物品",
	["Lo que llevas pescado: %s."] = "你目前釣到的：%s。",
	["Lo que me sirve"] = "對我有用的",
	["Lo que menos vale: %s"] = "最不值錢的：%s",
	["Lo que más conviene ahora"] = "現在最划算的",
	["Lo que más rinde cerca de ti"] = "附近最划算的事",
	["Lo que más te pegó: %s (%s)."] = "打你最痛的：%s（%s）。",
	["Lo que más te pegó: %s, de %s (%s)."] = "打你最痛的：%s，來自 %s（%s）。",
	["Lo que no está a la vista no sale aquí."] = "畫面上看不到的東西不會出現在這裡。",
	["Lo que obtuviste en esta sesión"] = "本次獲得的東西",
	["Lo que pescaste"] = "你釣到的",
	["Lo que pide %s antes, en orden."] = "%s的前置條件，依順序。",
	["Lo que quieras contarle al desarrollador de Alfa."] = "任何你想告訴 Alfa 開發者的話。",
	["Lo que quieras; la marcas tú cuando la hagas."] = "隨你寫什麼；完成後由你自己勾選。",
	["Lo que revisé"] = "我檢查了什麼",
	["Lo que sabe de Alfa"] = "她知道的 Alfa",
	["Lo que sacas en %s: %s."] = "你在%s釣到的：%s。",
	["Lo que se pesca aquí"] = "這裡能釣到的",
	["Lo que se queda la subasta de cada venta. Suele ser 5 % en la de tu facción y 15 % en la neutral. Es un estimado."] = "拍賣場從每筆成交中抽取的部分。通常陣營拍賣場為 5%，中立拍賣場為 15%。這是估計值。",
	["Lo que sigue"] = "接下來",
	["Lo que sigue en tu build no está en tu árbol"] = "你配點接下來的部分不在你的天賦樹中",
	["Lo que sigue para tu nivel: %s."] = "適合你等級的下一個：%s。",
	["Lo que sigue pide este nivel: hasta entonces, la guía no te manda allá."] = "接下來的內容需要這個等級：在那之前，指南不會讓你過去。",
	["Lo que sugiere Alfa"] = "Alfa 的建議",
	["Lo que te falta para llegar a 300"] = "練到 300 還缺的東西",
	["Lo que te falta para una mazmorra, en un aviso. También con /alfa listo."] = "去地城還缺什麼，用提醒告訴你。也可以用 /alfa listo。",
	["Lo que te ha contado"] = "她告訴過你的話",
	["Lo que te ofrece Lya (su botón)"] = "莉婭的提議（她的按鈕）",
	["Lo que te pasa a ti: curación recibida, esquivas, recursos. Puede necesitar /reload la primera vez."] = "發生在你身上的：受到的治療、閃躲、資源。第一次可能需要 /reload。",
	["Lo que te piden"] = "要你做的事",
	["Lo que tenía ya está hecho, omitido o fuera de tu registro. Ármalo otra vez con las misiones que tienes ahora."] = "裡面的內容已完成、已略過或不在你的任務日誌中。用你現在的任務重新規劃。",
	["Lo que trajo la última versión de Alfa, contado corto."] = "Alfa 最新版本帶來了什麼，簡短說說。",
	["Lo que tu build necesita de tu equipo y dónde conseguirlo."] = "你的配點對裝備的需求，以及在哪裡取得。",
	["Lo que tu clase se pone antes de pelear está activo."] = "你的職業戰鬥前要上的增益已生效。",
	["Lo que tu profesión de recolección junta mejor."] = "你的採集專業最擅長採集的東西。",
	["Lo que vale"] = "價值",
	["Lo que ya tienes en el banco"] = "銀行裡已有的物品",
	["Lo recolectaste %d veces"] = "你採集過 %d 次",
	["Lo recolectaste 1 vez"] = "你採集過 1 次",
	["Lo revisa el desarrollador de Alfa. En ese canal nadie más ve tu mensaje. Si aún no estás en el Discord, entra con la invitación de arriba."] = "由 Alfa 的開發者查看。在那個頻道裡，其他人看不到你的訊息。如果你還沒加入 Discord，請用上方的邀請加入。",
	["Lo sigues"] = "正在跟隨",
	["Lo sigues: el rastreador te muestra la meta de ahora y la flecha va a cada lugar."] = "正在跟隨：追蹤器顯示目前目標，箭頭會帶你去每個地點。",
	["Lo siguiente"] = "接下來",
	["Lo siguiente para ti"] = "你接下來該做的",
	["Lo sueltan"] = "掉落來源",
	["Lo suma a tu lista de compras de Comercio, con lo que pide su receta."] = "把它加入交易的購物清單，包括配方需要的材料。",
	["Lo último que consultaste"] = "最近查詢的內容",
	["Lo último que te dije"] = "我最後說的話",
	["Lobo"] = "狼",
	["Lobos conectados"] = "線上狼群",
	["Logrado el %s"] = "達成於 %s",
	["Logrados"] = "已達成",
	["Logro de pesca: %s"] = "釣魚成就：%s",
	["Logros"] = "成就",
	["Logros de pesca"] = "釣魚成就",
	["Lord Kazzak, un demonio enorme, ronda las Tierras Devastadas; en el Clásico es un jefe de mundo para bandas."] = "巨大的惡魔卡札克領主在詛咒之地遊蕩；在經典版中他是需要團隊挑戰的世界首領。",
	["Lord Xavius, el consejero de Azshara, convenció a los Altonato de abrirle la puerta a Sargeras. Cuando murió, Sargeras lo trajo de vuelta como el primer sátiro."] = "艾薩拉的顧問薩維斯領主說服上層精靈為薩格拉斯打開大門。他死後，薩格拉斯讓他復活成了第一個薩特。",
	["Los Altonato eran la nobleza élfica que vivía para la magia del Pozo. Su reina, Azshara, era tan bella que su pueblo la adoraba."] = "上層精靈是為永恆之井的魔法而活的精靈貴族。他們的女王艾薩拉美得讓人民崇拜她。",
	["Los Amani pelearon contra los altos elfos durante miles de años. Su capital, Zul'Aman, está en los bosques cerca de Quel'Thalas."] = "阿曼尼與高等精靈交戰了數千年。他們的首都祖阿曼位於奎爾薩拉斯附近的森林中。",
	["Los Barbabronce ganaron la Guerra de los Tres Martillos, y por eso Forjaz es suya."] = "銅鬚氏族贏得了三錘之戰，所以鐵爐堡歸他們所有。",
	["Los Claros de Tirisfal guardan las ruinas de Lordaeron, el reino de Arthas. Bajo su antigua capital, los Renegados levantaron Entrañas."] = "提里斯法林地保存著洛丹倫——阿薩斯的王國——的廢墟。被遺忘者在其舊都地下建起了幽暗城。",
	["Los Defias usan cosechadores mecánicos que trabajan solos en los campos... y no les gustan las visitas."] = "迪菲亞使用會自己在田裡幹活的收割傀儡…而且它們不喜歡訪客。",
	["Los Furiarena de Zul'Farrak son trols del desierto, primos lejanos de los Lanza Negra."] = "祖爾法拉克的沙怒食人妖是沙漠食人妖，是暗矛的遠親。",
	["Los Gurubashi llamaron a Hakkar, el Desollador de Almas. Cuando vieron lo que hacía, las demás tribus se unieron para echarlo."] = "古拉巴什召喚了奪魂者哈卡。看到他的所作所為後，其他部族聯手把他趕了出去。",
	["Los Hierro Negro invocaron a Ragnaros sin querer al final de la Guerra de los Tres Martillos, y desde entonces son sus esclavos."] = "三錘之戰末期，黑鐵矮人意外召喚了拉格納羅斯，從此淪為他的奴隸。",
	["Los Hierro Negro también excavan en Uldaman, buscando lo mismo que los enanos de Forjaz."] = "黑鐵矮人也在奧達曼挖掘，尋找和鐵爐堡矮人相同的東西。",
	["Los Lanza Negra suelen terminar sus frases con un «mon». ¡Se pega, mon!"] = "暗矛部族說話常在句尾加個「mon」。會傳染的，mon！",
	["Los PNJ dejan de hablar al saludarte o al darte misiones. También calla las voces de error."] = "NPC 跟你打招呼或給你任務時不再說話。也會關閉錯誤語音。",
	["Los Perdidos del pantano son draenei que llegaron de Draenor y quedaron cambiados para siempre."] = "沼澤裡的失落者是從德拉諾來的德萊尼，他們永遠地改變了。",
	["Los Páramos de Poniente eran el granero de Ventormenta; hoy muchas de sus granjas están en manos de la Hermandad Defias."] = "西部荒野曾是暴風城的糧倉；如今那裡許多農場都落入了迪菲亞兄弟會手中。",
	["Los Renegados aguantan bajo el agua mucho más que los vivos. ¡No necesitan respirar tanto!"] = "被遺忘者在水下能待的時間比活人長得多。他們不太需要呼吸！",
	["Los Renegados entraron a la Horda gracias a los tauren, que esperaban encontrarles una cura. Muchos orcos aún no se fían de ellos."] = "被遺忘者能加入部落，多虧了牛頭人，他們希望能為被遺忘者找到解藥。許多獸人至今仍不信任他們。",
	["Los Renegados hicieron de Rémol, un viejo pueblo humano, su primera parada en Tirisfal."] = "被遺忘者把古老的人類城鎮布瑞爾當作他們在提里斯法林地的第一站。",
	["Los Renegados nuevos despiertan en Camposanto, en Tirisfal, como no-muertos libres del Rey Exánime."] = "新的被遺忘者在提里斯法林地的喪鐘鎮醒來，成為擺脫巫妖王控制的不死族。",
	["Los Renegados pueden comerse cadáveres para recuperar vida. Yo prefiero las salchichas, gracias."] = "被遺忘者可以吃屍體來恢復生命力。我還是比較喜歡香腸，謝謝。",
	["Los Renegados recuerdan quiénes fueron en vida, y eso pesa más que cualquier herida."] = "被遺忘者記得自己生前是誰，這比任何傷口都沉重。",
	["Los Renegados son no-muertos que recuperaron su voluntad cuando el poder del Rey Exánime se debilitó."] = "被遺忘者是在巫妖王力量減弱時重獲自由意志的不死族。",
	["Los Tótem Siniestro son tauren que no quieren a la Horda; su jefa Magatha vive en la misma Cima del Trueno."] = "恐怖圖騰是不喜歡部落的牛頭人；他們的首領瑪加薩就住在雷霆崖。",
	["Los ajustes de los recordatorios están en la búsqueda de la ventana de Alfa."] = "提醒的設定可以在 Alfa 視窗的搜尋中找到。",
	["Los altos elfos pelearon con la Alianza en la Segunda Guerra por una vieja deuda de sangre con el linaje de Thoradin."] = "第二次戰爭中，高等精靈因為對索拉丁血脈的一筆古老血債而與聯盟並肩作戰。",
	["Los altos elfos que sobrevivieron a la Plaga empezaron a llamarse elfos de sangre, en honor a los suyos caídos. Kael'thas los guía."] = "在天譴軍團中倖存的高等精靈開始自稱血精靈，以紀念他們陣亡的同胞。凱爾薩斯領導著他們。",
	["Los antídotos que haces curan venenos. ¡En las arañas de Vallefresno se agradecen!"] = "你做的抗毒藥劑能解毒。對付梣谷的蜘蛛時特別受歡迎！",
	["Los anuncios esperan a que el juego termine de escribir la zona, y el botón de Alfa queda siempre a la vista en el minimapa."] = "公告會等遊戲寫完區域名稱再出現，Alfa 的按鈕在小地圖上一直看得到。",
	["Los aqir eran un imperio antiguo de insectos que peleó contra los trols. De ellos vienen los qiraji de Ahn'Qiraj y los nerubianos del norte."] = "阿基爾是一個與食人妖交戰的古老蟲族帝國。安其拉的其拉蟲人和北方的蛛魔都源自他們。",
	["Los avisos"] = "提示",
	["Los avisos de viaje hablan como la manada: «La manada viaja», el lobo en el aro y una huellita que camina mientras llega tu barco."] = "旅行提醒像狼群一樣說話：「狼群出行」，環中的狼，還有船到來時一路前行的爪印。",
	["Los avisos pequeños de Alfa los dice Lya en su globo, con su botón, en vez de salir arriba. Si está oculta o en combate, salen como siempre."] = "Alfa 的小提醒由莉婭在氣泡裡說出，帶著按鈕，不再彈在上方。她隱藏或你在戰鬥中時，照常顯示。",
	["Los ayudantes de los enemigos."] = "敵人的幫手。",
	["Los botones de otros addons alrededor del minimapa solo aparecen al pasar el ratón por encima. El de Alfa siempre queda a la vista."] = "小地圖周圍其他插件的按鈕只在滑鼠移到上面時才出現。Alfa 的按鈕一直都看得到。",
	["Los cebos suben tu habilidad de pesca un rato: úsalos en aguas difíciles."] = "魚餌能暫時提高你的釣魚技能：在難釣的水域用上。",
	["Los cementerios del Ocaso están llenos de no-muertos levantados por nigromantes que se esconden en el bosque."] = "暮色森林的墓地裡滿是被藏身林中的死靈法師喚起的不死族。",
	["Los centauros dicen descender de Zaetar, hijo del semidiós Cenarius, y de Theradras, la princesa de la tierra. Pelean entre sus clanes casi tanto como contra los demás."] = "半人馬自稱是半神塞納留斯之子札爾塔與大地公主瑟萊德絲的後代。他們各部族之間的內鬥幾乎和對外作戰一樣多。",
	["Los cinco Aspectos Dragón recibieron su poder de los titanes: Alexstrasza la vida, Ysera el sueño, Nozdormu el tiempo, Malygos la magia y Neltharion la tierra."] = "五位守護巨龍的力量來自泰坦：雅立史卓莎掌管生命，伊瑟拉掌管夢境，諾茲多姆掌管時間，瑪里苟斯掌管魔法，奈薩里奧掌管大地。",
	["Los clanes Gelkis y Magram de Desolace pelean entre sí, y ambos buscan aliados entre los aventureros."] = "淒涼之地的吉爾吉斯與瑪格拉姆部族互相爭鬥，雙方都在冒險者中尋找盟友。",
	["Los clanes orcos tienen historias distintas: Lobo Gélido, Grito de Guerra, Roca Negra, Faucedraco... cada uno con su orgullo."] = "獸人各氏族的歷史各不相同：霜狼、戰歌、黑石、龍喉…每個都有自己的驕傲。",
	["Los cruzados escarlata vienen en grupos y algunos curan: interrumpan a los que curan."] = "血色十字軍成群出現，有些會治療：打斷會治療的。",
	["Los críticos hacen el doble de daño y al guerrero le dan más ira."] = "致命一擊造成雙倍傷害，還會讓戰士獲得更多怒氣。",
	["Los cuatro dragones verdes de la pesadilla, Ysondre, Lethon, Emeriss y Taerar, aparecen junto a los grandes árboles del Sueño."] = "夢魘中的四隻綠龍——伊索德雷、雷索、艾莫莉絲和泰拉爾——會出現在夢境之樹旁。",
	["Los cuatro señores elementales son Ragnaros del fuego, Al'Akir del aire, Therazane de la tierra y Neptulon del agua."] = "四大元素領主是火焰的拉格納羅斯、風的奧拉基爾、大地的瑟拉贊恩和水的奈普圖隆。",
	["Los cultistas del Martillo Crepuscular usan piedras de viento para invocar a sus señores; con su disfraz, tú también puedes."] = "暮光之錘的信徒用風之石召喚他們的領主；穿上他們的偽裝，你也可以。",
	["Los datos de Alfa no cargaron (%s)."] = "Alfa 的資料沒有載入（%s）。",
	["Los datos de Alfa no traen botín propio de sus jefes."] = "Alfa 的資料中沒有它的首領專屬戰利品。",
	["Los datos de las mazmorras no están cargados."] = "地城資料尚未載入。",
	["Los datos de las mazmorras se cargan fuera de combate. Esta página se llena sola al terminar la pelea."] = "地城資料會在脫離戰鬥後載入。戰鬥結束後此頁面會自動填滿。",
	["Los datos del mundo (Codex) no están disponibles: faltan los bancos, las misiones y de dónde sale cada cosa."] = "世界資料（Codex）無法使用：缺少魚群、任務以及各種東西的來源。",
	["Los datos del mundo de Alfa están apagados: activa «Alfa Codex» en la lista de addons."] = "Alfa 的世界資料已停用：請在插件清單中啟用「Alfa Codex」。",
	["Los datos son del medidor oficial del juego: tú, tu grupo o banda y sus mascotas."] = "資料來自遊戲官方的傷害統計：你、你的隊伍或團隊以及他們的寵物。",
	["Los dioses antiguos son seres de antes de los titanes, encerrados bajo la tierra de Azeroth. C'Thun y Yogg-Saron susurran a quien quiera escuchar."] = "古神是比泰坦更古老的存在，被囚禁在艾澤拉斯的地底。克蘇恩與尤格薩倫會向任何願意傾聽的人低語。",
	["Los dioses antiguos susurran en la mente de los mortales; muchos cultos, como el Martillo Crepuscular, nacieron de escucharlos."] = "古神在凡人的腦海中低語；許多邪教，比如暮光之錘，都是因為聽信了他們而誕生的。",
	["Los dos"] = "兩者",
	["Los dos bandos"] = "兩個陣營",
	["Los dracoleones son las monturas voladoras de la Horda; los grifos, las de la Alianza; y los hipogrifos, las de los elfos de la noche."] = "雙足飛龍是部落的飛行坐騎；獅鷲是聯盟的；角鷹獸則屬於夜精靈。",
	["Los dracónidos negros rondan la entrada de la guarida de Onyxia, al sur del marjal."] = "黑龍人在沼澤南部奧妮克希亞巢穴的入口處巡邏。",
	["Los dracónidos son los soldados de los dragones; los negros sirven a Nefarian en la Montaña Roca Negra."] = "龍人是巨龍的士兵；黑色的龍人在黑石山為奈法利安效力。",
	["Los draenei huyeron de su mundo, Argus, con el profeta Velen. Su nombre quiere decir «los exiliados»."] = "德萊尼跟隨先知維倫逃離了他們的世界阿古斯。他們的名字意為「流亡者」。",
	["Los dragones cromáticos, con escamas de todos los colores, son experimentos de Nefarian. Su obra más temida es Chromaggus."] = "鱗片五顏六色的多彩龍是奈法利安的實驗品。他最可怕的作品是克洛瑪古斯。",
	["Los dragones negros se disfrazan de humanos para engañar: Onyxia es Lady Katrana Prestor en Ventormenta, y Nefarian se hace llamar Lord Victor Nefarius."] = "黑龍會偽裝成人類來騙人：奧妮克希亞在暴風城是卡特拉娜·普瑞斯托女士，奈法利安則自稱維克多·奈法利斯領主。",
	["Los dragones verdes siguen vigilando el templo hundido para que nadie vuelva a llamar a Hakkar."] = "綠龍仍在看守沉沒的神廟，免得有人再次召喚哈卡。",
	["Los elementales de fuego de La Garganta de Fuego y del Cráter de Un'Goro sueltan materiales de fuego que piden muchas profesiones."] = "灼熱峽谷和安戈洛環形山的火元素會掉落許多專業都需要的火焰材料。",
	["Los elementales de fuego y las arañas de lava son los vecinos de siempre de La Garganta de Fuego."] = "火元素和熔岩蜘蛛是灼熱峽谷的老鄰居。",
	["Los elfos de la noche fueron inmortales gracias a Nordrassil, hasta que lo sacrificaron para vencer a Archimonde en el Monte Hyjal."] = "夜精靈曾因諾達希爾而永生，直到他們為了在海加爾山擊敗阿克蒙德而將它犧牲。",
	["Los elfos de la noche montan sables, grandes felinos. No es por nada, pero un lobo es más simpático."] = "夜精靈騎的是豹，一種大型貓科動物。不是我自誇，狼可親切多了。",
	["Los elfos de la noche nuevos empiezan en la Cañada Umbría, en Teldrassil, entre arañas y fuegos fatuos."] = "新的夜精靈從泰達希爾的幽影谷開始，身邊是蜘蛛和小精靈。",
	["Los elfos de la noche pueden fundirse con las sombras cuando se quedan quietos."] = "夜精靈站著不動時能融入陰影。",
	["Los elfos de la noche se unieron a la Alianza después de la Tercera Guerra."] = "夜精靈在第三次戰爭後加入了聯盟。",
	["Los enanos Hierro Negro tomaron Dun Modr, al norte de Los Humedales, y desde ahí molestan a quien cruce el puente."] = "黑鐵矮人佔領了濕地北部的丹莫德，在那裡騷擾所有過橋的人。",
	["Los enanos creen descender de los terráneos de piedra de los titanes, y por eso la Liga de Expedicionarios excava sin parar."] = "矮人相信自己是泰坦的岩石土靈的後裔，所以探險者協會不停地挖掘。",
	["Los enanos de Forjaz pelean contra los Hierro Negro en Los Humedales y en las Tierras Inhóspitas."] = "鐵爐堡的矮人在濕地和荒蕪之地與黑鐵矮人作戰。",
	["Los enanos nuevos empiezan en un valle helado de Dun Morogh, peleando contra trols de las nieves y troggs."] = "新的矮人從丹莫洛一座冰冷的山谷開始，對抗冰霜食人妖和穴居人。",
	["Los encantadores también hacen varitas: los magos, sacerdotes y brujos te lo agradecerán."] = "附魔師也能做魔杖：法師、牧師和術士都會感謝你。",
	["Los enemigos cercanos pegan menos. Muy útil cuando tanqueas a varios."] = "附近敵人的攻擊變弱。同時坦好幾隻時非常有用。",
	["Los enemigos de alrededor pegan menos."] = "周圍的敵人造成的傷害降低。",
	["Los enemigos de tus misiones marcados sobre su placa de nombre y los objetos de misión brillando en tus bolsas."] = "你任務中的敵人會在名條上標出，任務物品會在背包中發光。",
	["Los enemigos lanzan radiación y veneno: lleven pociones de vida."] = "敵人會施放輻射與毒素：記得帶治療藥水。",
	["Los enemigos más débiles, que el juego marca con un signo de menos."] = "最弱的敵人，遊戲會用減號標示牠們。",
	["Los errores de Alfa que se atraparon, para copiarlos en tu reporte."] = "捕捉到的 Alfa 錯誤，可複製到你的回報裡。",
	["Los espíritus de las elfas caídas que la Plaga esclaviza se vuelven banshees. Sylvanas es la más famosa de todas."] = "被天譴軍團奴役的陣亡精靈女性的靈魂會變成女妖。希瓦娜斯是其中最有名的一位。",
	["Los fragmentos de alma se ganan drenando el alma del enemigo justo cuando muere."] = "在敵人死亡的那一刻吸取它的靈魂，就能獲得靈魂碎片。",
	["Los frascos del Clásico duran dos horas y aguantan aunque mueras: por eso las bandas los piden tanto."] = "經典版的精煉藥劑能持續兩小時，死亡也不會消失：所以團隊這麼需要它們。",
	["Los frascos los venden los proveedores de alquimia. Herboristería es su mejor pareja: tú juntas las hierbas."] = "鍊金用品商人出售瓶子。草藥學是它最好的搭檔：草藥自己採。",
	["Los frascos más poderosos llevan Loto negro, la hierba más rara de Azeroth."] = "最強的精煉藥劑需要黑蓮花，這是艾澤拉斯最稀有的草藥。",
	["Los fuegos artificiales también son ingeniería. ¡Uno para festejar cada nivel!"] = "煙火也是工程學的一部分。每升一級就放一個慶祝吧！",
	["Los fuegos fatuos son espíritus de elfos de la noche que siguen cuidando el bosque después de morir."] = "小精靈是夜精靈的靈魂，死後仍繼續守護著森林。",
	["Los furbolgs Fauces de Madera son de los pocos que no se han corrompido; sus túneles llevan a Cuna del Invierno y al Claro de la Luna."] = "木喉熊怪是少數沒有被腐化的熊怪；牠們的隧道通往冬泉谷與月光林地。",
	["Los furbolgs de Costa Oscura se están corrompiendo, y los elfos de Auberdine no saben bien por qué."] = "黑海岸的熊怪正在被腐化，奧伯丁的精靈們也不太清楚原因。",
	["Los furbolgs eran un pueblo pacífico de hombres oso, pero la corrupción de los demonios enloqueció a muchas de sus tribus."] = "熊怪原本是愛好和平的熊人種族，但惡魔的腐化讓牠們許多部族都發了瘋。",
	["Los geomantes lanzan fuego y ponen tótems: interrúmpanlos y rompan los tótems."] = "地卜師會施放火焰並放置圖騰：打斷他們並打掉圖騰。",
	["Los gnomos empiezan con los enanos en Dun Morogh: Gnomeregan está perdida y tu gente vive refugiada en Forjaz."] = "地精和矮人一起從丹莫洛開始：諾姆瑞根已經失守，你的族人在鐵爐堡避難。",
	["Los gnomos inventaron el Tranvía Subterráneo que une Forjaz con Ventormenta."] = "地精建造了連接鐵爐堡和暴風城的礦道地鐵。",
	["Los gnomos que se quedaron en Gnomeregan quedaron dañados por la radiación; algunos perdieron la razón."] = "留在諾姆瑞根的地精受到了輻射傷害；有些人失去了理智。",
	["Los goblins de la fundición tienen ayudantes cerca: miren alrededor antes de atacar."] = "鑄造廠的地精附近有幫手：攻擊前先看看四周。",
	["Los goblins vienen de la isla de Kezan, y su gran ciudad es Minahonda. Le son más leales al oro que a cualquier bando."] = "哥布林來自克贊島，他們的大城市是安德麥。比起任何陣營，他們更忠於金幣。",
	["Los grandes árboles que hablan en Darnassus y Vallefresno son Ancestros, guardianes del bosque."] = "達納蘇斯和梣谷那些會說話的大樹是古樹，森林的守護者。",
	["Los grifos (o dragones) a los lados de la barra principal."] = "主快捷列兩側的獅鷲（或雙足飛龍）。",
	["Los grifos (o dragones) a los lados de la barra principal. «Del color del estilo» necesita el estilo de las barras; «Ocultos» funciona siempre."] = "主快捷列兩側的獅鷲（或雙足飛龍）。「風格顏色」需要開啟快捷列風格；「隱藏」始終有效。",
	["Los gules, las abominaciones y las gárgolas son los soldados más comunes de la Plaga. Las abominaciones se cosen con partes de muchos cadáveres."] = "食屍鬼、憎惡和石像鬼是天譴軍團最常見的士兵。憎惡是用許多屍體的部位縫起來的。",
	["Los herreros hacen llaves que abren cofres y cajas cerradas. ¡Útil y divertido!"] = "鐵匠能打造鑰匙，打開寶箱和上鎖的箱子。又實用又好玩！",
	["Los humanos fueron los primeros en aprender magia de los altos elfos, allá en las Guerras Trol."] = "早在食人妖戰爭時期，人類就是第一個向高等精靈學習魔法的種族。",
	["Los infernales son demonios que la Legión arroja desde el cielo como meteoritos."] = "地獄火是燃燒軍團像隕石一樣從天上扔下來的惡魔。",
	["Los ingenieros pueden fabricar mascotas mecánicas, como una ardilla."] = "工程師可以製造機械寵物，比如一隻松鼠。",
	["Los instructores y vendedores de pesca se ven en el mapa y el minimapa."] = "釣魚訓練師與商人會顯示在地圖與小地圖上。",
	["Los jefes opcionales y raros se descubren al terminar la mazmorra."] = "選擇性首領與稀有首領會在完成地城後揭曉。",
	["Los jefes se descubren al vencerlos: su nombre y su botín quedan ocultos hasta entonces. Sus consejos siempre se pueden ver."] = "首領要擊敗後才會揭曉：在那之前其名稱與戰利品都會隱藏。提示則隨時都能查看。",
	["Los kits de armadura que haces le sirven a todo el mundo: siempre hay quien los compre."] = "你做的護甲片對每個人都有用：總有人會買。",
	["Los kodos son los compañeros de viaje de los tauren, y en Desolace está su cementerio."] = "科多獸是牛頭人的旅伴，牠們的墳場在淒涼之地。",
	["Los kóbolds de las minas de Elwynn cuidan sus velas como un tesoro: bajo tierra, la luz lo es todo."] = "艾爾文森林礦坑裡的地狗把蠟燭當寶貝一樣守護：在地底下，光就是一切。",
	["Los lobos aprenden Aullido furioso, que sube el daño de tu grupo. ¡Ya ves, los lobos somos lo máximo!"] = "狼會學會狂怒之嚎，能提升你隊伍的傷害。看吧，我們狼是最棒的！",
	["Los lobos de tu zona saben dónde estás. Te aviso quién viene."] = "區域裡的狼知道你在哪。我會告訴你誰來了。",
	["Los lobos que se dejan ver en el mapa. Un clic en su marca y la flecha te lleva."] = "允許在地圖上被看到的狼。點擊牠們的標記，箭頭就會帶你過去。",
	["Los lobos que usan Alfa y se dejan ver en el mapa, y tu grupo, que ves ahora."] = "使用 Alfa 並允許在地圖上被看到的狼，以及你現在看到的隊伍成員。",
	["Los logros de la manada: se ganan pescando, cocinando lo que pescas y explorando aguas nuevas. Cada uno se anuncia una sola vez."] = "狼群的成就：透過釣魚、烹飪釣到的魚與探索新水域來獲得。每個成就只宣布一次。",
	["Los lugares que pides ver en el mapa desde la Enciclopedia."] = "你從百科中要求在地圖上顯示的地點。",
	["Los maestros de vuelo de tu facción y los neutrales: verdes si ya los conoces, ámbar con «?» si te falta descubrirlos. Clic: seguirlo con la flecha."] = "你陣營與中立的飛行管理員：已知的顯示為綠色，尚未發現的顯示為琥珀色並帶「?」。點擊：用箭頭跟隨它。",
	["Los maestros de vuelo de tu zona que todavía no conoces, resaltados. Clic: la flecha te lleva."] = "你所在區域裡還不認識的飛行管理員，會被醒目標示。點擊：箭頭帶你去。",
	["Los magos de Dalaran forman el Kirin Tor, su consejo de sabios."] = "達拉然的法師組成了他們的賢者議會祈倫托。",
	["Los marcos de Curación están apagados"] = "治療框架已關閉",
	["Los marcos se mueven fuera de combate."] = "框架只能在戰鬥外移動。",
	["Los marcos, fondos, botones y letras del propio juego, con títulos en oro."] = "遊戲內建的框架、背景、按鈕與字型，標題為金色。",
	["Los mismos marcadores de misiones en el minimapa."] = "在小地圖上顯示相同的任務標記。",
	["Los múrlocs hablan con gorgoteos y burbujas: ese «mrglglgl» es su idioma de verdad."] = "魚人用咕嚕聲和泡泡說話：那句「mrglglgl」就是牠們真正的語言。",
	["Los nagas y sátiros lanzan escarcha y rayos: interrumpan a los lanzadores primero."] = "納迦和薩特會施放冰霜與閃電：先打斷施法者。",
	["Los nerubianos, arañas gigantes de Rasganorte, pelearon contra el Rey Exánime y perdieron; muchos hoy le sirven."] = "北裂境的巨型蜘蛛蛛魔曾與巫妖王作戰並落敗；如今許多蛛魔為他效力。",
	["Los no-muertos de la Plaga no sienten miedo ni cansancio, y por eso es tan difícil detenerlos."] = "天譴軍團的不死族不知恐懼也不知疲倦，所以才這麼難以阻擋。",
	["Los nodos de la zona que miras, con su nombre, nivel y cuántas veces los recolectaste al pasar el ratón. Clic en uno: la flecha te lleva."] = "你正在查看的地區中的採集點；滑鼠移到上面可查看名稱、等級與你採集過的次數。點擊一個：箭頭會帶你過去。",
	["Los nodos que se pisarían en pantalla van en un solo pin con su cantidad. Al acercar el mapa se separan."] = "在畫面上會重疊的採集點會合併成一個標記並顯示數量。放大地圖時就會分開。",
	["Los nodos que tienes cerca. El punto del rastreo del juego dice si ahora hay algo ahí."] = "你附近的採集點。遊戲的追蹤點會告訴你現在那裡有沒有東西。",
	["Los nodos que trae Alfa. Sin esto solo ves los que tú descubriste."] = "Alfa 內建的採集點。關閉時只會看到你自己發現的。",
	["Los números de las habilidades de tu mascota."] = "你寵物技能的傷害數字。",
	["Los números de lo que curas encima de quien recibe."] = "你的治療數字，顯示在受治療者上方。",
	["Los números de los golpes de tu mascota."] = "你寵物近戰攻擊的傷害數字。",
	["Los números de tu daño encima de quien golpeas."] = "你的傷害數字，顯示在被你攻擊的目標上方。",
	["Los números son orientativos: cada receta da puntos según su color (naranja siempre, amarillo casi siempre, verde a veces)."] = "數字僅供參考：每個配方依顏色給點數（橘色必定漲、黃色幾乎都漲、綠色有時漲）。",
	["Los oasis de Los Baldíos se están secando y llenando de bestias raras: los Druidas del Colmillo, que salieron de las Cuevas de los Lamentos, los corrompen."] = "貧瘠之地的綠洲正在乾涸，到處是怪異的野獸：從哀嚎洞穴出來的尖牙德魯伊正在腐化牠們。",
	["Los objetos se juntan al final de tus bolsas en lugar de al principio."] = "物品會集中在背包的最後面，而不是最前面。",
	["Los orcos Faucedraco siguen en Los Humedales, aunque ya sin la Reina Dragón."] = "龍喉獸人還在濕地，雖然已經失去了巨龍女王。",
	["Los orcos Roca Negra de Rend se adueñaron de la cumbre de la montaña y la llaman su hogar."] = "雷德的黑石獸人佔據了山頂，把那裡當成自己的家。",
	["Los orcos Roca Negra ocupan una vieja fortaleza humana al este de las montañas."] = "黑石獸人佔據著山脈東邊一座古老的人類要塞。",
	["Los orcos llegaron de Draenor corrompidos por la sangre de Mannoroth. Thrall los sacó de los campos de internamiento y fundó la nueva Horda."] = "獸人從德拉諾來到這裡時，已被瑪諾洛斯之血腐化。索爾把他們從收容所中解救出來，建立了新部落。",
	["Los orcos nuevos empiezan en el Valle de los Retos, en Durotar, donde prueban su valor."] = "新的獸人從杜洛塔的試煉谷開始，在那裡證明自己的勇氣。",
	["Los orcos vienen de Draenor, un mundo que hoy está roto y se llama Terrallende."] = "獸人來自德拉諾，那個世界如今已經破碎，被稱為外域。",
	["Los otros %d puntos del plan llegan con tus próximos niveles."] = "規劃中其他 %d 點會在你接下來升級時取得。",
	["Los peleteros hacen carcajes y bolsas de munición para los cazadores."] = "製皮師會為獵人製作箭袋和彈藥袋。",
	["Los polvos y las esencias salen de desencantar equipo verde o mejor. Cada tanto tu instructor te pide una varilla rúnica nueva."] = "塵和精華來自分解綠色或更好的裝備。訓練師不時會要你做一根新的符文棒。",
	["Los portales a pie que puedes usar, con a dónde llevan."] = "你可以步行進入的傳送門，以及它們通往哪裡。",
	["Los precios cambian: después de estos días Alfa te recuerda escanear otra vez."] = "價格會變動：超過這些天數後，Alfa 會提醒你重新掃描。",
	["Los primeros caballeros de la muerte los creó Gul'dan: cuerpos de caballeros humanos caídos con almas de brujos orcos."] = "第一批死亡騎士是古爾丹創造的：陣亡人類騎士的軀體，裝著獸人術士的靈魂。",
	["Los puntos de ruta que ponen otros addons, y el comando /way, apuntan la flecha de Alfa. Un addon que espere los ajustes de otro addon de puntos de ruta puede no funcionar con esto encendido."] = "其他插件設定的路徑點以及 /way 指令會由 Alfa 的箭頭指引。開啟後，需要其他路徑點插件自身設定的插件可能無法正常運作。",
	["Los puntos de vuelo y de viaje ya se ven en el mapa."] = "飛行點與旅行地點現在會顯示在地圖上。",
	["Los puntos que ganas en la cuenta también llenan el registro del Legado: premios de aspecto, sin ventaja en el juego. Al salir Forever son un rifle de réplica de Forjaz (juguete), la cría de oso espectral (mascota), el tabardo del oso espectral y las riendas del oso espectral (montura)."] = "你在帳號上獲得的點數也會填充傳承獎勵進度：外觀獎勵，不影響遊戲平衡。Forever 推出時的獎勵有鐵爐堡氣槍複製品（玩具）、幽靈熊寶寶（寵物）、幽靈熊外袍與幽靈熊韁繩（坐騎）。",
	["Los puntos que ganas también llenan el registro del Legado, con premios de aspecto como la cría de oso espectral."] = "你獲得的點數也會填充傳承獎勵進度，獎勵有幽靈熊寶寶之類的外觀物品。",
	["Los raros están apagados (página Descubrir)."] = "稀有怪已關閉（「探索」頁面）。",
	["Los raros que cayeron hace poco"] = "最近被擊殺的稀有怪",
	["Los raros también en el minimapa."] = "也在小地圖上顯示稀有怪。",
	["Los recolectaste %d veces en total"] = "你總共採集過 %d 次",
	["Los rincones de tu zona que todavía no pisas, con la experiencia que da descubrirlos."] = "你區域裡還沒去過的角落，以及探索它們能獲得的經驗。",
	["Los sacerdotes Atal'ai siguieron adorando a Hakkar en secreto. Los desterraron, y levantaron su templo en el Pantano de las Penas."] = "阿塔萊祭司秘密地繼續崇拜哈卡。他們被流放後，在悲傷沼澤建起了神廟。",
	["Los servicios también en el minimapa."] = "也在小地圖上顯示服務。",
	["Los señores del terror, como Mal'Ganis, Balnazzar y Varimathras, eran los carceleros que la Legión le puso al Rey Exánime."] = "恐懼魔王，比如瑪爾加尼斯、巴納札爾和瓦里瑪薩斯，是燃燒軍團派來看守巫妖王的獄卒。",
	["Los señores elementales servían a los dioses antiguos. Cuando los titanes encerraron a esos dioses, desterraron a los elementales a sus propios planos."] = "元素領主曾效忠於古神。泰坦囚禁了那些神之後，把元素放逐到了牠們自己的位面。",
	["Los spots de farmeo están apagados (Ajustes de La Jauría)."] = "刷點已關閉（La Jauría 設定）。",
	["Los sumos sacerdotes de Zul'Gurub tomaron el poder de los loa animales: el murciélago, la serpiente, la araña, la pantera y el tigre."] = "祖爾格拉布的高階祭司奪取了動物洛阿的力量：蝙蝠、蛇、蜘蛛、豹和虎。",
	["Los sátiros de Azshara sueltan tela vil, muy buscada por los sastres."] = "艾薩拉的薩特會掉落惡魔布，裁縫們非常搶手。",
	["Los talentos confirmados no se quitan gratis: revisa la lista antes de aceptar."] = "確認後的天賦無法免費重置：接受前請先檢查清單。",
	["Los talentos que siguen en el plan no están en tu árbol o no se pueden tomar todavía. Ponlos a mano en la ventana de talentos del juego o elige otro build."] = "配點中接下來的天賦不在你的天賦樹中，或暫時無法點。請在遊戲的天賦視窗中手動點，或選擇其他配點。",
	["Los tauren Tótem Siniestro tienen campamentos en Las Mil Agujas, y no son nada amigables."] = "恐怖圖騰牛頭人在千針石林有營地，一點也不友善。",
	["Los tauren ayudaron a los Renegados a entrar a la Horda, con la esperanza de encontrarles una cura."] = "牛頭人幫助被遺忘者加入了部落，希望能為他們找到解藥。",
	["Los tauren de Viento Libre viven en lo alto de Las Mil Agujas, a salvo de los centauros."] = "亂風崗的牛頭人住在千針石林的高處，遠離半人馬。",
	["Los tauren de Viento Libre viven en lo alto de las agujas, unidas por puentes colgantes, a salvo de los centauros de abajo."] = "亂風崗的牛頭人住在石針頂上，彼此之間以吊橋相連，遠離下方的半人馬。",
	["Los tauren honran a la Madre Tierra. Dicen que el sol y la luna son sus ojos: An'she y Mu'sha."] = "牛頭人崇敬大地之母。他們說太陽和月亮是她的眼睛：安舍與穆莎。",
	["Los tauren llaman An'she al sol y Mu'sha a la luna: los ojos de la Madre Tierra."] = "牛頭人把太陽叫做安舍，把月亮叫做穆莎：它們是大地之母的眼睛。",
	["Los tauren nuevos empiezan en el Campamento Narache, en Mulgore."] = "新的牛頭人從莫高雷的納拉其營地開始。",
	["Los tauren vivían como nómadas, acosados por los centauros, hasta que Cairne Pezuña de Sangre se alió con Thrall. Con la ayuda de la Horda encontraron su hogar en Mulgore."] = "牛頭人曾過著游牧生活，飽受半人馬侵擾，直到凱恩·血蹄與索爾結盟。在部落的幫助下，他們在莫高雷找到了家園。",
	["Los tesoros también en el minimapa."] = "也在小地圖上顯示寶藏。",
	["Los titanes dejaron guardianes de piedra y metal en Azeroth. En Uldaman todavía hay uno despierto: Archaedas."] = "泰坦在艾澤拉斯留下了岩石與金屬的守護者。奧達曼裡還有一位醒著：阿紮達斯。",
	["Los titanes le dieron forma a Azeroth y dejaron guardianes y ciudades, como Uldaman, para cuidar su obra."] = "泰坦塑造了艾澤拉斯，並留下守護者和像奧達曼這樣的城市來照看他們的作品。",
	["Los titanes son seres colosales que recorren el cosmos poniendo orden en los mundos. Los más famosos forman el Panteón, que guiaba Aman'Thul."] = "泰坦是在宇宙中巡遊、為各個世界帶來秩序的巨大存在。最有名的泰坦組成了萬神殿，曾由阿曼蘇爾領導。",
	["Los titanes usaron este cráter como un jardín de pruebas para la vida; por eso hay dinosaurios y plantas gigantes."] = "泰坦把這個火山口當作生命的試驗花園；所以這裡有恐龍和巨大的植物。",
	["Los troggs huyen cuando tienen poca vida y traen amigos: deténganlos antes de que escapen."] = "穴居人生命值低時會逃跑並找來同伴：在他們逃走前攔住他們。",
	["Los troggs invadieron Gnomeregan, y los gnomos inundaron su propia ciudad de radiación al intentar sacarlos. Fue idea del mekigeniero Termochufe."] = "穴居人入侵了諾姆瑞根，地精們為了把他們趕出去，反而讓自己的城市充滿了輻射。這是機械大師瑟瑪普拉格的主意。",
	["Los troggs salieron de las profundidades de Uldaman. Todo indica que son una creación antigua de los titanes que salió mal."] = "穴居人是從奧達曼的深處出來的。種種跡象表明，他們是泰坦一項失敗的古老造物。",
	["Los trols Lanza Negra conocieron a Thrall en las islas donde naufragó su flota rumbo a Kalimdor. Su líder Sen'jin murió ahí, y desde entonces los guía su hijo Vol'jin."] = "暗矛食人妖是在索爾前往卡林多途中艦隊失事的島上遇見他的。他們的首領森金死在那裡，此後一直由他的兒子沃金領導他們。",
	["Los trols Lanza Negra empiezan con los orcos, en el Valle de los Retos de Durotar."] = "暗矛食人妖和獸人一起，從杜洛塔的試煉谷開始。",
	["Los trols adoran a espíritus llamados loa. Hakkar es uno de ellos, y de los más peligrosos."] = "食人妖崇拜一種叫做洛阿的神靈。哈卡就是其中之一，也是最危險的之一。",
	["Los trols de estas tierras descienden de los Amani, el antiguo imperio de los trols del bosque. En Jintha'Alor siguen levantando sus altares."] = "這片土地上的食人妖是阿曼尼的後裔，那是森林食人妖的古老帝國。他們仍在辛薩羅建造祭壇。",
	["Los vendedores de suministros de pesca tienen cañas, lombrices y baratijas."] = "釣魚用品商人販售魚竿、蚯蚓與閃亮的小玩意。",
	["Los worgen son hombres lobo de origen misterioso. Arugal los trajo a Lordaeron. ¡No me confundas con ellos, eh!"] = "狼人是來歷神秘的人狼。是阿魯高把他們帶到了洛丹倫。可別把我跟他們搞混了！",
	["Los zepelines salen de las torres junto a Orgrimmar hacia Entrañas y hacia Grom'gol, en la Vega de Tuercespina."] = "飛艇從奧格瑪旁邊的塔樓出發，開往幽暗城和荊棘谷的格羅姆高。",
	["Los árboles del Legado son tres: Profesiones, Aventura y Recursos. Al salir Forever, cada personaje gasta hasta 16 puntos."] = "傳承天賦樹共有三棵：專業、冒險和足智多謀。Forever 推出時，每個角色最多可花費 16 點。",
	["Los élites y los raros de tu zona que te pueden ganar: en rojo los que te pasan por mucho. Se arman al abrir el mapa de Alfa."] = "你區域裡能打敗你的精英和稀有怪：遠高於你等級的以紅色顯示。開啟 Alfa 地圖時產生。",
	["Los íconos, los nombres y tu flecha se mueven pegados al mapa al hacer zoom o arrastrar: ya no brincan un píxel."] = "縮放或拖曳時，圖示、名稱和你的箭頭緊貼地圖移動：不再跳動一個像素。",
	["Los últimos Altonato de Kalimdor siguen en La Masacre: se llaman Shen'dralar y cuidan su vieja biblioteca."] = "卡林多最後的上層精靈仍留在厄運之槌：他們叫辛德拉，守護著他們古老的圖書館。",
	["Los últimos puntos."] = "最後的點數。",
	["Lothar cayó ante Orgrim Martillo Maldito al pie de la Montaña Roca Negra. Turalyon tomó su lugar y ganó la Segunda Guerra."] = "洛薩在黑石山腳下敗給了奧格林·毀滅之錘。圖拉楊接替了他，贏得了第二次戰爭。",
	["Luego cópialo con Ctrl+C."] = "然後按 Ctrl+C 複製。",
	["Lugar"] = "位置",
	["Lugar conocido: el punto del rastreo del juego dice si ahora hay algo."] = "已知位置：遊戲的追蹤點會告訴你現在有沒有東西。",
	["Lugar de los marcos"] = "框架位置",
	["Lugar desconocido"] = "未知地點",
	["Lugar: %s"] = "地點：%s",
	["Luna"] = "月光",
	["Lunes"] = "星期一",
	["Luz y efectos"] = "光照與特效",
	["Lya"] = "Lya",
	["Lya ahora es una loba negra de cuerpo completo, con 39 cuadros de animación: se sienta, corre, se busca la cola, bosteza y duerme enroscada."] = "Lya 現在是一匹全身的黑色母狼，有 39 格動畫：她會坐下、奔跑、追自己的尾巴、打哈欠，還會蜷成一團睡覺。",
	["Lya aprende"] = "莉婭在學習",
	["Lya apunta aquí tus pasos grandes: tu primera mazmorra, tus niveles, tu primera montura y más."] = "莉婭在這裡記下你的重要時刻：第一個地城、你的等級、第一隻坐騎等等。",
	["Lya apunta tus pasos grandes (tu primera mazmorra, tus niveles, tu primera montura...) y festeja cada página nueva."] = "莉婭記下你的重要時刻（第一個地城、你的等級、第一隻坐騎……），並慶祝每一頁新篇章。",
	["Lya contigo"] = "莉婭陪著你",
	["Lya cuenta historias"] = "Lya 說故事",
	["Lya de cuerpo completo"] = "全身的 Lya",
	["Lya descansa. La llamas con /alfa lya o /alfa ayuda cuando quieras."] = "莉婭休息了。想找她就用 /alfa lya 或 /alfa ayuda。",
	["Lya en las mazmorras"] = "地城裡的莉婭",
	["Lya en las mazmorras, con ánimo, su salchicha y su despedida; y te enseña Alfa en 5 pasos."] = "莉婭進地城、有情緒、要香腸、會道別；還會用 5 步帶你認識 Alfa。",
	["Lya en tu pantalla"] = "畫面上的 Lya",
	["Lya encontró un tesoro"] = "莉婭找到了寶藏",
	["Lya es quien olfatea los raros y los tesoros: su tarjeta trae «Ir de caza», «Su ficha» y «Seleccionarlo»."] = "稀有怪和寶藏由莉婭嗅出：她的卡片有「去狩獵」、「它的資料」和「選取它」。",
	["Lya está calladita"] = "Lya 安靜下來了",
	["Lya está descansando"] = "Lya 正在休息",
	["Lya festeja cuando un lobo de tu hermandad llega al nivel 60, consigue su primera montura o caza un raro."] = "當公會裡的狼升到 60 級、拿到第一匹坐騎或獵到稀有怪時，莉婭會一起慶祝。",
	["Lya fue una gran perrita: noble, leal y siempre al lado de los suyos, la gordita consentida de la casa. Alfa la recuerda así, como la loba que cuida a la manada y nunca deja a nadie atrás."] = "Lya 是一隻很棒的小狗：高貴、忠誠，總是陪在家人身邊，是家裡被寵壞的小胖妞。Alfa 就這樣記住她，把她當作守護狼群、從不丟下任何人的母狼。",
	["Lya guarda la historia de cada misión que tomas, aunque la aceptes sin leerla. Tú sigue la flecha: ella se acuerda de todo."] = "Lya 會保存你接下的每個任務的故事，即使你沒讀就接受了。你只管跟著箭頭走：她什麼都記得。",
	["Lya lleva tu historia, aprende qué consejos ya no quieres y te avisa de tus oficios."] = "莉婭記錄你的故事，學會你不想再聽的建議，並提醒你的專業。",
	["Lya olfateó un raro"] = "莉婭嗅到了稀有怪",
	["Lya platica mucho más: lore de Warcraft, datos de cada zona, de tu raza, tu clase y tus profesiones, y consejos de eventos y de farmeo. ¡Y le encantan las salchichas!"] = "Lya 的話多了很多：魔獸世界的背景故事、每個地區的趣聞，你的種族、職業和專業，還有節日和刷怪的建議。而且她超愛香腸！",
	["Lya platica según la hora del día, las fiestas de Azeroth y la zona donde andas."] = "莉婭會聊聊一天中的時刻、艾澤拉斯的節慶，以及你所在的區域。",
	["Lya recuerda lo que te dijo, tiene una tecla para su botón y te cuenta tu semana de caza y tu mejor día."] = "莉婭記得對你說過的話，她的按鈕有專屬按鍵，還會告訴你本週狩獵和最佳一天。",
	["Lya saluda a tu mascota y, si eres cazador, te avisa cuando tiene hambre o está triste."] = "莉婭會跟你的寵物打招呼；如果你是獵人，牠餓了或不開心時她會告訴你。",
	["Lya se fue a descansar. Vuelve con /alfa lya."] = "Lya 去休息了。用 /alfa lya 叫她回來。",
	["Lya se queda calladita una hora. Aquí sigue, cuidándote."] = "Lya 安靜一小時。她還在這裡守著你。",
	["Lya se queda en tu pantalla: consejos cortos, historias y atajos a todo Alfa."] = "莉婭留在你的螢幕上：簡短建議、故事和通往 Alfa 一切的捷徑。",
	["Lya te acompaña"] = "Lya 陪著你",
	["Lya te cuenta"] = "莉婭跟你說",
	["Lya te cuenta cuánto tardaron, cuántas veces caíste y lo mejor que sacaste."] = "莉婭告訴你花了多久、倒下幾次，以及你拿到最好的東西。",
	["Lya te dice los avisos"] = "莉婭說出提醒",
	["Lya te enseña la ventana de Alfa en 5 pasos"] = "莉婭用 5 步帶你認識 Alfa 視窗",
	["Lya te enseña la ventana de Alfa en 5 pasos. También con /alfa recorrido."] = "莉婭用 5 步帶你認識 Alfa 視窗。也可以用 /alfa recorrido。",
	["Lya te enseña tu clase"] = "莉婭教你職業",
	["Lya te enseña tu clase y te ayuda al morir; respaldos, diagnóstico y Alfa más ligero."] = "莉婭教你職業、在你死亡時幫忙；備份、診斷和更輕量的 Alfa。",
	["Lya te espera"] = "Lya 在等你",
	["Lya te guía, un asistente más sencillo y las guaridas"] = "莉婭帶路、更簡單的設定和巢穴",
	["Lya te lo dice todo"] = "莉婭都告訴你",
	["Lya tiene mucho que contar"] = "Lya 有很多話要說",
	["Lya volvió. Dale clic cuando quieras un consejo."] = "Lya 回來了。想聽建議時就點她。",
	["Lya vuelve a contarte sus consejos desde el principio."] = "Lya 會從頭再跟你說一遍她的建議。",
	["Lya vuelve a decirte todos esos consejos."] = "莉婭會再次告訴你所有這些建議。",
	["Lya vuelve a decirte todos los consejos que callaste."] = "莉婭會再次告訴你所有已關閉的建議。",
	["Lya vuelve a hablar."] = "Lya 又開口說話了。",
	["Lya y su manada"] = "莉婭和她的狼群",
	["Lya y tu mascota"] = "莉婭和你的寵物",
	["Lya, la loba de confianza del Alfa"] = "Lya，Alfa 最信任的母狼",
	["Lya, la loba negra que te acompaña, está en memoria de la perrita de Toxic. Te platica de cada zona, te da consejos y, claro, le encantan las salchichas."] = "莉婭是陪在你身邊的黑色母狼，為紀念 Toxic 的小狗而生。她會跟你聊每個區域，給你建議，當然，她超愛香腸。",
	["Lya, la manada y tus récords"] = "莉婭、狼群和你的紀錄",
	["Lya, tu guía, la flecha, los avisos, la pesca y los marcos de Combate y Curación: los arrastras a donde quieras. También con /alfa acomodar."] = "Lya、你的指南、箭頭、提示、釣魚以及戰鬥和治療框架：想放哪裡就拖到哪裡。也可以用 /alfa acomodar。",
	["Lánzalo antes de la siguiente pelea."] = "在下一場戰鬥前施放它。",
	["Lánzalo antes de pelear."] = "戰鬥前施放。",
	["Línea de la ruta"] = "路線線條",
	["Línea de tiempo apagada"] = "時間軸已關閉",
	["Línea de tiempo del jefe"] = "首領時間軸",
	["Línea de tiempo prendida"] = "時間軸已開啟",
	["Maestro"] = "大師",
	["Maestro de armas"] = "武器大師",
	["Maestro de batalla"] = "戰場軍官",
	["Maestro de establos"] = "獸欄管理員",
	["Maestro de vuelo"] = "飛行管理員",
	["Maestro del agua"] = "水域大師",
	["Maestros de armas"] = "武器大師",
	["Maestros de batalla"] = "戰場軍官",
	["Maestros de establos"] = "獸欄管理員",
	["Maestros de vuelo"] = "飛行管理員",
	["Maestría elemental: tu siguiente hechizo es crítico y gratis."] = "元素精通：你的下一個法術必定致命一擊且免費。",
	["Maestría nueva: %s (%d)"] = "新的精通：%s（%d）",
	["Magia"] = "魔法",
	["Mago"] = "法師",
	["Maiev Cantosombrío fue la carcelera de Illidan durante diez mil años, al frente de las Vigilantes."] = "瑪翼夫·影歌率領看守者，做了伊利丹一萬年的獄卒。",
	["Mal'Ganis, el señor del terror, guió la plaga en Lordaeron. Arthas lo persiguió hasta Rasganorte, y esa cacería lo perdió."] = "恐懼魔王瑪爾加尼斯在洛丹倫主導了瘟疫。阿薩斯一路追他到北裂境，正是這場追獵毀了他。",
	["Maldiciones y daño con el tiempo: pones tus hechizos y el monstruo muere solo mientras pasas al siguiente."] = "詛咒與持續傷害：上完法術後怪物會自己死掉，你可以直接打下一隻。",
	["Maldición"] = "詛咒",
	["Maldición que hace cada vez más daño."] = "傷害越來越高的詛咒。",
	["Malfurion Tempestira fue el primer druida de los elfos de la noche. Aprendió del semidiós Cenarius, a quien llamaba shan'do: «maestro honrado»."] = "瑪法里恩·怒風是夜精靈的第一位德魯伊。他師從半神塞納留斯，稱他為 shan'do：「尊敬的導師」。",
	["Malfurion Tempestira, el gran druida, está perdido en el Sueño Esmeralda, y Tyrande lo espera."] = "偉大的德魯伊瑪法里恩·怒風迷失在翡翠夢境中，泰蘭妲一直在等他。",
	["Malla"] = "鎖甲",
	["Malygos, el Tejehechizos, guía a los dragones azules. La traición de Alamuerte casi acaba con su vuelo, y nunca se repuso del todo."] = "織法者瑪里苟斯領導著藍龍。死亡之翼的背叛幾乎讓他的龍軍團覆滅，他從此一蹶不振。",
	["Manada"] = "狼群",
	["Manda al chat del grupo una línea con el enlace de la misión cuando completas sus objetivos, otra cuando está lista para entregar y otra al entregarla; todo el grupo la ve, con o sin Alfa. Apagado, esas líneas solo te salen a ti. Nunca en banda."] = "完成任務目標時向隊伍聊天發送一行帶任務連結的訊息，可交付時再發一行，交付時再發一行；全隊都看得到，不論有沒有 Alfa。關閉時這些訊息只有你看得到。團隊中不發送。",
	["Mano derecha"] = "主手",
	["Mano firme"] = "穩如磐石",
	["Mano izquierda"] = "副手",
	["Mano principal"] = "主手",
	["Mano secundaria"] = "副手",
	["Manos"] = "手部",
	["Mantén Furia recta encendida cuando tanquees."] = "當坦克時保持正義之怒開啟。",
	["Mantén Grito de batalla siempre puesto."] = "一直保持戰鬥怒吼。",
	["Mantén Seccionar en el rival para que no huya."] = "讓對手一直保持斷筋效果，他就跑不掉。",
	["Mantén al monstruo lejos: tu mascota lo detiene mientras disparas."] = "讓怪物離你遠一點：寵物拖住它，你負責射擊。",
	["Maná"] = "法力",
	["Maná cada 5 s"] = "每 5 秒法力恢復",
	["Maná de los curanderos"] = "治療者的法力",
	["Maná tras la pelea"] = "戰鬥後的法力",
	["Mapa de Alfa"] = "Alfa 地圖",
	["Mapa del mundo"] = "世界地圖",
	["Mapa estable y 46 arreglos"] = "地圖穩定，另有 46 項修正",
	["Mapa y marcadores"] = "地圖與標記",
	["Mar abierto y zonas de nivel 35 en adelante. El rango Artesano lo da Nat Pagle en el Marjal Revolcafango con su misión."] = "開闊海域與 35 級以上的地區。專家級釣魚由塵泥沼澤的納特·帕格透過他的任務傳授。",
	["Maraudon es sagrado para los centauros: ahí descansa el espíritu de Zaetar, el padre de su raza."] = "瑪拉頓是半人馬的聖地：他們種族之父札爾塔的靈魂安息在那裡。",
	["Marca a los enemigos y empieza por el más peligroso."] = "標記敵人，從最危險的開始打。",
	["Marca al enemigo y todos le pegan más a distancia. Ponla antes de empezar."] = "標記敵人，讓大家在遠程打得更痛。開打前先加上。",
	["Marca al enemigo: todos le pegan más."] = "標記敵人：所有人對它造成更多傷害。",
	["Marca de lo Salvaje"] = "野性印記",
	["Marca el botón de tu barra que tiene la habilidad sugerida."] = "標示快捷列上帶有建議技能的按鈕。",
	["Marca en el mapa a los instructores y vendedores de pesca de tu facción."] = "在地圖上標出你陣營的釣魚訓練師與商人。",
	["Marca en el minimapa la entrada de cada mazmorra (en verde las que ya hiciste). El mapa del mundo ya las marca solo."] = "在小地圖上標記每個地城的入口（已完成的以綠色顯示）。世界地圖本身已經有標記。",
	["Marca un spot con «Spot aquí» en La Jauría o /alfa spot. Sale dorado en tu mapa y, si lo compartes, también en el de tu hermandad."] = "在 La Jauría 中用「此處刷點」或 /alfa spot 標記刷點。它會以金色顯示在你的地圖上；如果你分享，也會出現在公會成員的地圖上。",
	["Marca un spot de farmeo donde estás (/alfa spot <texto>)"] = "在你所在的位置標記一個刷點（/alfa spot <文字>）",
	["Marcador"] = "標記",
	["Marcador borrado"] = "標記已刪除",
	["Marcador puesto: %s."] = "已放置標記：%s。",
	["Marcadores con Mayús+clic derecho en el mapa del juego"] = "在遊戲地圖上用 Shift+右鍵放置標記",
	["Marcadores propios para compartir y seguir con la flecha."] = "可分享並用箭頭跟隨的自訂標記。",
	["Marcar a quien te falta para una misión"] = "標出任務還需要的目標",
	["Marcar como chatarra (%d)"] = "標記為垃圾（%d）",
	["Marcar como hecha"] = "標記為已完成",
	["Marcar como hecha (o desmarcar)"] = "標記為已完成（或取消標記）",
	["Marcar con calavera"] = "標記骷髏",
	["Marcar el mejor vuelo"] = "標出最佳飛行",
	["Marcar el raro para todos"] = "為所有人標記稀有怪",
	["Marcar la mejor recompensa para ti"] = "標出最適合你的獎勵",
	["Marcar las que no valen la pena"] = "標記不值得做的任務",
	["Marcar para abandonar"] = "標記為放棄",
	["Marcas sobre cada objeto"] = "物品上的標記",
	["Marcaste como chatarra: %s. Se vende sola al hablar con un comerciante."] = "已標記為垃圾：%s。與商人交談時會自動賣出。",
	["Marcaste como chatarra: %s. Véndela con «Vender la chatarra» en el comerciante."] = "已標記為垃圾：%s。在商人處用「出售垃圾」賣掉它。",
	["Marcaste un spot de farmeo: «%s»."] = "你標記了一個刷點：「%s」。",
