	["Marcos de Curación encendidos."] = "治療框架已開啟。",
	["Marcos de grupo de Alfa"] = "Alfa 的隊伍框架",
	["Marcos de grupo de Alfa: pasas el ratón sobre un compañero y haces clic para curarlo."] = "Alfa 的隊伍框架：把滑鼠移到隊友身上並點擊即可治療。",
	["Marcos de grupo y banda para curar con un clic, con preajustes por clase."] = "一鍵治療的隊伍與團隊框架，並附有各職業的預設方案。",
	["Marcos encendidos"] = "框架已開啟",
	["Marcos y barra"] = "框架與快捷列",
