	["Mascotas"] = "寵物",
	["Mascotas enemigas"] = "敵方寵物",
	["Materiales"] = "商業物品",
	["Mayús"] = "Shift",
	["Mayús+Espacio sigue saltando"] = "Shift+空白鍵 仍然跳躍",
	["Maza de dos manos"] = "雙手錘",
	["Maza de una mano"] = "單手錘",
	["Mazmorra"] = "地城",
	["Mazmorra a la vista. Pelea al objetivo que marque tu grupo y todo sale mejor."] = "前方有地城。攻擊隊伍標記的目標，一切都會更順利。",
	["Mazmorra: %s"] = "地城：%s",
	["Mazmorras"] = "地城",
	["Mazmorras (3): derrotar al último jefe de todas las mazmorras de nivel 15-25, 26-45 y 46-60 (un punto por grupo)."] = "地城（3）：擊敗 15-25、26-45 與 46-60 級所有地城的最終首領（每組一點）。",
	["Mazmorras claras"] = "地城一目了然",
	["Mazmorras en el camino"] = "沿途的地城",
	["Mazmorras hechas"] = "已完成的地城",
	["Mazmorras y bandas"] = "地城與團隊副本",
	["Mazmorras: los avisos de jefes que tu juego sí trae ya no salen apagados."] = "地城：你的遊戲中有的首領警報不再顯示為關閉。",
	["Mazthoril es la guarida de los dragones azules, siempre atentos a quién usa la magia."] = "麥索瑞爾是藍龍的巢穴，牠們時刻留意著誰在使用魔法。",
	["Mañana"] = "明天",
	["Me cuesta leer Alfa, ¿qué hago?"] = "Alfa 的字我看不太清楚，怎麼辦？",
	["Me encanta cazar contigo. ¡Vamos por la siguiente!"] = "我好喜歡和你一起狩獵。去打下一個吧！",
	["Me gusta cuidarte la espalda. Para eso estoy."] = "我喜歡守著你的背後。我就是為此而在。",
	["Me gusta este paso tranquilo. Así se disfruta el camino."] = "我喜歡這種悠閒的步調。這樣才能好好享受旅途。",
	["Me gusta ir contigo. Se nota que sabes lo que haces."] = "我喜歡和你一起走。看得出你很清楚自己在做什麼。",
	["Me morí, ¿corro por mi cuerpo o voy con el ángel?"] = "我死了：是跑回屍體，還是找靈魂醫者？",
	["Me quedo aquí sentadita contigo. Tres caídas no te hacen menos lobo. ¿Reparamos y pedimos ayuda?"] = "我就坐在這裡陪你。倒下三次也不會讓你不像狼。我們修理一下，再求助好嗎？",
	["Me salté la historia de una misión"] = "我跳過了任務劇情",
	["Media"] = "中",
	["Medianos y graves"] = "中等與嚴重",
	["Medias"] = "中",
	["Medidor de daño"] = "傷害統計",
	["Medio"] = "中",
	["Medivh era hijo de Aegwynn, la Guardiana anterior. Ella escondió en él el poder del Guardián sin saber que Sargeras también se escondía ahí."] = "麥迪文是上一任守護者艾格文的兒子。她把守護者的力量藏在他體內，卻不知道薩格拉斯也藏在那裡。",
	["Medivh era hijo de Aegwynn, la Guardiana, y de Nielas Aran, un mago de la corte de Ventormenta."] = "麥迪文是守護者艾格文與暴風城宮廷法師尼拉斯·阿然之子。",
	["Medivh murió a manos de Khadgar y Lothar, pero años después regresó como el misterioso profeta que llevó a Thrall a Kalimdor."] = "麥迪文死於卡德加和洛薩之手，但多年後他以神秘先知的身分歸來，帶領索爾前往卡林多。",
	["Medivh, poseído por Sargeras, abrió el camino para que la Horda llegara a Azeroth."] = "被薩格拉斯附身的麥迪文為部落打開了通往艾澤拉斯的道路。",
	["Mejor %s"] = "改為%s",
	["Mejor a nivel %d · niveles %d a %d"] = "最適合 %d 級 · %d 到 %d 級",
	["Mejor con la manada: llámala y cacen juntos."] = "和狼群一起更好：呼喚他們一起狩獵。",
	["Mejor no ir sin compañía: puede salir caro."] = "最好別一個人去：可能會付出代價。",
	["Mejor:"] = "最佳：",
	["Mejora"] = "增強",
	["Mejora [reporte]"] = "改進建議",
	["Mejora para subir"] = "增強（練等）",
	["Mejora tu defensa con escudo."] = "提升你持盾時的防禦。",
	["Mejorar el cuadro de información"] = "強化滑鼠提示",
	["Mejorar el minimapa"] = "強化小地圖",
	["Mejorar el probador"] = "強化試衣間",
	["Mejoras de equipo"] = "裝備提升",
	["Memoria de Alfa"] = "Alfa 的記憶體",
	["Mensajes de aviso en pantalla"] = "畫面警報訊息",
	["Mensajes enviados: %d (frenados: %d) · recibidos: %d · en cola: %d"] = "已傳送訊息：%d（被限流：%d）· 已接收：%d · 佇列中：%d",
	["Mentor"] = "導師",
	["Menú del jugador"] = "玩家選單",
	["Menú y bolsas"] = "選單與背包",
	["Mercancías generales"] = "雜貨",
	["Meta cumplida"] = "目標已達成",
	["Meta cumplida (%d de %d)"] = "目標已達成（%d / %d）",
	["Metas de pesca"] = "釣魚目標",
	["Mi configuración"] = "我的設定",
	["Mi entrenador"] = "我的訓練師",
	["Mi oreja derecha se para sola cuando alguien dice «salchicha». Pruébalo."] = "只要有人說「香腸」，我的右耳就會自己豎起來。試試看。",
	["Mi panza hizo un ruido. No fui yo, fue la panza."] = "我的肚子咕嚕叫了一聲。不是我，是肚子。",
	["Mi plan"] = "我的計畫",
	["Mi plan perfecto: una buena cacería y luego salchichas junto a la fogata."] = "我的完美計畫：好好狩獵一場，然後在營火旁吃香腸。",
	["Mi plan · %s"] = "我的計畫 · %s",
	["Mi plan · %s · %d de %d"] = "我的計畫 · %s · %d / %d",
	["Mi primera montura"] = "我的第一匹坐騎",
	["Mi propio plan"] = "我自己的計畫",
	["Mi ruta"] = "我的路線",
	["Mi ruta: hacer oro"] = "我的路線：賺金幣",
	["Mi ruta: subir rápido"] = "我的路線：快速練等",
	["Mientras caminas o corres, tu tecla hace lo de siempre (con Espacio, saltar)."] = "你走路或奔跑時，按鍵保持原本功能（設為空白鍵時就是跳躍）。",
	["Mientras el corcho está en el agua, una línea fina con el tiempo, tu habilidad y lo último que sacaste."] = "魚漂在水中時，顯示一條細線，包含時間、你的技能與上一次的漁獲。",
	["Mientras estás aquí"] = "你在這裡時",
	["Mientras estás aquí: %s"] = "既然在這裡：%s",
	["Mientras la haces"] = "做任務的同時",
	["Mientras los druidas dormían en el Sueño Esmeralda, las Centinelas de Tyrande cuidaron solas los bosques de Kalimdor."] = "德魯伊在翡翠夢境中沉睡時，泰蘭妲的哨兵們獨自守護著卡林多的森林。",
	["Mientras más alto el nivel de las bestias, mejor el cuero que sueltan."] = "野獸的等級越高，掉落的皮革就越好。",
	["Mientras más nivel tenga la bestia, más habilidad te pide para desollarla."] = "野獸的等級越高，剝皮所需的技能就越高。",
	["Mientras pescas"] = "釣魚時",
	["Mientras pescas se ve solo el mundo y la barra de pesca. Nunca en combate: al empezar uno, todo vuelve."] = "釣魚時只顯示世界與釣魚條。戰鬥中絕不會這樣：一進入戰鬥，一切都會恢復。",
	["Mientras pescas, el juego se sigue oyendo aunque estés en otra ventana."] = "釣魚時，即使你切到其他視窗，也能繼續聽到遊戲聲音。",
	["Mientras tenga la maldición, cura antes de que la vida baje mucho."] = "中詛咒期間，在生命值掉太多之前就先治療。",
	["Mientras vuelas en grifo, la línea de tu viaje en el mapa de Alfa: por dónde vas y dónde aterrizas."] = "乘坐獅鷲飛行時，在 Alfa 地圖上顯示你的旅程路線：你現在在哪裡，會在哪裡降落。",
	["Mientras, junta el oro: con la equitación y la montura se va casi todo."] = "同時存好金幣：騎術與坐騎幾乎會花光它們。",
	["Mil y un peces"] = "一千零一條魚",
	["Mina, herboriza, pesca en un banco o abre un cofre: aquí verás cuánto, qué te dio cada nodo y en qué zona."] = "採礦、採草藥、在魚群釣魚或打開寶箱：這裡會顯示數量、每個採集點給了你什麼以及在哪個地區。",
	["Minas, hierbas y tesoros en tu mapa"] = "地圖上的礦脈、草藥與寶藏",
	["Minería"] = "採礦",
	["Minería es su mejor pareja. Necesitas un martillo de herrero y trabajar junto a un yunque."] = "採礦是它最好的搭檔。你需要一把鐵匠之錘，並在鐵砧旁工作。",
	["Minería, hierbas, pesca y tesoros en tu mapa y minimapa, con rutas de farmeo e historial."] = "在地圖與小地圖上顯示礦物、草藥、魚群與寶藏，並提供採集路線與歷史記錄。",
	["Minería, hierbas, pesca y tesoros también en el mapa grande de Alfa: al acercarte a una zona salen agrupados, con su cantidad."] = "採礦、草藥、釣魚和寶藏也會顯示在 Alfa 的大地圖上：放大到某個區域時，它們會依數量分組顯示。",
	["Minimapa"] = "小地圖",
	["Minimapa cuadrado"] = "方形小地圖",
	["Minutos entre consejos"] = "建議間隔（分鐘）",
	["Minutos entre historias"] = "故事間隔（分鐘）",
	["Mira a sus jefes y sus consejos antes de cada pelea."] = "每場戰鬥前查看它的首領與提示。",
	["Mira a una criatura primero: así Alfa sabe en qué plano estás."] = "先看一眼某個生物：這樣 Alfa 才知道你在哪個位面。",
	["Mira a una criatura y Alfa te dice en qué guarida estás"] = "看一眼生物，Alfa 就告訴你在哪個巢穴",
	["Mira bien alrededor; las cosas importantes no se esconden tanto."] = "仔細看看四周；重要的東西不會藏得太深。",
	["Mira en la Enciclopedia de dónde sale."] = "在百科中查看它的來源。",
	["Mira la línea de tiempo: llegan tres ataques de prueba"] = "請看時間軸：會出現三個測試攻擊",
	["Mira las bolsas o el banco de otro de tus personajes."] = "查看你其他角色的背包或銀行。",
	["Mira quién llegó: %s, de la familia %s. Nos vamos a llevar bien... casi siempre."] = "看看誰來了：%s，%s家族的一員。我們會處得很好的…大多數時候。",
	["Mira si llevas lo que hace falta: el equipo reparado, espacio, comida y lo de tu clase."] = "檢查你是否帶齊所需：修好的裝備、背包空間、食物和職業物品。",
	["Mira tus retos en el Legado del juego"] = "在遊戲的傳承中查看你的挑戰",
	["Mira «Camino al 60» en Hoy: cuántas horas te faltan a tu ritmo y cuánto avanzaste hoy. «Ver el camino» te dice qué guías y mazmorras te tocan."] = "看看「今天」裡的「通往 60 級之路」：照你的節奏還要幾小時，以及你今天走了多遠。「查看路線」會告訴你哪些指南和地城適合你。",
	["Mis bolsas son un desorden"] = "我的背包一團亂",
	["Mis planes"] = "我的計畫",
	["Mis planes: la flecha va sola al siguiente lugar"] = "我的計畫：箭頭會自動指向下一個地點",
	["Mis rutas"] = "我的路線",
	["Misceláneo"] = "其他",
	["Misiles arcanos: daño constante que no se interrumpe fácil."] = "秘法飛彈：穩定的傷害，不容易被打斷。",
