	["Moviendo"] = "移動中",
	["Mucho daño con tu arma a distancia: disparos fuertes antes de que el monstruo llegue."] = "用遠程武器造成大量傷害：在怪物靠近前就打出強力射擊。",
	["Mucho daño de sombra que va creciendo. Una maldición por enemigo."] = "大量逐漸增強的暗影傷害。每個敵人只能上一個詛咒。",
	["Mucho maná y hechizos arcanos potentes: el mago que menos descansa."] = "大量法力與強力的秘法法術：最不需要休息的法師。",
	["Mucho tiempo sin verte, %s. Repasa tus misiones antes de salir."] = "好久不見，%s。出發前先看看你的任務。",
	["Muchos"] = "多",
	["Muchos enemigos duermen a un jugador: no es grave, el sueño se quita solo."] = "很多敵人會催眠一名玩家：不要緊，睡眠會自己解除。",
	["Muchos: consejos del momento y de vez en cuando uno de Alfa. Pocos: menos seguido. Solo importantes: al morir, al subir de nivel y en tus logros."] = "多：當下的建議，偶爾還有一則關於 Alfa 的。少：頻率較低。只看重要的：死亡、升級與達成里程碑時。",
	["Muchísima amenaza en un golpe."] = "一擊就產生大量仇恨。",
	["Muelle de %s"] = "%s碼頭",
	["Muelles y torres de zepelín, con a dónde van."] = "碼頭與飛艇塔，以及它們的目的地。",
	["Muertes"] = "死亡次數",
	["Muerto"] = "死亡",
	["Muestra la ventana de guía y la flecha, y cierra esta ventana para que las veas."] = "顯示指南視窗與箭頭，並關閉此視窗，讓你看得到它們。",
	["Muestra la vida en número, debajo del nombre."] = "在名字下方以數字顯示生命值。",
	["Muestra lo que aún no exploras, con un tono más frío para distinguirlo."] = "顯示你尚未探索的區域，並以較冷的色調加以區分。",
	["Muestra un aviso de ejemplo para que veas dónde sale."] = "顯示一則範例提醒，讓你看看它出現在哪裡。",
	["Muestra un ícono encima del corcho: así sabes que tu tecla lo va a recoger."] = "在浮標上方顯示圖示，讓你知道按鍵會收起它。",
	["Mueve lo de Alfa con el ratón"] = "用滑鼠移動 Alfa 的元素",
	["Mueve tus marcos"] = "移動你的框架",
	["Mulgore de día: pasto hasta donde alcanza la vista y kodos pastando. Qué paz."] = "白天的莫高雷：一望無際的草原和吃草的科多獸。好寧靜。",
	["Mundo"] = "世界",
	["Munición"] = "彈藥",
	["Muradin Barbabronce acompañó a Arthas a Rasganorte. Cuando Arthas tomó la espada, un trozo de hielo golpeó a Muradin y lo dieron por muerto."] = "穆拉丁·銅鬚隨阿薩斯前往北裂境。阿薩斯拿起那把劍時，一塊冰擊中了穆拉丁，大家都以為他死了。",
	["Muradin Barbabronce le enseñó a Arthas a pelear cuando el príncipe era joven."] = "王子年少時，是穆拉丁·銅鬚教會了阿薩斯戰鬥。",
	["Muro de escudo dura más."] = "盾牆持續更久。",
	["Muro de escudo dura más: te salva en los jefes."] = "盾牆持續更久：打首領時能救你一命。",
	["Muy grande"] = "特大",
	["Muy peligroso para tu nivel: mejor con grupo o rodéalo."] = "對你的等級非常危險：最好組隊，或者繞開。",
	["Muy pronto"] = "即將推出",
	["Muéstrala u ocúltala. También con su tecla o con /alfa guia."] = "顯示或隱藏它。也可以使用它的按鍵或 /alfa guia。",
	["Muévete a las zonas de nivel 10 a 20. Las lombrices ayudan a que no se escapen. Pide el rango Experto desde 125."] = "轉到 10 到 20 級的地區。蚯蚓能讓魚不那麼容易跑掉。125 點起去學高級。",
	["Muñecas"] = "手腕",
	["Márcala cuando la hagas"] = "完成後勾選它",
	["Márcalo con la calavera y todo tu grupo lo verá."] = "給它標上骷髏，全隊都看得到。",
	["Más"] = "更多",
	["Más Abrumar gracias a Desgarrar."] = "因為撕裂而有更多壓制的機會。",
	["Más Golpes heroicos: más daño por pelea."] = "更多英勇打擊：每場戰鬥造成更多傷害。",
	["Más adelante"] = "之後",
	["Más adelante eliges entre ingeniería gnómica y goblin: los inventos gnómicos fallan a veces de forma muy graciosa, y los goblin explotan más."] = "之後你要在地精工程學和哥布林工程學之間選擇：地精的發明有時會以非常滑稽的方式失靈，哥布林的則更容易爆炸。",
	["Más adelante eliges especialidad: de escamas de dragón, elemental o tribal."] = "之後你要選擇專精：龍鱗製皮、元素製皮或部族製皮。",
	["Más adelante eliges especialidad: forjador de armaduras o armero, y los armeros, entre espadas, mazas y hachas."] = "之後你要選擇專精：防具鍛造師或武器鍛造師，武器鍛造師還要在劍、錘和斧之中選擇。",
	["Más adelante: %s."] = "之後：%s。",
	["Más aguante para ti y tus amigos. Dásela a todo el grupo antes de empezar."] = "為你和朋友們提升耐力。開打前給全隊加上。",
	["Más aguante y seguridad. Matas un poco más lento, pero casi no mueres."] = "更耐打、更安全。殺怪稍微慢一點，但幾乎不會死。",
	["Más alto, atraviesa objetos más grandes antes de acercarse."] = "數值越高，鏡頭在拉近之前能穿過越大的物體。",
	["Más alto, los objetos lejanos tardan más en desaparecer."] = "數值越高，遠處的物體越晚消失。",
	["Más alto, más nítido. Demasiado puede marcar bordes y brillos."] = "數值越高越清晰。太高可能讓邊緣與高光過於明顯。",
	["Más alto, ves más a los lados."] = "數值越高，兩側看到的範圍越大。",
	["Más amenaza."] = "更多仇恨。",
	["Más amenaza: los monstruos se quedan contigo."] = "更多仇恨：怪物會一直打你。",
	["Más armadura para ti y tu grupo cercano. Una buena aura para empezar."] = "為你和附近的隊友提升護甲。很適合開局用的光環。",
	["Más armadura y más poder. Mantenlo siempre puesto."] = "更多護甲和更多力量。一直保持開著。",
	["Más armadura y regeneras vida. Mantenla siempre puesta."] = "更多護甲和生命恢復。一直保持開著。",
	["Más armadura, atributos y resistencias. Dásela a todo el grupo."] = "提升護甲、屬性和抗性。給全隊加上。",
	["Más baja, la niebla se ve más ligera y cuesta menos."] = "數值越低，霧看起來越淡，也越省資源。",
	["Más bajo, se siguen viendo objetos pequeños a lo lejos."] = "數值越低，遠處的小物體仍會保持可見。",
	["Más cerca de tu paso"] = "離你的步驟最近",
	["Más crítico en Abrumar, ideal contra pícaros que esquivan."] = "提高壓制的致命一擊率，非常適合對付會閃躲的盜賊。",
	["Más crítico."] = "更多致命一擊。",
	["Más daño con dos manos."] = "雙手武器傷害更高。",
	["Más daño con el tiempo."] = "更多持續傷害。",
	["Más daño con escudo."] = "持盾時傷害更高。",
	["Más daño con escudo: lo que hace que Protección suba bien."] = "持盾時傷害更高：這就是防護練等順利的原因。",
	["Más daño con tu arma de dos manos, que es la que usas."] = "你使用的雙手武器傷害更高。",
	["Más daño con tu arma de dos manos."] = "雙手武器傷害更高。",
	["Más daño de sangrado; abre Heridas profundas."] = "流血傷害更高；解鎖重傷。",
	["Más daño mientras llevas escudo."] = "裝備盾牌時傷害更高。",
	["Más daño y más riesgo. Matas rápido, pero un error se paga caro."] = "傷害更高、風險也更高。殺怪很快，但一失誤就要付出代價。",
	["Más de 40 arreglos: combate y curación en mazmorras, el buzón cuenta bien tu dinero y la placa de llegada se va sola."] = "40 多項修正：地城中的戰鬥與治療，郵箱正確計算你的金錢，抵達牌會自己消失。",
	["Más de mi gente"] = "再說說我的族人",
	["Más defensa desde el principio."] = "從一開始就有更多防禦。",
	["Más defensa: te golpean y te hacen crítico menos seguido."] = "更多防禦：你被命中與被致命一擊的次數更少。",
	["Más defensa: te hacen menos críticos."] = "更多防禦：你受到的致命一擊更少。",
	["Más detalle al acercar el mapa"] = "放大地圖時顯示更多細節",
	["Más distancia, sombras finas y agua con reflejos."] = "更遠的視距、細緻的陰影與帶反射的水面。",
	["Más en Calidad de vida"] = "更多內容見「便利功能」",
	["Más espacio en el banco"] = "更多銀行空間",
	["Más firme y en tu idioma"] = "更穩定，也更懂你的語言",
	["Más fuerza para ti y tu grupo cercano."] = "為你和附近的隊友提升力量。",
	["Más golpe crítico para todo lo que haces."] = "所有攻擊的致命一擊率都提高。",
	["Más golpe crítico, que también te da más ira."] = "更高的致命一擊率，也會給你更多怒氣。",
	["Más golpe crítico."] = "更高的致命一擊率。",
	["Más golpes bloqueados con el escudo, y cada bloqueo te da ira."] = "用盾牌格擋更多攻擊，而且每次格擋都會給你怒氣。",
	["Más golpes críticos, pero recibes más daño. La postura para hacer daño."] = "更多致命一擊，但你受到的傷害也更多。輸出用的姿態。",
	["Más guías"] = "更多指南",
	["Más intelecto para ti y tus amigos. Dáselo al grupo antes de empezar."] = "為你和朋友們提升智力。開打前給隊伍加上。",
	["Más ira al cargar."] = "衝鋒時獲得更多怒氣。",
	["Más ira al cargar: tu primer golpe llega antes."] = "衝鋒時獲得更多怒氣：你的第一擊更早打出來。",
	["Más ira al empezar la pelea."] = "戰鬥開始時獲得更多怒氣。",
	["Más ira al empezar."] = "開場時獲得更多怒氣。",
	["Más ira por cada golpe, sobre todo con armas rápidas."] = "每次攻擊獲得更多怒氣，用快速武器時特別明顯。",
	["Más ira por cada golpe: más Golpe heroico y Golpe mortal."] = "每次攻擊獲得更多怒氣：能用更多英勇打擊與致死打擊。",
	["Más ira por golpe."] = "每次攻擊獲得更多怒氣。",
	["Más ira por golpe: más habilidades seguidas."] = "每次攻擊獲得更多怒氣：能連續使用更多技能。",
	["Más lugares"] = "更多地點",
	["Más maná con el tiempo. Ideal para quien cura y para ti."] = "持續恢復更多法力。很適合治療者，也適合你。",
	["Más maná y algo de crítico con hechizos."] = "更多法力與一些法術致命一擊。",
	["Más opciones"] = "更多選項",
	["Más opciones de Mundo"] = "更多世界選項",
	["Más opciones de apariencia"] = "更多外觀選項",
	["Más opciones del ícono"] = "更多圖示選項",
	["Más para tu personaje"] = "為你的角色提供更多",
	["Más pasto"] = "更多草地",
	["Más pasto, más horizonte, niebla ligera y rayos de sol, sin pedirle de más a tu PC. Se deshace en Mundo > Paisaje y gráficos (o /alfa paisaje)."] = "更多草地、更遠的地平線、淡淡的霧與陽光光束，又不會讓你的電腦太吃力。可在「世界 > 風景與圖形」（或 /alfa paisaje）中復原。",
	["Más pasto, más horizonte, niebla ligera y rayos de sol. Bonito sin pedir de más."] = "更多草地、更遠的地平線、淡淡的霧與陽光光束。好看又不吃配備。",
	["Más poder de ataque a distancia. El aspecto para pelear."] = "更多遠程攻擊強度。戰鬥用的守護。",
	["Más poder de ataque para tu grupo."] = "提高隊伍的攻擊強度。",
	["Más poder de ataque por varios minutos. Dásela a los que pelean cuerpo a cuerpo."] = "幾分鐘內提升攻擊強度。給你的近戰朋友加上。",
	["Más sangrado; abre Heridas profundas."] = "更多流血傷害；解鎖重傷。",
	["Más velocidad de ataque: mantenlo puesto."] = "提高攻擊速度：讓它一直生效。",
	["Más vida: aguantas más golpes antes de tener que comer o descansar."] = "更多生命值：在需要吃東西或休息前能多扛幾下。",
	["Mínimas"] = "最低",
	["Mínimo"] = "最低",
	["Módulos activados"] = "模組已開啟",
	["Músculos"] = "秀肌肉",
	["Música mientras pescas"] = "釣魚時的音樂",
	["Nada"] = "無",
	["Nada coincide"] = "沒有符合的項目",
	["Nada con ese nombre"] = "沒有這個名字的東西",
	["Nada con ese nombre."] = "沒有這個名字的東西。",
	["Nada de esto le sirve a tu clase"] = "這些都不適合你的職業",
	["Nada en este grupo"] = "這一組沒有物品",
	["Nada nuevo"] = "沒有新的",
	["Nada nuevo por aprender"] = "沒有新的技能可學",
	["Nada nuevo por aprender."] = "沒有新的可學。",
	["Nada por aquí"] = "這裡什麼都沒有",
	["Nada por regalar por ahora."] = "暫時沒有可以送的東西。",
	["Nada que acomodar aquí: abre un comerciante para vender tu chatarra o habla con un banquero para guardar tus materiales."] = "這裡沒什麼要整理的：開啟商人賣掉垃圾，或找銀行職員存放材料。",
	["Nada que aplicar"] = "沒有可套用的項目",
	["Nada que entregar todavía"] = "還沒有可交付的",
	["Nada que recoger"] = "沒有可接取的",
	["Nada que reparar"] = "沒有需要修理的裝備",
	["Nada que soltar"] = "沒有要放棄的",
	["Nada que vender por ahora: lo que llevas sirve o vale más guardado."] = "目前沒有可賣的：你帶的東西有用，或存起來更值錢。",
	["Nada: todo esto lo haces tú."] = "無：這些都由你自己來做。",
	["Nadie a la vista tiene ubicación ahora: en una instancia o desconectados. Cuando vuelvan al mundo, aparecen aquí y en tu mapa."] = "視野中現在沒有人有位置：在副本中或已離線。回到世界後，他們會出現在這裡與你的地圖上。",
	["Nadie abrió la puerta"] = "沒人開門",
	["Nadie busca grupo ahora. ¡Pon tu anuncio!"] = "現在沒人在找隊伍。發佈你的公告吧！",
	["Nadie de la manada a la vista"] = "視野中沒有狼群成員",
	["Nadie de la manada anda en otra guarida de esta zona ahora."] = "現在狼群裡沒人在本區域的其他巢穴。",
	["Nadie de la manada anda en otro plano"] = "狼群裡沒人在其他位面",
	["Nadie de la manada dijo tener «%s» (todavía)."] = "狼群裡（暫時）沒人說有「%s」。",
	["Nadie de la manada respondió desde otro plano. Prueba en un rato o pídelo en el Discord de La Jauría."] = "狼群裡沒人從其他位面回應。過一會兒再試，或去 La Jauría 的 Discord 問問。",
	["Nadie para adoptar por ahora: los lobos salen aquí cuando la manada los ve."] = "現在沒有可以收養的狼：狼群看到他們時，就會出現在這裡。",
	["Nadie respondió desde la %s. Prueba en un rato o pídelo en el Discord de La Jauría."] = "%s裡沒人回應。稍後再試或去 La Jauría 的 Discord 問問。",
	["Nadie tiene esa guarida abierta ahora."] = "現在沒人開著那個巢穴。",
	["Naranja"] = "橘色",
	["Nat Pagle, el pescador legendario, vive en una isla del Marjal Revolcafango."] = "傳奇漁夫納特·帕格住在塵泥沼澤的一座島上。",
	["Nat Pagle, el pescador más famoso, vive en una isla del marjal; sus misiones son para pescadores pacientes."] = "最有名的漁夫納特·帕格住在沼澤中的一座島上；他的任務適合有耐心的釣客。",
	["Nat Pagle, en el Marjal Revolcafango, te pide cuatro peces raros: con su misión aprendes el rango Artesano."] = "塵泥沼澤的納特·帕格要你帶來四條稀有魚：完成他的任務就能學會專家級釣魚。",
	["Naxxramas, la necrópolis de Kel'Thuzad, flota sobre estas tierras como una sombra."] = "納克薩瑪斯是科爾蘇加德的浮空城，像一道陰影般飄浮在這片土地上空。",
	["Necesita la base de misiones (página Misiones)."] = "需要任務資料庫（「解任務」頁面）。",
	["Necesita las rutas a pie de Alfa (Alfa_Nav), que se cargan solas con «Seguir caminos reales» encendido."] = "需要 Alfa 的步行路線（Alfa_Nav），開啟「沿真實道路行走」後會自動載入。",
	["Necesita un monitor HDR"] = "需要 HDR 螢幕",
	["Necesitas %s"] = "你需要%s",
	["Necesitas %s con %s"] = "你需要%s（%s）",
	["Necesitas %s para esta cadena: apréndela con un instructor."] = "這個任務鏈需要%s：請向訓練師學習。",
	["Necesitas %s para juntarlo: apréndela con un instructor de profesiones."] = "採集它需要%s：請向專業技能訓練師學習。",
	["Necesitas al menos 2 misiones listas para entregar."] = "至少需要 2 個已完成的任務才能交。",
	["Necesitas una hermandad: el tablón es de los lobos de la tuya."] = "你需要一個公會：公告板是你公會裡的狼專用的。",
	["Necesitas una hermandad: «¿Quién tiene...?» pregunta a los lobos de la tuya."] = "你需要一個公會：「誰有…？」是問你公會裡的狼。",
	["Neltharion, el Guardián de la Tierra, escuchó los susurros de los dioses antiguos y se convirtió en Alamuerte."] = "大地守護者奈薩里奧聽信了古神的低語，變成了死亡之翼。",
	["Ner'zhul abrió varios portales en Draenor y la magia desgarró el planeta. Lo que quedó flota en la nada y se llama Terrallende."] = "耐奧祖在德拉諾開啟了多道傳送門，魔法撕裂了整個星球。殘存的部分漂浮在虛空中，被稱為外域。",
	["Nethergarde es un bastión de magos de la Alianza que vigila el Portal Oscuro, por si algo vuelve a cruzar."] = "守望堡是聯盟法師的要塞，負責監視黑暗之門，以防再有什麼東西穿過來。",
