	["No se ve en pantalla. Tráela de vuelta cuando quieras (también con /alfa lya)."] = "她現在不在畫面上。隨時可以讓她回來（也可以用 /alfa lya）。",
	["No siempre aparece en la mina: si lo ves, es un jefe más con buen botín."] = "他不一定會出現在礦坑裡：如果看到他，就是多一個掉好東西的首領。",
