	["No sé si alguien en Azeroth cocina salchichas como las de casa... pero si encuentras una receta, ¡me avisas!"] = "不知道艾澤拉斯有沒有人能做出家裡那種香腸…要是你找到配方，記得告訴我！",
	["No sé si se puede tomar"] = "無法確定能否接取",
	["No te alcanza"] = "錢不夠",
