	["No tienes marcadores en el mapa de Alfa. Pon uno en el mapa y vuelve aquí."] = "你在 Alfa 的地圖上沒有標記。在地圖上放一個，然後回到這裡。",
	["No tienes mascota: llámala."] = "你沒有寵物：召喚牠。",
	["No tienes mascota: si murió, revívela."] = "你沒有寵物：如果牠死了，復活牠。",
	["No tienes misiones para este plan con ese filtro."] = "依此篩選條件，你沒有可用於此計畫的任務。",
	["No tienes puntos libres. El siguiente talento del plan (%s) te toca en el nivel %d."] = "你沒有未分配點數。配點中的下一個天賦（%s）在 %d 級時點。",
