	["Nota de entrenar en tu guía"] = "指南中的訓練提示",
	["Nota libre"] = "自由備註",
	["Notas del lobo"] = "狼的筆記",
	["Novedades de Alfa %s"] = "Alfa %s 新功能",
	["Nozdormu, el Atemporal, cuida el curso del tiempo. Dicen que conoce el día de su propia muerte, y aun así sigue con su deber."] = "永恆者諾茲多姆守護著時間的流動。據說他知道自己死去的那一天，卻依然堅守職責。",
	["Nuestra manada en Discord: ayuda, avisos y reportes. Haz clic en el enlace y cópialo con Ctrl+C."] = "我們在 Discord 上的狼群：協助、公告與問題回報。點擊連結後用 Ctrl+C 複製。",
