	["Oclusión ambiental"] = "環境光遮蔽",
	["Oculta"] = "已隱藏",
	["Oculta el botón con el número de addons en la esquina del minimapa. Esos addons se siguen abriendo con su comando, como /alfa."] = "隱藏小地圖角落顯示插件數量的按鈕。這些插件仍可用各自的指令開啟，例如 /alfa。",
	["Oculta el rastreador del juego a la derecha de la pantalla, con sus misiones, logros y profesiones. No con la interfaz de mando."] = "隱藏畫面右側的遊戲追蹤器，包括其中的任務、成就與專業。使用控制器介面時無效。",
	["Oculta lo que tu clase no puede usar o no le conviene: armadura de otro tipo, armas que no usas, piezas sin nada para tu especialización."] = "隱藏你的職業無法使用或不適合的物品：其他類型的護甲、你不用的武器，以及對你的專精毫無幫助的裝備。",
	["Oculta los avisos que son para otro papel (por ejemplo, los del tanque si tú curas)."] = "隱藏針對其他職責的警報（例如你是治療時隱藏坦克的警報）。",
	["Oculta los mensajes de ataques que van contra otro jugador."] = "隱藏針對其他玩家的攻擊訊息。",
