	["Ocultas"] = "隱藏",
	["Ocultas como en el juego, reveladas, o reveladas con un tono más frío para saber dónde no has estado."] = "像遊戲中一樣隱藏、直接顯示，或以較冷的色調顯示，讓你知道哪裡還沒去過。",
	["Oculto en el modelo."] = "已在模型上隱藏。",
