	["Ojo con tu ruta"] = "注意你的路線",
	["Ojo de pescador"] = "漁夫之眼",
	["Ojo por aquí: %s tiene sus sorpresas."] = "這裡要小心：%s可藏著不少驚喜。",
	["Ojo: %s es de élite"] = "注意：%s 是精英",
	["Ojo: puedes quitar %s, pero ningún clic lo hace. Elígelo en Tus clics."] = "注意：你可以驅散 %s，但沒有設定對應的點擊。請在「你的點擊」中選擇。",
	["Ojo: tu clic para lanzar de Blizzard usa %d de estas teclas, y ese manda también aquí. Para igualarlos, usa «Usar también en los marcos de Blizzard»."] = "注意：你的 Blizzard 點擊施法使用了其中 %d 個按鍵，而且在這裡也會優先生效。若要讓兩者一致，請使用「也套用到 Blizzard 的框架」。",
	["Ojo: tu equipo anda al %d%%. Un herrero te lo deja como nuevo."] = "注意：你的裝備耐久度只剩 %d%%。找鐵匠修一下就跟新的一樣。",
	["Olas y superficie del agua. Llega hasta Ultra (3) y no más: valores mayores pueden cerrar el juego, por eso Alfa no los deja."] = "波浪與水面。最高到「極高（3）」：更高的數值可能導致遊戲當機，所以 Alfa 不允許。",
	["Olor a fogata"] = "營火的煙味",
	["Olvidar"] = "忘記",
	["Olvidar mi progreso aquí"] = "清除我在這裡的進度",
	["Omite este paso: la guía sigue con el siguiente. Puedes volver a él con Anterior."] = "跳過此步驟：指南會繼續下一步。你可以用「上一步」返回。",
	["Omite este paso: la guía sigue con el siguiente. Puedes volver a él desde «Ver detalle»."] = "跳過此步驟：指南會繼續下一步。你可以從「查看詳情」回到這一步。",
	["Omitir"] = "跳過",
