	["Ordenar por nombre"] = "依名字排序",
	["Orgrim Martillo Maldito murió peleando junto a Thrall durante la liberación de un campo de internamiento."] = "奧格林·毀滅之錘在解放一座收容所時，與索爾並肩作戰而死。",
	["Orgrim Martillo Maldito tomó el mando de la Horda y desarmó el Consejo de la Sombra de Gul'dan."] = "奧格林·毀滅之錘接掌了部落，並瓦解了古爾丹的暗影議會。",
	["Orgrimmar"] = "奧格瑪",
	["Orgrimmar está tallada en un cañón, y cada pueblo de la Horda tiene su propio valle dentro de la ciudad."] = "奧格瑪雕鑿在一座峽谷中，部落的每個種族在城裡都有自己的山谷。",
	["Orgrimmar lleva el nombre de Orgrim Martillo Maldito, el jefe de guerra que liberó a Thrall y le dejó su armadura y su martillo."] = "奧格瑪以奧格林·毀滅之錘命名，這位大酋長解救了索爾，並把自己的盔甲與戰錘留給了他。",
	["Orillas de sombra difuminadas, como la luz de verdad."] = "柔化陰影邊緣，就像真實的光線。",
	["Oro"] = "金錢",
