	["PNJ %d"] = "NPC %d",
	["Paciencia de lobo"] = "狼的耐心",
	["Paciencia: lo que se busca con calma, se encuentra."] = "耐心點：靜下心來找，就能找到。",
	["Paisaje"] = "風景",
	["Paisaje de la manada"] = "狼群風景",
