	["Palabras de ánimo"] = "鼓勵的話",
	["Paladín"] = "聖騎士",
	["Pan de especias de Mulgore"] = "莫高雷香料麵包",
	["Pan de maíz húmedo"] = "玉米麵包",
	["Pan de plátano suave"] = "軟香蕉麵包",
	["Pan recién horneado"] = "新鮮麵包",
	["Panel de estadísticas"] = "屬性面板",
	["Pantalla de película para capturas y paseos. Solo cambia cómo se ve: no da más FPS."] = "電影風格的畫面，適合截圖與觀光。只改變外觀：不會提高 FPS。",
	["Pantalla gris al morir"] = "死亡時畫面變灰",
	["Pantalla limpia"] = "清爽畫面",
	["Pantalla limpia: solo lo esencial"] = "清爽畫面：只顯示必要的",
	["Para abandonar"] = "要放棄的任務",
	["Para abrirlo con la tecla del mapa, enciende «Abrir el mapa de Alfa con la tecla del mapa» abajo."] = "要用地圖鍵開啟它，請開啟下方的「用地圖鍵開啟 Alfa 地圖」。",
	["Para adoptar, tu nivel debe pasar el suyo por 10 o más."] = "要收養，你的等級必須比他高 10 級或以上。",
	["Para alguien de tu hermandad, agrega su rango."] = "對你的公會成員，加上他的公會階級。",
	["Para armar la espada legendaria de Thunderaan, el Buscavientos, hacen falta dos ataduras que sueltan Garr y el barón Geddon en el Núcleo de Magma."] = "要組裝風之探尋者桑德蘭王子的傳說之劍，需要熔火之心裡加爾和迦頓男爵掉落的兩個束縛。",
	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "Alfa 會為每件物品比較三種做法：賣給商人、拿去拍賣，或加工成其他東西（用你會的配方或將它分解）。",
	["Para cambiar de plano con la manada, primero deja que te vea en el mapa (ajustes de La Jauría)."] = "要和狼群一起切換位面，先讓它在地圖上看到你（La Jauría 設定）。",
	["Para capturas y paseos. No da más FPS."] = "適合截圖與觀光。不會提高 FPS。",
	["Para cerrar tu rato con todo cobrado"] = "拿齊所有獎勵再收尾",
	["Para cerrarle el paso a la Legión, Malfurion y sus aliados destruyeron el Pozo de la Eternidad. La explosión hundió el centro de Kalimdor."] = "為了把燃燒軍團擋在門外，瑪法里恩和他的盟友摧毀了永恆之井。爆炸讓卡林多的中心沉入海底。",
	["Para comprar espacio, habla con un banquero."] = "要購買空間，請與銀行職員交談。",
	["Para conservar"] = "要保留的",
	["Para cruzar de los Reinos del Este a Kalimdor, toma un barco en el Puerto de Menethil, en Los Humedales."] = "要從東部王國前往卡林多，可以在濕地的米奈希爾港搭船。",
	["Para depositar, habla con un banquero."] = "要存放，請與銀行職員交談。",
	["Para empezar"] = "如何開始",
	["Para encantar necesitas una vara rúnica; con el tiempo la mejoras."] = "附魔需要一根符文棒；以後可以慢慢升級它。",
	["Para entregar"] = "待交付",
	["Para gastar"] = "可用",
	["Para invitar a %s a %s: abre «Hermandad y comunidades», elige %s, pulsa «Invitar a miembro» y escribe: %s"] = "要邀請%s加入%s：打開「公會與社群」，選擇%s，點擊「邀請成員」並輸入：%s",
	["Para ir de Los Humedales a las Tierras Altas de Arathi cruza el Puente Thandol, pero ojo con los Hierro Negro."] = "要從濕地前往阿拉希高地，就得過薩多爾大橋，但要小心黑鐵矮人。",
	["Para las recetas de %s."] = "用於 %s 的配方。",
	["Para leer mejor"] = "更易閱讀",
	["Para llamar a la manada, deja que te vean en el mapa (La Jauría)."] = "想呼喚狼群，請讓他們在地圖上看到你（La Jauría）。",
	["Para llegar a la Fuente del Sol, la Plaga de Arthas arrasó Quel'Thalas y su capital, Lunargenta."] = "為了抵達太陽之井，阿薩斯的天譴軍團摧毀了奎爾薩拉斯和它的首都銀月城。",
	["Para lo que elegiste no hay uno con este estilo: Alfa usa el más cercano."] = "你選的組合沒有這種風格的配點：Alfa 會使用最接近的。",
	["Para marcarlo, clic derecho en su retrato y elige la calavera."] = "要標記它，右鍵點擊它的頭像並選擇骷髏。",
	["Para mi nivel (±3)"] = "適合我的等級（±3）",
	["Para minar torio, el Cráter de Un'Goro y Cuna del Invierno tienen muchas vetas."] = "要挖瑟銀的話，安戈洛環形山和冬泉谷有很多礦脈。",
	["Para mí"] = "適合我",
	["Para no chocar con él, Alfa no reemplaza tus bolsas mientras esté activo. Igual puedes abrir la ventana de Alfa desde aquí."] = "為避免衝突，它啟用期間 Alfa 不會取代你的背包。你仍然可以從這裡開啟 Alfa 的視窗。",
	["Para no moverla sin querer. Sin bloquear, arrástrala a donde quieras."] = "以免不小心移動她。解鎖後可以把她拖到任何地方。",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "避免隊伍重複顯示。只能在戰鬥外變更。",
	["Para proponer una cita, deja que la manada te vea en el mapa."] = "要提議集合，請讓狼群能在地圖上看到你。",
	["Para que no choquen, Alfa no toma tu tecla ni cambia tus ajustes. Desactiva uno de los dos en la lista de addons (pantalla de personajes) y recarga. Si dejas Alfa, tomará sola la tecla que usabas en el otro addon."] = "為避免衝突，Alfa 不會接管你的按鍵，也不會更改你的設定。請在插件清單（角色選擇畫面）中停用其中一個並重新載入。如果保留 Alfa，它會自動沿用你在其他插件用的按鍵。",
	["Para que no dejes botín tirado por falta de espacio."] = "以免因為空間不足而撿不了戰利品。",
	["Para quien prefiere seleccionar con el izquierdo: la cura de ese clic pasa al botón central. Se vuelve a aplicar tu preajuste."] = "適合喜歡用左鍵選取目標的人：原本左鍵的治療會移到中鍵。並會重新套用你的預設方案。",
	["Para recoger ahora"] = "現在可接取",
	["Para subir de nivel"] = "升級所需",
	["Para subir solo, el daño de las sombras ayuda mucho: los hechizos que dañan con el tiempo trabajan por ti."] = "單人升級時，暗影傷害很有幫助：持續傷害法術會替你幹活。",
	["Para tela de nivel bajo, los Defias de los Páramos de Poniente sueltan lino y lana a montones."] = "要找低級布料，西部荒野的迪菲亞會掉落大量亞麻布和毛料。",
	["Para templar la espada élfica Quel'Serrar hay que dejarla en el piso y que Onyxia le eche su aliento de fuego encima."] = "要淬鍊精靈之劍奎爾塞拉，得把它放在地上，讓奧妮克希亞對它噴火。",
	["Para ti"] = "適合你",
	["Para ti ahora"] = "你現在適合的",
	["Para tu %s"] = "%s專屬",
	["Para tu habilidad conviene pescar en: %s."] = "以你的技能，適合在這些地方釣魚：%s。",
	["Para tu nivel"] = "適合你的等級",
	["Para tu nivel (%d)"] = "適合你的等級（%d）",
	["Para tu nivel ahora"] = "現在適合你的等級",
	["Para tu personaje de nivel %d"] = "適合你的 %d 級角色",
	["Para vender"] = "要賣的",
	["Para vender, habla con un comerciante."] = "要出售，請與商人交談。",
	["Para ver cuánto procesador usa cada parte, escribe /console scriptProfile 1 y luego /reload. Hace el juego un poco más lento: cuando termines, /console scriptProfile 0 y /reload."] = "想看每個部分佔用多少 CPU，輸入 /console scriptProfile 1 然後 /reload。這會讓遊戲稍微變慢：用完後輸入 /console scriptProfile 0 並 /reload。",
	["Para ver las guaridas de la manada, deja que te vean en el mapa."] = "想看狼群的巢穴，請讓他們在地圖上看到你。",
	["Para ver y romper los tótems enemigos."] = "用來發現並摧毀敵方圖騰。",
	["Para verlas mejor"] = "讓它們更顯眼",
	["Para volver a acumularla, descansa (o cierra sesión) en una posada o una ciudad."] = "想再次累積，請在旅店或城鎮中休息（或登出）。",
	["Para: %s."] = "用於：%s。",
	["Parada"] = "招架",
	["Parada %d de %d"] = "第 %d/%d 站",
	["Parar"] = "招架",
	["Paras más golpes de otros guerreros y pícaros."] = "招架更多來自其他戰士與盜賊的攻擊。",
	["Paras más golpes."] = "招架更多攻擊。",
	["Paras más golpes: recibes menos daño desde el principio."] = "招架更多攻擊：從一開始就受到更少傷害。",
	["Paras un poco más."] = "招架稍微更多。",
	["Paraste un golpe: el contraataque está listo."] = "你招架了一次攻擊：反擊已就緒。",
	["Paraste un golpe: tu contraataque está listo y desarma al enemigo."] = "你招架了一次攻擊：你的反擊已就緒，還會繳械敵人。",
	["Paraste un golpe: tu contraataque inmoviliza al enemigo."] = "你招架了一次攻擊：你的反擊會讓敵人無法移動。",
	["Partes de Alfa apagadas"] = "已關閉的 Alfa 部分",
	["Partes de Alfa de otra versión"] = "來自其他版本的 Alfa 部分",
	["Partes de Alfa que no cargaron"] = "沒有載入的 Alfa 部分",
	["Paré por el combate: lo demás sigue en el buzón."] = "因戰鬥暫停：其餘的還在信箱裡。",
	["Pasa el ratón por cualquier cosa de Alfa y te digo para qué sirve. Pulsa tu tecla otra vez para terminar."] = "把滑鼠移到 Alfa 的任何東西上，我會告訴你它有什麼用。再按一次你的按鍵結束。",
	["Pasa el ratón sobre un compañero y cúralo con un clic."] = "滑鼠移到隊友上，點擊一下即可治療。",
	["Pasa el ratón sobre un compañero y haz clic: el izquierdo %s y el derecho %s."] = "將滑鼠移到隊友身上並點擊：左鍵%s，右鍵%s。",
	["Pasa enfermedades: quítalas si tu clase puede."] = "他會散播疾病：你的職業能驅散的話就驅散。",
	["Pasa tu build a un amigo o usa el que te pasen."] = "把你的配點分享給朋友，或使用別人分享的配點。",
	["Pasar solo al siguiente paso"] = "自動進入下一步",
	["Pasas tu vida a tu demonio para curarlo."] = "把你的生命值導給你的惡魔來治療牠。",
	["Paso %d"] = "步驟 %d",
	["Paso %d de %d"] = "步驟 %d / %d",
	["Paso a paso"] = "一步一步",
	["Pasos de nivel claros"] = "清楚的等級步驟",
	["Pasos que siguen, numerados"] = "接下來的步驟（附編號）",
	["Pastel de cerezas casero"] = "自製櫻桃派",
	["Pata de jabalí salvaje"] = "野豬腿",
	["Pausa"] = "暫停",
	["Pausa para el lunch: tú comes, yo miro con ojitos tiernos."] = "午餐時間：你吃，我用水汪汪的眼睛看著你。",
	["Peces"] = "魚類",
	["Pecho"] = "胸部",
	["Pedazo de pan duro"] = "硬麵包",
	["Pedir ayuda a la manada"] = "向狼群求助",
	["Pedir entrar"] = "請求進入",
	["Pedir entrar a su guarida (%s)"] = "請求進入他的巢穴（%s）",
	["Pedirle un consejo"] = "向她要一則建議",
	["Pediste %s; el juego lo dejó en %s."] = "你要求的是 %s；遊戲設為了 %s。",
	["Pediste ayuda con %s. Te aviso quién viene."] = "你請求幫忙對付 %s。我會告訴你誰來了。",
	["Pega aquí (Ctrl+V) el texto de una ruta de Alfa."] = "在這裡貼上（Ctrl+V）Alfa 路線的文字。",
	["Pega aquí el texto que copiaste con «Exportar»"] = "在這裡貼上你用「匯出」複製的文字",
	["Pega aquí una cadena que empiece con ALFA1; (Ctrl + V) y pulsa Importar. Alfa revisa cada talento contra tu árbol."] = "在這裡貼上以 ALFA1; 開頭的字串（Ctrl + V），然後按「匯入」。Alfa 會對照你的天賦樹檢查每個天賦。",
	["Pega el texto de «Exportar» para traer esa configuración. Lo de ahora queda guardado como perfil por si acaso."] = "貼上「匯出」的文字來恢復那套設定。為保險起見，目前的設定會儲存為設定檔。",
	["Pega fuerte pero no tiene trucos: es un buen jefe para aprender."] = "攻擊很痛但沒有特別的技巧：是很適合練習的首領。",
	["Pega fuerte y se protege con un escudo de luz: empieza con la vida llena."] = "攻擊很痛，還會用聖光護盾保護自己：滿血再開打。",
	["Pega fuerte: ve con cuidado y con la vida llena."] = "打得很痛：小心點，滿血再上。",
	["Pega muchas veces seguidas al tanque: no dejes que su vida baje de la mitad."] = "他會連續攻擊坦克很多次：不要讓坦克的生命值掉到一半以下。",
	["Pega muy fuerte: empieza la pelea con la vida llena."] = "攻擊非常痛：滿血再開打。",
	["Pega primero una cadena de build de Alfa."] = "請先貼上 Alfa 的配點字串。",
	["Pega primero una cadena de escala de estadísticas."] = "請先貼上屬性權重字串。",
	["Pega una cadena de escala de estadísticas (Ctrl+V), la que copiaste desde donde la compartieron."] = "貼上屬性權重字串（Ctrl+V），也就是你從分享處複製的那段。",
	["Pega varias veces seguidas: empieza con la vida llena."] = "他會連續攻擊好幾次：滿血再開打。",
	["Pegas a dos: útil contra mascotas y grupos."] = "一次打兩個：對付寵物與隊伍時很有用。",
	["Pegas más después de recibir críticos."] = "受到致命一擊後打得更痛。",
	["Pegas más fuerte después de recibir críticos."] = "受到致命一擊後打得更痛。",
	["Pegas más fuerte después de recibir un golpe crítico."] = "受到致命一擊後打得更痛。",
	["Pelea con un solo monstruo a la vez; si vienen dos, usa Golpes de barrido."] = "一次只打一隻怪；如果來了兩隻，就用橫掃攻擊。",
	["Pelea siempre con la vida llena; no encadenes monstruos sin descansar."] = "一律滿血再打；不要不休息就連續拉怪。",
	["Pelear contra otros jugadores: aguantar, frenar y rematar."] = "與其他玩家對戰：撐住、減速、收尾。",
	["Peletería"] = "製皮",
	["Peletería hace cuero con armadura y aguante para la forma de oso."] = "製皮能做出帶有護甲與耐力的皮甲，適合熊形態。",
	["Peletería hace malla para ti; Desuello te da el material sin gastar oro."] = "製皮能幫你做鎖甲；剝皮讓你不花錢就有材料。",
	["Peletería hace piezas de cuero con agilidad y aguante; Desuello te da el cuero."] = "製皮能做出帶有敏捷與耐力的皮甲；剝皮提供皮革。",
	["Peligro"] = "危險",
	["Peligros"] = "危險",
	["Peligrosa para tu nivel"] = "對你的等級很危險",
	["Pendiente"] = "待完成",
	["Pequeñas tareas que Alfa hace por ti al abrir un comerciante, al despojar y al viajar."] = "開啟商人、拾取與旅行時，Alfa 替你做的小事。",
	["Pequeños íconos en cada ataque: si es para el tanque, para quien cura, si se puede quitar o si es mortal."] = "每個攻擊上的小圖示：標示是針對坦克、治療者，是否可以驅散，或是否致命。",
	["Perdimos el rastro de %s: ya no sabemos dónde está."] = "失去了 %s 的蹤跡：已不知道對方在哪裡。",
	["Perfil guardado"] = "設定檔已儲存",
	["Perjuicios que puedes quitar"] = "可驅散的減益效果",
	["Personaje"] = "角色",
	["Pesca"] = "釣魚",
	["Pesca %d/%d"] = "釣魚 %d/%d",
	["Pesca 10 de oro en valor en una sola sesión."] = "在一次釣魚中釣到價值 10 金幣的東西。",
	["Pesca 25 especies distintas."] = "釣到 25 種不同的魚。",
	["Pesca 5 especies distintas en una misma zona."] = "在同一地區釣到 5 種不同的魚。",
	["Pesca 5 especies distintas."] = "釣到 5 種不同的魚。",
	["Pesca de Alfa apagada. Tu tecla y tus ajustes quedan como siempre."] = "Alfa 釣魚功能已關閉。你的按鍵與設定維持原樣。",
	["Pesca de Alfa encendida, pero en pausa mientras otro addon de pesca esté activo."] = "Alfa 釣魚功能已開啟，但在其他釣魚插件啟用期間會暫停。",
	["Pesca de Alfa encendida."] = "Alfa 釣魚功能已開啟。",
	["Pesca en 10 zonas distintas."] = "在 10 個不同的地區釣魚。",
	["Pesca en los bancos de peces que flotan en el agua: dan más que pescar en cualquier lado."] = "在水面上漂著的魚群裡釣魚：收穫比在別處釣多。",
	["Pesca en los bancos de peces que flotan en el agua: dan más y a veces sorpresas."] = "在水面上漂著的魚群裡釣魚：收穫更多，有時還有驚喜。",
	["Pesca un trofeo o un pez de concurso."] = "釣到一條獎盃魚或大賽用魚。",
	["Pesca una hora en una sola sesión."] = "在一次釣魚中連續釣一小時。",
	["Pesca: si te atacan mientras vuelve tu equipo normal, ya no pierdes piezas."] = "釣魚：如果你在換回平常裝備時遭到攻擊，不會再遺失裝備。",
	["Pescando"] = "釣魚中",
	["Pescar %d más"] = "再釣 %d 條",
	["Pescar %s: llevas %s"] = "釣%s：目前 %s",
	["Pescar un pez en particular…"] = "釣某一種特定的魚…",
	["Pescar: lanzar y recoger"] = "釣魚：拋竿與收竿",
	["Pescar: volver a lanzar"] = "釣魚：重新拋竿",
	["Pescaste %d."] = "你釣到了 %d 條。",
	["Pesos de %s activos: las flechas de mejora ya los usan."] = "%s的權重已啟用：提升箭頭已在使用。",
	["Pestaña nueva"] = "新分頁",
	["Pestañas con el estilo"] = "分頁套用風格",
	["Pez"] = "魚",
	["Picadura de serpiente: daño con el tiempo."] = "毒蛇釘刺：持續傷害。",
	["Pide %d de Cocina y aprender la receta."] = "需要烹飪 %d 並學會配方。",
	["Pide %d de habilidad de pesca."] = "需要釣魚技能 %d。",
	["Pide al grupo que espere unos segundos antes de atacar."] = "請隊友等幾秒再開始攻擊。",
	["Pide ayuda con %s."] = "請求幫忙對付 %s。",
	["Pide ayuda con un élite o un raro: los lobos de tu zona reciben tu lugar y te avisa quién viene."] = "遇到精英或稀有怪就請求幫助：區域裡的狼會收到你的位置，你會知道誰來了。",
	["Pide ayuda donde está."] = "在所在位置請求幫助。",
	["Pide grupo"] = "需要組隊",
	["Pide «Cerrar mis misiones» en Ruta: te llevo a terminar las que llevas y luego a entregarlas, en el mejor orden."] = "在「路線」裡選「完成我的任務」：我照最佳順序帶你做完再交掉。",
	["Pidiendo los precios a la subasta..."] = "正在向拍賣場索取價格...",
	["Piedra"] = "岩石",
	["Piedra de hogar a tiempo"] = "爐石正是時候",
	["Piel o armadura demoníaca"] = "惡魔皮膚或魔甲術",
	["Pierna de carne"] = "大塊肉",
	["Piernas"] = "腿部",
	["Pies"] = "腳部",
	["Piezas de cuero basto: lo que te enseñe tu instructor o un patrón."] = "硬甲皮製品：訓練師或圖樣教你的那些。",
	["Piezas de cuero cosido a mano que te enseñe tu instructor."] = "訓練師教你的手工皮製品。",
	["Piezas de cuero grueso que te enseñe tu instructor."] = "訓練師教你的厚皮製品。",
	["Piezas de cuero pesado que te enseñe tu instructor."] = "訓練師教你的重皮製品。",
	["Piezas de hierro y de acero que te enseñe tu instructor."] = "訓練師教你的鐵和鋼製品。",
	["Piezas de mitril: lo que tu instructor te enseña con barras de mitril."] = "秘銀製品：訓練師教你用秘銀錠做的那些。",
	["Piezas de torio: lo que tu instructor te enseña con barras de torio."] = "瑟銀製品：訓練師教你用瑟銀錠做的那些。",
	["Pinta del color de la clase el fondo del nombre en tu marco y en el del objetivo cuando es un jugador."] = "將你的框架、以及目標為玩家時的目標框架，名字背景改為職業顏色。",
	["Pizarra"] = "石板",
	["Placas"] = "鎧甲",
