	["Poco probable (%d)"] = "不太可能（%d）",
	["Pocos"] = "較少",
	["Pocos lugares de %s en %s"] = "%s地點很少（%s）",
	["Pocos precios"] = "價格資料不多",
	["Poder a distancia"] = "遠程攻擊強度",
	["Poder arcano: más daño un rato, mientras te sobre maná."] = "秘法強化：一段時間內傷害提高，法力有餘時使用。",
	["Poder con hechizos"] = "法術能量",
	["Poder de ataque"] = "攻擊強度",
	["Poder de ataque a distancia"] = "遠程攻擊強度",
	["Polestar es de código abierto:"] = "Polestar 是開源的：",
	["Polvo arcano"] = "魔粉",
	["Polvo cegador"] = "閃光粉",
	["Pon Seccionar en cuanto llegues al rival y mantenlo puesto."] = "一接近對手就上斷筋，並保持效果。",
	["Pon ahora"] = "現在點",
	["Pon todos tus hechizos de daño en el tiempo y deja que tu demonio aguante."] = "上好所有持續傷害法術，讓你的惡魔扛住怪物。",
	["Pon tu escudo y tu daño en el tiempo antes de que el monstruo llegue."] = "在怪物靠近前，先上護盾與持續傷害。",
	["Pon tu objeto en la pestaña de vender: a un lado te digo su precio sugerido, cómo le fue estos días y te aviso si lo das muy barato. El precio lo pones tú."] = "把物品放進出售欄：我會在旁邊告訴你建議價格、這幾天的行情，賣太便宜時提醒你。價格由你決定。",
	["Pon tu piedra de hogar en la posada donde tengas más misiones."] = "把爐石綁定在你任務最多的那間旅店。",
	["Pon tu tótem abrasador: dispara al enemigo por ti."] = "放下灼熱圖騰：它會替你攻擊敵人。",
	["Pon tus tótems al empezar cada pelea grande."] = "每場大戰開始時放下你的圖騰。",
	["Pon un cebo 10 veces."] = "上魚餌 10 次。",
	["Pon un tótem antes de empezar la pelea."] = "開打前先放一個圖騰。",
	["Pon una trampa antes de empezar la pelea y lleva al monstruo hacia ella."] = "開打前先放陷阱，再把怪物引過去。",
	["Pon venenos en tus armas siempre."] = "武器上一定要上毒藥。",
	["Pone el enlace en el chat."] = "把連結貼到聊天中。",
	["Pone la flecha ahí."] = "把箭頭設在那裡。",
	["Pone los ajustes de un perfil que guardaste. Algunas cosas se ven completas al recargar."] = "套用你儲存的設定檔。有些內容重新載入後才會完整顯示。",
	["Pone los marcos donde estaban al instalar Alfa."] = "將框架移回安裝 Alfa 時的位置。",
	["Pone tres ataques de prueba en la línea de tiempo para que veas dónde sale. Se borran solos. Para moverla: menú del juego (Esc) > Modo de edición."] = "在時間軸上放三個測試攻擊，讓你看到它顯示在哪裡。它們會自動消失。要移動它：遊戲選單（Esc）> 編輯模式。",
	["Pone una maldición que baja la curación que recibes: quítala si tu clase puede."] = "他會施放降低受到治療量的詛咒：你的職業能解除的話就解除。",
	["Pone una maldición que te debilita y un fuego que quema poco a poco: quita la maldición si puedes."] = "他會施放削弱你的詛咒，以及持續灼燒的火焰：能解除詛咒的話就解除。",
	["Poner el cebo"] = "上魚餌",
	["Poner la flecha aquí"] = "把箭頭設在這裡",
	["Poner la flecha hasta ahí"] = "把箭頭指向那裡",
	["Ponerme el equipo de pesca"] = "換上我的釣魚裝備",
	["Ponerme lo de pesca"] = "換上釣魚裝備",
	["Ponerme una meta"] = "給自己定個目標",
	["Ponerte la recompensa si es mejor"] = "獎勵更好時就裝備上",
	["Ponlo de espaldas al grupo para que su golpe solo te dé a ti."] = "讓他背對隊伍，這樣他的攻擊只會打到你。",
	["Ponlo de espaldas al grupo y aguanta: la pelea es corta."] = "讓他背對隊伍並撐住：這場戰鬥很短。",
	["Ponlos al empezar a pelear."] = "戰鬥開始時放下圖騰。",
	["Ponte esto"] = "穿上這個",
	["Ponte la caña primero."] = "請先裝備魚竿。",
	["Ponte un conjunto guardado o guarda lo que llevas puesto."] = "穿上已儲存的設定，或儲存身上的裝備。",
	["Ponte un escudo antes de empezar cada pelea."] = "每場戰鬥開始前先上護盾。",
	["Ponte una meta: un pez, capturas, tiempo o valor."] = "定個目標：一種魚、漁獲數、時間或價值。",
	["Ponérmelo"] = "裝備上",
	["Por Costa Oscura anda un explorador de la Liga muy despistado, que siempre necesita que alguien le eche la mano."] = "黑海岸有一位非常迷糊的探險者協會勘探員，總是需要有人幫他一把。",
	["Por ahora, guárdalo todo"] = "目前全部保留",
	["Por bolsa"] = "依背包",
	["Por categorías"] = "依分類",
	["Por clase"] = "依職業",
	["Por debajo de tu nivel"] = "低於你的等級",
	["Por defecto"] = "預設",
	["Por dentro, Alfa está construido sobre Polestar, de fitzforge y The Polestar authors (GPL-3.0): su motor de guías, flecha y datos. Alfa lo adapta, le suma sus propios módulos y sigue siendo libre."] = "在內部，Alfa 建構於 fitzforge 和 The Polestar authors（GPL-3.0）的 Polestar 之上：它的指南、箭頭和資料引擎。Alfa 加以改編，加入自己的模組，並保持自由。",
	["Por descubrir"] = "未探索",
	["Por dónde sale: %s"] = "傳送途徑：%s",
	["Por dónde se pasa a otra zona (caminos, pasos, túneles y puertas), con una flecha hacia ella y su rango de niveles. Se ven al acercarte a una zona."] = "通往其他地區的地方（道路、山口、隧道與大門），附指向該地區的箭頭及其等級範圍。放大到某個地區時就會顯示。",
	["Por ejemplo: primero un objeto, luego 10 de oro, luego subir cocina y al final el banco."] = "例如：先拿一件物品，然後存 10 金幣，再提升烹飪，最後去銀行。",
	["Por eso empezamos con esta configuración: para que cada quien arme su experiencia a su gusto. Todo se puede cambiar después."] = "所以我們從這個設定開始：讓每個人都能依自己的喜好打造體驗。之後一切都可以變更。",
	["Por estas montañas se llega al Valle de Alterac, donde la Guardia Pico Tormenta y el clan Lobo Gélido pelean sin descanso."] = "穿過這些山脈就能到達奧特蘭克山谷，雷矛衛隊和霜狼氏族在那裡無休止地戰鬥。",
	["Por grupo"] = "依小隊",
	["Por honor (JcJ)"] = "榮譽兌換（PvP）",
	["Por hora"] = "每小時",
	["Por hora: %s"] = "每小時：%s",
	["Por la Alianza mandan Bolvar como regente en Ventormenta, Magni en Forjaz, Tyrande en Darnassus y Mekkatorque con los gnomos."] = "聯盟方面，柏瓦爾以攝政王身分統治暴風城，麥格尼統治鐵爐堡，泰蘭妲統治達納蘇斯，梅卡托克領導地精。",
	["Por la selva de Feralas caminan gigantes enormes. ¡Cuidado con sus pisadas!"] = "菲拉斯的叢林裡走著巨大的巨人。小心他們的腳步！",
	["Por lograr"] = "尚未達成",
	["Por los canales de Entrañas corre una baba verde que mejor ni probar."] = "幽暗城的運河裡流著綠色的黏液，最好別嚐。",
	["Por mazmorra"] = "依地城",
	["Por nivel: jefes, botín, misiones, la entrada y consejos."] = "依等級：首領、戰利品、任務、入口與提示。",
	["Por nombre"] = "依名字",
	["Por nombre, tipo o calidad (verde, azul...) y por nivel de objeto: 20, >20, 20-30. Lo que coincide se resalta."] = "依名稱、類型或品質（綠色、藍色……）以及物品等級搜尋：20、>20、20-30。符合的會標示出來。",
	["Por reputación"] = "聲望兌換",
	["Por rol"] = "依角色定位",
	["Por terminar"] = "進行中",
	["Por una salchicha te sigo hasta Rasganorte. Bueno, te seguiría igual."] = "為了一根香腸，我能跟你去北裂境。好吧，沒有香腸我也會跟著你。",
	["Por unos segundos no recibes daño físico. Tu salvavidas cuando las cosas se ponen feas."] = "幾秒內你不受任何物理傷害。情況變糟時的救命技。",
	["Por zona (este personaje)"] = "依地區（此角色）",
	["Porcentaje de vida"] = "生命值百分比",
	["Portal a %s"] = "通往%s的傳送門",
	["Portales"] = "傳送門",
	["Posada"] = "旅店",
	["Posada de %s"] = "%s旅店",
	["Posadas"] = "旅店",
	["Posadero"] = "旅店老闆",
	["Posaderos"] = "旅店老闆",
	["Posaderos; se marca el de tu piedra de hogar."] = "旅店老闆；你爐石綁定的那位會被標記。",
	["Preajuste «%s» listo para tus clics."] = "預設方案「%s」已套用到你的點擊配置。",
	["Preajustes"] = "預設方案",
	["Preajustes listos para usar"] = "可直接使用的預設方案",
	["Preajustes, ajustes escondidos del juego, cámara, placas y filtros para que el mundo se vea mejor."] = "預設、遊戲隱藏設定、鏡頭、名條與濾鏡，讓世界看起來更美。",
	["Precio"] = "價格",
	["Precio de %s"] = "%s的價格",
	["Precio sugerido"] = "建議價格",
	["Precios %s · %s objetos"] = "價格 %s · %s 件物品",
	["Precios al día"] = "價格是最新的",
	["Precios de la subasta"] = "拍賣價格",
	["Precios viejos"] = "價格已過時",
	["Precios y qué conviene vender."] = "價格以及什麼值得賣。",
	["Precisión"] = "命中",
	["Precisión con hechizos"] = "法術命中",
	["Preguntar a la manada"] = "詢問狼群",
	["Preguntas"] = "問題",
	["Pregúntale a Lya"] = "問問莉婭",
	["Pregúntale a Lya: clic derecho en ella y «¿En qué te ayudo?». Te explica cada parte de Alfa y te lleva con un clic."] = "問問莉婭：右鍵她選「我能幫你什麼？」。她講解 Alfa 的每個部分，一點就帶你過去。",
	["Pregúntale a Lya: todo lo de Alfa explicado y a un clic"] = "問問莉婭：Alfa 的一切都有解釋，一點就到",
	["Pregúntale a la manada"] = "問問狼群",
	["Pregúntale a un guardia de la ciudad por el instructor de la profesión."] = "向城裡的守衛詢問專業訓練師的位置。",
	["Premio final: %s"] = "最終獎勵：%s",
	["Premio final: %s de experiencia"] = "最終獎勵：%s 經驗",
	["Premio: %s"] = "獎勵：%s",
	["Prendas de lana que te enseñe tu instructor."] = "訓練師教你的毛料衣物。",
	["Prendas de seda que te enseñe tu instructor."] = "訓練師教你的絲綢衣物。",
	["Prendas de tejido mágico que te enseñe tu instructor."] = "訓練師教你的魔紋布衣物。",
	["Prendas de tela rúnica que te enseñe tu instructor."] = "訓練師教你的符文布衣物。",
	["Prende la ayuda de rotación en Combate: te sugiero qué usar ahora y qué sigue. Solo sugiero; los botones los presionas tú."] = "在「戰鬥」裡打開循環助手：我建議現在用什麼、接下來用什麼。我只建議，按鍵是你按。",
	["Prende la línea de tiempo, los íconos de ayuda y los mensajes medianos y graves."] = "開啟時間軸、輔助圖示，以及中等與嚴重的訊息。",
	["Prende los marcos de Curación: pasas el ratón sobre un compañero y con un clic lo curas."] = "打開「治療」框架：滑鼠移到隊友身上，一鍵治療。",
	["Prende todo el sistema de avisos de jefes de Blizzard: la línea de tiempo y los mensajes en pantalla. Sin esto, lo demás no se ve."] = "開啟 Blizzard 完整的首領警報系統：時間軸與畫面訊息。沒開啟的話，其他設定都不會顯示。",
	["Prender o apagar"] = "開啟或關閉",
	["Prenderlo"] = "開啟",
	["Prepara tus marcos de curación"] = "設定你的治療框架",
	["Prepara tus marcos en 3 pasos"] = "3 步設定你的框架",
	["Preparando %s… %s"] = "正在準備%s… %s",
	["Preparando %s… la ficha se completa sola."] = "正在準備%s… 詳細頁面會自動補齊。",
	["Preparando la enciclopedia…"] = "正在準備百科…",
	["Preparando lo que contiene… la ficha se completa sola."] = "正在準備內含物品… 詳細頁面會自動補齊。",
	["Preparando lo que da… la ficha se completa sola."] = "正在準備提供的東西… 詳細頁面會自動補齊。",
	["Preparando lo que vende y suelta… la ficha se completa sola."] = "正在準備販售與掉落的物品… 詳細頁面會自動補齊。",
	["Preparar la mazmorra"] = "準備地城",
	["Prepárame"] = "幫我準備",
	["Prepárate para entrar"] = "準備進入",
	["Prepárate: llega en %s"] = "準備好：%s後到達",
	["Presencia mental: tu siguiente hechizo es instantáneo."] = "氣定神閒：你的下一個法術變為瞬發。",
	["Primer aviso"] = "第一次提醒",
	["Primer tirón"] = "第一次咬鉤",
	["Primero cobra lo que ya hiciste: una ruta por el camino más corto, junta por PNJ."] = "先交付你已完成的：一條最短路線，依 NPC 分組。",
	["Primero con el banco de la hermandad"] = "優先使用公會銀行",
	["Primero crea una ruta: /alfa recoleccion ruta"] = "請先建立路線：/alfa recoleccion ruta",
	["Primero defensa: paras muchos más golpes y descansas menos."] = "防禦優先：招架更多攻擊，休息更少。",
	["Primero elige tu build"] = "請先選擇你的配點",
	["Primero necesitas %s, que se toma a nivel %d."] = "首先你需要%s，%d 級可接。",
	["Primero pelean contra el Comandante Mograine; cuando cae, ella llega y lo resucita."] = "先和血色十字軍指揮官莫格萊尼戰鬥；他倒下後，她會出現並復活他。",
	["Primero prende la línea de tiempo del jefe."] = "請先開啟首領時間軸。",
	["Primero sale su trituradora; al romperla, Sneed baja y pelea a pie."] = "先出現的是他的伐木機；打壞之後，斯尼德會跳下來徒步戰鬥。",
	["Primero toma %s"] = "先接取%s",
	["Primero un objeto, luego oro, luego una profesión y al final el banco: tú eliges el orden."] = "先拿一件物品，然後金幣，再一項專業，最後去銀行：順序由你決定。",
	["Primero: %s"] = "首先：%s",
	["Primeros auxilios"] = "急救",
	["Primeros auxilios le sirve a cualquier clase, sobre todo a las que no se curan solas."] = "急救對任何職業都有用，尤其是不能自我治療的職業。",
	["Primeros auxilios sirve a cualquier clase: unas vendas te sacan de apuros."] = "急救對任何職業都有用：幾條繃帶就能幫你脫困。",
	["Principal"] = "主要",
	["Principal [mano]"] = "主手",
	["Probador"] = "試衣間",
	["Probar"] = "試試看",
	["Probar con 20"] = "以 20 人測試",
	["Probar con 5"] = "以 5 人測試",
	["Probar el aviso"] = "測試提醒",
	["Probar la línea de tiempo"] = "測試時間軸",
	["Probar la pantalla limpia"] = "試試清爽畫面",
	["Probar la ventana"] = "試用視窗",
	["Probar otra vez"] = "重試",
	["Probar un aviso"] = "測試提醒",
	["Procesador: Alfa usa %.2f ms por cuadro ahora. Lo que más usa:"] = "CPU：Alfa 現在每幀佔用 %.2f 毫秒。佔用最多的：",
	["Procesador: Alfa usó %.0f ms desde que entraste o recargaste. Lo que más usa:"] = "CPU：自你登入或重新載入以來，Alfa 共用了 %.0f 毫秒。佔用最多的：",
	["Profesiones"] = "專業",
	["Profesiones (18): llegar a 150, 225 y 300 en Alquimia, Herrería, Encantamiento, Ingeniería, Peletería y Sastrería."] = "專業（18）：鍊金術、鍛造、附魔、工程學、製皮與裁縫分別達到 150、225 與 300。",
	["Profesiones que te sirven"] = "對你有用的專業",
	["Profesiones: más puntos de habilidad, más recursos al recolectar, mejores precios con los vendedores, más platos y más peces."] = "專業：更多技能點數、採集時獲得更多資源、商人價格更優惠、更多菜餚與更多魚。",
	["Profesión"] = "專業",
	["Promedio de la sesión: %s XP por hora."] = "本次平均：每小時 %s 經驗值。",
	["Promedio de la sesión: %s XP por hora. XP ganada: %s."] = "本次平均：每小時 %s 經驗。獲得經驗：%s。",
	["Proponer"] = "提議",
	["Proponer la siguiente guía"] = "推薦下一個指南",
	["Propusiste una cita"] = "你提議了一次集合",
	["Propón qué, el día y la hora: a los lobos de tu hermandad con Alfa les llega con «Voy». Te recuerdo 15 minutos antes."] = "提議做什麼、哪天、幾點：你公會裡裝了 Alfa 的狼會收到，並附「我去」按鈕。我會提前 15 分鐘提醒你。",
	["Propón una salida a la manada (/alfa cita mañana 21:30 Minas)"] = "向狼群提議一次出遊（/alfa cita tomorrow 21:30 礦坑）",
	["Propón una salida con día y hora y recibe las de tu hermandad con «Voy». Lya te la recuerda 15 minutos antes."] = "提議一次附日期和時間的出遊，並透過「我去」接收公會的提議。莉婭會提前 15 分鐘提醒你。",
	["Protección"] = "防護",
	["Protección [paladín]"] = "防護",
	["Protección para subir"] = "防護（練等）",
	["Protección para subir [paladín]"] = "防護（練等）",
	["Protege a un aliado de todo daño físico un momento. Salva a quien cura."] = "讓一個盟友在片刻內免疫所有物理傷害。救你的治療者。",
	["Proyectiles"] = "彈藥",
	["Prueba"] = "測試",
	["Prueba con %d: arrastra para mover"] = "%d 人測試：拖曳以移動",
	["Prueba con el nombre del pueblo o de la zona."] = "試試城鎮或區域的名字。",
	["Prueba con otra búsqueda o quita un filtro."] = "試試其他搜尋詞或移除一個篩選條件。",
	["Prueba con otra palabra o elige Todas."] = "試試其他詞，或選擇「全部」。",
	["Prueba con otra palabra o quita el filtro."] = "試試別的關鍵字，或取消篩選。",
	["Prueba con otra palabra, como «pasto», «niebla» o «sombras»."] = "試試別的關鍵字，例如「草」、「霧」或「陰影」。",
	["Prueba con otra palabra, en español o en inglés, o quita un filtro."] = "試試其他詞（西班牙文或英文），或移除一個篩選條件。",
	["Prueba con otra palabra."] = "試試其他詞。",
	["Prueba con otro filtro."] = "試試其他篩選條件。",
	["Prueba de Alfa %d"] = "Alfa 測試 %d",
	["Prueba tus clics"] = "測試你的點擊",
	["Pruébala fuera de mazmorras y bandas."] = "請在地城與團隊副本以外的地方測試。",
	["Préndelo para ver jefes, botín, misiones y consejos de cada mazmorra."] = "開啟後可查看每個地城的首領、戰利品、任務與提示。",
	["Préndelos abajo, en «Lya y su manada»."] = "在下方的「莉婭和她的狼群」中開啟。",
	["Publicar"] = "發佈",
	["Puede controlar la mente de un jugador: no lo ataquen, esperen a que se le pase."] = "他會心靈控制一名玩家：不要攻擊那名玩家，等效果結束。",
	["Puede convertir a alguien en huargo: no ataquen a ese jugador, se le pasa solo."] = "他會把人變成狼人：不要攻擊那名玩家，效果會自己消失。",
	["Puede dormir a alguien del grupo: sigue peleando, se despierta solo."] = "她會催眠隊伍中的某人：繼續戰鬥，他會自己醒來。",
	["Puede dormir a alguien y golpear a todos los que están cerca."] = "他會催眠某人，並攻擊附近所有人。",
	["Puede lanzarte por los aires con un gancho: regresa rápido para que no vaya tras quien cura."] = "他的上鉤拳會把你打飛：快點跑回來，以免他去追治療者。",
	["Puede pisotear a los que pelean cuerpo a cuerpo: mantén su vida alta."] = "他會踐踏近戰玩家：讓他們的生命值保持在高檔。",
	["Puede que el archivo se dañara. Tienes un respaldo del %s."] = "檔案可能損壞了。你有一份 %s 的備份。",
	["Puede que hayas omitido lo que queda o que aún no te toque. Elige otra guía o vuelve a esta más adelante."] = "你可能略過了剩下的部分，或者還沒輪到。選擇另一份指南，或稍後再回來。",
	["Puedes Cargar en actitud defensiva: empiezas a tanquear sin cambiar de actitud."] = "你可以在防禦姿態下衝鋒：不必切換姿態就能開始坦怪。",
	["Puedes abrir cerraduras: practica con cajas fuertes y cofres, y ofrécele el servicio a tu grupo."] = "你能開鎖：拿保險箱和寶箱練手，再為你的隊伍提供這項服務。",
	["Puedes cambiar cada tramo."] = "每個路段都可以更換。",
	["Puedes crear comida y agua para todo el grupo. ¡Y si un día aprendes a hacer salchichas, me avisas!"] = "你能為全隊製造食物和水。要是哪天你學會做香腸，記得告訴我！",
	["Puedes desollar casi cualquier bestia que mates: el cuero sale de todos lados."] = "你殺的野獸幾乎都能剝皮：皮革到處都有。",
	["Puedes hacerte amigo de los piratas Velasangre matando goblins de Bahía del Botín... aunque luego los guardias goblin te odiarán."] = "殺藏寶海灣的哥布林可以和血帆海盜交朋友…不過之後哥布林衛兵會恨死你。",
	["Puedes revivir a tus compañeros fuera de combate: en una mazmorra eres de lo más valioso."] = "你能在非戰鬥狀態下復活同伴：在地城裡你是最寶貴的人之一。",
	["Puedes revivirte tú solo al morir. Necesitas un ankh."] = "你死後可以自己復活。需要一個十字章。",
	["Puedes tomarla"] = "你可以接取",
	["Puedes usarlo"] = "你可以使用",
	["Puedes vender %d cosas por unos %s."] = "你可以賣掉 %d 件東西，約 %s。",
	["Puedes vender %s (unos %s)."] = "你可以賣掉%s（約 %s）。",
	["Puedes vender %s por %s."] = "你可以把%s賣出%s。",
	["Puedes volver a ese paso desde «Ver detalle»."] = "你可以從「查看詳情」回到那一步。",
	["Puedo usar"] = "我能使用",
	["Puesto"] = "已套用",
	["Pulsa %s %s"] = "按 %s %s",
	["Pulsa Cocinar: cada clic hace un lote. Tienes que estar junto a un fuego."] = "點擊「烹飪」：每次點擊做一批。你必須在火堆旁邊。",
	["Pulsa Guiarme y la flecha te lleva de parada en parada desde la más cercana."] = "按下「帶我去」，箭頭會從最近的站點開始逐站帶你。",
	["Pulsa una tecla…"] = "請按一個鍵…",
	["Pulsa «Cambiar de plano» en La Jauría o escribe /alfa plano: le pido a un lobo con su guarida abierta en otro plano que te invite. Acepta, y al llegar sales del grupo."] = "在 La Jauría 點「切換位面」或輸入 /alfa plano：我會請一隻在其他位面開著巢穴的狼邀請你。接受邀請，到了之後離開隊伍。",
	["Punta de Torio es el campamento de la Hermandad del Torio, y ahí se juntan Alianza y Horda para hacer negocios."] = "瑟銀哨塔是瑟銀兄弟會的營地，聯盟和部落都在那裡做生意。",
	["Puntería"] = "射擊",
	["Puntería para subir"] = "射擊（練等）",
	["Punto %d de tu build (nivel %d), hasta %d/%d."] = "你配點的第 %d 點（%d 級），到 %d/%d。",
	["Puntos %d a %d de tu build (niveles %d a %d)."] = "你配點的第 %d 到 %d 點（%d 到 %d 級）。",
	["Puntos de ruta"] = "路徑點",
	["Puntos de vuelo"] = "飛行點",
	["Puntos del legado"] = "傳承點數",
	["Puntos por gastar"] = "有未分配點數",
	["Página Ruta"] = "「路線」頁面",
	["Pásale el ratón: en su cuadro te digo lo que ganas y lo que pierdes contra lo que llevas puesto, con números. Lo primero es lo que más le sirve a tu clase."] = "把滑鼠移上去：在它的提示框裡，我會用數字告訴你和身上裝備相比得到和失去什麼。最前面的是對你職業最有用的。",
	["Pégalo en %s del Discord de La Jauría."] = "把它貼到 La Jauría Discord 的 %s。",
	["Pícaro"] = "盜賊",
	["Pídeme el «Circuito de la zona» (página Ruta o el menú del rastreador): junto las que llevas y las que puedes tomar aquí y te llevo por el camino más corto."] = "找我要「區域環線」（路線頁面或追蹤器的選單）：我會把你身上的任務和這裡能接的任務集合起來，帶你走最短的路。",
	["Que Lya te la cuente"] = "讓莉婭說給你聽",
	["Que a ese compañero le falta el buff de tu clase. Pasa el ratón sobre su marco: te digo con qué clic se lo das."] = "表示那名隊友缺少你職業的增益效果。把滑鼠移到他的框架上：我會告訴你用哪個點擊幫他加上。",
	["Que la manada vea a mi personaje en el mapa"] = "讓狼群在地圖上看到我的角色",
	["Que me vean en el mapa"] = "讓他們在地圖上看到我",
	["Queda 1"] = "剩 1 個",
	["Queda lejos: unos %s de camino"] = "距離很遠：約 %s 路程",
	["Quedan %d"] = "剩 %d 個",
	["Quedan %d casillas libres y no llevas nada que convenga vender: guarda algo en el banco."] = "剩餘 %d 個空格，且沒有值得賣的東西：存一些到銀行吧。",
	["Quedan %d casillas libres. Puedes vender %s (unos %s)."] = "剩餘 %d 個空格。你可以賣掉%s（約 %s）。",
	["Quedan %s"] = "剩餘 %s",
	["Quedó sin pasos: agrega tramos o recalcula."] = "沒有任何步驟：請新增路段或重新計算。",
	["Quema al enemigo de golpe y durante un rato. Buen inicio de pelea."] = "立即灼燒敵人並持續燃燒。很好的起手技。",
	["Quema al enemigo un rato."] = "讓敵人燃燒一段時間。",
	["Quien instala Alfa ya tiene encendidos los colores de clase, el cuadro de información, el probador, el minimapa y las barras con el estilo de Alfa."] = "新安裝的 Alfa 已預設開啟職業顏色、滑鼠提示、試衣間、小地圖和 Alfa 風格的快捷列。",
	["Quien lleva la insignia de La Jauría la luce en el borde de su retrato: en el tuyo, el de tu objetivo y el de tu foco."] = "擁有 La Jauría 徽章的人會在頭像邊緣顯示它：你的、你目標的和你專注目標的頭像。",
	["Quien recibe la misión"] = "任務交付人",
	["Quien repara tu equipo"] = "能修理裝備的人",
	["Quien te pegue cuerpo a cuerpo se lastima. Pónsela al que tanquea."] = "近戰攻擊你的人會受到傷害。給你的坦克加上。",
	["Quien use Alfa en tu grupo lo recibe y puede seguirlo."] = "隊伍中使用 Alfa 的人會收到並可以跟隨。",
	["Quienes apoyan y construyen Polestar, el motor en el que se basa Alfa."] = "支持和開發 Polestar 的人們，Polestar 是 Alfa 所依據的引擎。",
	["Quienes apoyan, construyen y reportan errores de Polestar, el motor en el que se basa Alfa."] = "支持、開發 Polestar 並回報其錯誤的人們，Polestar 是 Alfa 所依據的引擎。",
	["Quienes usan Alfa y comparten te ven en su mapa y pueden seguirte, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase cada 10 segundos mientras te mueves (cada 4 minutos si estás quieto), nunca dentro de mazmorras. Va por un canal oculto de Alfa: no sale en el chat, pero alguien que entre a ese canal con otro addon podría leerlo."] = "使用 Alfa 並分享位置的人能在地圖上看到你並跟隨你，你也能跟隨他們。移動時每 10 秒（靜止時每 4 分鐘）傳送你的區域、位置、等級和職業，在地城中從不傳送。它透過 Alfa 的隱藏頻道傳送：不會顯示在聊天中，但用其他插件加入該頻道的人可以讀取。",
	["Quienes van contigo y usan Alfa ven cómo vas en las misiones que comparten."] = "和你同行並使用 Alfa 的人可以看到你在共享任務中的進度。",
	["Quiero"] = "我想要",
	["Quiero unirme"] = "我想加入",
	["Quieto"] = "站立",
	["Quita el corte visible donde termina una capa de sombra y empieza la siguiente."] = "消除一層陰影結束、下一層開始處的明顯接縫。",
	["Quita la columna de botones junto al chat (menú, canales y voz). Los comandos como /s, /g o /canal siguen igual."] = "移除聊天框旁的一列按鈕（選單、頻道與語音）。/s、/g 或 /頻道 等指令照常可用。",
	["Quita los grifos de los lados de la barra principal. Edit Mode también tiene su propia opción para esto."] = "移除主快捷列兩側的獅鷲。編輯模式也有專門的選項可以做到。",
	["Quita magia mala a un aliado, o magia buena a un enemigo."] = "移除盟友身上的有害魔法，或敵人身上的有益魔法。",
	["Quita un perfil que ya no usas. Tus ajustes de ahora no cambian."] = "刪除不再使用的設定檔。你目前的設定不會改變。",
	["Quita un veneno a un aliado."] = "移除盟友身上的一種毒藥。",
	["Quita un veneno o una enfermedad a un aliado."] = "移除盟友身上的一種毒藥或疾病。",
	["Quita una enfermedad. Úsala en lugares llenos de no-muertos."] = "移除一種疾病。在滿是不死族的地方使用。",
	["Quita una maldición a un aliado."] = "移除盟友身上的一個詛咒。",
	["Quita veneno, enfermedad y magia. Úsalo cuando alguien trae algo malo encima."] = "移除毒藥、疾病和魔法。有人身上有討厭的東西時使用。",
