	["Qué guardar"] = "存什麼",
	["Qué habilidad presionar ahora y cuáles siguen, avisos de reacción y el top de daño de tu grupo."] = "現在該按哪個技能、接下來按哪些、反應提醒，以及你隊伍的傷害排行。",
	["Qué habilidad presionar ahora, cuándo cortar, tu amenaza, tus recargas y el resumen de cada pelea."] = "現在該按哪個技能、何時打斷、你的仇恨、你的冷卻，以及每場戰鬥的總結。",
