	["Qué hacer con ella"] = "要怎麼處理它",
	["Qué hacer con lo que llevas"] = "隨身物品怎麼處理",
	["Qué hacías, qué esperabas y qué pasó. Si puedes, cómo hacer que vuelva a pasar."] = "你當時在做什麼、期望發生什麼、實際發生了什麼。如果可以，說說怎樣能讓它再次發生。",
