	["Qué se refleja en el agua: el cielo, el terreno y lo demás."] = "水面反射的內容：天空、地形與其他一切。",
	["Qué se ve"] = "顯示內容",
	["Qué son"] = "是什麼",
	["Qué son, cómo se gana cada uno, en qué se gastan y cuántos tienes."] = "它們是什麼、每一點如何獲得、用在哪裡，以及你有多少。",
	["Qué talento poner ahora y por qué, tu build en dos clics, tu árbol y tu equipo."] = "現在該點哪個天賦及原因、兩下點擊搞定配點、你的天賦樹與裝備。",
	["Qué talento poner y por qué, ayuda de rotación y el daño del grupo."] = "該點哪個天賦及原因、輸出循環助手，以及隊伍的傷害。",
	["Qué tan definidas se ven las sombras del mundo y de los personajes."] = "世界與角色陰影的清晰程度。",
	["Qué tan difíciles pueden ser las misiones que Alfa elige (siempre de las que ya puedes tomar)."] = "Alfa 所選任務的難度上限（一律是你現在就能接的任務）。",
	["Qué tan grande escribe Lya en su globo. También con clic derecho sobre ella."] = "莉婭在氣泡裡寫字的大小。也可以右鍵點她。",
