	["Ravenholdt, la mansión de los pícaros, se esconde en las montañas de Alterac. Si no te invitan, ni la buscas."] = "盜賊的莊園拉文霍德藏在奧特蘭克的山裡。沒人邀請的話，就別去找了。",
