	["Rexxar, el señor de las bestias, recorre los caminos de Desolace con su osa Misha."] = "獸王雷克薩帶著他的熊米莎在淒涼之地的道路上遊蕩。",
	["Rexxar, mitad orco y mitad ogro, es un señor de las bestias que ayudó a fundar Durotar. Siempre lo acompaña su osa Misha."] = "雷克薩是半獸人半巨魔的獸王，曾協助建立杜洛塔。他的熊米莎總是陪在他身邊。",
	["Reír"] = "大笑",
