	["Rueda: zoom  ·  Arrastra: mover  ·  Clic derecho: marcador  ·  Ctrl+clic: llévame"] = "滾輪：縮放  ·  拖曳：移動  ·  右鍵：標記  ·  Ctrl+點擊：帶我去",
