	["Sal de combate y vuelve a intentarlo."] = "請脫離戰鬥後再試一次。",
	["Sal de tu grupo primero: el juego te pasa a la guarida de quien te invita."] = "請先離開隊伍：遊戲會把你帶到邀請你的人的巢穴。",
	["Sal de tu grupo primero: el juego te pasa al plano de quien te invita."] = "先離開你的隊伍：遊戲會把你轉到邀請你的人的位面。",
	["Salchichas que le diste"] = "你給她的香腸",
	["Sale de tu registro. Para hacerla otra vez tendrías que volver a pedirla."] = "它會從你的任務日誌中移除。想再做的話，必須重新接取。",
	["Sale en aguas abiertas; los datos del juego no dicen dónde. Tu diario lo anota cuando lo saques."] = "它來自開闊水域；遊戲資料沒有說明在哪裡。釣到後你的圖鑑會記下來。",
	["Salen de tu registro. Para hacerlas otra vez tendrías que volver a pedirlas."] = "這些任務會從你的任務日誌中移除。想再做的話必須重新接取。",
