	["Sanación"] = "治療",
	["Sanador"] = "治療者",
	["Sangrado fuerte desde el nivel 13; lo necesitas para Heridas profundas."] = "從等級 13 起就有強力的流血；點重傷需要它。",
	["Sangrado fuerte; abre Heridas profundas."] = "強力的流血；解鎖重傷。",
	["Sangre fría: tu siguiente remate es crítico seguro."] = "冷血：你的下一個終結技必定致命一擊。",
	["Sapphiron, el dragón de escarcha de Naxxramas, fue un dragón azul antes de que la Plaga lo levantara."] = "納克薩瑪斯的冰霜巨龍薩菲隆，在被天譴軍團復活之前是一條藍龍。",
	["Sargeras fue el gran campeón del Panteón. De tanto pelear contra demonios concluyó que la creación no tenía remedio, y fundó la Legión Ardiente."] = "薩格拉斯曾是萬神殿的偉大勇士。與惡魔戰鬥太久之後，他認定創造已無可救藥，於是建立了燃燒軍團。",
	["Sastrería"] = "裁縫",
	["Sastrería hace tu ropa con lo que cae en mazmorras, y Encantamiento deshace lo que no usas y mejora tu equipo."] = "裁縫用地城掉落的材料幫你做衣服，附魔則能分解你用不到的東西並強化你的裝備。",
	["Sastrería y Encantamiento: tu equipo siempre al día."] = "裁縫與附魔：讓你的裝備一直跟得上等級。",
	["Scholomance, en la isla de Caer Darrow, es la escuela donde la Plaga enseña nigromancia. Antes fue el hogar de la familia Barov."] = "通靈學院位於凱爾達隆島上，是天譴軍團教授死靈法術的學校。它以前是巴羅夫家族的宅邸。",
	["Se abandona con «Abandonar marcadas», que pide confirmación."] = "用「放棄已標記的任務」放棄，會要求確認。",
	["Se abre a nivel %d: te faltan %d niveles. Mientras, sigue tu ruta."] = "%d 級開放：還差 %d 級。在此期間，繼續你的路線。",
	["Se abre al salir de combate."] = "脫離戰鬥後開啟。",
	["Se abre al terminar %s."] = "完成%s後開放。",
	["Se abren con la B. Elige la vista (todo junto, por categorías o por bolsa), busca por nombre o nivel y arrastra tus bolsas en su barra para cambiarlas."] = "按 B 開啟。選擇檢視（全部合併、依分類或依背包），依名稱或等級搜尋，並在背包列拖曳背包即可替換。",
	["Se acabaron los textos cortados con «…» en Hoy, La Jauría, Buscar cerca y la Enciclopedia."] = "「今天」、La Jauría、「搜尋附近」和百科中不再有被「…」截斷的文字。",
	["Se acabó el aviso «Alfa_Builds se ha bloqueado…»: la ventana de talentos, el clic para lanzar y el Legado ahora los abre el juego, y tus hechizos se lanzan sin problema desde el libro."] = "不會再出現「Alfa_Builds 已被封鎖…」的警告了：天賦視窗、點擊施法與傳承現在都由遊戲自己開啟，你的法術也能從法術書正常施放。",
	["Se acabó tu XP descansada"] = "你的休息經驗用完了",
	["Se acelera a sí mismo y lanza rayos: interrúmpelo."] = "他會為自己加速並施放閃電：打斷他。",
	["Se acelera a sí mismo: interrúmpelo si puedes."] = "他會為自己加速：可以的話就打斷他。",
	["Se activó Claridad: tu siguiente hechizo es gratis."] = "節能施法已觸發：你的下一個法術免費。",
	["Se activó Claridad: tus Misiles arcanos salen gratis."] = "節能施法已觸發：你的秘法飛彈免費。",
	["Se activó Trance de las Sombras: tu Descarga de las Sombras es instantánea."] = "暗影冥思已觸發：你的暗影箭變為瞬發。",
	["Se agregó el sonido %d a tu lista."] = "已將聲音 %d 加入你的清單。",
	["Se aplica al salir de combate."] = "脫離戰鬥後套用。",
	["Se aprende con %s"] = "向%s學習",
	["Se borra el progreso de mazmorras de este personaje. No se puede deshacer."] = "會刪除此角色的地城進度。此動作無法復原。",
	["Se borran las sesiones guardadas de este personaje. La sesión de ahora sigue contando."] = "會刪除此角色已儲存的遊戲記錄。目前這次仍會繼續記錄。",
	["Se borran las sesiones, las zonas y los objetos de este personaje. No se puede deshacer."] = "會刪除此角色的各次記錄、地區與物品資料。此動作無法復原。",
	["Se borran los %d marcadores de todos tus personajes. No se puede deshacer."] = "將刪除你所有角色的 %d 個標記。此操作無法復原。",
	["Se borran los jefes vencidos, las veces completada y el botín anotado de %s para este personaje."] = "會刪除此角色在%s已擊敗的首領、完成次數與記錄的戰利品。",
	["Se borran los precios guardados de la subasta de este reino y facción. Tus recetas se quedan."] = "會刪除此伺服器與陣營已儲存的拍賣價格。你的配方會保留。",
	["Se borran todas las peleas guardadas, también en la ventana del medidor del juego."] = "清除所有已儲存的戰鬥，遊戲傷害統計視窗中的也會清除。",
	["Se borran tus sesiones, tu diario, tus logros y tus metas de este personaje. Tu habilidad de pesca no cambia."] = "會清除此角色的釣魚記錄、圖鑑、成就與目標。你的釣魚技能不會改變。",
	["Se carga al salir de combate"] = "脫離戰鬥後載入",
	["Se cerró el buzón antes de terminar."] = "完成前信箱關閉了。",
	["Se cerró la subasta antes de recibir los precios. Vuelve a intentarlo después."] = "收到價格之前拍賣場就關閉了。請稍後再試。",
	["Se cerró la ventana de clic para lanzar de Blizzard. Vuelve a pulsar «Abrir clic para lanzar» para abrirla."] = "Blizzard 的點擊施法視窗已關閉。再按一次「開啟點擊施法」即可開啟。",
	["Se cumple al llegar a ese nivel."] = "達到該等級時即達成。",
	["Se cura a sí mismo: interrumpe su curación."] = "他會治療自己：打斷他的治療。",
	["Se cura comiendo: mátenlo rápido."] = "他會靠吃東西回血：盡快把他打死。",
	["Se cura: interrúmpelo."] = "他會治療自己：打斷他。",
	["Se descubren todos los jefes de %s, como si la hubieras terminado. Si te equivocas, puedes olvidar tu progreso aquí."] = "會顯示%s的所有首領，就像你已經通關一樣。如果弄錯了，可以在這裡清除你的進度。",
	["Se detuvo al cerrar el banco: guardaste %d y faltaron %d."] = "銀行已關閉，已停止：存入 %d 件，剩下 %d 件。",
	["Se detuvo al entrar en combate: guardaste %d y faltaron %d."] = "進入戰鬥，已停止：存入 %d 件，剩下 %d 件。",
	["Se enciende cuando el enemigo esquiva: pega fuerte y no se puede esquivar. Úsalo en cuanto brille."] = "敵人閃躲後亮起：傷害高且無法被閃躲。一亮就用。",
	["Se enciende tras bloquear, esquivar o parar. Barato y con mucha amenaza: el favorito del tanque."] = "格擋、閃躲或招架後亮起。便宜又仇恨高：坦克的最愛。",
	["Se enfurece al final: guarden su mejor daño."] = "他在最後會狂怒：把最強的輸出留著。",
	["Se enfurece con poca vida: termínenlo rápido."] = "他生命值低時會狂怒：盡快解決他。",
	["Se enfurece y pega más fuerte con el tiempo: mátenlo rápido."] = "他會越來越憤怒，攻擊越來越痛：盡快把他打死。",
	["Se entrega con %s"] = "交給%s",
	["Se entrega dentro"] = "在副本內交付",
	["Se escapó"] = "魚跑掉了",
	["Se fabrica"] = "製造",
	["Se marcan como chatarra"] = "會被標記為垃圾",
	["Se me antoja un buen filete de jabalí. Solo digo."] = "好想吃一塊野豬排。我只是說說。",
	["Se pelea bajo el agua: vigila tu barra de respiración y sube a tomar aire si hace falta."] = "要在水下和他戰鬥：注意你的呼吸條，需要時浮上去換氣。",
	["Se pesca"] = "釣魚獲得",
	["Se protege con su escudo y aturde: ataquen a los otros dos primero."] = "他會用盾牌保護自己並擊昏人：先打另外兩個。",
	["Se puede al salir de combate."] = "脫離戰鬥後即可。",
	["Se puede anunciar al salir de combate."] = "脫離戰鬥後即可通報。",
	["Se puede enviar ahora: %s"] = "現在可以傳送：%s",
	["Se pueden conseguir"] = "可取得",
	["Se pusieron %d ajustes. Algunas cosas se ven completas al recargar."] = "已套用 %d 項設定。有些內容重新載入後才會完整顯示。",
	["Se pusieron %d ajustes. Las líneas que no eran válidas (%d) se dejaron fuera."] = "已套用 %d 項設定。無效的行（%d 行）已略過。",
	["Se pusieron %d de %d opciones"] = "已設定 %d/%d 個選項",
	["Se queda en el modo limpio."] = "維持簡潔模式。",
	["Se quita %s de tu lista de compras."] = "已從你的購物清單中移除 %s。",
	["Se quita de tu lista. Si lo necesitas otra vez, vuelve a importar su cadena."] = "會從你的清單中移除。如果之後還需要，請重新匯入它的字串。",
	["Se quitan los nodos que anotaste al recolectar y cuántas veces los recolectaste. La base incluida se queda. No se puede deshacer."] = "將移除你採集時記錄的採集點及採集次數。內建資料庫會保留。此操作無法復原。",
	["Se quitan todas las metas. Tus objetos no se tocan."] = "所有目標都會被移除。不會動到你的物品。",
	["Se quitó el sonido %d de tu lista."] = "已將聲音 %d 從你的清單移除。",
	["Se saltan (no están en tu árbol): %s."] = "已略過（不在你的天賦樹中）：%s。",
	["Se teletransporta a las orillas de la sala: si peleas cuerpo a cuerpo, síguelo."] = "他會傳送到房間邊緣：近戰職業請跟上他。",
	["Se toma dentro de la mazmorra: ahí la verás."] = "在地城內接取：你會在那裡看到它。",
	["Se ve completo al recargar."] = "重新載入後才會完整顯示。",
	["Se ve después de reiniciar los gráficos."] = "重新啟動圖形後才會顯示。",
	["Se vende ahora"] = "現在就賣",
	["Se vende en"] = "販售處",
	["Se vende en %s cada uno."] = "每個售價 %s。",
	["Seccionar puede inmovilizar al rival: no se te escapa."] = "斷筋可能讓對手無法移動：他逃不掉。",
	["Seccionar puede inmovilizar: nadie se te escapa para traer amigos."] = "斷筋可能讓目標無法移動：沒有人能逃走找救兵。",
	["Secundaria"] = "次要",
	["Secundaria [mano]"] = "副手",
	["Secundario: no cuenta en tus dos"] = "次要專業：不算在你的兩個專業裡",
	["Sed de sangre: tu golpe más fuerte, cada vez que esté listo."] = "嗜血：你最強的攻擊，冷卻好就用。",
	["Seguimiento"] = "跟隨",
	["Seguir"] = "跟隨",
	["Seguir (flecha y ruta)"] = "跟隨（箭頭與路線）",
	["Seguir a %s"] = "跟隨%s",
	["Seguir con %s"] = "繼續%s",
	["Seguir el terreno"] = "隨地形調整",
	["Seguir esta guía"] = "跟隨此指南",
	["Seguir esta ruta"] = "跟隨這條路線",
	["Seguir este build"] = "跟隨這個配點",
	["Seguir este plan"] = "跟隨此計畫",
	["Seguir jugando"] = "繼續遊戲",
	["Seguir muestra tu guía y la flecha, y cierra esta ventana para que las veas."] = "「繼續」會顯示你的指南與箭頭，並關閉此視窗讓你看到它們。",
	["Seguir por aquí"] = "走這條路",
	["Seguir ruta"] = "跟隨路線",
	["Seguir sola con la siguiente guía"] = "自動繼續下一份指南",
	["Seguir un build de %s"] = "跟隨一個%s配點",
	["Segundos junto a la barra"] = "在進度條旁顯示秒數",
	["Según su leyenda, los jabaespines nacieron de la sangre de Agamaggan, el gran jabalí semidiós. Por eso viven entre espinas gigantes."] = "根據他們的傳說，野豬人誕生於野豬半神阿迦瑪甘的鮮血。所以他們住在巨大的荊棘之間。",
	["Seleccionar objetivo"] = "選取目標",
	["Seleccionar para copiar"] = "選取以複製",
	["Seleccionar todo"] = "全選",
	["Seleccionarlo"] = "選取它",
	["Sello"] = "聖印",
	["Semilla de Tuercespina"] = "荊棘谷種子",
	["Semilla de arce"] = "楓樹種子",
	["Semilla de carpe"] = "角樹種子",
	["Semilla de fresno"] = "灰木種子",
	["Semilla de palo de hierro"] = "鐵木種子",
	["Sencillo"] = "簡潔",
	["Sencillo: solo Hoy, Ruta, Mapa, Bolsas y Lya a la vista, y menos avisos. Completo: todo Alfa. Lo demás sigue funcionando."] = "簡潔：只顯示今天、路線、地圖、背包和莉婭，提醒也更少。完整：Alfa 的全部。其他功能照常運作。",
	["Sepia"] = "懷舊棕",
	["Servicio"] = "服務",
	["Servicios"] = "服務",
	["Servicios en el minimapa"] = "小地圖上的服務",
	["Será una mejora más adelante"] = "以後會是提升",
	["Sesiones anteriores"] = "先前的記錄",
	["Sesiones que guarda el diario"] = "日誌保留的遊戲記錄數",
	["Sesiones, diario, logros y metas de este personaje. No se puede deshacer."] = "此角色的釣魚記錄、圖鑑、成就與目標。無法復原。",
	["Sesión de pesca nueva."] = "新的釣魚記錄。",
	["Señalar"] = "指向",
	["Señor de las aguas"] = "水域之主",
	["Si Toxic, el fundador de La Jauría, anda cerca, Alfa te avisa para que lo saludes."] = "如果La Jauría的創始人Toxic在附近，Alfa會提醒你去打個招呼。",
	["Si aguantas bien, usa Golpe heroico con la ira sobrante para más amenaza."] = "如果你撐得住，就用多餘的怒氣施放英勇打擊來增加仇恨。",
	["Si algo sale mal, tu habilidad para desaparecer te saca de la pelea. Úsala antes de que sea tarde."] = "情況不妙時，你的消失技能能讓你脫離戰鬥。要趁還來得及時用。",
	["Si alguien de la manada te pasa uno, impórtalo y Alfa te guía con él punto por punto."] = "如果狼群裡有人給你一個配點，匯入後 Alfa 會一點一點帶你點。",
	["Si alguien de tu grupo también trae Alfa, nuestras Lyas se saludan al juntarse y a veces platican. Es poquito y nunca en combate. Se apaga en mi página: «Lya y su manada»."] = "如果隊伍裡也有人用 Alfa，組隊時我們的莉婭會互相打招呼，有時還會聊幾句。只聊一點點，戰鬥中從不聊。可以在我的頁面關閉：「莉婭和她的狼群」。",
	["Si alguien de tu grupo también trae Alfa, sus Lyas se saludan y a veces platican. Poquito y nunca en combate."] = "如果隊伍裡也有人用 Alfa，你們的莉婭會互相打招呼，有時還會聊幾句。只聊一點點，戰鬥中從不聊。",
	["Si alguien huye, puede traer a más presos: deténganlo con un ataque que lo frene."] = "如果有敵人逃跑，可能會引來更多囚犯：用減速技能攔住他。",
	["Si alguna vez ves salchichas en una posada, guárdame una… o dos."] = "要是在旅店看到香腸，幫我留一根……或兩根。",
	["Si bajas por el Gran Elevador, verás por qué se llama así: cientos de agujas de roca."] = "搭大升降梯下去，你就會明白為什麼叫這個名字：數百根石針。",
	["Si casi todo lo que vas a entregar está en el pueblo de tu piedra y estás lejos, Lya te lo dice."] = "如果你要交的幾乎都在爐石所在的城鎮，而你離得很遠，莉婭會告訴你。",
	["Si cierras tres veces el mismo tipo de consejo, Lya te pregunta si ya no quieres que te lo diga."] = "如果你關掉同一類建議三次，莉婭會問你是否不想再聽了。",
	["Si en estas fechas ves calabazas en las posadas, es Halloween: los posaderos te dan dulces con truco o trato, y a veces un disfraz."] = "如果這個時候你在旅店看到南瓜，那就是萬鬼節：旅店老闆會在不給糖就搗蛋時給你糖果，有時還有服裝。",
	["Si en estas fechas ves faroles y fuegos artificiales, es el Festival Lunar: visita a los Ancestros por el mundo, que cada uno te da una moneda."] = "如果這個時候你看到燈籠和煙火，那就是春節：去拜訪世界各地的長者，每位都會給你一枚硬幣。",
	["Si en febrero las ciudades huelen a perfume, es «Amor en el aire»: la gente reparte regalos y hasta los guardias reciben detalles."] = "如果二月的城市裡飄著香水味，那就是「情人節」：人們互贈禮物，連衛兵都會收到小禮物。",
	["Si encuentras un hueso, es mío. ¿Trato hecho?"] = "要是找到骨頭，就歸我了。說好囉？",
	["Si eres desollador, las zonas llenas de bestias, como raptores, kodos o felinos, te dan cuero sin parar."] = "如果你是剝皮者，到處是野獸的地區，比如迅猛龍、科多獸或豹子，能源源不斷地給你皮革。",
	["Si está fuera de tu alcance, su marco se ve más tenue."] = "隊友超出你的施法距離時，其框架會變淡。",
	["Si estás en combate, espera a que termine."] = "如果在戰鬥中，會等戰鬥結束。",
	["Si fabricas para otros, cobra justo: la gente vuelve y te recomienda."] = "如果你為別人製作物品，收費要公道：人家會回頭並推薦你。",
	["Si hay fiesta te lo digo al entrar. Y según la hora y la zona te cuento lo que pasa por ahí."] = "如果有節慶，你登入時我會告訴你。我還會依時間和區域，告訴你附近在發生什麼。",
	["Si hoy cuesta, mañana sale. Aquí sigo contigo."] = "今天不順，明天就會好。我還在這裡陪著你。",
	["Si juegas sin grupo, la ventana se esconde."] = "不在隊伍中時，視窗會隱藏。",
	["Si la abandonas, pierdes la cadena: después sigue “%s”."] = "放棄的話，你會失去這條任務鏈：接下來是「%s」。",
	["Si la pelea va mal, desvanécete y vuelve a empezar."] = "如果戰鬥不順，就用消失脫身再重新開始。",
	["Si la recompensa tiene varias opciones, eliges tú."] = "如果獎勵有多個選項，由你選擇。",
	["Si la terminas"] = "如果完成它",
	["Si la vida baja de la mitad y el sanador no llega, usa Último recurso."] = "如果生命值掉到一半以下而治療者補不上，就使用破釜沉舟。",
	["Si le dices «Ya no» a un consejo, sale aquí para que puedas devolverlo cuando quieras."] = "如果你對某條建議說「不用了」，它會出現在這裡，隨時可以恢復。",
	["Si le haces el gesto de gallina a una gallina de granja muchas veces, a veces te pide ayuda... y la historia termina en mascota."] = "如果你對農場的小雞做很多次小雞表情，有時牠會向你求助…故事的結局是一隻寵物。",
	["Si levantas algo que se puede regalar y le sirve a un lobo conectado, Alfa te lo dice con «Regalárselo»."] = "如果你拾取到可以贈送、而線上的狼用得上的東西，Alfa 會用「送給他」告訴你。",
	["Si llega a 0 % se rompe y deja de darte sus estadísticas. Repara cuanto antes con un herrero o un vendedor que repare."] = "耐久度降到 0% 就會損壞，不再提供任何屬性。請盡快找鐵匠或能修理的商人修理。",
	["Si llegas a exaltado con otra raza de tu bando, te venden sus monturas. ¡Un kodo para un orco o un sable de la noche para un humano!"] = "如果你和本陣營另一個種族達到崇拜，他們就會賣坐騎給你。獸人騎科多獸，人類騎夜刃豹！",
	["Si llevas puesto el abalorio del Alba Argenta, los no-muertos de las Tierras de la Peste sueltan piedras que cambias por reputación y fichas."] = "如果你戴著銀色黎明的飾品，瘟疫之地的不死族會掉落石頭，可以換取聲望和徽記。",
	["Si lo que te dan mejora tu equipo, te lo pones al salir de combate."] = "如果得到的東西能提升你的裝備，脫離戰鬥後就會自動裝備。",
	["Si moviste los avisos y ya no los encuentras."] = "如果你移動過提醒後找不到它們。",
	["Si mueres seguido, cambia al estilo Tranquilo."] = "如果你常常死，就改成「穩健」風格。",
	["Si necesitas silencio, con clic derecho me callas un rato."] = "如果你需要安靜，右鍵點我，我就安靜一會兒。",
	["Si no eres druida, al Claro de la Luna se llega por los túneles de los Fauces de Madera, desde Frondavil."] = "如果你不是德魯伊，就要從費伍德森林穿過木喉隧道才能到月光林地。",
	["Si no eres tanque: con cuánta amenaza se pone amarilla."] = "如果你不是坦克：仇恨到多少時變黃。",
	["Si no tienes ninguna abierta, abre la recomendada para tu nivel."] = "如果你沒有開啟任何指南，就開啟適合你等級的推薦指南。",
	["Si nos perdemos en %s, tú lees el mapa y yo sigo el rastro."] = "如果我們在%s迷路了，你看地圖，我來追蹤氣味。",
	["Si peleas de lejos, quédate lejos de ella."] = "遠程職業請離她遠一點。",
	["Si quieres matar más rápido en solitario, cambia a Armas cuando tengas oro para reiniciar."] = "如果想單練時殺得更快，等有錢重置天賦時就改點武器。",
	["Si quieres, tu personaje aparece en el mapa del juego de los lobos que usan Alfa, y ellos en el tuyo: quién anda cerca, dónde y, con un clic, la flecha te lleva. Solo es el lugar de tu personaje dentro de WoW, nunca tu ubicación real. Tu grupo se ve siempre."] = "如果你願意，你的角色會出現在使用 Alfa 的狼的遊戲地圖上，牠們也會出現在你的地圖上：誰在附近、在哪裡，點一下箭頭就會帶你過去。這只是你的角色在 WoW 中的位置，絕不是你的真實位置。你的隊伍一律可見。",
	["Si sigues el consejo"] = "照建議處理",
	["Si sigues la cadena del mariscal Windsor, en Ventormenta destaparás quién es en realidad Lady Prestor."] = "跟著溫德索爾元帥的任務鏈走，你會在暴風城揭穿普瑞斯托女士的真面目。",
	["Si sigues la historia del Templo Sumergido, en el pantano te espera Itharius, un dragón verde."] = "如果你繼續追查沉沒的神廟的故事，綠龍伊薩里奧斯會在沼澤裡等你。",
	["Si sigues los consejos"] = "照建議處理",
	["Si sigues los consejos ganas %s"] = "依建議操作可賺 %s",
	["Si sueltan poco, no te desesperes. Pasa en toda buena caza."] = "掉得少也別灰心。好的狩獵都會這樣。",
	["Si te alcanzan, usa tus golpes cuerpo a cuerpo y aléjate otra vez."] = "如果被追上了，就用近戰攻擊，然後再拉開距離。",
	["Si te baja mucho la vida, cambia a actitud defensiva: tu ira no se pierde."] = "如果生命值掉很多，就切換到防禦姿態：你的怒氣不會損失。",
	["Si te invitan a su grupo, acepta con el botón del juego: el juego te pasa a su guarida al rato."] = "如果他們邀請你入隊，用遊戲按鈕接受：不久後遊戲會帶你去他們的巢穴。",
	["Si te invitan a su grupo, acepta con el botón del juego: el juego te pasa a su plano al rato."] = "如果他們邀請你入隊，用遊戲的按鈕接受：遊戲很快就會把你轉到他們的位面。",
	["Si te llega equipo mejor que lo que llevas, te aviso con «Ponte esto» y un botón para ponértelo. Solo con tu clic, y nunca en combate."] = "如果你拿到比身上更好的裝備，我會用「穿上這個」告訴你，並附上裝備按鈕。只在你點擊時，戰鬥中絕不會。",
	["Si te pegan mientras te vendas, se corta: aléjate un poco antes de usarla."] = "包紮時被打就會中斷：使用前先稍微走遠一點。",
	["Si te quedas sin lanzar"] = "如果你停止拋竿",
	["Si te sobra un pedacito de carne, aquí hay una panza que lo recibe con gusto."] = "如果你還剩一小塊肉，這裡有個肚子很樂意收下。",
	["Si tienes poco tiempo, si no tienes con quién jugar o quién te ayude, puedes apoyarte en Alfa y en Lya en tu travesía."] = "如果你時間不多，或者沒人一起玩、沒人幫你，可以在旅途中依靠 Alfa 與 Lya。",
	["Si tu caña no tiene cebo, tu tecla pone el mejor que tengas (o el que prefieras) antes de lanzar."] = "如果魚竿上沒有魚餌，你的按鍵會在拋竿前裝上你最好的魚餌（或你偏好的那種）。",
	["Si tu clase lo puede quitar, su marco se pinta del color del perjuicio y sale su ícono arriba a la derecha. Pasa el ratón y te digo con qué clic se quita; si ningún clic lo hace, elígelo en «Tus clics»."] = "如果你的職業能驅散，他的框架會染成該減益效果的顏色，右上角顯示它的圖示。滑鼠移上去我會告訴你用哪個點擊驅散；如果沒有，請在「你的點擊」中選擇。",
	["Si tu objetivo es un jugador, su fondo toma el color de su clase en lugar del de su reacción."] = "如果你的目標是玩家，其背景會使用職業顏色，而不是敵友關係的顏色。",
	["Si tu plano se llena de cazadores, Lya te propone pasarte al de un lobo de la manada con su guarida abierta. Una vez cada 15 minutos."] = "如果你的位面擠滿了獵人，莉婭會建議你轉到一隻開著巢穴的狼群夥伴的位面。每 15 分鐘一次。",
	["Si tu rango lo permite, la hermandad paga y tu dinero pone el resto."] = "如果你的公會階級允許，就由公會支付，不足部分用你自己的錢。",
	["Si tú o tus personajes pueden"] = "你或你的角色會附魔時",
	["Si un día ganamos mucho oro, yo ya sé en qué gastarlo: salchichas."] = "要是哪天我們賺了好多金幣，我早就想好怎麼花了：香腸。",
	["Si un enemigo te persigue, no corras: acércate al tanque."] = "如果有敵人追你，不要亂跑：靠近坦克。",
	["Si un enemigo viene hacia ti, llévalo hacia el tanque: no corras lejos."] = "如果有敵人衝向你，把它帶到坦克身邊：不要跑遠。",
	["Si un lobo de tu hermandad busca un objeto que llevas, Alfa le dice cuántos tienes. Solo eso y solo cuando pregunta."] = "如果公會裡的狼在找你身上帶的物品，Alfa 會告訴他你有幾個。只有這個，而且只在他問的時候。",
	["Si un lugar está lleno de jugadores farmeando lo mismo, cámbiate de zona: te rinde más."] = "如果某個地方擠滿了刷同樣東西的玩家，就換個地區：收穫會更多。",
	["Si un monstruo esquiva, usa Abrumar enseguida (Alfa te avisa)."] = "如果怪物閃躲了，立刻使用壓制（Alfa 會提醒你）。",
	["Si una misión se pone difícil, pide ayuda en el chat. En manada todo pesa menos."] = "任務變難時，就在聊天裡求助。在狼群中，一切都會輕鬆些。",
	["Si una subasta no se vende, pierdes el depósito: no pongas precios fuera de la realidad."] = "拍賣沒賣出去的話，你會損失保證金：別定離譜的價格。",
	["Si vendes todo al comerciante"] = "全部賣給商人",
	["Si ves a otro lobo por ahí, salúdalo de mi parte."] = "如果你在附近看到別的狼，替我打個招呼。",
	["Si ves carpas de colores en Villadorada o en Mulgore, llegó la Feria de la Luna Negra: hay juegos, premios y cartas que se juntan en mazos."] = "如果你在閃金鎮或莫高雷看到彩色帳篷，就是暗月馬戲團來了：有遊戲、獎品，還有能湊成整套的卡片。",
	["Si viajas con un mago, pídele un portal a la capital: te ahorra mucho camino."] = "如果和法師同行，請他開一個去主城的傳送門：能省下很多路。",
	["Siempre"] = "總是",
	["Siempre con cebo"] = "一律帶餌",
	["Siempre: te ofrece la historia de cada misión y un dato de cada zona nueva. A veces: de las misiones que tomas sin leer, y no siempre. Solo si le pido: con clic derecho, «Cuéntame algo de aquí». Las historias se guardan igual."] = "總是：她會提議說每個任務的故事，以及每個新地區的一則趣聞。有時：針對你沒讀就接下的任務，而且不是每次都說。只在我要求時：右鍵點擊「跟我說說這裡」。無論如何故事都會被保存。",
	["Siete días de caza contigo. Esto ya es costumbre, y me encanta."] = "和你一起狩獵七天了。這已經成了習慣，我好喜歡。",
	["Sigilo"] = "潛行",
	["Sigilo y emboscadas: tú eliges cuándo pelear y desapareces cuando quieres."] = "潛行與伏擊：由你決定何時開打，想消失就消失。",
	["Siglos después de la División, los Altonato que no soltaban la magia arcana fueron desterrados. Cruzaron el mar y fundaron Quel'Thalas: son los altos elfos."] = "大分裂之後數百年，不肯放棄秘法魔法的上層精靈被流放。他們渡海建立了奎爾薩拉斯：他們就是高等精靈。",
	["Siglos después, los orcos Faucedraco usaron el Alma de Demonio para tener presa a Alexstrasza y criar dragones de guerra para la Horda."] = "數百年後，龍喉獸人利用惡魔之魂囚禁了雅立史卓莎，為部落繁育戰龍。",
	["Sigue a tu lado, pero no habla hasta las %s."] = "她還在你身邊，但要到 %s 才會說話。",
	["Sigue a tu lado, pero no habla por un rato."] = "她還在你身邊，只是暫時不說話。",
	["Sigue con los pasos de la guía"] = "繼續照著指南的步驟來",
	["Sigue donde ibas"] = "繼續上次進度",
	["Sigue la flecha."] = "跟著箭頭走。",
	["Sigue la flecha: las paradas van en el orden más corto, juntas por PNJ."] = "跟著箭頭走：站點依最短順序排列，依 NPC 分組。",
	["Sigue subiendo: %d de %d"] = "繼續提升：%d / %d",
	["Sigue tu guía"] = "跟著你的指南",
	["Sigue: %s"] = "下一步：%s",
	["Sigue: %s. Lee sus consejos antes de la pelea."] = "下一個：%s。戰鬥前先看它的提示。",
	["Sigues a %s"] = "正在跟隨%s",
	["Sigues con tu equipo de pesca."] = "你還穿著釣魚裝備。",
	["Siguiendo"] = "跟隨中",
	["Siguiendo a %s."] = "正在跟隨 %s。",
	["Siguiendo el rastro"] = "正在追蹤",
	["Siguiendo el rastro de %s. La flecha te lleva hasta su posición."] = "正在追蹤 %s 的蹤跡。箭頭會帶你到對方的位置。",
	["Siguiendo tu ruta de %s"] = "正在跟隨你的%s路線",
	["Siguiente"] = "下一個",
	["Siguiente lugar"] = "下一個地點",
	["Siguiente parada:"] = "下一站：",
	["Siguiente paso de la guía"] = "指南的下一個步驟",
	["Siguiente rango: %s"] = "下一個等級：%s",
	["Siguiente: %s (%d de %d)"] = "下一個：%s（%d / %d）",
	["Silencia los sonidos que agregues por su número de archivo (FileDataID): /alfa silenciar <número>; /alfa silenciar quitar <número> lo quita."] = "依檔案編號（FileDataID）將你加入的聲音靜音：/alfa silenciar <編號>；/alfa silenciar quitar <編號> 可移除。",
	["Silenciar 1 hora"] = "靜音 1 小時",
	["Silenciar sonidos"] = "靜音聲音",
	["Silenciar un sonido por su número (FileDataID)"] = "依編號（FileDataID）將聲音靜音",
	["Silithus es la puerta de Ahn'Qiraj, donde los silítidos y los qiraji sirven al dios antiguo C'Thun."] = "希利蘇斯是安其拉的門戶，異種蟲與其拉蟲人在那裡侍奉古神克蘇恩。",
	["Sin Minería no ves filones; sin Herboristería, hierbas; sin Pesca, bancos. Los tesoros siempre se ven."] = "沒有採礦就看不到礦脈；沒有草藥學就看不到草藥；沒有釣魚就看不到魚群。寶藏則一律顯示。",
	["Sin Pesca"] = "未學釣魚",
	["Sin XP descansada"] = "沒有休息經驗",
	["Sin acción"] = "無動作",
	["Sin activar"] = "未啟用",
	["Sin aprender"] = "未學會",
	["Sin aullido"] = "不要狼嚎",
	["Sin bloqueos y más claro"] = "不再被封鎖，也更清楚",
	["Sin cadena"] = "無任務鏈",
	["Sin cambiar de forma."] = "未變形。",
	["Sin cambios"] = "沒有變化",
	["Sin consejos para este jefe: vayan con calma y escuchen al tanque."] = "這個首領沒有提示：慢慢來，聽坦克的。",
	["Sin datos"] = "沒有資料",
	["Sin demonio"] = "沒有惡魔",
	["Sin el ratón encima, la barra guarda sus botones y deja solo lo que pasa."] = "滑鼠不在上面時，釣魚條會收起按鈕，只顯示正在發生的事。",
	["Sin encantar"] = "未附魔",
	["Sin fuente conocida"] = "無已知來源",
	["Sin grupo"] = "未組隊",
	["Sin historial todavía."] = "還沒有價格紀錄。",
	["Sin límite de tiempo"] = "無時間限制",
	["Sin mascota"] = "沒有寵物",
	["Sin metas todavía"] = "還沒有目標",
	["Sin metas todavía. Pulsa + para ponerte una: un pez, capturas, tiempo o valor."] = "還沒有目標。按 + 設定一個：一種魚、漁獲數、時間或價值。",
	["Sin metas todavía: ábrelo y agrégale una."] = "還沒有目標：開啟它並新增一個。",
	["Sin munición"] = "沒有彈藥",
	["Sin objeto"] = "沒有物品",
	["Sin otros personajes, uno solo puede ganar 29: 3 por subir de nivel, 6 de profesiones, 12 de JcJ, 2 de aventura y 6 de mazmorras y bandas. El resto sale de subir otras clases."] = "沒有分身的話，一個角色最多能獲得 29 點：升級 3 點、專業 6 點、PvP 12 點、冒險 2 點、地城與團隊副本 6 點。其餘的來自練其他職業。",
	["Sin precio todavía: escanea la subasta."] = "還沒有價格：請掃描拍賣場。",
	["Sin precios"] = "沒有價格",
	["Sin precios todavía"] = "還沒有價格",
	["Sin profesión"] = "沒有專業",
	["Sin sello"] = "沒有聖印",
	["Sin tecla"] = "無按鍵",
	["Sin tener una tecla abajo: lo prendes o lo apagas con su atajo, o aquí."] = "不用一直按住按鍵：用它的快捷鍵開啟或關閉，或者在這裡。",
	["Sin tinte"] = "無色調",
	["Sin ubicación"] = "無位置",
	["Sin ubicación ahora: en una instancia o fuera del mapa"] = "目前無位置：在副本中或不在地圖上",
	["Sin veneno"] = "沒有毒藥",
	["Sin zona"] = "無地區",
	["Sobre Lya"] = "關於 Lya",
	["Sobre tu compañero, este clic %s."] = "對隊友，這個點擊會%s。",
	["Solo %s"] = "僅限%s",
	["Solo al acabarse"] = "只在用完時",
	["Solo al moverte"] = "僅在移動時",
	["Solo buffs"] = "只有增益效果",
	["Solo con quienes usan Alfa y aceptaron compartir. Tú decides."] = "只與使用 Alfa 並同意分享的人分享。由你決定。",
	["Solo cuando estás en grupo"] = "僅在隊伍中時",
	["Solo cuando te llame"] = "叫你時再來",
	["Solo el botín que me sirve"] = "只顯示我能用的戰利品",
	["Solo ellos: tú no la tienes."] = "只有他們有：你沒有這個任務。",
	["Solo en una fiesta del año"] = "僅限年度節慶期間",
	["Solo en warcraft.wiki.gg e Icy Veins: cuántos puntos pide cada premio (15, 25, 40 y 55). Ninguna fuente publica cuánto cuesta cada rango de los árboles: míralo en la ventana del Legado."] = "只有 warcraft.wiki.gg 與 Icy Veins 列出了每個獎勵需要多少點（15、25、40 與 55）。沒有任何來源公布天賦樹每一級的花費：請在傳承視窗中查看。",
	["Solo encontré %d misiones que te sirvan ahora."] = "目前只找到 %d 個適合你的任務。",
	["Solo hay que llevar el recado. ¡Fácil, como pedirme una salchicha!"] = "只要把口信送到就行。很簡單，就像跟我要一根香腸一樣！",
	["Solo importantes"] = "只看重要的",
	["Solo la entrada"] = "只去入口",
	["Solo las misiones de tu ruta"] = "只接你路線上的任務",
	["Solo las que puedes tomar: tu bando, raza, clase y nivel, y que no hayas hecho."] = "只顯示你能接的：你的陣營、種族、職業與等級，且尚未完成。",
	["Solo lo de mi papel"] = "只顯示我的職責",
	["Solo lo esencial a la vista. Las barras y retratos se esconden al terminar el combate."] = "只顯示必要的東西。快捷列和頭像會在戰鬥結束後隱藏。",
	["Solo lo esencial a la vista. Pulsa tu tecla otra vez para ver todo."] = "只顯示必要的東西。再按一次你的按鍵就能看到全部。",
	["Solo lo esencial a la vista: Hoy, Ruta, Mapa, Bolsas y Lya, y menos avisos. Lo demás sigue ahí cuando lo busques."] = "只顯示最重要的：今天、路線、地圖、背包和莉婭，提醒也更少。其他的需要時隨時都在。",
	["Solo lo que tu clase puede usar y le conviene a tu especialización."] = "只顯示你的職業能用且適合你專精的。",
	["Solo lo que tu personaje puede usar hoy: clase, armadura, armas, nivel y profesión."] = "只顯示你的角色現在能用的：職業、護甲、武器、等級與專業。",
	["Solo lo que ya puedes recolectar"] = "只顯示你現在能採集的",
	["Solo los de la zona donde estás."] = "只顯示你所在地區的。",
	["Solo los de tus profesiones, en el mapa del mundo y en el minimapa."] = "只顯示你的專業相關的，在世界地圖與小地圖上。",
	["Solo los graves"] = "只顯示嚴重的",
	["Solo los que me apuntan a mí"] = "只顯示針對我的",
	["Solo misiones de XP, las mejores cerca de ti, en tres tandas."] = "只有經驗值任務，挑選你附近最好的，分成三批。",
	["Solo para %s."] = "僅限%s。",
	["Solo para mirar: tu paso de ahora no cambia. Alfa avanza sola cuando lo cumples."] = "僅供檢視：你的目前步驟不會改變。完成目前步驟後，Alfa 會自動前進。",
	["Solo peleas de al menos"] = "只統計至少持續",
	["Solo pide tela: guarda la que te sale de los enemigos y sube mientras viajas."] = "它只需要布料：留著敵人掉的布，在旅途中順便練。",
	["Solo puedes tener dos principales a la vez; las secundarias son libres. Se aprenden con su entrenador en las ciudades."] = "同一時間只能有兩個主要專業；次要專業不受限制。在城市中向對應的訓練師學習。",
	["Solo salen los clanes donde puedes invitar, y Alfa te confirma en el chat a quién invitaste. Lo apagas en La Jauría > Invitar."] = "只會顯示你有權限邀請的地方，Alfa 會在聊天中確認你邀請了誰。可在 La Jauría > 邀請 中關閉。",
	["Solo se admite la versión 1 de la cadena de escala."] = "僅支援第 1 版權重字串。",
	["Solo si falta"] = "只在缺少時",
	["Solo si le pido"] = "只在我要求時",
	["Solo sirve con un monitor HDR y el HDR de Windows encendido (Configuración > Pantalla). Sin eso, déjalo apagado: los colores se ven lavados."] = "只在使用 HDR 螢幕並開啟 Windows HDR（設定 > 顯示器）時有效。否則請保持關閉：顏色會顯得泛白。",
	["Solo su atajo"] = "只用它的快捷鍵",
	["Solo tocan gráficos: nunca la cámara, el ratón ni la interfaz. «Deshacer» devuelve lo que tenías antes del último que aplicaste."] = "它們只變動圖形：絕不變動鏡頭、滑鼠或介面。「復原」會恢復你套用上一個預設之前的設定。",
	["Solo tu grupo y quienes usan Alfa y aceptaron compartir."] = "僅限你的隊伍以及使用 Alfa 並同意分享的人。",
	["Solo tú"] = "只有你",
	["Solo tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "只顯示你、你的隊伍、你的標記與指南的下一步。",
	["Solo él ve tu nivel, tu zona y tu misión de ahora."] = "只有他能看到你的等級、區域和目前任務。",
	["Sombra"] = "暗影",
	["Sombra para subir"] = "暗影（練等）",
	["Sombra suave en rincones, pliegues y bajo los objetos: da volumen a todo."] = "角落、皺褶與物體下方的柔和陰影：讓一切更有立體感。",
	["Sombras"] = "陰影",
	["Sombras con bordes más finos. Usa más memoria de video."] = "陰影邊緣更精細。會佔用更多顯示記憶體。",
	["Sombras suaves"] = "柔和陰影",
	["Son %s más que venderlo todo al comerciante."] = "比全部賣給商人多 %s。",
	["Son puntos de tu cuenta: los ganas con los retos del Legado (logros de Forever) en cualquier personaje, y cada personaje los gasta por su cuenta en sus árboles."] = "這是帳號點數：在任何角色上完成傳承挑戰（Forever 的成就）即可獲得，每個角色各自將其花在自己的天賦樹上。",
	["Son tres enanos que pelean juntos: uno dispara de lejos, otro es muy veloz y otro se protege con escudo. Mátenlos uno por uno."] = "三個矮人一起戰鬥：一個從遠處射擊，一個速度很快，一個會用盾牌保護自己。一個一個解決他們。",
	["Sonido"] = "音效",
	["Sonido con el juego en segundo plano"] = "遊戲在背景執行時的聲音",
	["Sonido de los avisos"] = "提醒音效",
	["Sonido en los avisos urgentes"] = "緊急提醒時播放音效",
	["Sonido suave"] = "柔和的音效",
	["Sonido y avisos"] = "聲音與提醒",
	["Sonidos de gestos"] = "表情動作音效",
	["Sonidos de mascotas"] = "寵物音效",
	["Sonidos en tu lista (%d): %s"] = "你清單中的聲音（%d）：%s",
	["Sonidos suaves del juego: nada de voces ni sonidos repetidos."] = "遊戲中的柔和音效：沒有語音，也沒有重複的聲音。",
	["Sorpresa"] = "驚喜",
	["Sorpresas y cofres"] = "驚喜與寶箱",
	["Soy Lya, la loba de confianza del Alfa. Te acompaño, te cuento el lore de cada lugar y te ayudo con todo lo de Alfa. Y me encantan las salchichas."] = "我是莉婭，頭狼信賴的狼。我陪著你，講每個地方的傳說，幫你搞定 Alfa 的一切。我超愛香腸。",
	["Spot aquí"] = "此處刷點",
	["Spot de farmeo"] = "刷點",
	["Spot de farmeo de %s"] = "%s 的刷點",
	["Spots de farmeo"] = "刷點",
	["Stromgarde, la heredera de Strom, resiste a medias: trols, ogros y el Sindicato se pelean por sus ruinas."] = "斯托姆的繼承者激流堡勉強支撐著：食人妖、巨魔與辛迪加在它的廢墟上爭鬥。",
	["Su arpón envenena: quita el veneno si puedes."] = "他的魚叉有毒：能解毒的話就解毒。",
	["Su botín está por descubrir"] = "戰利品待發現",
	["Su electricidad salta de un jugador a otro: sepárense."] = "他的電流會在玩家之間跳躍：分散站位。",
	["Su ficha"] = "它的資料",
	["Su final no alcanzó a guardarse."] = "它的結局沒來得及保存。",
	["Su grupo está lleno o no puede invitar."] = "他的隊伍已滿或無法邀請。",
	["Su guarida ya no está abierta."] = "他的巢穴已不再開放。",
	["Su mordida envenena: quita el veneno si puedes."] = "他的啃咬有毒：能解毒的話就解毒。",
	["Su nombre ya está en el correo: pon %s y envíalo."] = "他的名字已經填在郵件裡了：放入 %s 並寄出。",
	["Su oro y sus recompensas ya son tuyos: solo falta entregarlas."] = "它們的金幣與獎勵已經是你的了：只差交付。",
	["Su plano está lleno de gente. Si le abres tu guarida, Alfa lo invita a tu grupo y sale solo al llegar."] = "他們的位面很擁擠。如果你打開巢穴，Alfa 會邀請他們入隊，到了之後他們就會離開。",
	["Su rayo salta de un jugador a otro: no se queden todos juntos."] = "他的閃電會從一名玩家跳到另一名：不要全部站在一起。",
	["Su rayo salta de un jugador a otro: sepárense un poco."] = "他的閃電會從一名玩家跳到另一名：稍微分散站位。",
	["Suave"] = "柔和",
	["Subasta"] = "拍賣",
	["Subasta:"] = "拍賣：",
	["Subastador"] = "拍賣師",
	["Subastadores"] = "拍賣師",
	["Subastar"] = "拍賣",
	["Subastar %d"] = "拍賣 %d",
	["Sube %d nivel"] = "升 %d 級",
	["Sube %d niveles"] = "升 %d 級",
	["Sube al nivel"] = "升到等級",
	["Sube al nivel %d"] = "升到 %d 級",
	["Sube al nivel %d: te falta %d%%"] = "升到 %d 級：還差 %d%%",
	["Sube al nivel %d: te faltan %s de experiencia"] = "升到 %d 級：還差 %s 經驗",
	["Sube hasta %d con los pasos de abajo."] = "照下面的步驟把它提升到 %d。",
	["Sube los efectos y baja la música y el ambiente para que oigas el chapoteo. Al terminar, todo vuelve a como estaba."] = "調高音效、調低音樂與環境音，讓你聽得到水花聲。釣完後一切都會恢復原樣。",
	["Sube tu profesión o junta sus materiales donde más hay."] = "提升你的專業，或在材料最多的地方收集。",
	["Sube tus oficios con lo que tienes cerca."] = "用附近的資源提升你的專業。",
	["Subidón de adrenalina: recuperas energía mucho más rápido."] = "能量刺激：能量恢復速度大幅提高。",
	["Subir"] = "上移",
	["Subir %s"] = "提升 %s",
	["Subir %s a %d"] = "將%s提升到 %d",
	["Subir cocina y pesca juntas"] = "同時提升烹飪與釣魚",
	["Subir como tanque: más lento que Armas, pero casi nunca mueres, juntas varios monstruos a la vez y llegas listo para tanquear cualquier mazmorra."] = "以坦克練等：比武器慢，但幾乎不會死，能一次拉好幾隻怪，練到滿等時也已準備好坦任何地城。",
	["Subir de nivel"] = "升級",
	["Subir de nivel, profesiones, hacer oro o mazmorras: dos clics y Alfa te lleva."] = "練等、專業、賺金幣或地城：點兩下，Alfa 就會帶你去。",
	["Subir de nivel, profesiones, oro o mazmorras."] = "練等、專業、金幣或地城。",
	["Subir el sonido al pescar"] = "釣魚時調高音量",
	["Subir rápido"] = "快速升級",
	["Subir solo"] = "單人練等",
	["Subir una profesión"] = "提升一項專業",
	["Succionar vida: daño con el tiempo que te cura."] = "生命虹吸：持續傷害，同時治療你。",
	["Suelta"] = "掉落",
	["Suelta el lanzamiento de ahora y lanza otra vez, sin poner equipo ni cebo."] = "放棄目前這一竿並重新拋竿，不換裝備也不上魚餌。",
	["Suelta lo que tienes en el cursor y vuelve a intentarlo."] = "先放下游標上拿著的東西，再試一次。",
	["Suelta una carta que empieza una misión: revisa su botín."] = "他會掉落一封能開始任務的信：記得檢查他的戰利品。",
	["Suelta una llave que abre una puerta más adelante: alguien debe recogerla."] = "他會掉落一把能打開前方大門的鑰匙：要有人撿起來。",
	["Suelta una nube de enfermedad a su alrededor: quiten enfermedades."] = "他會在周圍釋放疾病之雲：記得驅散疾病。",
	["Suelta una ola de fuego a su alrededor: si peleas de lejos, quédate lejos de él."] = "他會在周圍釋放一圈火焰：遠程職業請離他遠一點。",
	["Suena ahora, aunque el aullido esté apagado."] = "立即播放，即使狼嚎已關閉。",
	["Sueño con una montaña de salchichas... y yo en la punta, feliz."] = "我夢見一座香腸堆成的山…我開心地站在山頂。",
	["Sugerida para ti: %s"] = "為你推薦：%s",
	["Sugerir la piedra de hogar"] = "建議使用爐石",
	["Sugerir qué guardar"] = "建議存放的物品",
	["Sugerir qué vender"] = "建議該賣什麼",
	["Sugiere con la prioridad de Alfa para tu clase. Apagado, usa la ayuda de Blizzard cuando el juego da una sugerencia que Alfa puede leer; en combate Forever la oculta, así que ahí sigue la de Alfa."] = "依 Alfa 為你職業設定的優先順序給出建議。關閉時，若遊戲給出 Alfa 能讀取的建議，則使用暴雪的戰鬥輔助；戰鬥中 Forever 會隱藏它，因此仍使用 Alfa 的。",
	["Sulfuras es el martillo de Ragnaros. Con su ojo, los más valientes pueden forjar una versión legendaria."] = "薩弗拉斯是拉格納羅斯的戰錘。憑藉薩弗拉斯之眼，最勇敢的人能鍛造出它的傳說版本。",
	["Suma tus sesiones de hoy con este personaje."] = "此角色今天所有遊戲的總和。",
	["Suma «conseguir este objeto» a tu plan de ahora (o a uno nuevo)."] = "把「取得這件物品」加入你目前的計畫（或一個新計畫）。",
	["Supervivencia"] = "生存",
	["Supervivencia para subir"] = "生存（練等）",
	["Sus antojos y salchichas"] = "她的饞嘴和香腸",
	["Sus bolas de sombra pegan mucho: interrúmpelo."] = "他的暗影箭很痛：打斷他。",
	["Sus cariñitos"] = "她的暖心話",
	["Sus consejos"] = "她的建議",
	["Sus consejos te esperan en Alfa."] = "它的提示在 Alfa 中等著你。",
	["Sus jefes, su botín, sus misiones y cómo llegar."] = "它的首領、戰利品、任務以及如何前往。",
	["Sus misiones dan"] = "任務可獲得",
	["Sus rayos saltan entre jugadores: sepárense."] = "她的閃電會在玩家之間跳躍：分散站位。",
	["Susurrar"] = "密語",
	["Sutileza"] = "敏銳",
	["Sutileza para subir"] = "敏銳（練等）",
	["Sylvanas era hermana de Alleria y de Vereesa Brisaveloz. Hoy guía a los Renegados con mano firme."] = "希瓦娜斯是奧蕾莉亞和溫蕾薩·風行者的姊妹。如今她以鐵腕領導被遺忘者。",
	["Sylvanas recibe en el Barrio Real de Entrañas, con Varimathras a su lado."] = "希瓦娜斯在幽暗城的皇家區接見來客，瓦里瑪薩斯就在她身旁。",
	["Sylvanas tiene dos hermanas: Alleria, que se fue más allá del Portal Oscuro, y Vereesa, que se casó con el mago Rhonin."] = "希瓦娜斯有兩個姊妹：去了黑暗之門另一邊的奧蕾莉亞，以及嫁給法師羅寧的溫蕾薩。",
	["Sábado"] = "星期六",
	["Sí"] = "是",
	["Sí, que la manada me vea"] = "是的，讓狼群看到我",
	["Sí, que me vean"] = "是的，讓他們看到我",
	["Sí, sígueme diciendo"] = "好，繼續告訴我",
	["Sí, ya la hice"] = "是，我打過了",
	["Sí: Alfa, Clásico WoW o Cristal, con tu color. También puede vestir el chat, el minimapa y las barras."] = "能：Alfa、經典 WoW 或水晶，配你的顏色。還能裝扮聊天框、小地圖和快捷列。",
	["Sí: con /alfa limpia, o con tu tecla de pantalla limpia, escondo el chat, el minimapa y lo demás que elijas. Otra vez y vuelve todo."] = "可以：用 /alfa limpia 或你的清爽畫面按鍵，我會隱藏聊天框、小地圖和你選的其他東西。再按一次就全部回來。",
	["Sí: con el modo foco, en mazmorras y en combate me hago chiquita y me callo. Al terminar vuelvo. Está en mis ajustes."] = "可以：開啟專注模式後，在地城和戰鬥中我會變小並保持安靜。之後我就回來。這在我的設定裡。",
	["Sí: en Ajustes > Estilo y sonido elige «Sencillo» en «Cómo ves Alfa». Dejo a la vista solo lo esencial y te aviso menos."] = "可以：在 設定 > 風格與音效 的「Alfa 的顯示方式」裡選「簡潔」。我只留下最重要的，提醒也會更少。",
	["Sí: en las asignaciones de teclas del juego, en la sección Alfa, ponle una tecla a «Pregúntale a Lya» y otra a «Lo que te ofrece Lya», que hace lo de su botón."] = "可以：在遊戲按鍵設定的 Alfa 分類裡，給「問問莉婭」設一個鍵，再給「莉婭的提議」設一個，它會執行她按鈕的操作。",
	["Sí: en las asignaciones de teclas del juego, en la sección Alfa, ponle una tecla a «Pregúntale a Lya»."] = "可以：在遊戲按鍵設定的 Alfa 分類裡，給「問問莉婭」設個鍵。",
	["Sí: en «Mentor», pulsa «Adoptar» junto a un lobo 10 niveles menor. Si acepta, ves cómo va y te aviso si se atora."] = "可以：在「導師」中，點一隻比你低 10 級的狼旁邊的「收養」。如果他接受，你能看到他的進展，他卡住時我會告訴你。",
	["Sí: escribe /alfa nota y tu texto, o usa «Nota aquí» en La Jauría. Sale en tu mapa donde estás; un clic y la flecha te lleva."] = "可以：輸入 /alfa nota 加上內容，或在 La Jauría 中按「在這裡記筆記」。筆記會出現在你站的位置的地圖上；點一下，箭頭就會帶你過去。",
	["Sí: sale «[Misión] está lista para entregar» y «¡Misión completada!» en el chat del grupo. Solo, te sale a ti."] = "會：隊伍聊天裡會出現「[任務] 可以交付了」和「任務完成！」。單人時只有你看到。",
	["Símbolo de reyes"] = "王者印記",
	["Tabardo"] = "外袍",
	["Talentos"] = "天賦",
	["Talentos de %s"] = "%s的天賦",
	["Talentos te dice cuál sigue."] = "「天賦」會告訴你下一個點哪個。",
	["Talentos y combate"] = "天賦與戰鬥",
	["Talentos: qué poner ahora y tu build (/alfa builds aplicar | equipo | compartir)"] = "天賦：現在該點什麼與你的配點（/alfa builds aplicar | equipo | compartir）",
	["Tamaño"] = "大小",
	["Tamaño de la barra"] = "釣魚條大小",
	["Tamaño de las casillas"] = "格子大小",
	["Tamaño de las que siguen"] = "後續圖示的大小",
	["Tamaño de lo que atraviesa"] = "可穿過的物體大小",
	["Tamaño de su letra"] = "字體大小",
	["Tamaño del ícono"] = "圖示大小",
	["Tamaño en el mapa"] = "地圖上的大小",
	["Tamaño en el minimapa"] = "小地圖上的大小",
	["También con /alfa dps. No se cierra con Esc, para que la tengas a la vista al pelear."] = "也可用 /alfa dps。按 Esc 不會關閉，讓你戰鬥時一直看得到。",
	["También con /alfa limpia."] = "也可以用 /alfa limpia。",
	["También cuando el juego hace brillar otra habilidad"] = "遊戲讓其他技能發光時也提醒",
	["También dentro de cuevas, criptas y edificios."] = "在洞穴、墓穴與建築物內也一樣。",
	["También el de venenos, sangrados y efectos que duran."] = "也包括毒藥、流血與持續效果造成的傷害。",
	["También en el minimapa"] = "也顯示在小地圖上",
	["También en montura"] = "騎乘時也可以",
	["También está en el menú de opciones del juego."] = "也在遊戲的選項選單中。",
	["También fuera de combate"] = "戰鬥外也顯示",
	["También las de las mascotas de enemigos."] = "也包括敵人寵物的。",
	["También las que no son de la guía (de esas se encarga \"Aceptar misiones de la guía\"). No toma misiones grises, no entrega las que piden oro, monedas o materiales de oficio, y si hay varias recompensas eliges tú. Mantén presionado Mayús para hacerlo tú."] = "也包括不在指南中的任務（指南任務由「接受指南任務」處理）。不會接灰色任務，不會交付需要金錢、代幣或專業材料的任務，有多個獎勵時由你選擇。按住 Shift 可自己操作。",
	["También las que no son de tu guía"] = "也包括指南以外的任務",
	["También tu foco"] = "也包括你的專注目標",
	["Tanque"] = "坦克",
	["Tanque de amenaza"] = "仇恨型坦克",
	["Tanque de escudo"] = "盾牌型坦克",
	["Tanque en apuros"] = "坦克告急",
	["Tanque muralla"] = "銅牆鐵壁型坦克",
	["Tanqueas"] = "你負責坦克",
	["Taretha Foxton, una muchacha humana de Durnholde, fue la amiga de Thrall y lo ayudó a escapar."] = "敦霍爾德的人類姑娘塔蕾莎·弗斯頓是索爾的朋友，幫助他逃了出去。",
	["Tarjeta de habilidades nuevas al subir de nivel"] = "升級時顯示新技能卡片",
	["Tauren"] = "牛頭人",
	["Te abrimos un susurro para %s con tu mensaje. Revísalo y pulsa Intro para enviarlo."] = "已為你開啟給 %s 的密語並填好訊息。確認後按 Enter 傳送。",
	["Te acompaña"] = "陪伴你",
	["Te avisa al momento de %s."] = "%s亮起時立即提醒你。",
	["Te avisa cuando tu clase tiene algo que aprovechar ahora, como una habilidad que se encendió."] = "當你的職業現在有可以利用的東西時提醒你，例如剛被點亮的技能。",
	["Te aviso con «Regalárselo»: abre el comercio si está a tu lado o te deja su nombre en el correo. Necesitan compartir su clase y nivel."] = "我會用「送給他」提醒你：他在你旁邊就開啟交易，否則把他的名字填進郵件。對方需要分享自己的職業和等級。",
	["Te conviertes en felino: mucho daño cuerpo a cuerpo y puedes acechar."] = "你變成獵豹：近戰傷害很高，還能潛行。",
	["Te conviertes en foca: nadas rápido y respiras bajo el agua."] = "你變成海豹：游得快，還能在水下呼吸。",
	["Te conviertes en guepardo y corres más rápido. Solo al aire libre."] = "你變成獵豹，跑得更快。只能在戶外使用。",
	["Te conviertes en lobo y corres más rápido. ¡Como yo!"] = "你變成狼，跑得更快。就像我一樣！",
	["Te conviertes en oso: más armadura y más vida. Para tanquear y aguantar."] = "你變成熊：更多護甲和生命值。用來坦怪和扛傷害。",
	["Te cura toda la vida a cambio de tu maná. Guárdalo para una emergencia."] = "用你的法力把自己治療到滿血。留著應急用。",
	["Te da %s."] = "可獲得%s。",
	["Te da consejos cortos y ánimo sin repetirse: cada frase sale tres veces como mucho. Dale clic para pedirle uno; clic derecho para sus opciones."] = "她會給你簡短的建議與鼓勵，而且不會重複：每句話最多出現三次。點她就能要一則；右鍵點擊可開啟她的選項。",
	["Te da ira a cambio de un poco de vida. Úsala para empezar una pelea con ira."] = "用一點生命值換怒氣。開打前用來攢怒氣。",
	["Te da poder de ataque: cada golpe pega más. Para el guerrero también sube el bloqueo con escudo."] = "提供攻擊強度：每一擊都更痛。對戰士來說還能提高盾牌格擋值。",
	["Te damos la bienvenida a Alfa, el todo en uno de La Jauría."] = "歡迎使用 Alfa，La Jauría 的多合一插件。",
	["Te dice qué comprar a tu nivel y te lleva al vendedor de comida más cercano. El agua, solo si usas maná."] = "告訴你這個等級該買什麼，並帶你去最近的食物商人。只有用法力的才需要水。",
	["Te dice qué pieza está por romperse, para que la repares a tiempo."] = "告訴你哪件裝備快要損壞，讓你及時修理。",
	["Te enseña %s."] = "可學會%s。",
	["Te enseña Pesca y sus rangos. También vende la caña básica."] = "教授釣魚及其等級。也販售基礎魚竿。",
	["Te falta"] = "缺少",
	["Te falta %s"] = "你缺少%s",
	["Te falta 1 nivel para el 60"] = "還差 1 級到 60 級",
	["Te falta 1 nivel para tomarla."] = "還差 1 級才能接取。",
	["Te falta 1 paso"] = "還差 1 步",
	["Te falta 1 rincón."] = "還剩 1 個角落。",
	["Te falta Aspecto del halcón: más poder a distancia."] = "你缺少雄鷹守護：提高遠程攻擊強度。",
	["Te falta Aura de disparo certero: más poder a distancia para tu grupo."] = "缺少強擊光環：為你的隊伍提供更多遠程攻擊強度。",
	["Te falta Bendición de poderío: más poder de ataque."] = "你缺少力量祝福：提高攻擊強度。",
	["Te falta Escudo de relámpagos."] = "你缺少閃電之盾。",
	["Te falta Escudo sagrado: bloqueas más."] = "你缺少神聖之盾：提高格擋。",
	["Te falta Espinas."] = "你缺少荊棘術。",
	["Te falta Fuego interior: más armadura."] = "你缺少心靈之火：提高護甲。",
	["Te falta Grito de batalla: más poder de ataque para ti y tu grupo."] = "你缺少戰鬥怒吼：提高你與隊伍的攻擊強度。",
	["Te falta Intelecto Arcano: más maná."] = "你缺少秘法智慧：提高法力。",
	["Te falta Marca de lo Salvaje."] = "你缺少野性印記。",
	["Te falta Palabra de poder: entereza: más vida."] = "你缺少真言術：韌：提高生命值。",
	["Te falta aprender la receta."] = "你還需要學會配方。",
	["Te falta el tótem de Fuerza de la tierra: más fuerza."] = "缺少大地之力圖騰：更多力量。",
	["Te falta este vuelo: háblale al maestro de vuelo para aprenderlo."] = "你還沒有這條飛行路線：和飛行管理員交談來學會它。",
	["Te falta ira: Enfurecer te la da."] = "怒氣不足：狂怒可以給你怒氣。",
	["Te falta ira: Ira sangrienta te la da gratis."] = "怒氣不足：血性狂暴可免費提供怒氣。",
	["Te falta ira: esta habilidad te la da al recibir golpes."] = "怒氣不足：這個技能會在你受到攻擊時給你怒氣。",
	["Te falta la forma de las Sombras: más daño de sombras y menos daño recibido."] = "缺少暗影形態：更高的暗影傷害，受到的傷害更少。",
	["Te falta la forma de lechúcico lunar: más daño con tus hechizos."] = "缺少梟獸形態：你的法術傷害更高。",
	["Te falta la profesión"] = "缺少該專業",
	["Te falta reputación"] = "聲望不足",
	["Te falta tu armadura demoníaca."] = "缺少你的惡魔護甲。",
	["Te falta tu armadura: ponte una."] = "缺少護甲：施放一個。",
	["Te falta un aspecto: el del halcón da más poder a distancia."] = "缺少守護：雄鷹守護提供更多遠程攻擊強度。",
	["Te falta un aspecto: el del mono te ayuda a esquivar."] = "缺少守護：靈猴守護幫助你閃躲。",
	["Te falta una bendición: Poderío da más poder de ataque."] = "缺少祝福：力量祝福提供更多攻擊強度。",
	["Te falta una bendición: Sabiduría te devuelve maná."] = "缺少祝福：智慧祝福為你恢復法力。",
	["Te falta una bendición: Santuario reduce el daño que recibes."] = "缺少祝福：庇護祝福減少你受到的傷害。",
	["Te faltan %d de %d materiales"] = "你還缺 %d / %d 種材料",
