	["Te faltan %s"] = "還差 %s",
	["Te faltan %s XP para el nivel %d"] = "還差 %s 經驗升到 %d 級",
	["Te faltan %s XP para el nivel %d, a tu ritmo actual."] = "還差 %s 經驗值升到 %d 級（以你目前的速度計算）。",
	["Te faltan %s de experiencia para el nivel %d"] = "還差 %s 經驗升到 %d 級",
	["Te faltan %s niveles para el %d"] = "還差 %s 級到 %d 級",
	["Te faltan ingredientes para el siguiente lote."] = "下一批缺少材料。",
	["Te faltan ingredientes."] = "缺少材料。",
	["Te faltan niveles para llegar a %d: la guía te lo marca y sigues subiendo con tu ruta."] = "你還需要練等才能到 %d 級：指南會標出來，你繼續依路線練等。",
	["Te faltan niveles: cada nivel desde el 10 te da un punto."] = "等級不夠：從等級 10 起每升一級可獲得一點。",
	["Te haces el muerto y los enemigos te olvidan. Tu mejor salida si algo sale mal."] = "你假死，敵人就會忘了你。情況不妙時最好的脫身辦法。",
	["Te la da %s, en %s."] = "由%s提供，位於%s。",
	["Te la da %s."] = "由%s提供。",
	["Te la dio %s"] = "由%s給予",
	["Te la dio %s · Se entrega con %s"] = "由%s給予 · 交給%s",
	["Te la dio y la recibe %s"] = "由%s給予並交付",
	["Te lleva a las misiones de tu ruta que ya puedes tomar."] = "帶你去接你路線上已經可以接的任務。",
	["Te lleva al Claro de la Luna, un lugar tranquilo para entrenar."] = "帶你去月光林地，一個安靜的訓練之地。",
	["Te llevo a %s"] = "帶你去%s",
	["Te llevo a entregarlas todas en el mejor orden."] = "我帶你照最佳順序全部交掉。",
	["Te llevo a la mejor fuente. Recuerda que una montura pide nivel, equitación y oro."] = "帶你去最佳來源。記得，坐騎需要等級、騎術與金幣。",
	["Te llevo a quien recibe cada una y recoges las que siguen."] = "我會帶你去找每個任務的交付人，你再接取後續任務。",
	["Te llevo la cuenta de tu día de caza: misiones, niveles, oro, raros y el tiempo. Escribe /alfa lya dia y te lo cuento."] = "我會記錄你的狩獵日：任務、等級、金幣、稀有怪和時間。輸入 /alfa lya dia 我就告訴你。",
	["Te llevo la cuenta de tu semana de caza y tu mejor día. Escribe /alfa lya semana y te lo cuento."] = "我會記錄你本週的狩獵和最佳一天。輸入 /alfa lya semana 我就告訴你。",
	["Te lo da un PNJ"] = "由 NPC 給予",
	["Te lo enseña cualquier instructor de este oficio en las ciudades. Puedes tener dos oficios principales; Cocina y Primeros auxilios no cuentan."] = "主城裡任何一位該專業的訓練師都能教。你可以學兩個主要專業；烹飪和急救不算。",
	["Te lo enseña cualquier instructor de pesca. Hasta que lo aprendas, tu habilidad no pasa del tope."] = "任何釣魚訓練師都能教你。在你學會之前，技能無法超過上限。",
	["Te lo enseña tu entrenador."] = "你的訓練師會教你。",
	["Te lo enseñan desde el nivel %d."] = "從 %d 級開始可以學。",
	["Te lo pido de corazón: nunca desuelles a un lobo enfrente de mí, ¿sí?"] = "我真心拜託你：千萬別在我面前剝狼皮，好嗎？",
	["Te los enseña tu entrenador."] = "你的訓練師會教你。",
	["Te presento a Lya"] = "認識一下莉婭",
	["Te pusiste «%s»: %d piezas."] = "你穿上了「%s」：%d 件。",
	["Te queda 1 casilla libre."] = "還剩 1 個空格子。",
	["Te queda 1 espacio"] = "只剩 1 格",
	["Te queda 1."] = "你還剩 1 個。",
	["Te queda muy poco maná: Estimular lo recupera."] = "你的法力所剩無幾：啟動可以恢復。",
	["Te queda muy poco maná: Evocación lo recupera."] = "你的法力所剩無幾：喚醒可以恢復。",
	["Te queda poca XP descansada"] = "你的休息經驗快用完了",
	["Te queda poca agua"] = "你的水快沒了",
	["Te queda poca comida"] = "你的食物快沒了",
	["Te queda poca comida y agua"] = "你的食物和水快沒了",
	["Te queda poco maná y te sobra vida: cambia vida por maná."] = "法力不多而生命力有餘：用生命換法力。",
	["Te queda poco maná: cambia vida por maná."] = "法力不足：用生命值換取法力。",
	["Te queda poco maná: usa tu varita."] = "法力不多了：用你的魔杖。",
	["Te quedan %d casillas libres."] = "還剩 %d 個空格子。",
	["Te quedan %d de %d espacios"] = "剩餘 %d / %d 格",
	["Te quedan %d espacios en las bolsas. Vende lo gris o guarda en el banco."] = "背包只剩 %d 格。賣掉灰色物品或存進銀行。",
	["Te quedan %d."] = "你還剩 %d 個。",
	["Te quedaste sin agua"] = "你的水沒了",
	["Te quedaste sin comida"] = "你的食物沒了",
	["Te quedaste sin comida ni agua"] = "你的食物和水都沒了",
	["Te saluda según la hora, comenta la zona y a veces se sienta a pedirte algo con su huesito."] = "她會依時間跟你打招呼，評論所在的地區，有時還會叼著小骨頭坐下來向你討東西。",
	["Te sobra ira y hay varios enemigos: tu siguiente golpe alcanza a dos."] = "怒氣充足且有多個敵人：你的下一次攻擊能命中兩個目標。",
	["Te sobra ira: gástala en tu siguiente golpe."] = "怒氣充足：在下一次攻擊中消耗掉。",
	["Te sobra ira: tu siguiente golpe es más fuerte."] = "怒氣充足：你的下一次攻擊更強。",
	["Te sugiere objetivos de pasos más adelante que tienes muy cerca."] = "推薦離你很近的後續步驟目標。",
	["Te sugiere qué habilidad usar ahora y cuáles siguen. Solo sugiere: nunca presiona nada por ti."] = "建議現在該用哪個技能以及接下來用哪些。它只是建議：絕不會替你按任何鍵。",
	["Te teletransporta a tu ciudad. Necesitas una runa de teletransporte."] = "把你傳送到你的主城。需要一個傳送符文。",
	["Te teletransportas unos metros hacia adelante. Para escapar de raíces y aturdimientos."] = "把你向前傳送幾碼。能擺脫定身和昏迷。",
	["Te vuelve inmune un rato. Úsalo para salvarte o para escapar."] = "讓你免疫一段時間。用來自救或逃跑。",
	["Te vuelves invisible al caminar. Acércate sin que te vean y elige cómo empezar."] = "你在行走時隱形。悄悄靠近，自己決定怎麼開打。",
	["Tecla del modo pesca"] = "釣魚模式按鍵",
	["Tecla fija para pescar"] = "固定釣魚按鍵",
	["Tecla grande"] = "大號按鍵顯示",
	["Tecla para abrir o cerrar el modo"] = "開啟或關閉此模式的按鍵",
	["Tecla para volver a lanzar"] = "重新拋竿按鍵",
	["Tecla y modo pesca"] = "按鍵與釣魚模式",
	["Tela"] = "布甲",
	["Teldrassil es tan grande que entre sus ramas hay colinas, lagos y cuevas."] = "泰達希爾大到枝幹上有山丘、湖泊和洞穴。",
	["Teldrassil es un árbol del mundo que los elfos de la noche plantaron sin la bendición de los dragones. Por eso no les dio la inmortalidad."] = "泰達希爾是夜精靈在沒有巨龍祝福的情況下種下的世界之樹。所以它沒有賜予他們永生。",
	["Teldrassil se plantó para recuperar la inmortalidad, pero sin la bendición de los dragones. Algo en él no anda bien."] = "種下泰達希爾是為了找回永生，但沒有得到巨龍的祝福。它有些地方不太對勁。",
	["Teldrassil siempre tiene una luz suave, como si el árbol mismo nos cuidara."] = "泰達希爾總有一抹柔光，好像那棵樹在守護著我們。",
	["Ten siempre a mano una poción de vida: este build no perdona errores."] = "隨時準備一瓶治療藥水：這個配點不容許失誤。",
	["Tenga o no"] = "無論是否擁有",
	["Tengo hambre… ¿me compartes algo de tu mochila?"] = "我餓了……能從你的背包裡分我點吃的嗎？",
	["Tengo muchas misiones a medias, ¿qué hago?"] = "我有很多做了一半的任務，怎麼辦？",
	["Tengo poco tiempo, ¿qué hago?"] = "我沒多少時間，該做什麼？",
	["Terenas Menethil, rey de Lordaeron, unió a los reinos en la Alianza de Lordaeron. Años después, su propio hijo Arthas lo mató en su trono."] = "洛丹倫國王泰納瑞斯·米奈希爾把各王國聯合成洛丹倫聯盟。多年後，他的親生兒子阿薩斯在王座上殺死了他。",
	["Termina la configuración para usar Alfa (2 minutos)."] = "完成設定即可使用 Alfa（2 分鐘）。",
	["Terminada"] = "已完成",
	["Terminado: cumpliste todas sus metas."] = "已完成：你達成了它的所有目標。",
	["Terminar"] = "結束",
	["Terminar la cadena de Lord Valthalak también es un reto del Legado."] = "完成瓦薩拉克公爵的任務鏈也是一項傳承挑戰。",
	["Terminaste %d de sus misiones: entrégalas y recoge las que siguen."] = "你完成了它的 %d 個任務：交付後接取後續任務。",
	["Terminaste 1 de sus misiones: entrégala y recoge las que siguen."] = "你完成了它的 1 個任務：交付後接取後續任務。",
	["Terminaste esta guía."] = "你完成了這個指南。",
	["Terminaste esta guía. Elige la siguiente para seguir subiendo."] = "你完成了這個指南。選擇下一個繼續升級。",
	["Termínala antes de entregarla."] = "先完成再繳交。",
	["Terreno, como el minimapa"] = "地形，像小地圖一樣",
	["Terreno: al acercarte se ve el suelo real del minimapa, con sus montañas, ríos y tonos. Clásico: solo el mapa pintado del juego."] = "地形：放大後會顯示小地圖的真實地面，包括山脈、河流與色調。經典：只顯示遊戲的手繪地圖。",
	["Tesoro"] = "寶藏",
	["Tesoro de la manada: %s"] = "狼群的寶藏：%s",
	["Tesoros"] = "寶藏",
	["Tesoros en el mapa"] = "地圖上的寶藏",
	["Tesoros en el minimapa"] = "小地圖上的寶藏",
	["Texto de combate flotante"] = "浮動戰鬥文字",
	["Texto sobre tu personaje"] = "角色上方的文字",
	["Textos y cajas mejor alineados en las ventanas de Alfa."] = "Alfa 各視窗中的文字和方框對齊得更好了。",
	["Texturas del mundo"] = "世界材質",
	["Texturas del suelo"] = "地面材質",
	["Texturas proyectadas"] = "投影材質",
	["Texturas y nitidez"] = "材質與銳利化",
	["Theradras, la princesa de la tierra, es hija de Therazane. Amó a Zaetar, hijo de Cenarius, y sus hijos, los centauros, terminaron matándolo."] = "大地公主瑟萊德絲是瑟拉贊恩的女兒。她愛上了塞納留斯之子札爾塔，而他們的孩子半人馬最後卻殺了他。",
	["Theramore la fundó Jaina Valiente con los humanos que salieron de Lordaeron antes de su caída."] = "塞拉摩由珍娜·普勞德摩爾和在洛丹倫陷落前離開的人類共同建立。",
	["Thrall eligió esta tierra roja y seca para que los orcos libres empezaran de nuevo, lejos de los campos de internamiento de los humanos."] = "索爾選擇了這片赤紅乾燥的土地，讓獲得自由的獸人遠離人類的收容所，重新開始。",
	["Thrall es el chamán más famoso: los elementos le responden como a nadie."] = "索爾是最有名的薩滿：元素對他的回應無人能比。",
	["Thrall gobierna la Horda desde Orgrimmar como jefe de guerra, con la mirada puesta en la paz."] = "索爾以大酋長身分在奧格瑪統治部落，目光放在和平上。",
	["Thrall liberó a los orcos de los campos de internamiento con la ayuda de Grom Grito Infernal y de Orgrim Martillo Maldito."] = "索爾在葛羅姆·地獄吼和奧格林·毀滅之錘的幫助下，把獸人從收容所中解放出來。",
	["Thrall nació en Draenor, hijo de Durotan y Draka. Aedelas Blackmoore lo encontró de bebé y lo llamó «Thrall», que quiere decir esclavo."] = "索爾出生在德拉諾，是杜洛坦和德拉卡的兒子。艾德拉斯·黑摩爾在他還是嬰兒時發現了他，給他取名「索爾」，意思是奴隸。",
	["Thrall quiere que los orcos recuperen el honor que tenían antes de la corrupción demoníaca."] = "索爾希望獸人找回他們在被惡魔腐化之前擁有的榮耀。",
	["Tiempo"] = "時間",
	["Tiempo de juego por sesión"] = "每次的遊戲時間",
	["Tiempo hasta que pica"] = "到魚上鉤的時間",
	["Tiempo máximo entre los dos clics. Súbelo si tus dobles clics no lanzan."] = "兩次點擊之間的最長間隔。如果雙擊無法拋竿，請調高此值。",
	["Tiempo pescando"] = "釣魚時長",
	["Tiempo: %s"] = "時間：%s",
	["Tiene cuatro partes que se hacen por separado: Cementerio, Biblioteca, Armería y Catedral, de la más fácil a la más difícil."] = "這裡分成四個區域，要分開打：墓地、圖書館、軍械庫與大教堂，由易到難。",
	["Tienes"] = "你有",
	["Tienes %d"] = "你有 %d 個",
	["Tienes %d  ·  en %s"] = "你有 %d  ·  在%s",
	["Tienes %d casillas libres"] = "你有 %d 個空格",
	["Tienes %d de %d"] = "你擁有 %d / %d",
	["Tienes %d de %d casillas de bolsa en el banco."] = "你有 %d/%d 個銀行背包欄位。",
	["Tienes %d de %d casillas de bolsa. La siguiente cuesta %s; después pon una bolsa en ella."] = "你有 %d/%d 個背包欄位。下一個需要 %s；之後放一個背包進去。",
	["Tienes %d encendidas. Abajo está cada una, con lo que hace, por si quieres cambiar algo."] = "你已開啟 %d 項。下方列出每一項及其作用，方便你調整。",
	["Tienes %d misiones listas"] = "你有 %d 個已完成的任務",
	["Tienes %d misiones listas para entregar"] = "你有 %d 個任務可交付",
	["Tienes %d misiones listas para entregar. ¿Las juntamos en una ruta?"] = "你有 %d 個任務可以交付。要把它們排成一條路線嗎？",
	["Tienes %d para gastar"] = "你有 %d 點可用",
	["Tienes %d piezas mejores para pescar en tus bolsas."] = "你的背包裡有 %d 件更好的釣魚裝備。",
	["Tienes %d puntos de talento: empieza por %s"] = "你有 %d 點天賦點數：先點%s",
	["Tienes %d puntos fuera de %s. Alfa nunca quita talentos: para seguir este build, reinicia tus talentos con tu entrenador de clase y Alfa te los vuelve a poner con un clic. O elige el build de la rama que ya llevas."] = "你有 %d 點不在%s中。Alfa 絕不會移除天賦：要跟隨這個配點，請找職業訓練師重置天賦，Alfa 會一鍵幫你重新點好。或者選擇你已點的天賦系的配點。",
	["Tienes %d puntos libres, pero los talentos que siguen en %s no existen en tu árbol (puede que cambiaran con un parche). Ponlos a mano en la ventana del juego o prueba otro estilo."] = "你有 %d 點未分配點數，但%s中接下來的天賦在你的天賦樹中不存在（可能被修正檔改動了）。請在遊戲視窗中手動點，或試試其他風格。",
	["Tienes %s de %s"] = "你有 %s / %s",
	["Tienes %s precios de tus búsquedas. Para conocer todos, escanea en la casa de subastas."] = "你有 %s 個來自搜尋的價格。想知道全部的價格，請在拍賣場掃描。",
	["Tienes 1 misión lista para entregar"] = "你有 1 個任務可交付",
	["Tienes 5 puntos de combo y estás en grupo: el sangrado rinde más."] = "你有 5 點連擊點數且在隊伍中：流血效果更划算。",
	["Tienes 5 puntos de combo: el remate más fuerte."] = "你有 5 點連擊點數：最強的終結技。",
	["Tienes 5 puntos de combo: muerde fuerte."] = "你有 5 點連擊點數：狠狠咬下去。",
	["Tienes 6 guías abiertas"] = "你開啟了 6 個指南",
	["Tienes activado «Rechazar invitaciones a hermandad» en Ajustes > Comodidades > Social: apágalo para que te llegue la invitación."] = "你在「設定 > 便利功能 > 社交」中開啟了「拒絕公會邀請」：請將它關閉，才能收到邀請。",
	["Tienes cambios sin confirmar en la ventana de talentos: se descartan antes de aplicar."] = "天賦視窗中有尚未確認的變更：套用前會先捨棄。",
	["Tienes cambios sin guardar en la ventana de talentos del juego: guárdalos o deshazlos ahí primero"] = "遊戲的天賦視窗中有未儲存的變更：請先在那裡儲存或復原",
	["Tienes encendido «solo las misiones de mi ruta»: solo acepta las de tu ruta."] = "你已開啟「只接我路線上的任務」：只會接受你路線上的任務。",
	["Tienes furia: úsalo antes de la siguiente pelea, te da más poder de ataque a ti y a tu grupo."] = "你有怒氣：在下一場戰鬥前使用它，可以提高你和隊友的攻擊強度。",
	["Tienes habilidades nuevas"] = "你有新技能可學",
	["Tienes habilidades sin aprender (%d). Aprenderlas te hace más fuerte."] = "你有 %d 個技能尚未學習。學會它們會讓你更強。",
	["Tienes la %s, %d versiones atrás."] = "你的版本是 %s，落後 %d 個版本。",
	["Tienes la %s."] = "你的版本是 %s。",
	["Tienes más rangos de los que pide tu build."] = "你點的等級比配點要求的多。",
	["Tienes puesto «%s». Abre la ventana para afinar cada detalle: distancia, pasto, niebla, agua, cámara, placas y filtros."] = "你已套用「%s」。開啟視窗可以微調每個細節：距離、草地、霧、水、鏡頭、名條與濾鏡。",
	["Tienes puntos fuera del plan: Alfa no los quita, solo agrega."] = "你有規劃外的點數：Alfa 不會移除，只會新增。",
	["Tienes seis guías abiertas: cierra una y vuelve a intentarlo."] = "你開啟了六個指南：關閉一個後再試。",
	["Tienes todo %s"] = "你已擁有全部%s",
	["Tienes un hechizo para ir al Claro de la Luna, el santuario de los druidas."] = "你有一個法術能前往德魯伊的聖地月光林地。",
	["Tienes un punto de talento: %s"] = "你有一點天賦點數：%s",
	["Tienes una misión de clase"] = "你有一個職業任務",
	["Tinte de color"] = "色調",
	["Tipo"] = "類型",
	["Tirion Vadín fue expulsado de la Mano de Plata por defender a Eitrigg, un orco que le salvó la vida. Hoy Eitrigg aconseja a Thrall en Orgrimmar."] = "提里奧·弗丁因為維護救過他一命的獸人艾崔格，被逐出了白銀之手。如今艾崔格在奧格瑪為索爾出謀劃策。",
	["Tirion Vadín, el paladín expulsado de la orden, vive solo en una cabaña de estas tierras."] = "被逐出騎士團的聖騎士提里奧·弗丁獨自住在這片土地上的一間小屋裡。",
	["Toca %s."] = "該%s了。",
	["Toca ahora"] = "該點了",
	["Toca el interruptor para poner o quitar una; lo que tocas manda sobre el filtro."] = "撥動開關來加入或移除；你的手動選擇優先於篩選條件。",
	["Toca una tarjeta para prenderla o apagarla. Las encendidas llevan el borde de color."] = "點卡片開啟或關閉。開啟的卡片有彩色邊框。",
	["Toca «Seleccionarlo» otra vez, o usa el botón de raros."] = "再點一次「選取它」，或使用稀有怪按鈕。",
	["Tocando a la puerta de la %s"] = "正在敲%s的門",
	["Toda calidad"] = "所有品質",
	["Toda fuente"] = "所有來源",
	["Toda la cuenta"] = "整個帳號",
	["Toda ranura"] = "所有部位",
	["Todas"] = "全部",
	["Todas (%d)"] = "全部（%d）",
	["Todas las calidades"] = "所有品質",
	["Todas las guías de profesiones"] = "所有專業指南",
	["Todas las guías por zona y nivel, con la que Alfa te sugiere para ti."] = "依地區與等級列出所有指南，並標出 Alfa 為你推薦的那個。",
	["Todas las mascotas de compañía: dónde salen, cuánto cuestan y cuáles te faltan."] = "所有寵物：從哪裡取得、價格多少，以及你還缺哪些。",
	["Todas las mazmorras"] = "所有地城",
	["Todas las metas, notas y pasos de esta guía en otra ventana."] = "在另一個視窗中顯示這份指南的所有目標、備註與步驟。",
	["Todas las misiones"] = "所有任務",
	["Todas las misiones de aquí en el mejor orden, con la flecha."] = "這裡的所有任務，依最佳順序，跟著箭頭走。",
	["Todas las misiones de la zona en el mejor orden."] = "區域裡的所有任務，依最佳順序。",
	["Todas las misiones de tu zona (las que llevas y las que puedes tomar) en el mejor orden, como una guía."] = "你區域裡的所有任務（身上的和能接的），依最佳順序，像指南一樣。",
	["Todas las misiones que Lya te guardó, por zona, con su historia completa. También con /alfa historias."] = "Lya 為你保存的所有任務，依地區排列，附完整故事。也可以用 /alfa historias。",
	["Todas las monturas: cómo se consigue cada una, qué pide y si ya la tienes."] = "所有坐騎：每一匹如何取得、需要什麼，以及你是否已擁有。",
	["Todas las profesiones"] = "所有專業",
	["Todas las páginas de Alfa a la vista: mazmorras, talentos, combate, oficios, la manada y más."] = "Alfa 的所有頁面都顯示：地城、天賦、戰鬥、交易、狼群等等。",
	["Todas las secciones"] = "所有分區",
	["Todas las teclas de Alfa en un lugar"] = "Alfa 的所有按鍵都在一個地方",
	["Todas las teclas de Alfa en un lugar, para cambiarlas ahí mismo. También con /alfa teclas."] = "Alfa 的所有按鍵都在一個地方，可以直接變更。也可以用 /alfa teclas。",
	["Todas las zonas"] = "所有地區",
	["Todas las zonas y razas"] = "所有地區與種族",
	["Todavía es pronto"] = "現在還早",
	["Todavía nada en esta sesión"] = "本次還沒有收穫",
	["Todavía no"] = "還沒有",
	["Todavía no cambias de guarida"] = "你還沒換巢穴",
	["Todavía no conoces sus hechizos: se llenan al aprenderlos."] = "你還沒學會這些法術：學會後就會自動填入。",
	["Todavía no conozco tus recetas"] = "我還不知道你的配方",
	["Todavía no es para ti"] = "還不適合你",
	["Todavía no escribimos nada en tu historia. ¡Vamos a hacer algo grande!"] = "你的故事還一頁都沒寫。我們去做點大事吧！",
	["Todavía no estás en una hermandad. En la página La Jauría ves cómo unirte a la manada."] = "你還沒有加入公會。在 La Jauría 頁面可以了解如何加入狼群。",
	["Todavía no has pescado nada en esta sesión"] = "本次還沒有釣到任何東西",
	["Todavía no hay ayuda de rotación para ti"] = "還沒有適合你的輸出循環助手",
	["Todavía no hay datos de este personaje"] = "還沒有這個角色的資料",
	["Todavía no hay datos para esta gráfica."] = "此圖表還沒有資料。",
	["Todavía no hay foto de este banco"] = "這個銀行還沒有快照",
	["Todavía no hay guías para tu camino"] = "你的路線還沒有指南",
	["Todavía no hay peleas"] = "還沒有戰鬥記錄",
	["Todavía no hay progreso"] = "還沒有進度",
	["Todavía no hay una pelea anterior"] = "還沒有上一場戰鬥",
	["Todavía no hay una pelea que anunciar."] = "還沒有可通報的戰鬥。",
	["Todavía no hay una pelea que resumir."] = "還沒有可以總結的戰鬥。",
	["Todavía no lo pescas"] = "還沒釣到過",
	["Todavía no lo recolectas"] = "尚未採集過",
	["Todavía no lo sacas del agua. Cuando lo hagas, aquí verás cuántos llevas, cuándo y dónde."] = "你還沒把它從水裡釣上來。釣到後，這裡會顯示你釣了幾條、何時以及在哪裡。",
	["Todavía no pescas en %s. Lo que saques aquí se anota por zona."] = "你還沒在%s釣過魚。在這裡釣到的東西會依地區記錄。",
	["Todavía no puedes conseguirlo: %s."] = "你還無法取得它：%s。",
	["Todavía no recolectas nada"] = "還沒有採集任何東西",
	["Todavía no sabes pescar"] = "你還不會釣魚",
	["Todavía no se puede tomar: Alfa la recoge cuando se abra."] = "還不能接取：開放後 Alfa 會幫你接。",
	["Todavía no sigues ninguna guía. Elige una y Alfa te lleva paso a paso, con la flecha y la ruta."] = "你還沒有跟隨任何指南。選一個，Alfa 就會用箭頭和路線一步步帶你。",
	["Todavía no te alcanza."] = "你的錢還不夠。",
	["Todavía no tienes escalas propias. Pega una cadena de escala arriba."] = "尚無自訂權重。請在上方貼上權重字串。",
	["Todavía no tienes marcadores"] = "你還沒有標記",
	["Todavía no tienes rutas propias"] = "你還沒有專屬路線",
	["Todavía no tienes talentos para compartir."] = "你還沒有可分享的天賦。",
	["Todavía no tienes una guía abierta. Elige una y Alfa te lleva paso a paso: a dónde ir, qué hacer y con quién hablar."] = "你還沒有開啟任何指南。選一份，Alfa 就會一步一步帶你：去哪裡、做什麼、找誰說話。",
	["Todavía quedan pilones de los titanes en el cráter, y funcionan con cristales de colores."] = "火山口裡仍然矗立著泰坦的水晶塔，靠彩色水晶運作。",
	["Todo"] = "全部",
	["Todo Azeroth en un solo lienzo: acerca con la rueda, arrastra para moverte y pon tus marcadores con clic derecho."] = "整個艾澤拉斯盡在一張畫布上：用滾輪縮放，拖曳來移動，按右鍵放置你的標記。",
	["Todo a la mano"] = "一切觸手可及",
	["Todo a la vista otra vez"] = "全部重新顯示",
	["Todo al máximo seguro. Pide una tarjeta de video fuerte."] = "一切調到安全的最高值。需要強勁的顯示卡。",
	["Todo bien (lo más gastado: %d%%)"] = "一切正常（最低耐久度：%d%%）",
	["Todo como estaba antes de Alfa"] = "一切恢復到使用 Alfa 之前的樣子",
	["Todo con tu estilo"] = "一切都用你的風格",
	["Todo el juego, aunque no lo tengas"] = "整個遊戲，即使你沒有",
	["Todo el juego, aunque no lo tengas: objetos, PNJ, misiones, zonas y raros."] = "整個遊戲，即使你沒有：物品、NPC、任務、地區與稀有。",
	["Todo el juego, aunque no lo tengas: objetos, monturas, mascotas, PNJ, misiones, zonas y raros."] = "整個遊戲，即使你沒有：物品、坐騎、寵物、NPC、任務、地區與稀有怪。",
	["Todo el texto de Alfa un poco más grande, en cada ventana. Se suma al tamaño de Ajustes > Apariencia."] = "Alfa 每個視窗的文字都稍微放大。會疊加在「設定 > 外觀」的大小之上。",
	["Todo en orden"] = "一切正常",
	["Todo en orden: nada choca con Alfa."] = "一切正常：沒有和 Alfa 衝突的東西。",
	["Todo esto lo hace Alfa sola al hablar con quien da o recibe una misión. Mantén presionado Mayús para hacerlo tú en el momento."] = "與發放或接收任務的人交談時，Alfa 會自動完成這一切。按住 Shift 可以當場由你自己操作。",
	["Todo junto"] = "全部合併",
	["Todo junto muestra cada casilla en su lugar; por categorías agrupa equipo, consumibles, misiones y materiales; por bolsa pone cada bolsa en su bloque."] = "「全部合併」讓每一格都在原位；「依分類」將裝備、消耗品、任務物品與材料分組；「依背包」讓每個背包各自一區。",
	["Todo listo"] = "一切就緒",
	["Todo lo de Alfa, explicado por Lya y a un clic"] = "Alfa 的一切，莉婭來講，一點就到",
	["Todo lo que hay en Alfa"] = "Alfa 裡的一切",
	["Todo lo que no sea equipo"] = "所有非裝備物品",
	["Todo lo que se pinta en tus mapas, en un solo lugar. Lo de otros módulos de Alfa también llega aquí."] = "你地圖上顯示的所有內容，集中在一處。Alfa 其他模組的內容也會出現在這裡。",
	["Todo nivel"] = "所有等級",
	["Todo objeto, PNJ, misión, zona y raro, con dónde conseguirlo y «Guíame»."] = "所有物品、NPC、任務、地區與稀有怪，附取得地點與「帶我去」。",
	["Todo oficio"] = "所有職能",
	["Todo para el daño: críticos, sangrados y Abrumar muy seguido. Matas rapidísimo, pero no hay defensa extra: si se te juntan muchos, corre."] = "全力追求傷害：致命一擊、流血與頻繁的壓制。殺怪超快，但沒有額外的防禦：被一群怪圍住就快跑。",
	["Todo subtipo"] = "所有子類型",
	["Todo tipo"] = "所有類型",
	["Todos"] = "全部",
	["Todos llegan a %s"] = "都通往%s",
	["Todos los avisos de Alfa los dice Lya, también los de al entrar y el de hechizos nuevos, con letra más grande que cambias con su clic derecho."] = "Alfa 的所有提醒都由莉婭說出，包括登入時和新法術的提醒，字體更大，右鍵點她即可調整。",
	["Todos los de ese tipo, o solo uno (por ejemplo, solo cobre). Entre paréntesis, cuántos hay en tu zona."] = "該類型的全部，或只選一種（例如只選銅）。括號內是你所在地區的數量。",
	["Todos los materiales"] = "所有材料",
	["Todos los niveles"] = "所有等級",
	["Todos los objetos, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "所有物品、NPC、任務、地區與稀有，即使你沒有：誰掉落及掉落機率、誰販售及在哪裡、哪個任務給予以及如何前往。",
	["Todos los objetos, monturas, mascotas, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "所有物品、坐騎、寵物、NPC、任務、地區與稀有怪，即使你沒有：誰掉落、機率多少，誰販售、在哪裡，哪個任務給予以及如何前往。",
	["Todos los paladines sueñan con la Crematoria, la espada de Alexandros Mograine."] = "每個聖騎士都夢想得到亞歷山德羅·莫格萊尼的劍——灰燼使者。",
	["Todos los pasos"] = "所有步驟",
	["Todos los pasos de esta guía; clic en uno para verlo."] = "此指南的所有步驟；點擊任一步即可查看。",
	["Todos los pasos de la guía en la ventana de guía."] = "在指南視窗中查看指南的所有步驟。",
	["Todos los que callaste"] = "所有已關閉的",
	["Todos los tipos"] = "所有類型",
	["Todos tus personajes"] = "你所有的角色",
	["Todos tus puntos ya están gastados y parte de ellos fuera de este build. Para cambiarte a este build, reinicia tus talentos con tu entrenador de clase; después Alfa te los aplica con un clic."] = "你的點數已全部分配，其中有一部分不在此配點中。若要改用此配點，請找職業訓練師重置天賦；之後 Alfa 一鍵就能幫你點好。",
	["Todos: también los avisos leves. Solo los graves: únicamente lo que puede matarte."] = "全部：連輕微的警報也顯示。只顯示嚴重的：只顯示可能讓你死亡的。",
	["Toma el botín de la pesca enseguida, aunque tengas apagado el botín automático del juego."] = "立即拾取釣到的東西，即使遊戲的自動拾取已關閉也一樣。",
	["Toma el dinero y los objetos de tus cartas, una por una. Las de pago contra entrega y las de un MJ se quedan para que las abras tú."] = "逐封拿取郵件中的金錢和物品。貨到付款的郵件和 GM 郵件會留給你自己開啟。",
	["Toma las de tu ruta que tienes cerca"] = "接取附近你路線上的任務",
	["Toma las mejores de cerca que ya puedes hacer."] = "接取附近你現在就能做的最佳任務。",
	["Toma las mejores misiones de por aquí y después ciérralas juntas."] = "接取這附近的最佳任務，然後一起完成。",
	["Toma todo el botín de una vez cuando tienes el despojo automático."] = "開啟自動拾取時，一次拿走全部戰利品。",
	["Toma unas misiones cerca y Alfa las cierra contigo por el camino más corto."] = "在附近接幾個任務，Alfa 會和你一起依最短路線完成。",
	["Tomando tus cartas..."] = "正在拿取郵件...",
	["Tomar %s"] = "接受%s",
	["Tomar el vuelo de tu ruta"] = "搭乘路線上的航班",
	["Tomar la mejor recompensa"] = "選擇最好的獎勵",
	["Tomar todo"] = "全部拿取",
	["Tomarla"] = "接受它",
	["Tomarla, completarla o entregarla."] = "接受、完成或交付它。",
	["Tomaste otra misión de su grupo: esta ya no se abre."] = "你接了同組的另一個任務：這個不會再開放。",
	["Top %d de %s"] = "前 %d 名（%s）",
	["Top de daño"] = "傷害排行",
	["Tope por personaje"] = "每個角色的上限",
	["Torre de zepelines de %s"] = "%s飛艇塔",
	["Tortura mental: daño constante y frena al enemigo."] = "精神鞭笞：持續傷害並緩速敵人。",
	["Total"] = "總計",
	["Tramo %d de %d: %s."] = "第 %d / %d 段：%s。",
	["Trampas, golpes cuerpo a cuerpo de emergencia y mucha agilidad: el cazador más difícil de atrapar."] = "陷阱、緊急用的近戰攻擊與大量敏捷：最難被抓住的獵人。",
	["Tranquila, aquí nadie se queda atrás."] = "別擔心，這裡沒人會被丟下。",
	["Tranquilo"] = "穩健",
	["Transformar"] = "加工",
	["Transformar %d"] = "加工 %d",
	["Transmutar hierro en oro existe de verdad: el sueño de todo alquimista."] = "把鐵轉化成金真的存在：每個鍊金術師的夢想。",
	["Tranvía de %s"] = "%s地鐵站",
	["Tras aceptar o entregar, cierra la ventana del PNJ si solo ofrece misiones que tu guía no hace."] = "接受或交付後，如果 NPC 只提供指南不做的任務，就關閉其視窗。",
	["Tras la Guerra de los Tres Martillos, los Martillo Salvaje se fueron a Grim Batol y luego al Interior; los Hierro Negro, a la Montaña Roca Negra."] = "三錘之戰後，蠻錘氏族先去了格瑞姆巴托，後來又去了辛特蘭；黑鐵氏族則去了黑石山。",
	["Tras la Segunda Guerra, mantener a los orcos en los campos de internamiento costaba una fortuna. Esos impuestos ayudaron a romper la Alianza."] = "第二次戰爭後，把獸人關在收容所裡花費巨大。這些稅賦助長了聯盟的分裂。",
	["Tras las Guerras Trol, el viejo Arathor se repartió en siete reinos: Lordaeron, Ventormenta, Gilneas, Alterac, Stromgarde, Kul Tiras y Dalaran."] = "食人妖戰爭之後，古老的阿拉索分裂成七個王國：洛丹倫、暴風城、吉爾尼斯、奧特蘭克、激流堡、庫爾提拉斯和達拉然。",
	["Tratado"] = "聖契",
	["Treinta. La manada habla de ti."] = "三十級。狼群都在談論你。",
	["Tres caminos para cada objeto"] = "每件物品三種處理方式",
	["Tres estilos y el lobo"] = "三種風格與狼",
	["Tres pasos y listo"] = "三步搞定",
	["Tres pasos: tus clics, dónde van tus marcos y una prueba."] = "三步：你的點擊、框架位置與一次測試。",
	["Trescientos puntos. Eres maestro de tu oficio."] = "三百點。你已是這門專業的大師。",
	["Trilineal"] = "三線性",
	["Trinquete es un puerto goblin neutral: ahí se tolera a cualquiera que traiga oro, y su barco lleva hasta Bahía del Botín."] = "棘齒城是中立的哥布林港口：只要帶著金幣，誰都受歡迎，它的船開往藏寶海灣。",
	["Trofeo"] = "獎盃",
	["Trofeos y concurso"] = "獎盃與大賽",
	["Trols"] = "食人妖",
	["Trueno"] = "雷霆",
	["Tu Alfa ya está configurada. Revisa o cambia cualquier respuesta cuando quieras."] = "你的 Alfa 已設定完成。隨時可以查看或變更任何回答。",
	["Tu Grito de batalla llega a todo el grupo y dura más."] = "你的戰鬥怒吼範圍涵蓋整個隊伍，而且持續更久。",
	["Tu abisario aguanta los golpes por ti: deja que empiece la pelea."] = "你的虛空行者會替你承受攻擊：讓它先開打。",
	["Tu abisario: un demonio que aguanta golpes por ti. Perfecto para ir solo."] = "你的虛空行者：替你挨打的惡魔。單練的完美搭檔。",
	["Tu anuncio ya está en el tablón de la manada. Se quita solo en una hora."] = "你的公告已經貼在狼群公告板上了。一小時後會自動撤下。",
	["Tu aprendiz no gana experiencia desde hace 20 minutos. ¿Le echas la mano?"] = "你的學徒已經 20 分鐘沒獲得經驗了。去幫他一把嗎？",
	["Tu aprendiz: %s"] = "你的學徒：%s",
	["Tu arma a veces da golpes extra. De lo mejor para armas lentas."] = "你的武器有時會額外攻擊幾次。慢速武器的最佳選擇之一。",
	["Tu arma no tiene encantamiento: Lengua de fuego."] = "你的武器沒有附魔：火舌武器。",
	["Tu arma no tiene encantamiento: Muerdepiedras."] = "你的武器沒有附魔：石化武器。",
	["Tu arma no tiene encantamiento: Viento furioso."] = "你的武器沒有附魔：風怒武器。",
	["Tu arma no usa munición."] = "你的武器不使用彈藥。",
	["Tu arma pega con fuego. Buena para armas lentas."] = "你的武器帶上火焰攻擊。適合慢速武器。",
	["Tu arma secundaria pega más."] = "你的副手武器傷害更高。",
	["Tu armadura ya no aguanta mucho (%d%%). ¿Vamos a reparar?"] = "你的護甲快撐不住了（%d%%）。去修一下吧？",
	["Tu avance arriba, el paso en una tarjeta, los dos siguientes a la vista y los botones abajo."] = "進度在上方，目前步驟顯示在卡片中，接下來兩步一目了然，按鈕在下方。",
	["Tu avance de misiones con tu grupo"] = "與隊伍分享你的任務進度",
	["Tu ayuda de rotación está lista"] = "你的輸出循環助手已就緒",
	["Tu banco"] = "你的銀行",
	["Tu banco está completo"] = "你的銀行已全部解鎖",
	["Tu banco y lo que llevas"] = "你的銀行與隨身物品",
	["Tu banco ya tiene todas sus casillas."] = "你的銀行已擁有全部欄位。",
	["Tu barra de %s está vacía"] = "你的%s快捷列是空的",
	["Tu barra se llena al salir de combate."] = "脫離戰鬥後會填滿你的快捷列。",
	["Tu botón de emergencia."] = "你的緊急按鈕。",
	["Tu buff"] = "你的增益效果",
	["Tu build"] = "你的配點",
	["Tu camino"] = "你的路線",
	["Tu camino [mapa]"] = "你的路線",
	["Tu camino en el mapa y un aullido nuevo"] = "地圖上的路線和全新的狼嚎",
	["Tu camino: %d tramos, %s. Escribe arriba para ir a otro lugar."] = "你的路線：%d 段，%s。在上方輸入可以去別的地方。",
	["Tu caña tiene cebo: %s más."] = "你的魚竿上有魚餌：還剩 %s。",
	["Tu cita con la manada"] = "你和狼群的集合",
	["Tu cita, %s"] = "你的集合，%s",
	["Tu clase la gana con esta cadena de misiones."] = "你的職業透過這條任務鏈獲得它。",
	["Tu clase no lo usa: guárdalo para otro personaje o súbelo a la subasta."] = "你的職業用不到：留給其他角色，或拿去拍賣場賣。",
	["Tu clase no necesita recordatorio"] = "你的職業不需要提醒",
	["Tu clase no tiene habilidades de reacción. Si quieres, Alfa te avisa cuando el juego hace brillar una de tus habilidades (en Avisos, abajo)."] = "你的職業沒有反應類技能。如果需要，Alfa 可以在遊戲讓你的某個技能發光時提醒你（在下方「提醒」中）。",
	["Tu clase todavía no tiene uno propio: Alfa usa el más parecido."] = "你的職業還沒有專屬配點：Alfa 會使用最接近的。",
	["Tu cliente no deja cambiar talentos desde un addon. Usa la ventana de talentos del juego (tecla N)."] = "你的用戶端不允許插件變更天賦。請使用遊戲的天賦視窗（N 鍵）。",
	["Tu cliente no tiene la línea de tiempo de jefes."] = "你的用戶端沒有首領時間軸。",
	["Tu cliente no trae el medidor de daño del juego."] = "你的用戶端沒有遊戲內建的傷害統計。",
	["Tu cliente no trae la ayuda de combate de Blizzard."] = "你的用戶端沒有 Blizzard 的戰鬥輔助。",
	["Tu cola"] = "你的佇列",
	["Tu cola de cocina está vacía"] = "你的烹飪佇列是空的",
	["Tu color de acento"] = "你的強調色",
	["Tu compañera"] = "你的夥伴",
	["Tu compañera de caza"] = "你的狩獵夥伴",
	["Tu compañera en Alfa. Lleva el nombre de una gran perrita, en su memoria."] = "你在 Alfa 的夥伴。她的名字來自一隻很棒的小狗，以此紀念。",
	["Tu configuración como texto: guárdalo de respaldo o pásaselo a la manada."] = "以文字形式保存你的設定：留作備份，或分享給狼群。",
	["Tu configuración de Alfa"] = "你的 Alfa 設定",
	["Tu configuración quedó guardada como «%s»."] = "你的設定已儲存為「%s」。",
	["Tu corcel vil: una montura propia de brujo. ¡Felicidades!"] = "你的地獄戰馬：術士專屬的坐騎。恭喜！",
	["Tu correo"] = "你的郵件",
	["Tu cuerpo"] = "你的屍體",
	["Tu cuerpo está a %s, como %s corriendo."] = "你的屍體在 %s 外，步行約 %s。",
	["Tu cuerpo quedó dentro de %s: corre a su entrada."] = "你的屍體在%s裡：跑到它的入口。",
	["Tu curación"] = "你的治療",
	["Tu curación básica. Úsala entre peleas o cuando estés herido."] = "你的基礎治療。在戰鬥空檔或受傷時使用。",
	["Tu curación fuerte. Úsala entre peleas o cuando alguien está muy herido."] = "你的強力治療。在戰鬥空檔或有人重傷時使用。",
	["Tu curación más fuerte. Es lenta: empiézala antes de que sea tarde."] = "你最強的治療。施法慢：趁還來得及先開始。",
	["Tu daño"] = "你的傷害",
	["Tu demonio"] = "你的惡魔",
	["Tu demonio es más fuerte y tú más resistente: el brujo más seguro."] = "你的惡魔更強，你也更耐打：最安全的術士。",
	["Tu destino"] = "你的目的地",
	["Tu destino y tus marcadores ya no desaparecen cuando hay muchos pines."] = "圖釘很多時，你的目的地和標記不會再消失。",
	["Tu diario"] = "你的日誌",
	["Tu diario de mazmorras"] = "你的地城導覽手冊",
	["Tu día con la manada: el plan, lo urgente y tu clase."] = "你與狼群的一天：計畫、緊急事項與你的職業。",
	["Tu día de caza"] = "你的狩獵日",
	["Tu día de caza: Lya cuenta tus misiones, niveles, oro y raros del día. Pídeselo con /alfa lya dia."] = "你的狩獵日：莉婭統計當天的任務、等級、金幣和稀有怪。用 /alfa lya dia 問她。",
	["Tu elección"] = "你的選擇",
	["Tu entrenador de clase tiene algo para ti."] = "你的職業訓練師有東西給你。",
	["Tu entrenador de equitación"] = "你的騎術訓練師",
	["Tu entrenador tiene algo nuevo para ti"] = "你的訓練師有新東西可以教你",
	["Tu entrenador: %s (%s)."] = "你的訓練師：%s（%s）。",
	["Tu entrenador: %s."] = "你的訓練師：%s。",
	["Tu equipo está al %d %%: repara antes de entrar"] = "你的裝備耐久度只剩 %d %%：進去之前先修理",
	["Tu equipo está al %d%%. Mejor repararlo antes de la siguiente pelea."] = "你的裝備耐久度為 %d%%。最好在下一場戰鬥前修理。",
	["Tu equipo está por romperse"] = "你的裝備快壞了",
	["Tu equipo se está gastando"] = "你的裝備耐久度正在下降",
	["Tu equipo ya va en %d %%: cuídalo."] = "你的裝備耐久度已經只剩 %d %%：要愛惜它。",
	["Tu equipo, tus bolsas y tu entrenamiento están al día."] = "你的裝備、背包與訓練都沒問題。",
	["Tu escudo protege mucho, pero deja al aliado con el alma debilitada un rato: no puedes ponérselo otra vez enseguida."] = "你的護盾防護力很強，但會讓盟友暫時處於虛弱靈魂狀態：無法馬上再給他上一個。",
	["Tu especialización"] = "你的專精",
	["Tu estilo"] = "你的風格",
	["Tu estilo (Alfa, Clásico WoW o Cristal), el color de acento y el aullido."] = "你的風格（Alfa、經典 WoW 或玻璃）、強調色與狼嚎。",
	["Tu estilo, el color de acento, el aullido, leer mejor y tus atajos."] = "你的風格、強調色、狼嚎、更易閱讀和你的快捷鍵。",
	["Tu estilo: %s"] = "你的風格：%s",
	["Tu facción (%s)"] = "你的陣營（%s）",
	["Tu forma de viaje es un felino veloz... pero en una carrera yo no te la pondría fácil."] = "你的旅行形態是一隻敏捷的貓科動物…但要是賽跑，我可不會讓你輕鬆贏。",
	["Tu gente no confía en la magia arcana: recuerda bien lo que pasó con Azshara y el Pozo de la Eternidad."] = "你的族人不信任秘法魔法：他們清楚地記得艾薩拉和永恆之井發生過什麼。",
	["Tu gente, los humanos, desciende de las tribus que el rey Thoradin unió en Arathor hace miles de años."] = "你的族人——人類——是數千年前索拉丁國王在阿拉索統一的那些部族的後裔。",
	["Tu golpe más fuerte desde el nivel 40 hasta el 60."] = "從等級 40 到 60 你最強的攻擊。",
	["Tu golpe más fuerte desde el nivel 40."] = "從等級 40 起你最強的攻擊。",
	["Tu golpe más fuerte, crece con tu bloqueo."] = "你最強的攻擊，會隨格擋值成長。",
	["Tu golpe más fuerte, y además reduce las curas del enemigo."] = "你最強的攻擊，還能降低敵人受到的治療。",
	["Tu golpe más fuerte."] = "你最強的攻擊。",
	["Tu golpe principal contra jefes."] = "對付首領的主力攻擊。",
	["Tu golpe principal."] = "你的主力攻擊。",
	["Tu grupo"] = "你的隊伍",
	["Tu grupo en el mapa"] = "地圖上的隊伍",
	["Tu grupo o banda en el mapa y el minimapa, con el color de su clase."] = "在地圖與小地圖上用職業顏色顯示你的隊伍或團隊。",
	["Tu grupo y tu banda con su vida, para curar con un clic. Se cambia fuera de combate."] = "顯示你的隊伍與團隊成員的生命值，一鍵即可治療。只能在戰鬥外變更。",
	["Tu grupo, tu hermandad y tus amigos en el mapa, con Seguir y la página del clan."] = "在地圖上顯示你的隊伍、公會與好友，並提供「跟隨」與公會頁面。",
	["Tu guarida a la vista"] = "你的巢穴一目了然",
	["Tu guarida en el rastreador y en el cuadro de los lobos, y Lya te avisa si el juego te cambia de capa."] = "追蹤器和狼的滑鼠提示裡顯示你的巢穴，遊戲換位面時莉婭會提醒你。",
	["Tu guarida está abierta: si alguien de la manada pide entrar, Alfa lo invita a tu grupo."] = "你的巢穴已開啟：狼群裡有人想進來時，Alfa 會邀請他入隊。",
	["Tu guía"] = "你的指南",
	["Tu guía deja fuera las misiones que ya no dan experiencia, salvo que otra las necesite."] = "你的指南會略過不再給經驗的任務，除非其他任務需要它們。",
	["Tu guía está lista. Ábrela para ver tu paso."] = "你的指南已準備好。開啟它查看你的步驟。",
	["Tu guía puede elegir y avanzar sola, o preguntarte en cada cruce."] = "你的指南可以自行選擇並繼續，或在每個岔路口詢問你。",
	["Tu guía te lleva a entrenar en %d pasos."] = "你的指南會用 %d 步帶你去訓練。",
	["Tu guía te lleva a entrenar en este paso."] = "你的指南會在這一步帶你去訓練。",
	["Tu guía te lleva a tomarla."] = "你的指南會帶你去接這個任務。",
	["Tu guía terminó y el camino se abre"] = "你的指南結束了，前方出現岔路",
	["Tu guía y Hoy dicen lo mismo: al terminar «Desbloquear» vuelves solo a tu guía, y el final de una guía con pasos sin hacer ya no dice «terminaste»."] = "指南和「今天」說法一致：完成「解鎖」後會自動回到你的指南，有未完成步驟的指南結尾不再顯示「已完成」。",
	["Tu guía ya no te manda a entregar misiones sin terminar: primero te lleva a lo que falta, y «Cerrar mis misiones» se pone al día sola."] = "你的指南不會再叫你去繳交還沒完成的任務：會先帶你去完成剩下的部分，「完成我的任務」也會自動保持最新。",
	["Tu guía, más lista"] = "更聰明的指南",
	["Tu hechizo principal de fuego."] = "你的主要火焰法術。",
	["Tu hechizo principal."] = "你的主要法術。",
	["Tu hechizo principal: daño y frena al enemigo."] = "你的主要法術：造成傷害並緩速敵人。",
	["Tu hermandad conectada"] = "線上公會成員",
	["Tu hermandad sabe tu clase y tu nivel, para que te avisen si les sale algo que te sirve."] = "你的公會知道你的職業和等級，他們拾取到你用得上的東西時就能告訴你。",
	["Tu hermandad se entera cuando llegas al nivel 60, consigues tu primera montura o cazas un raro."] = "當你升到 60 級、拿到第一匹坐騎或獵到稀有怪時，你的公會會知道。",
	["Tu hermandad y tu grupo reciben los horarios que tomas, y tú los suyos."] = "你的公會與隊伍會收到你搭乘的時刻，你也會收到他們的。",
	["Tu historia"] = "你的故事",
	["Tu historia empieza pronto"] = "你的故事即將開始",
	["Tu historia tiene una página: %s."] = "你的故事有一頁：%s。",
	["Tu historial"] = "你的歷史記錄",
	["Tu insignia de La Jauría en el borde de tu retrato, y en el de tu objetivo si la lleva."] = "你的 La Jauría 徽章顯示在頭像邊緣；如果目標也有，也會顯示在目標頭像上。",
	["Tu insignia en los retratos"] = "頭像上的徽章",
	["Tu instalación está mezclada o incompleta (%s). Cierra el juego, borra todas las carpetas de Alfa en Interface/AddOns e instala Alfa de nuevo con la app de CurseForge o el zip más reciente (no \"Source code\")."] = "你的安裝混雜了不同版本或不完整（%s）。請關閉遊戲，刪除 Interface/AddOns 中所有 Alfa 資料夾，然後使用 CurseForge 應用程式或最新的壓縮檔重新安裝 Alfa（不要用「Source code」）。",
	["Tu instructor más cercano: %s, en %s."] = "最近的訓練師：%s，在%s。",
	["Tu instructor más cercano: %s."] = "最近的訓練師：%s。",
	["Tu ira se llena al pegar y al recibir golpes: entra a la pelea con Cargar para empezar con ira."] = "攻擊和挨打都會累積怒氣：用衝鋒開場，一開始就有怒氣。",
	["Tu libro no tiene hechizos para aliados"] = "你的法術書中沒有可對隊友施放的法術",
	["Tu lista de compras"] = "你的購物清單",
	["Tu lista de compras no pudo agregarlo."] = "無法加入你的購物清單。",
	["Tu lista de sonidos"] = "你的聲音清單",
	["Tu lista de sonidos está vacía. Agrega uno con /alfa silenciar <número>."] = "你的聲音清單是空的。用 /alfa silenciar <編號> 加入一個。",
	["Tu lista de sonidos quedó vacía."] = "你的聲音清單已清空。",
	["Tu lista está vacía"] = "你的清單是空的",
	["Tu lista ya tiene 20 metas: termina o quita alguna primero."] = "你的清單已有 20 個目標：先完成或移除一個。",
	["Tu lista: síguelos con la flecha, compártelos con el grupo, cámbialos o bórralos."] = "你的清單：用箭頭跟隨、分享給隊伍、變更或刪除。",
	["Tu loba compañera: consejos cortos, ánimo y nunca te deja atrás."] = "你的母狼夥伴：簡短的建議、鼓勵，而且從不丟下你。",
	["Tu loba compañera: te da consejos y ánimo. También con /alfa lya."] = "你的母狼夥伴：給你建議與鼓勵。也可以用 /alfa lya。",
	["Tu lugar resalta más: tu flecha lleva un aro y un pulso suave, y se ve bien hasta en la nieve."] = "你的位置更醒目：箭頭帶有光環和柔和的脈動，即使在雪地裡也看得清楚。",
	["Tu manada"] = "你的狼群",
	["Tu manada en el mapa: tu grupo y quienes usan Alfa y comparten. Síguelos con la flecha, invítalos y conoce al clan."] = "地圖上的狼群：你的隊伍以及使用 Alfa 並分享位置的人。用箭頭跟隨他們、邀請他們，並認識公會。",
	["Tu manada está fuera del mapa"] = "你的狼群不在地圖上",
	["Tu manáfago: quita magia y bloquea hechizos enemigos."] = "你的地獄獵犬：驅散魔法並封鎖敵人的法術。",
	["Tu mapa"] = "你的地圖",
	["Tu mapa del ratón está vacío: elige algo en una ranura primero."] = "你的滑鼠點擊配置是空的：請先為某個欄位選擇動作。",
	["Tu marcador"] = "你的標記",
	["Tu mascota"] = "你的寵物",
	["Tu mascota aprende habilidades de otras bestias: doma una que sepa lo que quieres y te lo enseña."] = "你的寵物能從其他野獸身上學技能：馴服一隻會你想要技能的野獸，牠就會教給你。",
	["Tu mascota hace gran parte del trabajo y aguanta los golpes: la forma más fácil y segura de subir con cazador."] = "寵物會幫你做大部分的事並承受攻擊：獵人最簡單、最安全的練等方式。",
	["Tu mascota tiene poca vida: cúrala."] = "你的寵物生命力很低：治療牠。",
	["Tu mejor día: %d misiones"] = "最佳一天：%d 個任務",
	["Tu mejor día: %d misiones."] = "你的最佳一天：%d 個任務。",
	["Tu mentor: %s"] = "你的導師：%s",
	["Tu montura de clase"] = "你的職業坐騎",
	["Tu montura rápida (nivel 60)"] = "你的快速坐騎（60 級）",
	["Tu munición"] = "你的彈藥",
	["Tu nivel"] = "你的等級",
	["Tu nivel, reparar, comida y bebida, y la entrada de la mazmorra para ti."] = "你的等級、修理、食物與飲料，以及適合你的地城入口。",
	["Tu nota"] = "你的備註",
	["Tu objetivo esquivó: Abrumar no se puede esquivar y pega fuerte. Necesita actitud de batalla."] = "你的目標閃躲了：壓制無法被閃躲且傷害很高。需要戰鬥姿態。",
	["Tu oro"] = "你的金幣",
	["Tu pantalla y tu compañera"] = "你的畫面與你的夥伴",
	["Tu papel"] = "你的職責",
	["Tu paso de ahora es el %d."] = "你目前在步驟 %d。",
	["Tu paso de ahora es el %d: %s."] = "你目前在步驟 %d：%s。",
	["Tu pelea"] = "你的戰鬥",
	["Tu personaje"] = "你的角色",
	["Tu personaje aparece en el mapa de quienes también se dejan ver. Solo su lugar en el juego y nunca dentro de mazmorras; va por un canal oculto que alguien con otro addon podría leer."] = "你的角色會出現在同樣公開位置的人的地圖上。只有在遊戲中的位置，在地城中不會顯示；它透過一個隱藏頻道傳送，使用其他插件的人可能讀取。",
	["Tu personaje deja de decir \"No tengo suficiente maná\", \"Eso todavía no está listo\" y parecidas. El texto rojo sigue."] = "你的角色不再說「法力不足」、「還沒準備好」之類的話。紅字提示仍會顯示。",
	["Tu personaje no aparece en el mapa de nadie de La Jauría. Lo cambias cuando quieras en la página de La Jauría."] = "你的角色不會出現在 La Jauría 任何人的地圖上。隨時可以在 La Jauría 頁面中變更。",
	["Tu personaje todavía no recolecta. Con Minería o Herboristería, Alfa une las minas o las hierbas de tu zona en una vuelta corta. Te las enseña un instructor de profesión."] = "你的角色還不會採集。學會採礦或草藥學後，Alfa 會把你所在地區的礦點或草藥串成一條短環線。專業訓練師可以教你。",
