	["Turalyon y Alleria Brisaveloz cruzaron el Portal Oscuro tras la guerra para cerrarles el paso a los orcos, y no regresaron."] = "戰後，圖拉楊和奧蕾莉亞·風行者穿過黑暗之門去阻截獸人，再也沒有回來。",
	["Tus %d puntos están donde tu build los pide. Lo que sigue es el equipo: piezas con las estadísticas que le sirven a tu build."] = "你的 %d 點都依配點點好了。接下來是裝備：帶有你配點所需屬性的裝備。",
	["Tus actitudes son de batalla, defensiva y rabiosa; elige la que pida el momento."] = "你的姿態有戰鬥、防禦和狂暴；依當下情況選擇。",
