	["Tus recetas que dejan ganancia"] = "你能賺錢的配方",
	["Tus spots de farmeo en el mapa, dorados y en su propia capa."] = "你的刷點顯示在地圖上，金色，有自己的圖層。",
	["Tus spots nuevos también salen en el mapa de los lobos de tu hermandad, y ves los suyos."] = "你的新刷點也會出現在公會狼群的地圖上，你也能看到他們的。",
	["Tus talentos"] = "你的天賦",
	["Tus tótems de tierra, fuego, agua y aire se ganan con misiones a lo largo de tu camino."] = "你的大地、火焰、水和空氣圖騰，要在旅途中透過任務獲得。",
	["Tuya"] = "你的",
	["Tyrande liberó a Illidan para pelear contra la Plaga, y Maiev, su carcelera, nunca se lo perdonó."] = "泰蘭妲釋放了伊利丹來對抗天譴軍團，他的獄卒瑪翼夫從未原諒她。",
	["Tótem"] = "圖騰",
	["Tótems"] = "圖騰",
	["Tótems enemigos"] = "敵方圖騰",
	["Tú"] = "你",
	["Tú no contestas: actívalo en los ajustes de abajo si quieres ayudar a la manada."] = "你不會回應：如果想幫狼群，在下面的設定裡開啟。",
	["Tú recibes los golpes y proteges al grupo. Necesitas escudo."] = "由你承受攻擊並保護隊伍。需要盾牌。",
	["Tú también contestas: si alguien busca algo que llevas, Alfa le dice cuántos tienes (solo eso)."] = "你也會回應：如果有人在找你身上帶的東西，Alfa 會告訴他你有幾個（只有這個）。",
	["Ubicación de %s"] = "%s的位置",
	["Ultra"] = "極高",
	["Un arma en cada mano y mucha ira: el que más daño hace en grupo."] = "雙手各持一把武器並有大量怒氣：組隊時傷害最高的配點。",
	["Un arma grande de dos manos y golpes que hacen sangrar. La forma más fácil de subir."] = "一把大雙手武器與造成流血的攻擊。最簡單的練等方式。",
	["Un aturdimiento cuando lo necesites."] = "需要時隨時可用的擊昏。",
	["Un aullido corto cada vez que entregas una misión. Viene apagado."] = "每次交任務時短促地嚎叫一聲。預設關閉。",
	["Un aullido de lobo, del propio juego, la primera vez que abres Alfa en cada sesión."] = "每次登入後第一次開啟 Alfa 時，播放一聲遊戲內建的狼嚎。",
	["Un aviso con sus jefes y lo que llevas vencido, con un clic a sus consejos."] = "一則提醒，顯示它的首領與你已擊敗的數量，點一下即可查看提示。",
	["Un aviso corto con el lugar, su zona y el tiempo de camino."] = "一則簡短提示，包含地點、所在地區與路程時間。",
	["Un aviso corto cuando se activa una habilidad que depende de lo que pasó, como Abrumar después de que el enemigo esquive."] = "當依賴剛才情況的技能被觸發時（例如敵人閃躲後的壓制），顯示簡短提醒。",
	["Un aviso cuando juntas todo lo de un material o la lista entera."] = "集齊某種材料或整份清單時提醒你。",
	["Un aviso cuando vences a un jefe nuevo, con un clic a su botín."] = "擊敗新首領時的提醒，點一下即可查看它的戰利品。",
	["Un aviso y una franja en tus bolsas con qué vender, qué conservar y a qué comerciante ir, con un clic para marcar la chatarra."] = "一則提醒與背包中的一欄，告訴你該賣什麼、該留什麼、去找哪個商人，一鍵標記垃圾。",
	["Un barrido oscuro y suave sobre los íconos mientras su recarga corre."] = "冷卻期間，圖示上會有一層柔和的深色轉圈。",
	["Un borde del color de la calidad: verde, azul, morado..."] = "以品質顏色顯示邊框：綠色、藍色、紫色...",
	["Un borde verde que late sobre el botón de tu barra con la habilidad sugerida, para encontrarlo rápido."] = "在快捷列上帶有建議技能的按鈕周圍顯示閃動的綠色邊框，讓你快速找到。",
	["Un brujo con dos compañeros puede invocar al resto del grupo a la entrada de una mazmorra."] = "術士在兩名同伴的幫助下，可以把隊伍其他人召喚到地城入口。",
	["Un buzón"] = "信箱",
	["Un clic bajito cuando Lya te dice algo."] = "Lya 跟你說話時發出輕輕的喀噠聲。",
	["Un clic te pone el conjunto (fuera de combate; en combate, al terminar). Lo que esté en el banco no se puede poner."] = "點一下穿上這套裝備（戰鬥外；戰鬥中則在結束後）。銀行裡的東西無法穿上。",
	["Un clic y queda solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "點一下就只保留必要內容：你、你的隊伍、你的標記與指南的下一步。",
	["Un compañero tiene %s y tú lo puedes quitar, pero ningún clic lo hace. Elige «%s» en Tus clics, en la página Curación."] = "有隊友中了 %s，你可以驅散，但沒有設定對應的點擊。到治療頁面的「你的點擊」中選擇「%s」。",
	["Un consejo"] = "小提示",
	["Un cuadro pequeño y movible con tu vida y las estadísticas que más pesan para tu clase. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "一個可移動的小框，顯示你的生命值與對你職業最重要的屬性。戰鬥中遊戲會隱藏部分數字：會保留最後讀到的數值。",
	["Un disparo instantáneo extra. Úsalo mientras corres o para rematar."] = "額外的瞬發射擊。移動中或收尾時用。",
	["Un enemigo"] = "單體",
	["Un error, una mejora o un comentario, directo al desarrollador"] = "錯誤、改進建議或意見，直接傳給開發者",
	["Un escudo que absorbe daño. Ponlo antes de que te peguen o en quien tanquea."] = "吸收傷害的護盾。挨打前先加上，或給你的坦克加上。",
	["Un fondo del color de tu clase bajo tu nombre."] = "在你的名字下方加上職業顏色的背景。",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "用盾牌打出超強一擊，並產生大量仇恨。",
	["Un golpe más para gastar ira."] = "多一個消耗怒氣的攻擊。",
	["Un golpe nuevo y fuerte para tu barra."] = "為你的快捷列添加一個新的強力攻擊。",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "對付難纏的怪物時大幅提升傷害；還能讓你免疫恐懼。",
	["Un grano fino de cine sobre el mundo."] = "世界上覆蓋一層細緻的電影顆粒。",
	["Un grano fino, como de cine. Casi no cuesta: se mueve unas 14 veces por segundo y solo mientras se ve."] = "細緻的電影風格顆粒。幾乎不耗資源：每秒變化約 14 次，而且只在可見時才運作。",
	["Un hechizo de tus barras tiene un rango viejo"] = "你的快捷列上有一個法術是舊等級",
	["Un lobo de nivel %d te quiere echar la mano: ve tu nivel, tu zona y tu misión, solo él. Acepta aquí o en La Jauría."] = "一隻 %d 級的狼想幫你一把：只有他能看到你的等級、區域和任務。在這裡或在 La Jauría 中接受。",
	["Un mapa de una pieza: al acercar ya no se ven pedazos pegados, y el terreno se une sin rayas ni cuadros."] = "渾然一體的地圖：放大時不再看到拼接的碎塊，地形無縫相連，沒有線條或方格。",
	["Un mapa impecable"] = "完美無瑕的地圖",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "任務需要的物品會有金色外框（能開始任務的物品會標上「!」）。",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo, con lo que haga falta antes."] = "你想要的物品：Alfa 會規劃取得它的路線，包括所需的前置條件。",
	["Un paisaje más bonito"] = "更美的風景",
	["Un paseíto y unas palabras. Así también se hace manada."] = "散散步、說幾句話。狼群也是這樣形成的。",
	["Un pescadito asado no me caería nada mal."] = "來條烤小魚也挺不錯的。",
	["Un pescadito asado para la loba que te acompaña no estaría nada mal, ¿eh?"] = "給陪著你的母狼來一條烤小魚，好像也不錯，對吧？",
	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "在接下來的步驟要去的地方放上附編號的小標記。",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "少量的致命一擊、閃躲與護甲。",
	["Un poco de vida de vuelta después de críticos."] = "致命一擊後回復少量生命值。",
	["Un poco más de defensa."] = "稍微多一點防禦。",
	["Un poco más de ira al cargar."] = "衝鋒時多一點怒氣。",
	["Un punto azul abajo a la derecha si a ese compañero le falta el buff de tu clase. Se revisa fuera de combate."] = "如果那名隊友缺少你職業的增益效果，右下角會出現一個藍點。在戰鬥外檢查。",
	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "點一點來解鎖下一排，也稍微減少失手。",
	["Un raro vuelve más o menos entre media hora y una hora después de caer. Aquí ves hace cuánto lo cazaron tú o la manada."] = "稀有怪死後大約半小時到一小時會重生。這裡顯示你或狼群多久前擊殺了它。",
	["Un raro: %s"] = "稀有怪：%s",
	["Un rayo que salta entre varios enemigos."] = "在多個敵人之間跳躍的閃電。",
	["Un reto de Lya para esta semana."] = "莉婭本週給你的一個挑戰。",
	["Un rincón de %s que todavía no pisas."] = "%s 裡一個你還沒踏足的角落。",
	["Un servicio cercano, un marcador de tu mapa, donde estás ahora o la entrada de una mazmorra."] = "附近的服務、你地圖上的標記、你現在的位置或地城入口。",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "在提供適合你等級任務的人頭上顯示驚嘆號。",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "在可繳交已完成任務的人頭上顯示問號。",
	["Un solo addon con todo lo que usas al jugar: guías paso a paso con flecha y ruta, mapa, bolsas, builds, curación con clic, recolección, mazmorras, pesca y comercio. Todo con el mismo estilo."] = "一個插件包含遊戲中用到的一切：附箭頭與路線的逐步指南、地圖、背包、配點、點擊治療、採集、地城、釣魚與交易。風格一致。",
	["Un solo día de precios: el historial crece con cada escaneo o búsqueda."] = "只有一天的價格：每次掃描或搜尋，紀錄都會增加。",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "打得很痛的坦克：為輸出很高的隊伍提供大量仇恨，代價是額外防禦較少。適合有一些經驗的坦克。",
	["Un tramo más en la ruta que armas en la página Ruta: Alfa elige el camino para conseguirlo."] = "在「路線」頁面建立的路線中再加一段：由 Alfa 選擇取得它的路徑。",
	["Un tótem que atrae los golpes de los enemigos. Te da un respiro."] = "一個吸引敵人攻擊的圖騰。讓你喘口氣。",
	["Un tótem que cura poco a poco a tu grupo."] = "一個緩慢治療你隊伍的圖騰。",
	["Un tótem que hace lentos a los enemigos cercanos. Para escapar o pelear con ventaja."] = "一個緩速附近敵人的圖騰。用來逃跑或占得優勢。",
	["Un tótem que le dispara fuego al enemigo. Ponlo al empezar."] = "一個向敵人噴火的圖騰。開打時放下。",
	["Un tótem que quita el miedo, el sueño y el encanto a tu grupo."] = "一個為你的隊伍移除恐懼、沉睡和魅惑的圖騰。",
	["Un tótem que reduce el daño que recibes cuerpo a cuerpo."] = "一個減少你受到的近戰傷害的圖騰。",
	["Un zarpazo fuerte en forma de oso. Genera mucha amenaza."] = "熊形態下的強力揮擊。產生大量仇恨。",
	["Un «?» en cada página de Alfa para que Lya te la explique, y su propia tecla."] = "Alfa 每頁都有讓莉婭講解的「?」，還有她專屬的按鍵。",
	["Un ícono con la habilidad que conviene ahora. Solo muestra: nunca aprieta nada por ti."] = "一個顯示現在最適合技能的圖示。只負責顯示：絕不會替你按任何鍵。",
	["Un ícono de misión en la placa de nombre de los enemigos y personajes que todavía necesitas para una misión de tu registro. En mazmorras el juego oculta esos datos y no se marcan."] = "在你任務日誌中仍需要的敵人與角色的名條上顯示任務圖示。在地城中遊戲會隱藏這些資料，因此不會標記。",
	["Un'Goro de día: dinosaurios por todas partes. Yo me quedo atrás de ti, ¿va?"] = "白天的安戈洛：到處都是恐龍。我待在你後面，好嗎？",
	["Una acción recomendada en grande y tu camino en un par de clics."] = "一個醒目的推薦動作，點幾下就能看到你的路線。",
	["Una barra bajo el buzón para tomar el dinero y los objetos de tus cartas con un clic, y lo que recibiste al final."] = "信箱下方的一條按鈕列，一鍵拿取郵件中的金錢和物品，最後顯示你收到了什麼。",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "一條顯示首領即將施放的攻擊與倒數時間的長條，讓你知道何時該移動或防禦。",
	["Una bienvenida nueva en 9 pasos con la intro del lobo: eliges el idioma de Alfa (hay 10) y cada cosa que hace sola por ti."] = "全新的 9 步歡迎設定，附狼的開場動畫：選擇 Alfa 的語言（共 10 種），以及它替你自動做的每一件事。",
	["Una cadena de texto lleva un build completo: la copias, la pasas y la pegan."] = "一段文字就能包含完整的配點：你複製、傳送，對方貼上即可。",
	["Una cantidad de oro; se cumple cuando la llevas encima."] = "一定數量的金幣；當你身上帶有這麼多時即達成。",
	["Una carta con objetos vence pronto"] = "一封附有物品的郵件即將到期",
	["Una categoría…"] = "某個分類…",
	["Una cuenta de prueba no puede compartir"] = "試玩帳號無法分享",
	["Una curación muy rápida pero cara. Para emergencias."] = "非常快但很耗法力的治療。緊急時用。",
	["Una curación más fuerte. Para cuando la vida baja mucho."] = "更強的治療。生命值掉很多時用。",
	["Una curación que salta entre tus compañeros heridos."] = "在受傷的朋友之間跳躍的治療。",
	["Una curación rápida y barata. Perfecta para mantener a todos de pie."] = "快速又便宜的治療。讓大家都站著的完美選擇。",
	["Una curación rápida. Para cuando no hay tiempo."] = "快速治療。沒時間時用。",
	["Una fila con vuelo, posada, reparar, banco, buzón y tu entrenador, a un clic."] = "一排按鈕：飛行、旅店、修理、銀行、信箱與你的訓練師，一鍵直達。",
	["Una flecha en pantalla que apunta a tu siguiente objetivo, con la distancia. Apagada: tú decides por dónde ir."] = "畫面上的箭頭會指向你的下一個目標，並顯示距離。關閉：由你自己決定怎麼走。",
	["Una flecha verde en cada objeto de tus bolsas que es una mejora para tu especialización."] = "在背包中每件對你專精有提升的物品上顯示綠色箭頭。",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "依你的職業與等級，比身上裝備更好的裝備會顯示綠色箭頭。",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "淺綠色的長條顯示即將到達的治療量。",
	["Una gran curación para todo el grupo mientras canalizas."] = "引導期間為全隊大量治療。",
	["Una guía para tu nivel y tu zona, o tu propia ruta de misiones."] = "適合你等級與地區的指南，或你自己的任務路線。",
	["Una hora de caza"] = "一小時的狩獵",
	["Una hora de caza, aviso de cadena, «Deshacer» al omitir y cuánto te falta de tu guía."] = "一小時狩獵、任務鏈提醒、跳過後「復原」，以及指南還剩多久。",
	["Una huella sobre la mejor para tu clase (o la que más vale al venderla) y «Alfa te recomienda». Nunca elige por ti."] = "在最適合你職業的獎勵（或賣價最高的）上標一個爪印和「Alfa 推薦」。從不替你選擇。",
	["Una lista de las grises que ya no valen la pena, con «Abandonar» en cada una (tú lo confirmas)."] = "列出不再值得做的灰色任務，每個都有「放棄」（由你確認）。",
	["Una loba gordita como yo necesita sus tres comidas... y sus botanas."] = "像我這樣胖嘟嘟的母狼需要一日三餐…還有零食。",
	["Una loba negra que te da consejos y ánimo en el camino, sin estorbar. En memoria de una gran perrita."] = "一匹黑色母狼，在路上給你建議與鼓勵，又不礙事。紀念一隻很棒的小狗。",
	["Una loba que cuida tan bien a su lobo merece una salchicha, ¿no crees?"] = "這麼會照顧自己狼的狼，值得一根香腸，你說是不是？",
	["Una línea con el enlace de la misión cuando completas sus objetivos, otra cuando está lista para entregar y otra al entregarla. En grupo la ve todo el grupo, con o sin Alfa; solo, sale en tu chat. Nunca en banda."] = "完成任務目標時發一行帶任務連結的訊息，可交付時再發一行，交付時再發一行。組隊時全隊都看得到，不論有沒有 Alfa；單人時顯示在你的聊天框。團隊中不發送。",
	["Una línea corta debajo del ícono, como «Golpe mortal: recarga lista». Cada una sale hasta 4 veces y luego se calla; su × la calla antes."] = "圖示下方的一行短文字，例如「致死打擊：冷卻完畢」。每條最多顯示 4 次，之後就不再出現；點它的 × 可以提前關閉。",
	["Una línea debajo del aviso con lo que pasó."] = "提醒下方一行說明剛才發生了什麼。",
	["Una línea roja arriba avisa cuando un enemigo va por ese compañero."] = "敵人鎖定該隊友時，上方會出現紅線提醒。",
	["Una mano"] = "單手",
	["Una meta que marcas tú (el botón de hecha del rastreador o de esta lista)."] = "由你自己勾選的目標（追蹤器或此清單中的完成按鈕）。",
	["Una misión"] = "一個任務",
	["Una moneda sobre lo gris y lo que marcaste como chatarra."] = "在灰色物品與你標記為垃圾的物品上顯示一枚硬幣。",
	["Una nota con el instructor más cercano cuando tienes habilidades nuevas."] = "當你有新技能時，提示最近的訓練師。",
	["Una piedra de salud para emergencias. Haz una antes de cada mazmorra."] = "一塊應急用的治療石。每次進地城前都做一塊。",
	["Una piedra que deja revivir al morir. Pónsela a quien cura."] = "一塊讓人死後能復活的石頭。給你的治療者用。",
	["Una revisión completa de todos los módulos: más de 60 arreglos."] = "全面檢查了所有模組：修正了 60 多個問題。",
	["Una revisión completa para la versión estable: más de 20 arreglos en mazmorras con grupo, combate, el mapa, Pesca, Talentos y más."] = "為穩定版進行的全面檢查：在組隊地城、戰鬥、地圖、釣魚、天賦等方面修正了 20 多個問題。",
	["Una ruta es tu árbol de tramos: misiones de XP, de oro, de clase, materiales u objetos. Elige una de estas para empezar:"] = "路線是由路段組成的樹：經驗、金幣或職業任務、材料或物品。選擇下面其中一個開始：",
	["Una ruta necesita al menos 3 lugares que tu habilidad alcance. Elige otro tipo o recurso abajo, o recolecta aquí: Alfa anota cada nodo que encuentras."] = "一條路線至少需要 3 個你的技能能採集的地點。請在下方選擇其他類型或資源，或在這裡採集：Alfa 會記錄你發現的每個採集點。",
	["Una ruta por los mejores lugares para tu habilidad, con unas misiones de XP en medio."] = "一條經過適合你技能的最佳地點的路線，中間穿插一些經驗任務。",
	["Una salchicha al día mantiene a la loba feliz. Es ciencia."] = "一天一根香腸，母狼開心一整天。這是科學。",
	["Una semana de caza juntos"] = "一起狩獵的一週",
	["Una sesión termina tras 20 minutos sin lanzar o cuando empiezas otra; entonces aparece aquí con lo que sacaste y dónde."] = "20 分鐘沒有拋竿或你開始新的一次時，本次釣魚就會結束；之後它會顯示在這裡，附上你釣到的東西與地點。",
	["Una sesión tranquila: nada nuevo que contar."] = "平靜的一次遊戲：沒有什麼新鮮事。",
	["Una tecla para todo: equipo, cebo, lanzar y recoger. Con diario, guía, cocina, metas y estadísticas."] = "一個鍵包辦一切：裝備、魚餌、拋竿與收竿。還有圖鑑、指南、烹飪、目標與統計。",
	["Una tormenta de hielo en un área. Ideal contra grupos."] = "在一片區域降下冰風暴。對付成群敵人很棒。",
	["Una vuelta de recolección en tu zona"] = "在你的區域採集一圈",
	["Une los %d lugares que tu habilidad alcanza en una vuelta corta, la dibuja en el mapa y la flecha te lleva de parada en parada."] = "把你的技能能採集的 %d 個地點連成一條短環線，畫在地圖上，箭頭會逐站帶你。",
	["Unir las capas de sombra"] = "融合陰影層",
	["Unirte al grupo de tus amigos"] = "加入好友的隊伍",
	["Uno de los dragones verdes de la pesadilla aparece en el Bosque del Ocaso, junto a un gran árbol."] = "夢魘中的一隻綠龍會出現在暮色森林的一棵巨樹旁。",
	["Uno menos"] = "少一個",
	["Uno más"] = "多一個",
	["Unos %d pasos a tu ritmo"] = "照你的節奏大約 %d 步",
	["Unos %s de juego a tu ritmo (%s XP por hora)."] = "照你的節奏大約還要玩 %s（每小時 %s 經驗）。",
	["Unos materiales: %s."] = "關於這些材料：%s。",
	["Unos pocos altos elfos siguen con la Alianza; viven en Quel'Danil, en las Tierras del Interior."] = "少數高等精靈仍留在聯盟；他們住在辛特蘭的奎爾丹尼爾。",
	["Unos prefieren que yo haga lo aburrido y otros quieren hacerlo todo. Tú dime, y si cambias de idea, lo cambias cuando quieras."] = "有人喜歡讓我做無聊的事，有人想全部自己來。告訴我吧，改主意了隨時可改。",
	["Usa %s"] = "使用%s",
	["Usa %s: tu tecla lo pone."] = "使用%s：你的按鍵會幫你裝上。",
	["Usa Bloquear con escudo cuando un jefe pegue fuerte."] = "首領打得很痛時，使用盾牌格擋。",
	["Usa Deseo de muerte al empezar contra un jefe."] = "打首領時一開場就使用死亡之願。",
	["Usa Deseo de muerte con monstruos difíciles, no con los fáciles."] = "對付難纏的怪物時才使用死亡之願，簡單的怪就不用。",
	["Usa Golpe mortal sobre todo contra sanadores."] = "優先對治療者使用致死打擊。",
	["Usa Golpes de barrido cuando haya dos o más enemigos juntos."] = "有兩個以上的敵人聚在一起時，使用橫掃攻擊。",
	["Usa Ira rabiosa para romper miedos."] = "用狂暴之怒解除恐懼。",
	["Usa Revancha cada vez que se ilumine y Hender armadura para sumar amenaza."] = "每次復仇亮起時就使用，並用破甲攻擊累積仇恨。",
	["Usa Transfusión de vida para recuperar maná a cambio de vida."] = "使用生命分流，以生命值換取法力。",
	["Usa a tu demonio para frenar al monstruo mientras lanzas."] = "讓你的惡魔拖住怪物，你負責施法。",
	["Usa el juicio y vuelve a poner tu sello enseguida."] = "使用審判，然後立刻重新上聖印。",
	["Usa el número de abajo en lugar del que detecta el juego."] = "使用下方的數值，而不是遊戲偵測到的數值。",
	["Usa el número de abajo para el blanco normal."] = "使用下方的數值作為一般白色。",
	["Usa el resaltado del propio juego sobre el botón de la habilidad sugerida."] = "在建議技能的按鈕上使用遊戲內建的標示效果。",
	["Usa la forma felina con un monstruo y la de oso si vienen varios."] = "對付一隻怪時用獵豹形態，來了好幾隻就用熊形態。",
	["Usa tu golpe principal para juntar puntos de combo y gástalos en tu remate."] = "用你的主力攻擊累積連擊點數，再用終結技消耗掉。",
	["Usa tu varita cuando quieras ahorrar maná."] = "想省法力時就用魔杖。",
	["Usa tus hechizos de control si se te juntan dos monstruos."] = "被兩隻怪圍住時，使用你的控場法術。",
	["Usa un arma lenta y fuerte: tus mejoras de arma pegan con cada golpe."] = "使用速度慢、威力強的武器：你的武器強化效果每一擊都會觸發。",
	["Usa una varita para rematar enemigos sin gastar maná."] = "用魔杖補刀，不用花法力。",
