	["Vacía"] = "空",
	["Vaelastrasz, un dragón rojo, está preso de Nefarian en la Guarida Alanegra. Antes de pelear contra ti, te presta su fuerza."] = "紅龍瓦拉斯塔茲是奈法利安囚禁在黑翼之巢的俘虜。在與你戰鬥之前，他會把自己的力量借給你。",
	["Vale la pena: abre “%s”"] = "值得做：開啟「%s」",
	["Vale la pena: da %s"] = "值得做：獲得 %s",
	["Vallefresno es un bosque precioso. Pero cuida de no enojar a sus espíritus antiguos."] = "梣谷是一片美麗的森林。但小心別惹怒那裡的古老靈魂。",
	["Valor de %s: llevas %s"] = "價值%s：目前 %s",
