	["Vamos a %s: sigue la flecha."] = "前往 %s：跟著箭頭走。",
	["Van: %s"] = "參加：%s",
	["Van: %s."] = "參加：%s。",
	["Variable del juego: %s"] = "遊戲變數：%s",
	["Varimathras sirve a Sylvanas en Entrañas. Es un señor del terror, así que nadie sabe cuánto le va a durar la lealtad."] = "瓦里瑪薩斯在幽暗城為希瓦娜斯效力。他是個恐懼魔王，所以沒人知道他的忠誠能維持多久。",
	["Varios"] = "其他",
	["Varios enemigos cerca: Nova sagrada los golpea a todos."] = "附近有多個敵人：神聖新星可以擊中所有敵人。",
	["Varios enemigos cerca: el cono los golpea y los frena."] = "附近有多個敵人：冰錐術會擊中並減速它們。",
	["Varios enemigos cerca: el tótem de magma los quema a todos."] = "附近有多個敵人：熔岩圖騰會灼燒所有敵人。",
	["Varios enemigos cerca: golpéalos a todos a la vez."] = "附近有多個敵人：同時攻擊它們。",
	["Varios enemigos cerca: la ola los golpea y los frena."] = "附近有多個敵人：衝擊波會擊中並減速它們。",
	["Varios enemigos juntos: el huracán los golpea a todos."] = "多個敵人聚在一起：颶風會擊中所有敵人。",
	["Varios enemigos juntos: la ventisca los golpea a todos."] = "多個敵人聚在一起：暴風雪會擊中所有敵人。",
	["Varios enemigos juntos: lluvia de fuego sobre ellos."] = "多個敵人聚在一起：對它們施放火焰之雨。",
	["Varios enemigos juntos: quémalos a todos a la vez."] = "多個敵人聚在一起：一次把它們全部燒掉。",
	["Varios enemigos: consagra el suelo bajo ti."] = "多個敵人：在腳下施放奉獻。",
	["Varios enemigos: el disparo alcanza a varios."] = "多個敵人：這次射擊能命中多個目標。",
	["Varios enemigos: el rayo salta entre ellos."] = "多個敵人：閃電會在它們之間跳躍。",
	["Varios enemigos: golpéalos a todos."] = "多個敵人：攻擊它們全部。",
	["Varios enemigos: tus golpes alcanzan a otro más."] = "多個敵人：你的攻擊會多命中一個。",
	["Varios misiles que no fallan. Bueno cuando el enemigo no se mueve."] = "幾發必中的飛彈。敵人站著不動時很好用。",
	["Varios puntos juntos: acércate en el mapa para verlos."] = "多個點聚在一起：在地圖上放大即可查看。",
	["Varita"] = "魔杖",
	["Vas en %d de %d"] = "進度 %d / %d",
	["Vas muy bien. Cada paso cuenta, aunque no lo parezca."] = "你做得很好。每一步都算數，即使看起來不像。",
	["Vas tras %s"] = "你正在追蹤%s",
	["Ve con cuidado: la presa también muerde."] = "小心點：獵物也會咬人。",
	["Ve quién de tu hermandad busca grupo y pon tu anuncio. Se quita solo en una hora."] = "看看公會裡誰在找隊伍，並發佈你的公告。一小時後會自動撤下。",
	["Veces completada"] = "完成次數",
	["Veces completadas"] = "完成次數",
	["Vegetación"] = "植被",
	["Veinte. Ya te respetan en los caminos."] = "二十級。路上的人已經敬你三分。",
	["Vela sagrada"] = "聖潔蠟燭",
	["Velen, Kil'jaeden y Archimonde guiaban a los eredar. Los dos últimos aceptaron el poder de Sargeras; Velen huyó."] = "維倫、基爾加丹和阿克蒙德曾領導埃雷達爾人。後兩者接受了薩格拉斯的力量；維倫則逃走了。",
	["Velocidad"] = "速度",
	["Velocidad del zoom"] = "縮放速度",
	["Ven a jugar con la manada, pregunta lo que quieras o cuéntanos si algo falla. Haz clic en el cuadro y cópialo con Ctrl+C (Cmd+C en Mac)."] = "來和狼群一起玩，想問什麼都行，出了問題也告訴我們。點擊文字框，用 Ctrl+C（Mac 上用 Cmd+C）複製。",
	["Vence a este jefe para descubrir su nombre y su botín."] = "擊敗此首領即可揭曉其名稱與戰利品。",
	["Vence a sus jefes para ver lo que sueltan, o apaga el modo historia en Ajustes."] = "擊敗它的首領即可看到掉落物，或在設定中關閉劇情模式。",
	["Vencido"] = "已擊敗",
	["Vendas para curarte sin gastar maná ni esperar: imprescindible para todos."] = "用繃帶治療自己，不耗法力也不用等：每個人都必備。",
	["Vende"] = "販售",
	["Vende cañas y cebos"] = "販售魚竿與魚餌",
	["Vende lo gris cada vez que pases por un pueblo: es oro fácil y libera espacio."] = "每次經過城鎮都賣掉灰色物品：既是輕鬆的金幣，又能騰出空間。",
	["Vende lo gris con cualquier vendedor o tira algo que ya no uses."] = "把灰色物品賣給任何商人，或丟掉不再用的東西。",
	["Vende lo que no usas y junta lo que cuesta aprender a montar."] = "賣掉不用的東西，存夠學騎術需要的錢。",
	["Vende los materiales en montones de 20 o de 10: así es como la gente los compra."] = "材料按 20 個或 10 個一組出售：大家都是這樣買的。",
	["Vende los objetos grises y lo que marcaste como basura. Nunca lo que marcaste para guardar."] = "出售灰色物品與你標記為垃圾的物品。絕不出售你標記為保留的物品。",
	["Vende tu chatarra en este comerciante (%d)."] = "把垃圾賣給這個商人（%d）。",
