	["{dia}/{mes}"] = "{mes}月{dia}日",
	["¡%d misiones entregadas hoy! Así se caza en manada."] = "今天已經交了 %d 個任務！狼群就是這樣狩獵的。",
	["¡%d misiones hoy! A este paso me debes una salchicha."] = "今天 %d 個任務！照這速度你要欠我一根香腸了。",
	["¡%d misiones hoy! Estás que no te para nadie."] = "今天完成了 %d 個任務！誰也擋不住你。",
	["¡%s al máximo: %d/%d! Ya no hay nada que te enseñen. Qué orgullo, de verdad."] = "%s 已滿級：%d/%d！已經沒有什麼可以教你的了。真為你驕傲。",
	["¡%s cazó a %s!"] = "%s 獵到了 %s！",
	["¡%s es tu aprendiz!"] = "%s 成了你的學徒！",
	["¡%s llegó al nivel %d!"] = "%s 升到了 %d 級！",
	["¡%s subió a nivel %d! Auuuu, felicidades."] = "%s 升到了 %d 級！嗷嗚，恭喜。",
	["¡%s tiene su primera montura!"] = "%s 拿到了第一匹坐騎！",
	["¡%s ya está feliz! Así sí da gusto cazar juntos."] = "%s 開心了！一起狩獵就該是這樣。",
	["¡%s!"] = "%s！",
	["¡%s! Hace días que no te veía. En Hoy te digo dónde íbamos."] = "%s！好幾天沒見到你了。在「今天」裡我會告訴你我們上次到哪裡了。",
	["¡%s! Si algo te pega, corre hacia el tanque, no lejos de él."] = "%s！被打的時候，往坦克那邊跑，別跑遠。",
	["¡%s! Te extrañé mucho. Vine corriendo en cuanto te vi llegar."] = "%s！我好想你。一看到你來，我就跑過來了。",
	["¡%s, listo! La manada aúlla por ti. Auuuu. ¿Y mi salchicha?"] = "%s，完成！狼群為你嚎叫。嗷嗚嗚。那我的香腸呢？",
	["¡%s, volviste! Te extrañé tanto que no paraba de mover la cola."] = "%s，你回來啦！我想你想得尾巴都搖個不停。",
	["¡Abrumar!"] = "壓制！",
	["¡Ahora sí te sigo corriendo con la lengua de fuera!"] = "現在我要吐著舌頭追著你跑啦！",
	["¡Ahí estás, %s! Si quieres un consejo, dame clic."] = "你在這裡呀，%s！想要建議就點我。",
	["¡Ahí estás, %s! Te estaba esperando… te extrañé."] = "你在這裡呀，%s！我一直在等你……好想你。",
	["¡Al máximo!"] = "滿級了！",
	["¡Arriba, lobo! Antes de volver a pelear, recupera vida y maná."] = "起來吧，狼！再次戰鬥之前，先恢復生命力與法力。",
	["¡Arriba, lobo! Caer es parte de la cacería. Al revivir, repara tu equipo."] = "起來吧，狼！倒下也是狩獵的一部分。復活後記得修理裝備。",
	["¡Arriba, lobo! Libera tu espíritu: la flecha te dice si conviene tu cuerpo o el sanador."] = "起來吧，狼！釋放靈魂：箭頭會告訴你是回到屍體更划算，還是找靈魂醫者。",
	["¡Arriba, lobo! Si eran muchos, la próxima jálalos de uno en uno."] = "起來吧，狼！如果怪太多，下次一隻一隻地拉。",
	["¡Arriba, nivel %d! Si tienes un punto de talento libre, no lo olvides."] = "升到 %d 級了！如果有未分配的天賦點數，別忘了。",
	["¡Así se ve un aviso!"] = "提醒就是這個樣子！",
	["¡Ataque de la victoria!"] = "乘勝追擊！",
	["¡Auuu! Juntas cazamos mejor."] = "嗷嗚！我們一起狩獵更厲害。",
	["¡Auuu! Toda la manada está de fiesta."] = "嗷嗚！整個狼群都在慶祝。",
	["¡Auuuu! La manada unida no se rinde."] = "嗷嗚嗚！團結的狼群絕不放棄。",
	["¡Auuuu! ¡Nivel %d y dos niveles en menos de media hora! Vas como lobo en luna llena."] = "嗷嗚！%d 級了，不到半小時就升了兩級！你就像滿月下的狼。",
	["¡Bien hecho! %s"] = "做得好！%s",
	["¡Buen día, %s! El sol ya salió en Azeroth. ¿Vamos?"] = "早安，%s！艾澤拉斯的太陽已經升起了。走吧？",
	["¡Buenas noches, %s! Las lobas cazamos mejor de noche."] = "晚安，%s！我們母狼在夜裡最會狩獵。",
	["¡Buenas tardes, %s! Buena hora para unas misiones."] = "午安，%s！正是做幾個任務的好時候。",
	["¡Buenas, %s! Paso a paso se llega lejos."] = "你好，%s！一步一步就能走得很遠。",
	["¡Buenos días! Un buen desayuno y a cazar, que la mañana rinde."] = "早安！吃頓好早餐就去狩獵：早上效率最高。",
	["¡Buenos días, %s! Me estiro, bostezo y estoy lista."] = "早安，%s！伸個懶腰、打個哈欠，我準備好囉。",
	["¡Bájale, casi se lo quitas al tanque!"] = "收著點，你快把仇恨從坦克那裡搶過來了！",
	["¡Claro! Saludo a tu mascota cuando la llamas y, si eres cazador, te aviso cuando tiene hambre o está triste para que le des de comer."] = "當然！你召喚寵物時我會跟牠打招呼；如果你是獵人，牠餓了或不開心時我會告訴你，好讓你餵牠。",
	["¡Completaste %s!"] = "你完成了%s！",
	["¡Contraataque!"] = "反擊！",
	["¡Cumplido! Salchicha ganada."] = "完成！贏得一根香腸。",
	["¡Córtale a tu foco!"] = "打斷你的專注目標！",
	["¡Córtalo!"] = "打斷牠！",
	["¡De vuelta con la manada!"] = "歡迎回到狼群！",
	["¡De vuelta en la manada, %s!"] = "歡迎回到狼群，%s！",
	["¡Ejecutar!"] = "斬殺！",
	["¡En Thelsamar venden morcilla! La morcilla de Thelsamar es casi una salchicha... ¿me compras una?"] = "塞爾薩瑪有賣血腸！塞爾薩瑪血腸差不多就是香腸了…給我買一根好嗎？",
	["¡Es Halloween de Azeroth! Pide dulces a los posaderos: a veces te disfrazan de algo chistoso."] = "萬鬼節到了！向旅店老闆要糖果：有時他們會把你變成好玩的樣子。",
	["¡Es ahora! Hasta las %s"] = "就是現在！持續到 %s",
	["¡Es el Festival del Fuego del Solsticio! Visita las hogueras de las ciudades y honra su llama."] = "仲夏火焰節到了！去主城的營火看看，向它們的火焰致敬。",
	["¡Espera! Dejas %d misiones listas sin entregar. Si no, mañana empezamos por ahí."] = "等等！你還有 %d 個已完成的任務沒交。不交的話，下次我們就從那裡開始。",
	["¡Esto le sirve a %s!"] = "這個 %s 用得上！",
	["¡Está lanzando!"] = "牠在施法！",
	["¡Explorada completa!"] = "已全部探索！",
	["¡Felicidades por el nivel %d, %s! Auuuu."] = "恭喜升到 %d 級，%s！嗷嗚。",
	["¡Feliz cumpleaños!"] = "生日快樂！",
	["¡Feliz cumpleaños, Alfa!"] = "Alfa，生日快樂！",
	["¡Gracias! Ya van %d salchichas que me das. Las llevo contadas, eh."] = "謝謝！你已經給我 %d 根香腸了。我可都數著呢。",
	["¡Hasta pronto! Aquí te espero, cuidando tu lugar."] = "回頭見！我在這裡等你，幫你守著位置。",
	["¡Hasta pronto! Hoy cazamos %s Aquí te espero."] = "回頭見！今天我們獵到了：%s 我在這裡等你。",
	["¡Hay algo nuevo en Alfa: %s! ¿Te lo enseño?"] = "Alfa 有新東西：%s！要我帶你看看嗎？",
	["¡Hola!"] = "嗨！",
	["¡Hola! Pregúntame lo que quieras de Alfa: te lo explico corto y te llevo."] = "嗨！關於 Alfa 隨便問：我簡單講講，再帶你過去。",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Cuido a la manada y voy contigo en el camino."] = "你好！我是 Lya，Alfa 最信任的母狼。我守護狼群，也會陪你一路同行。",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Voy a acompañarte en esta configuración y después en tu camino."] = "嗨！我是莉婭，頭狼信賴的狼。我會陪你完成這次設定，之後陪你上路。",
	["¡Hola, %s!"] = "嗨，%s！",
	["¡Hola, %s! Familia %s y de buena casta. Tú y yo vamos a cuidar a nuestro alfa."] = "你好，%s！%s家族，血統優良。你和我一起照顧我們的頭狼吧。",
	["¡Hola, %s! Hoy huele a buena cacería."] = "你好，%s！今天聞起來是個狩獵的好日子。",
	["¡Hola, %s! La tarde pinta tranquila. ¿Qué cazamos hoy?"] = "你好，%s！今天下午看起來很平靜。我們去獵點什麼？",
	["¡Hola, %s! Noche de luna: perfecta para la manada."] = "你好，%s！月夜——最適合狼群了。",
	["¡Hola, %s! Tú y yo vamos a cuidar a nuestro alfa."] = "你好，%s！你和我一起照顧我們的頭狼吧。",
	["¡Hoy Alfa cumple %d años! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "今天是 Alfa 的 %d 歲生日！La Jauría 用心為你打造了它。我們用一根香腸來慶祝好嗎？",
	["¡Hoy Alfa cumple 1 año! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "今天是 Alfa 的 1 歲生日！La Jauría 用心為你打造了它。我們用一根香腸來慶祝好嗎？",
	["¡Hoy cumplimos %d años cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "今天我們一起狩獵滿 %d 年了，%s！謝謝你讓我當你的母狼。嗷嗚嗚。",
	["¡Hoy cumplimos 1 año cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "今天我們一起狩獵滿 1 年了，%s！謝謝你讓我當你的母狼。嗷嗚嗚。",
	["¡La Lya de %s me contestó el saludo! Ya somos manada."] = "%s 的莉婭回應了我的招呼！我們現在是一個狼群了。",
	["¡La Lya de %s me saludó! Entre lobas nos entendemos."] = "%s 的莉婭跟我打招呼了！母狼之間最懂彼此。",
	["¡Le encantan! Pero las mías son más ricas."] = "牠超愛的！不過我的更好吃。",
	["¡Listo! %s precios guardados."] = "完成！已儲存 %s 個價格。",
	["¡Listo! Alfa ya es tuyo"] = "完成！Alfa 已經屬於你",
	["¡Llegó el Festival de Invierno! En Forjaz y Orgrimmar el árbol se llena de luces y regalos."] = "冬幕節到了！鐵爐堡和奧格瑪的大樹掛滿了燈和禮物。",
	["¡Lo lograste: %s! Esa salchicha de premio me la voy a comer despacito."] = "你做到了：%s！那根獎勵香腸我要慢慢吃。",
	["¡Lo tienes! %s ×%d"] = "到手了！%s ×%d",
	["¡Martillo de cólera!"] = "憤怒之錘！",
	["¡Mi primera salchicha contigo! Esta no la voy a olvidar nunca."] = "和你的第一根香腸！這根我永遠不會忘。",
	["¡Misión completada: %s!"] = "任務完成：%s！",
	["¡Mmm, qué rica! Gracias, eres el mejor lobo de la manada."] = "嗯，真好吃！謝謝，你是狼群裡最好的狼。",
	["¡Mordedura de mangosta!"] = "貓鼬撕咬！",
	["¡Nivel %d! Date un momento para presumirlo, te lo ganaste."] = "%d 級了！花點時間炫耀一下吧，這是你應得的。",
	["¡Nivel %d! Paso firme y colmillo afilado."] = "%d 級了！腳步穩健，獠牙鋒利。",
	["¡Nivel %d! Tu esfuerzo se nota. Sigue así."] = "%d 級了！你的努力看得見。繼續保持。",
	["¡Nivel %d! ¡Auuu! Así se sube en manada."] = "%d 級了！嗷嗚——狼群就是這樣升級的。",
	["¡Nivel %d, bien hecho! Revisa si tu entrenador tiene algo nuevo."] = "%d 級了，做得好！看看你的訓練師有沒有新東西。",
	["¡Nivel %d, y el anterior hace nada! Aúllo dos veces, una por cada uno. ¡Auuuu, auuuu!"] = "%d 級，上一級才剛升！我嚎兩聲，一級一聲。嗷嗚，嗷嗚！",
	["¡Nivel 10! Ya tienes talentos: elígelos con calma, Talentos te ayuda."] = "10 級了！你有天賦了：慢慢選，「天賦」會幫你。",
	["¡Nivel 20! Ya puedes con mazmorras de verdad. ¿Armamos grupo?"] = "20 級了！你可以挑戰真正的地城了。組個隊吧？",
	["¡Nivel 30! Ya vas a la mitad del camino. ¡Qué orgullo de manada!"] = "30 級了！你已經走完一半了。狼群真為你驕傲！",
	["¡Nivel 40! Ya puedes aprender a montar. ¡Tu primera montura te espera!"] = "40 級了！你可以學騎術了。你的第一匹坐騎在等你！",
	["¡Nivel 50! Ya se huele la cima. Junta oro para lo que viene."] = "50 級了！已經聞到頂峰的氣息了。為接下來的事存點金幣。",
	["¡Nivel 60! ¡Lo lograste, alfa! Ahora toca cazar en grande."] = "60 級了！你做到了，頭狼！現在該來一場大狩獵了。",
	["¡Nueva página en tu historia: %s! %s"] = "你的故事翻開新的一頁：%s！%s",
	["¡Nuevo récord: %d misiones en un día! Ni la manada te alcanza."] = "新紀錄：一天 %d 個任務！狼群都追不上你。",
	["¡Ojo! Tu precio está %d %% por debajo de lo que vale."] = "小心！你的價格比它的價值低了 %d %%。",
	["¡Otro nivel tan pronto! Nivel %d. ¡Auuuu, esta racha no la para nadie!"] = "這麼快又升級了！%d 級。嗷嗚，誰也擋不住這股氣勢！",
	["¡Perdiste su atención!"] = "你失去了牠的仇恨！",
	["¡Plan cumplido!"] = "計畫完成！",
	["¡Plan terminado!"] = "計畫完成！",
	["¡Primera vez! Nuevo en tu diario"] = "第一次！已加入你的圖鑑",
	["¡Qué buena racha traes! Sigue así."] = "你的狀態真好！繼續保持。",
	["¡Qué bueno tenerte de vuelta, %s! Aquí sigo, cuidándote la espalda."] = "真高興你回來了，%s！我還在這裡守著你的背後。",
	["¡Qué gusto verte de vuelta! Esto es lo que trae esta versión para ti y tu manada."] = "真高興再次見到你！這是本版本為你和你的狼群帶來的內容。",
	["¡Qué gusto verte, %s! La manada ya te esperaba."] = "真高興見到你，%s！狼群一直在等你。",
	["¡Repara tu equipo!"] = "修理你的裝備！",
	["¡Reto cumplido: %s! Me gané una salchicha... digo, te la ganaste tú. Bueno, nos la ganamos."] = "挑戰完成：%s！我贏得了一根香腸…我是說，是你贏的。好吧，是我們一起贏的。",
	["¡Revancha!"] = "復仇！",
	["¡Salchicha! *mueve la cola a toda velocidad* Gracias, gracias."] = "香腸！*尾巴搖得飛快* 謝謝，謝謝。",
	["¡Salimos de %s! %s adentro."] = "我們走出%s了！在裡面 %s。",
	["¡Salimos de la mazmorra! %s adentro."] = "我們走出地城了！在裡面 %s。",
	["¡Sesenta! Lo lograste. Me debes una salchicha gigante."] = "六十級！你做到了。你欠我一根超大香腸。",
	["¡Subiste a nivel %d! Cada nivel te hace más fuerte."] = "你升到了 %d 級！每升一級都讓你更強。",
	["¡Sí, acompáñame!"] = "好，陪著我！",
	["¡Te está atacando a ti!"] = "牠在攻擊你！",
	["¡Te extrañé, %s! Corrí hasta aquí para verte."] = "我好想你，%s！我一路跑過來，就是為了見你。",
	["¡Te extrañé, %s! Tu ruta sigue donde la dejaste."] = "我好想你，%s！你的路線還在你離開的地方。",
	["¡Terminaste %s!"] = "你完成了%s！",
	["¡Terminaste esta guía!"] = "你完成了這個指南！",
	["¡Terminaste esta guía! Elige la siguiente y sigue subiendo con la manada."] = "你完成了這份指南！選擇下一份，繼續和狼群一起升級吧。",
	["¡Terminaste tu guía!"] = "你完成了你的指南！",
	["¡Tienes todo!"] = "全都有了！",
	["¡Tierra a la vista! La manada desembarca en %s"] = "看到陸地了！狼群在%s登岸",
	["¡Tierra a la vista: %s!"] = "看見陸地了：%s！",
	["¡Todo listo para la mazmorra!"] = "地城準備就緒！",
	["¡Tu %s llegó a %d/%d! Ya puedes aprender el rango %s."] = "你的%s達到了 %d/%d！現在可以學習%s等級了。",
	["¡Tu lista de compras está completa!"] = "你的購物清單齊了！",
	["¡Tú!"] = "你！",
	["¡Va! Te lo sigo diciendo, con gusto."] = "好喔！我會繼續告訴你，樂意之至。",
	["¡Van %d misiones hoy! La manada está orgullosa."] = "今天 %d 個任務！狼群為你驕傲。",
	["¡Volviste, %s! Estira las patas y vámonos."] = "你回來了，%s！伸伸腿，我們出發吧。",
	["¡Voy!"] = "我來了！",
	["¡Vuelta completa!"] = "路線完成！",
	["¡Ya eres nivel %d! La manada aúlla por ti."] = "你已經 %d 級了！狼群為你嚎叫。",
	["¡Ya estamos en %s! Deja que el tanque jale primero y quédate cerca de quien cura."] = "我們到%s了！讓坦克先拉怪，你待在治療者附近。",
	["¡Ya estamos en la mazmorra! Deja que el tanque jale primero y quédate cerca de quien cura."] = "我們進地城了！讓坦克先拉怪，你待在治療者附近。",
	["¡Ya estás en la %s!"] = "你到了%s！",
	["¡Ya estás en otro plano!"] = "你已經在另一個位面了！",
	["¡Ya la desbloqueaste!"] = "你解鎖了！",
	["¡Ya llegaste al 60!"] = "你到 60 級了！",
	["¡Ya llegaste, %s! Te extrañé. ¿A dónde vamos hoy?"] = "你來啦，%s！我好想你。今天我們去哪裡？",
	["¡Ya llegó! Vamos, manada"] = "到了！走吧，狼群",
	["¡Ya terminaste %d misiones! Vamos a cobrar la recompensa."] = "你已經完成了 %d 個任務！我們去領獎勵吧。",
	["¡Ya!"] = "就是現在！",
	["¡Yo te la guardé! En Historias está todo lo que cuentan tus misiones, para leerlo cuando quieras."] = "我幫你存著！「故事」裡有你任務講過的一切，隨時可讀。",
	["¡Ñam! Con esta van %d. Eres mi persona favorita de todo Azeroth."] = "啊嗚！這是第 %d 根了。你是全艾澤拉斯我最喜歡的人。",
	["«%s» tiene su historia. ¿Te la cuento?"] = "「%s」有一段故事。要我說給你聽嗎？",
	["«%s» ya quedó. Su final vale la pena, ¿te lo cuento?"] = "「%s」已經完成了。它的結局很值得一聽，要我說給你聽嗎？",
	["«%s»: hay que llevar el recado y hablar con quien te espera."] = "「%s」：把口信送到，和等你的人談談。",
	["«%s»: toca %s."] = "「%s」：該%s了。",
	["«Alejar más la cámara» de Comodidades está encendido y manda sobre este valor al entrar."] = "便利功能中的「鏡頭拉得更遠」已開啟，登入時會覆蓋此數值。",
	["«Buscar cerca» en la página Hoy"] = "「今天」頁面中的「搜尋附近」",
	["«Buscar cerca» te lleva con flecha a lo que necesitas, y «Mis planes» arma tus propias metas, que se marcan solas."] = "「搜尋附近」會用箭頭帶你去你需要的地方，「我的計畫」可以制定你自己的目標，完成後會自動勾選。",
	["«Camino al 60» en Hoy"] = "「今天」裡的「通往 60 級之路」",
	["«Cerrar mis misiones» está al día"] = "「完成我的任務」已是最新",
	["«Igual que Alfa» sigue el estilo de Ajustes > Apariencia y cambia con él."] = "「與 Alfa 相同」會跟隨「設定 > 外觀」中的風格，並隨之變化。",
	["«Invitar al clan» en el clic derecho"] = "右鍵選單中的「邀請加入公會或社群」",
	["«Llévame a…» (página Ruta, tu tecla o /alfa llevame): eliges el lugar y te llevo con vuelos, barcos, zepelines y portales, tramo por tramo."] = "「帶我去…」（路線頁面、你的按鍵或 /alfa llevame）：選好地點，我會用飛行、船隻、飛艇和傳送門一段一段帶你去。",
	["«Llévame» pone la flecha en este paso; «Siguiente» lo da por hecho y te lleva al que sigue."] = "「帶我去」讓箭頭指向這一步；「下一步」標記完成並帶你去下一步。",
	["«Ponte esto» con el equipo mejor"] = "更好的裝備提示「穿上這個」",
	["«Ponte esto», lista de compras, oficios del 1 al 300 y subastar fácil."] = "「裝備上」、購物清單、專業 1 到 300 和輕鬆拍賣。",
	["«Prepárame» recoge solo las que ya puedes tomar y te lleva a la entrada."] = "「幫我準備」只會接取你現在能接的任務，並帶你去入口。",
	["«Reportar» ya los lleva."] = "「回報」裡已經包含了。",
	["«Seguir» en La Jauría ya no se suelta cuando tu guía cambia de paso ni cuando vas por tu cuerpo: al terminar, la flecha vuelve con quien sigues."] = "La Jauría 的「跟隨」不會在指南換步驟或你跑回屍體時中斷：結束後，箭頭會重新指向你跟隨的人。",
	["«Siempre» sirve si un amigo encantador te ayuda. Las tablas de desencantar son estimadas."] = "如果有會附魔的朋友幫忙，可以選「總是」。分解資料表是估計值。",
	["«Tomar todo» en el buzón"] = "信箱「全部拿取」",
	["«Tomar todo» en el buzón, tu oro por hora y aviso de bolsas casi llenas."] = "信箱「全部拿取」、每小時金幣，以及背包快滿時的提醒。",
	["«Ver el siguiente» te deja mirar el paso que viene y lo dice claro; y un solo contador de pasos hechos."] = "「查看下一步」讓你先看看接下來的步驟，並清楚標明正在預覽；已完成步驟也只用一個計數。",
	["«[Misión] está lista para entregar» y «¡Misión completada!» en el chat del grupo, para todos. Apagado, solo te salen a ti."] = "在隊伍聊天中向所有人顯示「[任務] 可以交付了」和「任務完成！」。關閉時只有你看到。",
	["«[Misión] está lista para entregar» y «¡Misión completada!». En grupo lo ve todo el grupo; solo, sale en tu chat."] = "「[任務] 可以交付了」和「任務完成！」。組隊時全隊可見；單人時顯示在你的聊天框。",
	["«¿Cuánto tiempo tienes?» en Hoy"] = "「今天」裡的「你有多少時間？」",
	["«¿Qué es esto?»"] = "「這是什麼？」",
	["«¿Qué es esto?»: la ayuda de Alfa"] = "「這是什麼？」：Alfa 的說明",
	["¿A cuánto vendo en la subasta?"] = "在拍賣場該賣多少錢？",
	["¿A dónde vuelo?"] = "我該飛去哪裡？",
	["¿Abandonar %d misiones?"] = "要放棄 %d 個任務嗎？",
	["¿Abandonar %d misión?"] = "要放棄 %d 個任務嗎？",
	["¿Abandonar esta misión?"] = "要放棄這個任務嗎？",
	["¿Algo raro?"] = "發現異常？",
	["¿Alguien de la manada tiene lo que busco?"] = "狼群裡有人有我需要的東西嗎？",
	["¿Aplicar estos talentos?"] = "要套用這些天賦嗎？",
	["¿Borrar el diario?"] = "要清除日誌嗎？",
	["¿Borrar el historial?"] = "要清除歷史記錄嗎？",
	["¿Borrar esta ruta?"] = "要刪除這條路線嗎？",
	["¿Borrar este build?"] = "要刪除這個配點嗎？",
	["¿Borrar este plan?"] = "刪除此計畫？",
	["¿Borrar lo que descubriste?"] = "要清除你發現的採集點嗎？",
	["¿Borrar los precios?"] = "要清除價格嗎？",
	["¿Borrar todo tu progreso?"] = "要清除你所有的進度嗎？",
	["¿Borrar todo tu registro de pesca?"] = "清除你的全部釣魚記錄？",
	["¿Borrar todos tus marcadores?"] = "刪除你的所有標記？",
	["¿Cuándo es nuestro cumpleaños?"] = "我們的生日是什麼時候？",
	["¿Cuándo sale el barco?"] = "船什麼時候開？",
	["¿Cuándo vuelve un raro?"] = "稀有怪什麼時候重生？",
	["¿Cuánto daño hago?"] = "我打了多少傷害？",
	["¿Cuánto de Alfa quieres ver?"] = "你想看到多少 Alfa？",
	["¿Cuánto decide Alfa por ti en el camino?"] = "一路上 Alfa 替你做多少決定？",
