	["¿Sabías que las lobas tenemos el mejor oído de la manada? Bueno, eso digo yo."] = "你知道嗎？我們母狼的聽力是狼群裡最好的。嗯，這是我說的。",
	["¿Sabías que…? Alfa junta tus misiones listas en una sola ruta corta."] = "你知道嗎…？Alfa 會把你已完成的任務排成一條短路線。",
	["¿Sabías que…? Alfa tiene tres estilos: Alfa, Clásico WoW y Cristal. Y yo me pongo el que elijas."] = "你知道嗎…？Alfa 有三種風格：Alfa、經典 WoW 與玻璃。你選哪種，我就換上哪種。",
	["¿Sabías que…? Alt+clic en un objeto lo abre en la Enciclopedia."] = "你知道嗎…？Alt+點擊物品就能在百科中開啟它。",
	["¿Sabías que…? Buscar cerca te lleva al herrero, al banco o al vuelo más cercano."] = "你知道嗎…？「搜尋附近」能帶你去最近的鐵匠、銀行或飛行點。",
	["¿Sabías que…? Comercio te dice si algo conviene venderlo, subastarlo o convertirlo."] = "你知道嗎…？「交易」會告訴你某樣東西是該賣給商人、拍賣還是加工。",
	["¿Sabías que…? Con /alfa reportar le cuentas a toxic3000 de un error o una idea."] = "你知道嗎…？用 /alfa reportar 可以把錯誤或想法告訴 toxic3000。",
	["¿Sabías que…? Con Pesca lanzas y recoges con una sola tecla."] = "你知道嗎…？用「釣魚」只需一個鍵就能拋竿與收竿。",
	["¿Sabías que…? Con clic derecho sobre mí puedes silenciarme una hora o pedirme menos consejos."] = "你知道嗎…？右鍵點擊我，可以讓我靜音一小時，或讓我少給點建議。",
	["¿Sabías que…? Con el botón del minimapa ocultas todo Alfa y lo vuelves a traer."] = "你知道嗎…？用小地圖按鈕可以隱藏整個 Alfa，也能再把它叫回來。",
	["¿Sabías que…? El mapa de Alfa muestra el terreno, tus marcadores y lo que hay cerca."] = "你知道嗎…？Alfa 的地圖會顯示地形、你的標記與附近的東西。",
	["¿Sabías que…? En Bolsas ves tus bolsas, tu banco y lo de todos tus personajes."] = "你知道嗎…？在「背包」中可以看到你的背包、銀行以及你所有角色的物品。",
	["¿Sabías que…? En La Jauría ves a tu grupo y a la manada que usa Alfa."] = "你知道嗎…？在 La Jauría 中可以看到你的隊伍與使用 Alfa 的狼群。",
	["¿Sabías que…? En Mis planes armas tu propia lista de metas y la flecha te guía."] = "你知道嗎…？在「我的計畫」中可以制定自己的目標清單，箭頭會為你指路。",
	["¿Sabías que…? En Talentos ves qué talento poner ahora y por qué."] = "你知道嗎…？在「天賦」中可以看到現在該點哪個天賦以及原因。",
	["¿Sabías que…? La Enciclopedia te dice dónde sale cada objeto, PNJ o misión."] = "你知道嗎…？百科會告訴你每件物品、每個 NPC 或任務在哪裡。",
	["¿Sabías que…? La página Hoy te dice qué hacer ahora y lo urgente de tu personaje."] = "你知道嗎…？「今天」頁面會告訴你現在該做什麼，以及你角色的緊急事項。",
	["¿Sabías que…? Mazmorras te dice cuál te toca y cómo prepararte."] = "你知道嗎…？「地城」會告訴你該去哪個以及如何準備。",
	["¿Sabías que…? Recolección te marca en el mapa minerales, hierbas y bancos de peces."] = "你知道嗎…？「採集」會在地圖上標出礦脈、草藥與魚群。",
	["¿Te conté que mi comida favorita son las salchichas? Ninguna otra cosa se le acerca."] = "我說過我最愛吃的是香腸嗎？別的都比不上。",
