	["última: %s"] = "最近一次：%s",
	["• El logo, el lobo, Lya y los módulos propios de Alfa son de toxic3000 / La Jauría (GPL-3.0)."] = "• 標誌、狼、莉婭和 Alfa 自己的模組屬於 toxic3000 / La Jauría（GPL-3.0）。",
	["• GatherLite, de Wuild (MIT): la base de nodos de recolección."] = "• GatherLite，作者 Wuild（MIT）：採集點資料庫。",
	["• Letras Inter, Fira Sans y Open Sans (SIL Open Font License 1.1)."] = "• 字型 Inter、Fira Sans 與 Open Sans（SIL Open Font License 1.1）。",
	["• Los datos que trae Polestar también vienen de QuestieDB, Efficient Games (CC BY 4.0), VMaNGOS, CMaNGOS y Factoruide (GPL) y de ForeverLevelingBiS de Thunder (MIT); sus avisos están en cada LICENSE-DATA.txt."] = "• Polestar 的資料也來自 QuestieDB、Efficient Games（CC BY 4.0）、VMaNGOS、CMaNGOS 和 Factoruide（GPL），以及 Thunder 的 ForeverLevelingBiS（MIT）；它們的聲明在各個 LICENSE-DATA.txt 中。",
	["• OpenMap, de OpenMap contributors (MIT): la lógica del mapa continuo y las máscaras de territorio."] = "• OpenMap，作者 OpenMap contributors（MIT）：無縫地圖邏輯與領地遮罩。",
	["• Polestar, de The Polestar authors (GPL-3.0): el motor de guías, navegación y datos (github.com/fitzforge/polestar)."] = "• Polestar，作者 The Polestar authors（GPL-3.0）：指南、導航與資料引擎（github.com/fitzforge/polestar）。",
	["• Shortest Path Forever, de Cillian Berragan (GPL-3.0-or-later): la navegación y los servicios cercanos."] = "• Shortest Path Forever，作者 Cillian Berragan（GPL-3.0-or-later）：導航與附近服務。",
	["• TerrainWorldMap, de Dramacydal (MIT): la tabla de mosaicos del terreno del mapa."] = "• TerrainWorldMap，作者 Dramacydal（MIT）：地圖地形圖塊表。",
	["• pfQuest, de shagu (MIT): datos de misiones, PNJ y objetos."] = "• pfQuest，作者 shagu（MIT）：任務、NPC 與物品資料。",
